ckScale = autoScale * settings.dockScale;\n          final currentDockHeight = (70.0 * effectiveDockScale).clamp(\n            38.0,\n            95.0,\n          );\n\n          final isIntersectingDock = openWindows.any(\n            (w) =>\n                !w.isMaximized &&\n                (w.position.dy + w.size.height) >\n                    (screenHeight - (currentDockHeight + 24)),\n          );\n          final hideDock =\n              ((isMaximized || isIntersectingDock) && !_isDockHovered) ||\n              (settings.dockAutoHide && !_isDockHovered);\n\n          return Stack(\n            children: [\n              Positioned.fill(\n                child: GestureDetector(\n                  onTap: () {\n                    setState(() {\n                      _showAppMenu = false;\n                      _showQuickSettings = false;\n                    });\n                  },\n                  child: _buildWallpaper(settings),\n                ),\n              ),\n\n              if (isMobile)\n                _buildMobileLayout(\n                  context,\n                  settings,\n                  windowManager,\n                  system,\n                  focusedWindow,\n                  apps,\n                )\n              else\n                _buildDesktopLayout(\n                  context,\n                  settings,\n                  windowManager,\n                  system,\n                  hideDock,\n                ),\n            ],\n          );\n        },\n      ),\n    );\n  }\n\n  Widget _buildDesktopLayout(\n    BuildContext context,\n    SystemSettings settings,\n    WindowManager windowManager,\n    SystemController system,\n    bool hideDock,\n  ) {\n    return Stack(\n      children: [\n        ...windowManager.windows\n            .where((w) => !w.isMinimized)\n            .map(\n              (w) => WindowFrame(\n                key: ValueKey(w.id),\n                windowData: w,\n                onClose: () => 