  "lib/window_manager.dart": "import 'package:flutter/material.dart';\n\nclass WindowData {\n  final String id;\n  final String title;\n  final Widget content;\n  final dynamic icon;\n  Offset position;\n  Size size;\n  bool isMinimized;\n  bool isMaximized;\n  bool isFocused;\n\n  WindowData({\n    required this.id,\n    required this.title,\n    required this.content,\n    required this.icon,\n    this.position = const Offset(100, 100),\n    this.size = const Size(800, 600),\n    this.isMinimized = false,\n    this.isMaximized = false,\n    this.isFocused = true,\n  });\n}\n\nclass WindowManager extends ChangeNotifier {\n  final List<WindowData> _windows = [];\n  List<WindowData> get windows => List.unmodifiable(_windows);\n\n  void openWindow(String id, String title, Widget content, dynamic icon) {\n    final index = _windows.indexWhere((w) => w.id == id);\n    if (index != -1) {\n      _windows[index].isMinimized = false;\n      focusWindow(id);\n      return;\n    }\n\n    final newWindow = WindowData(\n      id: id,\n      title: title,\n      content: content,\n      icon: icon,\n      position: Offset(\n        100.0 + (_windows.length * 30),\n        100.0 + (_windows.length * 30),\n      ),\n    );\n    _windows.add(newWindow);\n    focusWindow(id);\n  }\n\n  void closeWindow(String id) {\n    _windows.removeWhere((w) => w.id == id);\n    notifyListeners();\n  }\n\n  void minimizeWindow(String id) {\n    final index = _windows.indexWhere((w) => w.id == id);\n    if (index != -1) {\n      _windows[index].isMinimized = true;\n      notifyListeners();\n    }\n  }\n\n  void toggleMaximize(String id) {\n    final index = _windows.indexWhere((w) => w.id == id);\n    if (index != -1) {\n      _windows[index].isMaximized = !_windows[index].isMaximized;\n      notifyListeners();\n    }\n  }\n\n  void focusWindow(String id) {\n    for (var w in _windows) {\n      w.isFocused = (w.id == id);\n    }\n    final index = _windows.indexWhere((w) => w.id == id);\n    if (index != -1) {\n      final window = _windows.removeAt(index);\n      _windows.add(window);\n    }\n    notifyListeners();\n  }\n\n  void updatePosition(String id, Offset newPosition) {\n    final index = _windows.indexWhere((w) => w.id == id);\n    if (index != -1) {\n      _windows[index].position = newPosition;\n      notifyListeners();\n    }\n  }\n\n  void updateSize(String id, Size newSize) {\n    final index = _windows.indexWhere((w) => w.id == id);\n    if (index != -1) {\n      _windows[index].size = newSize;\n      notifyListeners();\n    }\n  }\n}",
  "lib/quick_settings.dart": "import 'package:flutter/material.dart';\nimport 'package:glass_kit/glass_kit.dart';\nimport 'package:google_fonts/google_fonts.dart';\nimport 'package:provider/provider.dart';\nimport 'system_settings.dart';\n\nclass QuickSettings extends StatelessWidget {\n  const QuickSettings({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    final settings = context.watch<SystemSettings>();\n    final isDark = Theme.of(context).brightness == Brightness.dark;\n    final onSurfaceColor = Theme.of(context).colorScheme.onSurface;\n\n    return GlassContainer.clearGlass(\n      width: 300,\n      height: 380,\n      borderRadius: BorderRadius.circular(16),\n      blur: 30,\n      color: isDark\n          ? Colors.black.withValues(alpha: 0.6)\n          : Colors.white.withValues(alpha: 0.8),\n      borderColor: onSurfaceColor.withValues(alpha: 0.1),\n      child: Padding(\n        padding: const EdgeInsets.all(20.0),\n        child: Column(\n          crossAxisAlignment: CrossAxisAlignment.start,\n          children: [\n            Row(\n              mainAxisAlignment: MainAxisAlignment.spaceBetween,\n              children: [\n                Text(\n                  'Control Center',\n                  style: GoogleFonts.inter(\n                    color: onSurfaceColor,\n                    fontSize: 16,\n                    fontWeight: FontWeight.bold,\n                  ),\n                ),\n                Icon(Icons.tune, color: settings.accentColor, size: 18),\n              ],\n            ),\n            const SizedBox(height: 20),\n            Wrap(\n              spacing: 12,\n              runSpacing: 12,\n              children: [\n                _QuickTile(\n                  icon: Icons.wifi,\n                  label: 'Wi-Fi',\n                  isOn: settings.wifi,\n                  accentColor: settings.accentColor,\n                  onTap: () => settings.setWifi(!settings.wifi),\n                ),\n                _QuickTile(\n                  icon: Icons.bluetooth,\n                  label: 'Bluetooth',\n                  isOn: settings.bluetooth,\n                  accentColor: settings.accentColor,\n                  onTap: () => settings.setBluetooth(!settings.bluetooth),\n                ),\n                _QuickTile(\n                  icon: settings.isDarkMode\n                      ? Icons.dark_mode\n                      : Icons.light_mode,\n                  label: settings.isDarkMode ? 'Dark Mode' : 'Light Mode',\n                  isOn: settings.isDarkMode,\n                  accentColor: settings.accentColor,\n                  onTap: () => settings.setDarkMode(!settings.isDarkMode),\n                ),\n                _QuickTile(\n                  icon: Icons.nightlight_round,\n                  label: 'Night Shift',\n                  isOn: settings.nightShift,\n                  accentColor: settings.accentColor,\n                  onTap: () => settings.setNightShift(!settings.nightShift),\n                ),\n              ],\n            ),\n            const SizedBox(height: 24),\n            _SliderRow(\n              icon: Icons.brightness_high,\n              value: settings.screenBrightness,\n              accentColor: settings.accentColor,\n              onChanged: (v) => settings.setScreenBrightness(v),\n            ),\n            const SizedBox(height: 16),\n            _SliderRow(\n              icon: settings.soundVolume == 0\n                  ? Icons.volume_off\n                  : (settings.soundVolume < 0.5\n                        ? Icons.volume_down\n                        : Icons.volume_up),\n              value: settings.soundVolume,\n              accentColor: settings.accentColor,\n              onChanged: (v) => settings.setSoundVolume(v),\n            ),\n            const Spacer(),\n            Row(\n              mainAxisAlignment: MainAxisAlignment.spaceBetween,\n              children: [\n                Text(\n                  'Battery: 84% • fyrOS 2.4',\n                  style: GoogleFonts.inter(\n                    color: onSurfaceColor.withValues(alpha: 0.5),\n                    fontSize: 12,\n                  ),\n                ),\n                const Icon(Icons.battery_4_bar, color: Colors.green, size: 16),\n              ],\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n}\n\nclass _QuickTile extends StatelessWidget {\n  final IconData icon;\n  final String label;\n  final bool isOn;\n  final Color accentColor;\n  final VoidCallback onTap;\n\n  const _QuickTile({\n    required this.icon,\n    required this.label,\n    required this.isOn,\n    required this.accentColor,\n    required this.onTap,\n  });\n\n  @override\n  Widget build(BuildContext context) {\n    final onSurfaceColor = Theme.of(context).colorScheme.onSurface;\n\n    return GestureDetector(\n      onTap: onTap,\n      child: AnimatedContainer(\n        duration: const Duration(milliseconds: 180),\n        width: 124,\n        padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 10),\n        decoration: BoxDecoration(\n          color: isOn\n              ? accentColor.withValues(alpha: 0.85)\n              : onSurfaceColor.withValues(alpha: 0.06),\n          borderRadius: BorderRadius.circular(12),\n          border: Border.all(\n            color: isOn\n                ? accentColor.withValues(alpha: 0.9)\n                : onSurfaceColor.withValues(alpha: 0.1),\n            width: 1,\n          ),\n        ),\n        child: Row(\n          children: [\n            Icon(icon, color: isOn ? Colors.white : onSurfaceColor, size: 18),\n            const SizedBox(width: 8),\n            Expanded(\n              child: Text(\n                label,\n                style: GoogleFonts.inter(\n                  color: isOn ? Colors.white : onSurfaceColor,\n                  fontSize: 12,\n                  fontWeight: FontWeight.w500,\n                ),\n                maxLines: 1,\n                overflow: TextOverflow.ellipsis,\n              ),\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n}\n\nclass _SliderRow extends StatelessWidget {\n  final IconData icon;\n  final double value;\n  final Color accentColor;\n  final ValueChanged<double> onChanged;\n\n  const _SliderRow({\n    required this.icon,\n    required this.value,\n    required this.accentColor,\n    required this.onChanged,\n  });\n\n  @override\n  Widget build(BuildContext context) {\n    final onSurfaceColor = Theme.of(context).colorScheme.onSurface;\n\n    return Row(\n      children: [\n        Icon(icon, color: onSurfaceColor.withValues(alpha: 0.6), size: 18),\n        const SizedBox(width: 12),\n        Expanded(\n          child: SliderTheme(\n            data: SliderTheme.of(context).copyWith(\n              trackHeight: 18,\n              thumbShape: SliderComponentShape.noThumb,\n              overlayShape: SliderComponentShape.noOverlay,\n              activeTrackColor: accentColor.withValues(alpha: 0.8),\n              inactiveTrackColor: onSurfaceColor.withValues(alpha: 0.08),\n            ),\n            child: Slider(value: value, onChanged: onChanged),\n          ),\n        ),\n      ],\n    );\n  }\n}",
  "lib/models/config_model.dart": "class AppConfig {\n  final ProfileConfig profile;\n  final List<SkillCategory> skills;\n  final List<SocialLink> socials;\n  final List<CustomApp> apps;\n  final List<ExperienceItem> experience;\n  final List<EducationItem> education;\n  final List<String> certifications;\n\n  AppConfig({\n    required this.profile,\n    required this.skills,\n    required this.socials,\n    required this.apps,\n    required this.experience,\n    required this.education,\n    required this.certifications,\n  });\n\n  factory AppConfig.fromJson(Map<String, dynamic> json) {\n    return AppConfig(\n      profile: ProfileConfig.fromJson(json['profile'] ?? {}),\n      skills:\n          (json['skills'] as List?)?.map((e) {\n            if (e is String)\n              return SkillCategory(category: 'Other', items: [e]);\n            return SkillCategory.fromJson(e);\n          }).toList() ??\n          [],\n      socials:\n          (json['socials'] as List?)\n              ?.map((e) => SocialLink.fromJson(e))\n              .toList() ??\n          [],\n      apps:\n          (json['apps'] as List?)?.map((e) => CustomApp.fromJson(e)).toList() ??\n          [],\n      experience:\n          (json['experience'] as List?)\n              ?.map((e) => ExperienceItem.fromJson(e))\n              .toList() ??\n          [],\n      education:\n          (json['education'] as List?)\n              ?.map((e) => EducationItem.fromJson(e))\n              .toList() ??\n          [],\n      certifications: List<String>.from(json['certifications'] ?? []),\n    );\n  }\n\n  Map<String, dynamic> toJson() => {\n    'profile': profile.toJson(),\n    'skills': skills.map((e) => e.toJson()).toList(),\n    'socials': socials.map((e) => e.toJson()).toList(),\n    'apps': apps.map((e) => e.toJson()).toList(),\n    'experience': experience.map((e) => e.toJson()).toList(),\n    'education': education.map((e) => e.toJson()).toList(),\n    'certifications': certifications,\n  };\n}\n\nclass ProfileConfig {\n  final String name;\n  final String title;\n  final String about;\n  final String profilePic;\n  final String tabTitle;\n  final String terminalName;\n  final String systemName;\n  final String email;\n  final String location;\n\n  ProfileConfig({\n    required this.name,\n    required this.title,\n    required this.about,\n    required this.profilePic,\n    required this.tabTitle,\n    required this.terminalName,\n    required this.systemName,\n    required this.email,\n    required this.location,\n  });\n\n  factory ProfileConfig.fromJson(Map<String, dynamic> json) {\n    return ProfileConfig(\n      name: json['name'] ?? '',\n      title: json['title'] ?? '',\n      about: json['about'] ?? '',\n      profilePic: json['profilePic'] ?? 'assets/face.jpg',\n      tabTitle: json['tabTitle'] ?? 'Portfolio',\n      terminalName: json['terminalName'] ?? 'archie',\n      systemName: json['systemName'] ?? 'fyrWeb',\n      email: json['email'] ?? '',\n      location: json['location'] ?? '',\n    );\n  }\n\n  Map<String, dynamic> toJson() => {\n    'name': name,\n    'title': title,\n    'about': about,\n    'profilePic': profilePic,\n    'tabTitle': tabTitle,\n    'terminalName': terminalName,\n    'systemName': systemName,\n    'email': email,\n    'location': location,\n  };\n}\n\nclass SocialLink {\n  final String id;\n  final String name;\n  final String url;\n  final String icon;\n\n  SocialLink({\n    required this.id,\n    required this.name,\n    required this.url,\n    required this.icon,\n  });\n\n  factory SocialLink.fromJson(Map<String, dynamic> json) {\n    return SocialLink(\n      id: json['id'] ?? '',\n      name: json['name'] ?? '',\n      url: json['url'] ?? '',\n      icon: json['icon'] ?? 'link',\n    );\n  }\n\n  Map<String, dynamic> toJson() => {\n    'id': id,\n    'name': name,\n    'url': url,\n    'icon': icon,\n  };\n}\n\nclass CustomApp {\n  final String id;\n  final String title;\n  final String? subtitle;\n  final String url;\n  final String icon;\n  final String color;\n  final List<String>? caseStudy;\n  final List<String>? devopsStudy;\n  final List<String>? sysadminStudy;\n  final String? architectureBadge;\n  final List<String>? tags;\n\n  CustomApp({\n    required this.id,\n    required this.title,\n    this.subtitle,\n    required this.url,\n    required this.icon,\n    required this.color,\n    this.caseStudy,\n    this.devopsStudy,\n    this.sysadminStudy,\n    this.architectureBadge,\n    this.tags,\n  });\n\n  factory CustomApp.fromJson(Map<String, dynamic> json) {\n    return CustomApp(\n      id: json['id'] ?? '',\n      title: json['title'] ?? '',\n      subtitle: json['subtitle'],\n      url: json['url'] ?? '',\n      icon: json['icon'] ?? 'apps',\n      color: json['color'] ?? '0xFF2196F3',\n      caseStudy: (json['caseStudy'] as List<dynamic>?)?.map((e) => e.toString()).toList(),\n      devopsStudy: (json['devopsStudy'] as List<dynamic>?)?.map((e) => e.toString()).toList(),\n      sysadminStudy: (json['sysadminStudy'] as List<dynamic>?)?.map((e) => e.toString()).toList(),\n      architectureBadge: json['architectureBadge'],\n      tags: (json['tags'] as List<dynamic>?)?.map((e) => e.toString()).toList(),\n    );\n  }\n\n  Map<String, dynamic> toJson() => {\n    'id': id,\n    'title': title,\n    if (subtitle != null) 'subtitle': subtitle,\n    'url': url,\n    'icon': icon,\n    'color': color,\n    if (caseStudy != null) 'caseStudy': caseStudy,\n    if (devopsStudy != null) 'devopsStudy': devopsStudy,\n    if (sysadminStudy != null) 'sysadminStudy': sysadminStudy,\n    if (architectureBadge != null) 'architectureBadge': architectureBadge,\n    if (tags != null) 'tags': tags,\n  };\n}\n\nclass ExperienceItem {\n  final String company;\n  final String role;\n  final String period;\n  final String description;\n\n  ExperienceItem({\n    required this.company,\n    required this.role,\n    required this.period,\n    required this.description,\n  });\n\n  factory ExperienceItem.fromJson(Map<String, dynamic> json) {\n    return ExperienceItem(\n      company: json['company'] ?? '',\n      role: json['role'] ?? '',\n      period: json['period'] ?? '',\n      description: json['description'] ?? '',\n    );\n  }\n\n  Map<String, dynamic> toJson() => {\n    'company': company,\n    'role': role,\n    'period': period,\n    'description': description,\n  };\n}\n\nclass EducationItem {\n  final String school;\n  final String degree;\n  final String period;\n\n  EducationItem({\n    required this.school,\n    required this.degree,\n    required this.period,\n  });\n\n  factory EducationItem.fromJson(Map<String, dynamic> json) {\n    return EducationItem(\n      school: json['school'] ?? '',\n      degree: json['degree'] ?? '',\n      period: json['period'] ?? '',\n    );\n  }\n\n  Map<String, dynamic> toJson() => {\n    'school': school,\n    'degree': degree,\n    'period': period,\n  };\n}\n\nclass SkillCategory {\n  final String category;\n  final List<String> items;\n\n  SkillCategory({required this.category, required this.items});\n\n  factory SkillCategory.fromJson(Map<String, dynamic> json) {\n    return SkillCategory(\n      category: json['category'] ?? '',\n      items: List<String>.from(json['items'] ?? []),\n    );\n  }\n\n  Map<String, dynamic> toJson() => {'category': category, 'items': items};\n}",
  "lib/main.dart": "import 'package:flutter/material.dart';\nimport 'package:google_fonts/google_fonts.dart';\nimport 'desktop_screen.dart';\nimport 'package:provider/provider.dart';\nimport 'system_settings.dart';\nimport 'window_manager.dart';\nimport 'system_controller.dart';\nimport 'dart:convert';\nimport 'package:flutter/services.dart';\nimport 'models/config_model.dart';\n\nvoid main() async {\n  WidgetsFlutterBinding.ensureInitialized();\n\n  final String configString = await rootBundle.loadString('assets/config.json');\n  final configJson = jsonDecode(configString);\n  final config = AppConfig.fromJson(configJson);\n\n  final windowManager = WindowManager();\n  final settings = SystemSettings();\n  await settings.init();\n\n  runApp(\n    MultiProvider(\n      providers: [\n        Provider<AppConfig>.value(value: config),\n        ChangeNotifierProvider<SystemSettings>.value(value: settings),\n        ChangeNotifierProvider.value(value: windowManager),\n        ChangeNotifierProvider(\n          create: (_) => SystemController(windowManager: windowManager),\n        ),\n      ],\n      child: const MyApp(),\n    ),\n  );\n}\n\nclass MyApp extends StatelessWidget {\n  const MyApp({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    final settings = context.watch<SystemSettings>();\n    final config = context.watch<AppConfig>();\n\n    return MaterialApp(\n      title: config.profile.tabTitle,\n      debugShowCheckedModeBanner: false,\n      theme: ThemeData(\n        brightness: settings.isDarkMode ? Brightness.dark : Brightness.light,\n        colorScheme: ColorScheme.fromSeed(\n          seedColor: settings.accentColor,\n          brightness: settings.isDarkMode ? Brightness.dark : Brightness.light,\n          surface: settings.isDarkMode\n              ? const Color(0xFF0A0A0A)\n              : const Color(0xFFF0F0F0),\n          onSurface: settings.isDarkMode ? Colors.white : Colors.black87,\n        ),\n        scaffoldBackgroundColor: settings.isDarkMode\n            ? Colors.black\n            : Colors.white,\n        textTheme:\n            GoogleFonts.interTextTheme(\n              settings.isDarkMode\n                  ? ThemeData.dark().textTheme\n                  : ThemeData.light().textTheme,\n            ).apply(\n              bodyColor: settings.isDarkMode ? Colors.white : Colors.black87,\n              displayColor: settings.isDarkMode ? Colors.white : Colors.black,\n            ),\n        useMaterial3: true,\n      ),\n      home: const DesktopScreen(),\n    );\n  }\n}",
  "lib/app_data.dart": "import 'package:flutter/material.dart';\nimport 'package:font_awesome_flutter/font_awesome_flutter.dart';\nimport 'apps/contact_app.dart';\nimport 'apps/terminal_app.dart';\nimport 'apps/file_explorer_app.dart';\nimport 'apps/settings_app.dart';\nimport 'apps/resume_app.dart';\nimport 'apps/code_editor_app.dart';\nimport 'apps/photo_album_app.dart';\nimport 'apps/music_player_app.dart';\nimport 'apps/grand_theft_ant/grand_theft_ant_app.dart';\nimport 'apps/case_study_app.dart';\nimport 'apps/infra_monitor_app.dart';\nimport 'models/config_model.dart';\n\nclass AppInfo {\n  final String id;\n  final String title;\n  final String? subtitle;\n  final Widget? content;\n  final dynamic icon;\n  final Color color;\n  final String? url;\n  final List<String>? caseStudy;\n  final List<String>? devopsStudy;\n  final List<String>? sysadminStudy;\n  final String? architectureBadge;\n  final List<String>? tags;\n\n  AppInfo({\n    required this.id,\n    required this.title,\n    this.subtitle,\n    this.content,\n    required this.icon,\n    this.color = Colors.blue,\n    this.url,\n    this.caseStudy,\n    this.devopsStudy,\n    this.sysadminStudy,\n    this.architectureBadge,\n    this.tags,\n  });\n}\n\nList<AppInfo> getApps(AppConfig config) {\n  final List<AppInfo> systemApps = [\n    AppInfo(\n      id: 'resume',\n      title: 'Resume',\n      content: const ResumeApp(),\n      icon: Icons.description_outlined,\n      color: Colors.orange,\n    ),\n    AppInfo(\n      id: 'infra_monitor',\n      title: 'Infra Monitor',\n      subtitle: 'GCP Cloud & SysAdmin Telemetry',\n      content: const InfraMonitorApp(),\n      icon: Icons.dns_rounded,\n      color: const Color(0xFF00B0FF),\n    ),\n    AppInfo(\n      id: 'terminal',\n      title: 'Terminal',\n      content: const TerminalApp(),\n      icon: Icons.terminal,\n      color: Colors.black,\n    ),\n    AppInfo(\n      id: 'files',\n      title: 'File Explorer',\n      content: const FileExplorerApp(),\n      icon: Icons.folder,\n      color: Colors.blue,\n    ),\n    AppInfo(\n      id: 'code',\n      title: 'Source Code',\n      content: const CodeEditorApp(),\n      icon: Icons.code,\n      color: const Color(0xFF1E1E1E),\n    ),\n    AppInfo(\n      id: 'photos',\n      title: 'Photos',\n      content: const PhotoAlbumApp(),\n      icon: Icons.photo_album,\n      color: Colors.purple,\n    ),\n    AppInfo(\n      id: 'music',\n      title: 'Music Player',\n      content: const MusicPlayerApp(),\n      icon: Icons.headphones,\n      color: Colors.teal,\n    ),\n    AppInfo(\n      id: 'grand_theft_ant',\n      title: 'Grand Theft Ant',\n      subtitle: '3D Open-World Bug Simulation',\n      content: const GrandTheftAntApp(),\n      icon: Icons.sports_esports_rounded,\n      color: const Color(0xFF7FA650),\n    ),\n    AppInfo(\n      id: 'contact',\n      title: 'Contact Me',\n      content: const ContactApp(),\n      icon: Icons.mail_outline,\n      color: Colors.green,\n    ),\n    AppInfo(\n      id: 'settings',\n      title: 'Settings',\n      content: const SettingsApp(),\n      icon: Icons.settings,\n      color: Colors.grey,\n    ),\n  ];\n\n  final List<AppInfo> customApps = config.apps.map((app) {\n    return AppInfo(\n      id: app.id,\n      title: app.title,\n      subtitle: app.subtitle,\n      url: app.url,\n      content: app.caseStudy != null ? CaseStudyApp(app: app) : null,\n      icon: _getIconData(app.icon),\n      color: Color(int.parse(app.color)),\n      caseStudy: app.caseStudy,\n      devopsStudy: app.devopsStudy,\n      sysadminStudy: app.sysadminStudy,\n      architectureBadge: app.architectureBadge,\n      tags: app.tags,\n    );\n  }).toList();\n\n  return [...systemApps, ...customApps];\n}\n\ndynamic _getIconData(String iconName) {\n  switch (iconName) {\n    case 'computer':\n      return Icons.computer;\n    case 'people':\n    case 'group':\n    case 'social':\n      return Icons.people_alt_rounded;\n    case 'code':\n      return Icons.code;\n    case 'language':\n      return Icons.language;\n    case 'github':\n      return FontAwesomeIcons.github;\n    case 'link':\n      return Icons.link;\n    case 'smartphone':\n      return Icons.smartphone;\n    case 'album':\n      return Icons.album;\n    case 'headphones':\n      return Icons.headphones;\n    case 'book':\n      return Icons.book;\n    case 'favorite':\n      return Icons.favorite;\n    case 'newspaper':\n      return Icons.newspaper;\n    case 'speedometer':\n    case 'speed':\n    case 'gauge':\n      return Icons.speed;\n    case 'cloud':\n      return Icons.cloud_done_rounded;\n    case 'dns':\n    case 'server':\n      return Icons.dns_rounded;\n    case 'terminal':\n      return Icons.terminal_rounded;\n    case 'docker':\n      return FontAwesomeIcons.docker;\n    case 'shield':\n    case 'security':\n      return Icons.shield_outlined;\n    case 'layers':\n      return Icons.layers_rounded;\n    case 'gamepad':\n    case 'game':\n    case 'sports_esports':\n      return Icons.sports_esports_rounded;\n    case 'bug':\n    case 'ant':\n      return Icons.pest_control_rounded;\n    default:\n      return Icons.apps;\n  }\n}",
  "lib/app_menu.dart": "import 'package:flutter/material.dart';\nimport 'package:glass_kit/glass_kit.dart';\nimport 'package:google_fonts/google_fonts.dart';\nimport 'app_data.dart';\nimport 'package:font_awesome_flutter/font_awesome_flutter.dart';\nimport 'package:provider/provider.dart';\nimport 'models/config_model.dart';\n\nclass AppMenu extends StatelessWidget {\n  final Function(String, String, Widget?, dynamic, {String? url}) onOpenApp;\n  final VoidCallback onClose;\n\n  const AppMenu({super.key, required this.onOpenApp, required this.onClose});\n\n  @override\n  Widget build(BuildContext context) {\n    return GlassContainer.clearGlass(\n      width: 250,\n      height: 500,\n      borderRadius: BorderRadius.circular(12),\n      blur: 30,\n      color: Colors.black.withOpacity(0.7),\n      borderColor: Colors.white.withOpacity(0.1),\n      child: Column(\n        crossAxisAlignment: CrossAxisAlignment.start,\n        children: [\n          Padding(\n            padding: const EdgeInsets.all(16.0),\n            child: Text(\n              'Applications',\n              style: GoogleFonts.inter(\n                color: Colors.white,\n                fontSize: 14,\n                fontWeight: FontWeight.bold,\n              ),\n            ),\n          ),\n          const Divider(color: Colors.white10, height: 1),\n          Expanded(\n            child: Consumer<AppConfig>(\n              builder: (context, config, child) {\n                final apps = getApps(config);\n                return ListView.builder(\n                  padding: const EdgeInsets.symmetric(vertical: 8),\n                  itemCount: apps.length,\n                  itemBuilder: (context, index) {\n                    final app = apps[index];\n                    return ListTile(\n                      dense: true,\n                      leading: app.icon is IconData\n                          ? Icon(app.icon, color: app.color, size: 18)\n                          : FaIcon(app.icon, color: app.color, size: 16),\n                      title: Text(\n                        app.title,\n                        style: GoogleFonts.inter(\n                          color: Colors.white,\n                          fontSize: 13,\n                        ),\n                      ),\n                      onTap: () {\n                        onOpenApp(\n                          app.id,\n                          app.title,\n                          app.content,\n                          app.icon,\n                          url: app.url,\n                        );\n                        onClose();\n                      },\n                    );\n                  },\n                );\n              },\n            ),\n          ),\n          const Divider(color: Colors.white10, height: 1),\n          ListTile(\n            dense: true,\n            leading: const Icon(\n              Icons.power_settings_new,\n              color: Colors.redAccent,\n              size: 18,\n            ),\n            title: Text(\n              'Shut Down...',\n              style: GoogleFonts.inter(color: Colors.white, fontSize: 13),\n            ),\n            onTap: onClose,\n          ),\n        ],\n      ),\n    );\n  }\n}",
  "lib/window_frame.dart": "import 'package:flutter/material.dart';\nimport 'package:google_fonts/google_fonts.dart';\nimport 'window_manager.dart';\nimport 'package:font_awesome_flutter/font_awesome_flutter.dart';\n\nclass WindowFrame extends StatelessWidget {\n  final WindowData windowData;\n  final VoidCallback onClose;\n  final VoidCallback onMinimize;\n  final VoidCallback onMaximize;\n  final VoidCallback onFocus;\n  final Function(Offset) onPositionChanged;\n  final Function(Size) onSizeChanged;\n\n  const WindowFrame({\n    super.key,\n    required this.windowData,\n    required this.onClose,\n    required this.onMinimize,\n    required this.onMaximize,\n    required this.onFocus,\n    required this.onPositionChanged,\n    required this.onSizeChanged,\n  });\n\n  @override\n  Widget build(BuildContext context) {\n    final isDark = Theme.of(context).brightness == Brightness.dark;\n    final surfaceColor = Theme.of(context).colorScheme.surface;\n    final onSurfaceColor = Theme.of(context).colorScheme.onSurface;\n\n    Widget windowContent = GestureDetector(\n      onTap: onFocus,\n      child: Container(\n        width: windowData.isMaximized ? null : windowData.size.width,\n        height: windowData.isMaximized ? null : windowData.size.height,\n        decoration: BoxDecoration(\n          borderRadius: BorderRadius.circular(windowData.isMaximized ? 0 : 12),\n          boxShadow: windowData.isMaximized\n              ? []\n              : [\n                  BoxShadow(\n                    color: windowData.isFocused\n                        ? Theme.of(\n                            context,\n                          ).colorScheme.primary.withValues(alpha: 0.3)\n                        : Colors.black.withValues(alpha: isDark ? 0.2 : 0.1),\n                    blurRadius: windowData.isFocused ? 40 : 30,\n                    spreadRadius: windowData.isFocused ? 8 : 5,\n                  ),\n                ],\n        ),\n        child: Stack(\n          children: [\n            Positioned.fill(\n              child: ClipRRect(\n                borderRadius: BorderRadius.circular(\n                  windowData.isMaximized ? 0 : 12,\n                ),\n                child: Column(\n                  children: [\n                    GestureDetector(\n                      onPanUpdate: windowData.isMaximized\n                          ? null\n                          : (details) {\n                              onPositionChanged(\n                                windowData.position + details.delta,\n                              );\n                            },\n                      onDoubleTap: onMaximize,\n                      child: Container(\n                        height: 38,\n                        width: double.infinity,\n                        decoration: BoxDecoration(\n                          color: isDark\n                              ? Colors.black.withValues(alpha: 0.9)\n                              : Colors.white.withValues(alpha: 0.95),\n                          border: Border(\n                            bottom: BorderSide(\n                              color: onSurfaceColor.withValues(alpha: 0.05),\n                            ),\n                          ),\n                        ),\n                        child: Padding(\n                          padding: const EdgeInsets.symmetric(horizontal: 12.0),\n                          child: Row(\n                            children: [\n                              _WindowControl(\n                                color: Colors.redAccent,\n                                onTap: onClose,\n                                icon: Icons.close,\n                              ),\n                              const SizedBox(width: 8),\n                              _WindowControl(\n                                color: Colors.orangeAccent,\n                                onTap: onMinimize,\n                                icon: Icons.remove,\n                              ),\n                              const SizedBox(width: 8),\n                              _WindowControl(\n                                color: Colors.greenAccent,\n                                onTap: onMaximize,\n                                icon: windowData.isMaximized\n                                    ? Icons.close_fullscreen\n                                    : Icons.fullscreen,\n                              ),\n                              const SizedBox(width: 12),\n                              windowData.icon is IconData\n                                  ? Icon(\n                                      windowData.icon,\n                                      color: onSurfaceColor.withValues(\n                                        alpha: 0.7,\n                                      ),\n                                      size: 14,\n                                    )\n                                  : FaIcon(\n                                      windowData.icon,\n                                      color: onSurfaceColor.withValues(\n                                        alpha: 0.7,\n                                      ),\n                                      size: 12,\n                                    ),\n                              const SizedBox(width: 8),\n                              Text(\n                                windowData.title,\n                                style: GoogleFonts.inter(\n                                  color: onSurfaceColor.withValues(alpha: 0.9),\n                                  fontSize: 13,\n                                  fontWeight: FontWeight.w500,\n                                ),\n                              ),\n                              const Spacer(),\n                              const SizedBox(width: 60),\n                            ],\n                          ),\n                        ),\n                      ),\n                    ),\n                    Expanded(\n                      child: Container(\n                        color: surfaceColor.withValues(alpha: 0.9),\n                        child: windowData.content,\n                      ),\n                    ),\n                  ],\n                ),\n              ),\n            ),\n\n            if (!windowData.isMaximized) ...[\n\n              Positioned(\n                right: 0,\n                top: 0,\n                bottom: 15,\n                width: 6,\n                child: MouseRegion(\n                  cursor: SystemMouseCursors.resizeLeftRight,\n                  child: GestureDetector(\n                    onPanUpdate: (details) {\n                      onSizeChanged(\n                        Size(\n                          (windowData.size.width + details.delta.dx).clamp(\n                            300.0,\n                            1200.0,\n                          ),\n                          windowData.size.height,\n                        ),\n                      );\n                    },\n                  ),\n                ),\n              ),\n\n              Positioned(\n                left: 0,\n                top: 0,\n                bottom: 15,\n                width: 6,\n                child: MouseRegion(\n                  cursor: SystemMouseCursors.resizeLeftRight,\n                  child: GestureDetector(\n                    onPanUpdate: (details) {\n                      final newWidth =\n                          (windowData.size.width - details.delta.dx).clamp(\n                            300.0,\n                            1200.0,\n                          );\n                      if (newWidth != windowData.size.width) {\n                        onSizeChanged(Size(newWidth, windowData.size.height));\n                        onPositionChanged(\n                          windowData.position + Offset(details.delta.dx, 0),\n                        );\n                      }\n                    },\n                  ),\n                ),\n              ),\n\n              Positioned(\n                bottom: 0,\n                left: 0,\n                right: 15,\n                height: 6,\n                child: MouseRegion(\n                  cursor: SystemMouseCursors.resizeUpDown,\n                  child: GestureDetector(\n                    onPanUpdate: (details) {\n                      onSizeChanged(\n                        Size(\n                          windowData.size.width,\n                          (windowData.size.height + details.delta.dy).clamp(\n                            200.0,\n                            800.0,\n                          ),\n                        ),\n                      );\n                    },\n                  ),\n                ),\n              ),\n\n              Positioned(\n                top: 0,\n                left: 0,\n                right: 0,\n                height: 6,\n                child: MouseRegion(\n                  cursor: SystemMouseCursors.resizeUpDown,\n                  child: GestureDetector(\n                    onPanUpdate: (details) {\n                      final newHeight =\n                          (windowData.size.height - details.delta.dy).clamp(\n                            200.0,\n                            800.0,\n                          );\n                      if (newHeight != windowData.size.height) {\n                        onSizeChanged(Size(windowData.size.width, newHeight));\n                        onPositionChanged(\n                          windowData.position + Offset(0, details.delta.dy),\n                        );\n                      }\n                    },\n                  ),\n                ),\n              ),\n\n              Positioned(\n                right: 0,\n                bottom: 0,\n                width: 15,\n                height: 15,\n                child: MouseRegion(\n                  cursor: SystemMouseCursors.resizeUpLeftDownRight,\n                  child: GestureDetector(\n                    onPanUpdate: (details) {\n                      onSizeChanged(\n                        Size(\n                          (windowData.size.width + details.delta.dx).clamp(\n                            300.0,\n                            1200.0,\n                          ),\n                          (windowData.size.height + details.delta.dy).clamp(\n                            200.0,\n                            800.0,\n                          ),\n                        ),\n                      );\n                    },\n                    child: Container(\n                      color: Colors.transparent,\n                      child: const Icon(\n                        Icons.drag_handle,\n                        size: 12,\n                        color: Colors.white24,\n                      ),\n                    ),\n                  ),\n                ),\n              ),\n            ],\n          ],\n        ),\n      ),\n    );\n\n    if (windowData.isMaximized) {\n      return Positioned(\n        left: 0,\n        top: 35,\n        right: 0,\n        bottom: 0,\n        child: windowContent,\n      );\n    }\n\n    return Positioned(\n      left: windowData.position.dx,\n      top: windowData.position.dy,\n      child: windowContent,\n    );\n  }\n}\n\nclass _WindowControl extends StatefulWidget {\n  final Color color;\n  final VoidCallback onTap;\n  final IconData icon;\n\n  const _WindowControl({\n    required this.color,\n    required this.onTap,\n    required this.icon,\n  });\n\n  @override\n  State<_WindowControl> createState() => _WindowControlState();\n}\n\nclass _WindowControlState extends State<_WindowControl> {\n  bool _isHovered = false;\n\n  @override\n  Widget build(BuildContext context) {\n    return MouseRegion(\n      onEnter: (_) => setState(() => _isHovered = true),\n      onExit: (_) => setState(() => _isHovered = false),\n      child: GestureDetector(\n        onTap: widget.onTap,\n        child: Container(\n          width: 12,\n          height: 12,\n          decoration: BoxDecoration(\n            color: widget.color,\n            shape: BoxShape.circle,\n          ),\n          child: _isHovered\n              ? Center(child: Icon(widget.icon, size: 8, color: Colors.black54))\n              : null,\n        ),\n      ),\n    );\n  }\n}",
  "lib/top_bar.dart": "import 'package:flutter/material.dart';\nimport 'package:glass_kit/glass_kit.dart';\nimport 'package:intl/intl.dart';\nimport 'package:google_fonts/google_fonts.dart';\nimport 'package:provider/provider.dart';\nimport 'system_settings.dart';\n\nclass TopBar extends StatelessWidget {\n  final VoidCallback onMenuTap;\n  final VoidCallback onQuickSettingsTap;\n\n  const TopBar({\n    super.key,\n    required this.onMenuTap,\n    required this.onQuickSettingsTap,\n  });\n\n  @override\n  Widget build(BuildContext context) {\n    final settings = context.watch<SystemSettings>();\n    final isDark = Theme.of(context).brightness == Brightness.dark;\n    final onSurfaceColor = Theme.of(context).colorScheme.onSurface;\n\n    final timePattern = settings.use24HourClock\n        ? (settings.showClockSeconds ? 'HH:mm:ss' : 'HH:mm')\n        : (settings.showClockSeconds ? 'h:mm:ss a' : 'h:mm a');\n    final dateFormatPattern = 'EEE MMM d  \$timePattern';\n\n    return GlassContainer.clearGlass(\n      height: 32,\n      width: double.infinity,\n      borderWidth: 0,\n      blur: 20,\n      color: isDark\n          ? Colors.black.withValues(alpha: 0.3)\n          : Colors.white.withValues(alpha: 0.3),\n      borderColor: Colors.transparent,\n      child: Padding(\n        padding: const EdgeInsets.symmetric(horizontal: 16.0),\n        child: Row(\n          children: [\n            GestureDetector(\n              onTap: onMenuTap,\n              child: Icon(Icons.menu, color: onSurfaceColor, size: 18),\n            ),\n            const Spacer(),\n            GestureDetector(\n              onTap: onQuickSettingsTap,\n              child: Row(\n                children: [\n                  Icon(\n                    settings.wifi ? Icons.wifi : Icons.wifi_off,\n                    color: settings.wifi\n                        ? onSurfaceColor\n                        : onSurfaceColor.withValues(alpha: 0.4),\n                    size: 16,\n                  ),\n                  if (settings.bluetooth) ...[\n                    const SizedBox(width: 12),\n                    Icon(\n                      Icons.bluetooth,\n                      color: settings.accentColor,\n                      size: 16,\n                    ),\n                  ],\n                  const SizedBox(width: 12),\n                  Icon(\n                    settings.soundVolume == 0\n                        ? Icons.volume_off\n                        : (settings.soundVolume < 0.5\n                              ? Icons.volume_down\n                              : Icons.volume_up),\n                    color: onSurfaceColor,\n                    size: 16,\n                  ),\n                  const SizedBox(width: 12),\n                  Icon(Icons.battery_full, color: onSurfaceColor, size: 16),\n                  const SizedBox(width: 12),\n                  Icon(Icons.tune, color: onSurfaceColor, size: 16),\n                ],\n              ),\n            ),\n            const SizedBox(width: 16),\n            GestureDetector(\n              onTap: onQuickSettingsTap,\n              child: StreamBuilder(\n                stream: Stream.periodic(const Duration(seconds: 1)),\n                builder: (context, snapshot) {\n                  return Text(\n                    DateFormat(dateFormatPattern).format(DateTime.now()),\n                    style: GoogleFonts.inter(\n                      color: onSurfaceColor,\n                      fontWeight: FontWeight.w500,\n                      fontSize: 13,\n                    ),\n                  );\n                },\n              ),\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n}",
  "lib/system_settings.dart": "import 'dart:convert';\nimport 'dart:typed_data';\nimport 'package:flutter/material.dart';\nimport 'package:shared_preferences/shared_preferences.dart';\nimport 'services/wallpaper_storage/wallpaper_storage.dart';\n\nclass SystemSettings extends ChangeNotifier {\n  SharedPreferences? _prefs;\n  bool _isInitialized = false;\n  final WallpaperStorageService _storageService = WallpaperStorageService();\n\n  bool _isDarkMode = true;\n  Color _accentColor = const Color(0xFF9C27B0);\n  String _wallpaperPath = 'assets/wallpaper.jpg';\n  Uint8List? _wallpaperBytes;\n  bool _isCustomWallpaper = false;\n  double _wallpaperBlur = 0.0;\n  double _wallpaperDim = 0.0;\n\n  bool _dockAutoHide = false;\n  double _dockScale = 1.0;\n\n  bool _use24HourClock = false;\n  bool _showClockSeconds = false;\n\n  double _soundVolume = 0.8;\n  bool _soundEffectsEnabled = true;\n  bool _enableGlassEffects = true;\n\n  double _screenBrightness = 1.0;\n  bool _nightShift = false;\n  bool _wifi = true;\n  bool _bluetooth = false;\n\n  bool get isInitialized => _isInitialized;\n  bool get isDarkMode => _isDarkMode;\n  Color get accentColor => _accentColor;\n  String get wallpaperPath => _wallpaperPath;\n  Uint8List? get wallpaperBytes => _wallpaperBytes;\n  bool get isCustomWallpaper => _isCustomWallpaper;\n  double get wallpaperBlur => _wallpaperBlur;\n  double get wallpaperDim => _wallpaperDim;\n  bool get dockAutoHide => _dockAutoHide;\n  double get dockScale => _dockScale;\n  bool get use24HourClock => _use24HourClock;\n  bool get showClockSeconds => _showClockSeconds;\n  double get soundVolume => _soundVolume;\n  bool get soundEffectsEnabled => _soundEffectsEnabled;\n  bool get enableGlassEffects => _enableGlassEffects;\n  double get screenBrightness => _screenBrightness;\n  bool get nightShift => _nightShift;\n  bool get wifi => _wifi;\n  bool get bluetooth => _bluetooth;\n\n  SystemSettings() {\n    init();\n  }\n\n  Future<void> init() async {\n    if (_isInitialized) return;\n    try {\n      _prefs = await SharedPreferences.getInstance();\n      final p = _prefs;\n      if (p != null) {\n        _isDarkMode = p.getBool('isDarkMode') ?? true;\n        _accentColor = Color(p.getInt('accentColor') ?? 0xFF9C27B0);\n        _wallpaperPath = p.getString('wallpaperPath') ?? 'assets/wallpaper.jpg';\n        _isCustomWallpaper = p.getBool('isCustomWallpaper') ?? false;\n        _wallpaperBlur = p.getDouble('wallpaperBlur') ?? 0.0;\n        _wallpaperDim = p.getDouble('wallpaperDim') ?? 0.0;\n        _dockAutoHide = p.getBool('dockAutoHide') ?? false;\n        _dockScale = p.getDouble('dockScale') ?? 1.0;\n        _use24HourClock = p.getBool('use24HourClock') ?? false;\n        _showClockSeconds = p.getBool('showClockSeconds') ?? false;\n        _soundVolume = p.getDouble('soundVolume') ?? 0.8;\n        _soundEffectsEnabled = p.getBool('soundEffectsEnabled') ?? true;\n        _enableGlassEffects = p.getBool('enableGlassEffects') ?? true;\n        _screenBrightness = p.getDouble('screenBrightness') ?? 1.0;\n        _nightShift = p.getBool('nightShift') ?? false;\n        _wifi = p.getBool('wifi') ?? true;\n        _bluetooth = p.getBool('bluetooth') ?? false;\n      }\n\n      if (_isCustomWallpaper ||\n          _wallpaperPath == 'custom' ||\n          _wallpaperPath.startsWith('data:image')) {\n        final customData = await _storageService.loadWallpaper();\n        if (customData != null && customData.isNotEmpty) {\n          _wallpaperPath = 'custom';\n          _isCustomWallpaper = true;\n          _decodeWallpaper(customData);\n        } else if (_wallpaperPath.startsWith('data:image')) {\n          _decodeWallpaper(_wallpaperPath);\n        }\n      }\n    } catch (e) {\n      debugPrint('Error loading SystemSettings: \$e');\n    }\n    _isInitialized = true;\n    notifyListeners();\n  }\n\n  void _decodeWallpaper(String path) {\n    try {\n      final base64Part = path.contains(',') ? path.split(',').last : path;\n      _wallpaperBytes = base64Decode(base64Part);\n    } catch (e) {\n      _wallpaperBytes = null;\n      debugPrint('Failed to decode wallpaper: \$e');\n    }\n  }\n\n  void setDarkMode(bool value) {\n    _isDarkMode = value;\n    _prefs?.setBool('isDarkMode', value);\n    notifyListeners();\n  }\n\n  void setAccentColor(Color color) {\n    _accentColor = color;\n    _prefs?.setInt('accentColor', color.toARGB32());\n    notifyListeners();\n  }\n\n  Future<void> setWallpaper(String path) async {\n    if (path.startsWith('data:image')) {\n      await setCustomWallpaperFromDataUrl(path);\n      return;\n    }\n\n    _wallpaperPath = path;\n    _wallpaperBytes = null;\n    _isCustomWallpaper = false;\n    _prefs?.setString('wallpaperPath', path);\n    _prefs?.setBool('isCustomWallpaper', false);\n    _storageService.clearWallpaper();\n    notifyListeners();\n  }\n\n  Future<void> setCustomWallpaperFromDataUrl(String rawDataUrl) async {\n    try {\n\n      final compressed = await _storageService.compressImage(\n        rawDataUrl,\n        maxDim: 1920,\n        quality: 0.85,\n      );\n\n      _decodeWallpaper(compressed);\n      _wallpaperPath = 'custom';\n      _isCustomWallpaper = true;\n\n      await _storageService.saveWallpaper(compressed);\n\n      _prefs?.setString('wallpaperPath', 'custom');\n      _prefs?.setBool('isCustomWallpaper', true);\n\n      if (compressed.length < 1000000) {\n        _prefs?.setString('cachedWallpaperData', compressed);\n      } else {\n        _prefs?.remove('cachedWallpaperData');\n      }\n\n      notifyListeners();\n    } catch (e) {\n      debugPrint('Error saving custom wallpaper: \$e');\n    }\n  }\n\n  Future<void> setCustomWallpaperFromBytes(\n    Uint8List bytes, {\n    String mimeType = 'image/png',\n  }) async {\n    final base64String = 'data:\$mimeType;base64,\${base64Encode(bytes)}';\n    await setCustomWallpaperFromDataUrl(base64String);\n  }\n\n  Future<void> resetWallpaper() async {\n    _wallpaperPath = 'assets/wallpaper.jpg';\n    _wallpaperBytes = null;\n    _isCustomWallpaper = false;\n    _wallpaperBlur = 0.0;\n    _wallpaperDim = 0.0;\n    _prefs?.setString('wallpaperPath', _wallpaperPath);\n    _prefs?.setBool('isCustomWallpaper', false);\n    _prefs?.remove('cachedWallpaperData');\n    _prefs?.setDouble('wallpaperBlur', 0.0);\n    _prefs?.setDouble('wallpaperDim', 0.0);\n    await _storageService.clearWallpaper();\n    notifyListeners();\n  }\n\n  void setWallpaperBlur(double value) {\n    _wallpaperBlur = value.clamp(0.0, 20.0);\n    _prefs?.setDouble('wallpaperBlur', _wallpaperBlur);\n    notifyListeners();\n  }\n\n  void setWallpaperDim(double value) {\n    _wallpaperDim = value.clamp(0.0, 0.7);\n    _prefs?.setDouble('wallpaperDim', _wallpaperDim);\n    notifyListeners();\n  }\n\n  void setDockAutoHide(bool value) {\n    _dockAutoHide = value;\n    _prefs?.setBool('dockAutoHide', value);\n    notifyListeners();\n  }\n\n  void setDockScale(double value) {\n    _dockScale = value.clamp(0.8, 1.3);\n    _prefs?.setDouble('dockScale', _dockScale);\n    notifyListeners();\n  }\n\n  void setUse24HourClock(bool value) {\n    _use24HourClock = value;\n    _prefs?.setBool('use24HourClock', value);\n    notifyListeners();\n  }\n\n  void setShowClockSeconds(bool value) {\n    _showClockSeconds = value;\n    _prefs?.setBool('showClockSeconds', value);\n    notifyListeners();\n  }\n\n  void setSoundVolume(double value) {\n    _soundVolume = value.clamp(0.0, 1.0);\n    _prefs?.setDouble('soundVolume', _soundVolume);\n    notifyListeners();\n  }\n\n  void setSoundEffectsEnabled(bool value) {\n    _soundEffectsEnabled = value;\n    _prefs?.setBool('soundEffectsEnabled', value);\n    notifyListeners();\n  }\n\n  void setEnableGlassEffects(bool value) {\n    _enableGlassEffects = value;\n    _prefs?.setBool('enableGlassEffects', value);\n    notifyListeners();\n  }\n\n  void setScreenBrightness(double value) {\n    _screenBrightness = value.clamp(0.3, 1.0);\n    _prefs?.setDouble('screenBrightness', _screenBrightness);\n    notifyListeners();\n  }\n\n  void setNightShift(bool value) {\n    _nightShift = value;\n    _prefs?.setBool('nightShift', value);\n    notifyListeners();\n  }\n\n  void setWifi(bool value) {\n    _wifi = value;\n    _prefs?.setBool('wifi', value);\n    notifyListeners();\n  }\n\n  void setBluetooth(bool value) {\n    _bluetooth = value;\n    _prefs?.setBool('bluetooth', value);\n    notifyListeners();\n  }\n\n  Future<void> resetAllSettings() async {\n    _isDarkMode = true;\n    _accentColor = const Color(0xFF9C27B0);\n    _wallpaperPath = 'assets/wallpaper.jpg';\n    _wallpaperBytes = null;\n    _isCustomWallpaper = false;\n    _wallpaperBlur = 0.0;\n    _wallpaperDim = 0.0;\n    _dockAutoHide = false;\n    _dockScale = 1.0;\n    _use24HourClock = false;\n    _showClockSeconds = false;\n    _soundVolume = 0.8;\n    _soundEffectsEnabled = true;\n    _enableGlassEffects = true;\n    _screenBrightness = 1.0;\n    _nightShift = false;\n    _wifi = true;\n    _bluetooth = false;\n\n    await _prefs?.clear();\n    await _storageService.clearWallpaper();\n    notifyListeners();\n  }\n}",
  "lib/dock.dart": "import 'package:flutter/material.dart';\nimport 'package:font_awesome_flutter/font_awesome_flutter.dart';\nimport 'app_data.dart';\nimport 'package:provider/provider.dart';\nimport 'models/config_model.dart';\nimport 'system_settings.dart';\nimport 'dart:ui';\n\nclass Dock extends StatelessWidget {\n  final Function(String, String, Widget?, dynamic, {String? url}) onOpenApp;\n\n  const Dock({super.key, required this.onOpenApp});\n\n  @override\n  Widget build(BuildContext context) {\n    final isDark = Theme.of(context).brightness == Brightness.dark;\n    final settings = context.watch<SystemSettings>();\n    final config = context.watch<AppConfig>();\n    final apps = getApps(config);\n    final screenWidth = MediaQuery.of(context).size.width;\n\n    const baseItemWidth = 56.0;\n    const baseDockPadding = 18.0;\n    final maxDockWidth = (screenWidth - 32.0).clamp(240.0, double.infinity);\n    final idealContentWidth = (apps.length * baseItemWidth) + baseDockPadding;\n\n    final autoScale = (maxDockWidth / idealContentWidth).clamp(0.40, 1.0);\n    final effectiveScale = autoScale * settings.dockScale;\n\n    final dockHeight = (70.0 * effectiveScale).clamp(38.0, 95.0);\n    final dockBorderRadius = (20.0 * effectiveScale).clamp(10.0, 24.0);\n    final dockHorizontalPadding = (9.0 * effectiveScale).clamp(4.0, 14.0);\n\n    return Center(\n      child: ClipRRect(\n        borderRadius: BorderRadius.circular(dockBorderRadius),\n        child: BackdropFilter(\n          filter: ImageFilter.blur(sigmaX: 25, sigmaY: 25),\n          child: Container(\n            height: dockHeight,\n            padding: EdgeInsets.symmetric(horizontal: dockHorizontalPadding),\n            decoration: BoxDecoration(\n              color: isDark\n                  ? Colors.white.withValues(alpha: 0.1)\n                  : Colors.black.withValues(alpha: 0.05),\n              borderRadius: BorderRadius.circular(dockBorderRadius),\n              border: Border.all(\n                color: isDark\n                    ? Colors.white.withValues(alpha: 0.2)\n                    : Colors.black.withValues(alpha: 0.1),\n              ),\n            ),\n            child: Row(\n              mainAxisSize: MainAxisSize.min,\n              mainAxisAlignment: MainAxisAlignment.center,\n              crossAxisAlignment: CrossAxisAlignment.center,\n              children: apps\n                  .map(\n                    (app) => _DockIcon(\n                      icon: app.icon,\n                      label: app.title,\n                      color: app.color,\n                      scale: effectiveScale,\n                      onTap: () => onOpenApp(\n                        app.id,\n                        app.title,\n                        app.content,\n                        app.icon,\n                        url: app.url,\n                      ),\n                    ),\n                  )\n                  .toList(),\n            ),\n          ),\n        ),\n      ),\n    );\n  }\n}\n\nclass _DockIcon extends StatefulWidget {\n  final dynamic icon;\n  final String label;\n  final Color color;\n  final VoidCallback onTap;\n  final double scale;\n\n  const _DockIcon({\n    required this.icon,\n    required this.label,\n    required this.color,\n    required this.onTap,\n    this.scale = 1.0,\n  });\n\n  @override\n  State<_DockIcon> createState() => _DockIconState();\n}\n\nclass _DockIconState extends State<_DockIcon> {\n  bool _isHovered = false;\n\n  @override\n  Widget build(BuildContext context) {\n    final s = widget.scale.clamp(0.40, 1.4);\n    final iconSize = (28.0 * s).clamp(13.0, 38.0);\n    final faIconSize = (26.0 * s).clamp(12.0, 36.0);\n    final containerPadding = (8.0 * s).clamp(3.0, 12.0);\n    final itemHorizontalPadding = (3.0 * s).clamp(1.0, 6.0);\n    final borderRadius = (12.0 * s).clamp(5.0, 16.0);\n\n    return Tooltip(\n      message: widget.label,\n      verticalOffset: -45 * s,\n      preferBelow: false,\n      child: MouseRegion(\n        onEnter: (_) => setState(() => _isHovered = true),\n        onExit: (_) => setState(() => _isHovered = false),\n        child: GestureDetector(\n          onTap: widget.onTap,\n          child: AnimatedContainer(\n            duration: const Duration(milliseconds: 180),\n            transform: Matrix4.diagonal3Values(\n              _isHovered ? 1.18 : 1.0,\n              _isHovered ? 1.18 : 1.0,\n              1.0,\n            ),\n            padding: EdgeInsets.symmetric(\n              horizontal: itemHorizontalPadding,\n              vertical: 2.0,\n            ),\n            child: Column(\n              mainAxisSize: MainAxisSize.min,\n              mainAxisAlignment: MainAxisAlignment.center,\n              children: [\n                Container(\n                  padding: EdgeInsets.all(containerPadding),\n                  decoration: BoxDecoration(\n                    color: widget.color.withValues(alpha: 0.85),\n                    borderRadius: BorderRadius.circular(borderRadius),\n                    boxShadow: [\n                      if (_isHovered)\n                        BoxShadow(\n                          color: Theme.of(\n                            context,\n                          ).colorScheme.primary.withValues(alpha: 0.5),\n                          blurRadius: 10 * s,\n                          spreadRadius: 2 * s,\n                        ),\n                    ],\n                  ),\n                  child: widget.icon is IconData\n                      ? Icon(widget.icon, color: Colors.white, size: iconSize)\n                      : FaIcon(\n                          widget.icon,\n                          color: Colors.white,\n                          size: faIconSize,\n                        ),\n                ),\n                if (_isHovered && s > 0.75) SizedBox(height: 2 * s),\n              ],\n            ),\n          ),\n        ),\n      ),\n    );\n  }\n}",
  "lib/apps/grand_theft_ant/game/world.dart": "import 'dart:math' as math;\nimport 'package:flutter/material.dart';\nimport 'macro_cache.dart';\nimport 'models.dart';\nimport 'sound.dart';\n\nclass RayHit {\n  final double distance;\n  final int wallType;\n  final bool hitVertical;\n  final double wallX;\n  final int mapX;\n  final int mapY;\n\n  const RayHit({\n    required this.distance,\n    required this.wallType,\n    required this.hitVertical,\n    required this.wallX,\n    required this.mapX,\n    required this.mapY,\n  });\n}\n\nclass CyberWorld {\n  static const int mapWidth = 112;\n  static const int mapHeight = 112;\n\n  late List<List<int>> grid;\n  final math.Random rng = math.Random(1859);\n  final CyberSound sound = CyberSound();\n  final MacroVisualsCache visualsCache = MacroVisualsCache();\n\n  Vec2 playerPos = const Vec2(56.0, 92.0);\n  double playerAngle = -math.pi / 2;\n  double bodyYaw = -math.pi / 2;\n  double playerPitch = 0.08;\n  double playerZ = 0.0;\n  double playerVz = 0.0;\n  double walkBobPhase = 0.0;\n  double walkBobIntensity = 0.0;\n  double mandiblePinchAnim = 0.0;\n\n  Vec2 cameraPos = const Vec2(56.0, 93.2);\n  double cameraZ = 0.22;\n  double cameraOrbitDist = 1.15;\n\n  double stamina = 100.0;\n  double maxStamina = 100.0;\n  double hydration = 100.0;\n  double maxHydration = 100.0;\n\n  BugVehicleType? mountedVehicle;\n  double mountedHealth = 100.0;\n  double mountedMaxHealth = 100.0;\n  int bugsRiddenCount = 0;\n  int bugsDefeatedCount = 0;\n  int forageCollected = 0;\n  int score = 0;\n\n  double dashCooldown = 0.0;\n  static const double maxDashCooldown = 0.45;\n  double dashActiveTimer = 0.0;\n  double attackAnim = 0.0;\n  double screenShake = 0.0;\n\n  final List<GrassStalk3D> grassStalks = [];\n  final List<MountableBug> mountableBugs = [];\n  final List<NpcAnt> npcAnts = [];\n  final List<RealLifeProp3D> realLifeProps = [];\n  final List<ForageItem> forageItems = [];\n  final List<NatureParticle3D> particles = [];\n  final List<FloatingNote3D> floatingNotes = [];\n  final List<FieldLogEntry> fieldLog = [];\n\n  Mission? activeMission;\n\n  int _nextEntityId = 1;\n  double totalTime = 0.0;\n  double _pollenSpawnTimer = 0.0;\n\n  bool denseFoliage;\n\n  CyberWorld({this.denseFoliage = false}) {\n    resetGame();\n  }\n\n  void setDenseFoliage(bool enabled) {\n    if (denseFoliage == enabled) return;\n    denseFoliage = enabled;\n    _spawnCityOfGrass();\n  }\n\n  BugVehicleSpec? get currentVehicleSpec =>\n      mountedVehicle != null ? BugVehicleSpec.of(mountedVehicle!) : null;\n\n  String get currentBiomeName {\n    if (playerPos.y >= 74) {\n      return 'Emerald Blade Avenue • Anthill Outpost';\n    } else if (playerPos.y < 32) {\n      return 'Dandelion Crown District';\n    } else if (playerPos.x < 48) {\n      return 'Clover Canopy Plaza';\n    } else if (playerPos.x > 72) {\n      return 'Tall Fescue Cathedral';\n    } else {\n      return 'Meadow Crossroads & Relic Glade';\n    }\n  }\n\n  void _generateOpenWorldMap() {\n    grid = List.generate(mapHeight, (_) => List<int>.filled(mapWidth, 0));\n\n    for (int x = 0; x < mapWidth; x++) {\n      grid[0][x] = 1;\n      grid[mapHeight - 1][x] = 1;\n    }\n    for (int y = 0; y < mapHeight; y++) {\n      grid[y][0] = 1;\n      grid[y][mapWidth - 1] = 1;\n    }\n  }\n\n  void _spawnCityOfGrass() {\n    grassStalks.clear();\n\n    const palettes = <(Color, Color, Color)>[\n\n      (Color(0xFF1B3B14), Color(0xFF3E7526), Color(0xFF9AC94B)),\n\n      (Color(0xFF163322), Color(0xFF356B43), Color(0xFF8BB858)),\n\n      (Color(0xFF244216), Color(0xFF52872E), Color(0xFFC4D65A)),\n\n      (Color(0xFF142B10), Color(0xFF2F5E21), Color(0xFF7FA83D)),\n    ];\n\n    final yStep = denseFoliage ? 1.4 : 4.2;\n    final lanes = denseFoliage\n        ? const [\n            8.0, 14.0, 20.0, 26.0, 32.0, 38.0, 44.0, 50.8,\n            61.2, 68.0, 74.0, 80.0, 86.0, 92.0, 98.0, 104.0,\n          ]\n        : const [14.0, 26.0, 38.0, 50.8, 61.2, 74.0, 86.0, 98.0];\n\n    final spawnOutpost = const Vec2(56.0, 92.0);\n\n    for (double y = 6.0; y <= 106.0; y += yStep) {\n      for (final laneX in lanes) {\n        final jitterX = (rng.nextDouble() - 0.5) * (denseFoliage ? 1.4 : 1.5);\n        final jitterY = (rng.nextDouble() - 0.5) * (denseFoliage ? 1.4 : 1.5);\n        final pos = Vec2(laneX + jitterX, y + jitterY);\n\n        if (pos.distanceTo(spawnOutpost) < 2.2) continue;\n        if (pos.distanceTo(const Vec2(28.0, 46.0)) < 2.0) continue;\n\n        final pal = palettes[rng.nextInt(palettes.length)];\n\n        final archTowardCenter = (laneX < 56.0)\n            ? (rng.nextDouble() - 0.3) * 0.9\n            : math.pi + (rng.nextDouble() - 0.7) * 0.9;\n\n        final heightRoll = rng.nextDouble();\n        double stalkHeight;\n        double stalkBaseWidth;\n        double archReach;\n        int subBlades;\n        GrassCrownType crown;\n\n        if (heightRoll < 0.32) {\n\n          stalkHeight = 0.45 + rng.nextDouble() * 0.60;\n          stalkBaseWidth = (denseFoliage ? 0.18 : 0.14) + rng.nextDouble() * 0.08;\n          archReach = 0.38 + rng.nextDouble() * 0.45;\n          subBlades = denseFoliage ? (6 + rng.nextInt(4)) : (4 + rng.nextInt(2));\n          crown = (rng.nextDouble() < 0.45)\n              ? GrassCrownType.cloverUmbrella\n              : GrassCrownType.archingBlade;\n        } else if (heightRoll < 0.68) {\n\n          stalkHeight = 1.10 + rng.nextDouble() * 1.0;\n          stalkBaseWidth = (denseFoliage ? 0.16 : 0.13) + rng.nextDouble() * 0.07;\n          archReach = 0.60 + rng.nextDouble() * 0.65;\n          subBlades = denseFoliage ? (6 + rng.nextInt(3)) : (3 + rng.nextInt(3));\n          crown = (rng.nextDouble() < 0.55)\n              ? GrassCrownType.seedPanicle\n              : GrassCrownType.dewdropBlade;\n        } else {\n\n          stalkHeight = 2.10 + rng.nextDouble() * (denseFoliage ? 2.4 : 2.0);\n          stalkBaseWidth = (denseFoliage ? 0.15 : 0.12) + rng.nextDouble() * 0.08;\n          archReach = (denseFoliage ? 0.85 : 0.65) + rng.nextDouble() * 1.05;\n          subBlades = denseFoliage ? (5 + rng.nextInt(3)) : (3 + rng.nextInt(3));\n          crown = (rng.nextDouble() < 0.5)\n              ? GrassCrownType.archingBlade\n              : GrassCrownType.dandelionTower;\n        }\n\n        grassStalks.add(GrassStalk3D(\n          pos: pos,\n          height: stalkHeight,\n          baseWidth: stalkBaseWidth,\n          archAngle: archTowardCenter,\n          archReach: archReach,\n          swayPhase: rng.nextDouble() * math.pi * 2,\n          baseColor: pal.\$1,\n          midColor: pal.\$2,\n          tipColor: pal.\$3,\n          crownType: crown,\n          subBlades: subBlades,\n        ));\n      }\n    }\n\n    final wildCount = denseFoliage ? 1500 : 180;\n    for (int i = 0; i < wildCount; i++) {\n      final pos = Vec2(\n        4.0 + rng.nextDouble() * (mapWidth - 8.0),\n        4.0 + rng.nextDouble() * (mapHeight - 8.0),\n      );\n      if (pos.distanceTo(spawnOutpost) < 2.2) continue;\n      if (pos.distanceTo(const Vec2(28.0, 46.0)) < 2.0) continue;\n\n      final pal = palettes[i % palettes.length];\n      final heightRoll = rng.nextDouble();\n      double stalkHeight;\n      double stalkBaseWidth;\n      double archReach;\n      int subBlades;\n\n      if (heightRoll < 0.38) {\n\n        stalkHeight = 0.40 + rng.nextDouble() * 0.60;\n        stalkBaseWidth = (denseFoliage ? 0.18 : 0.14) + rng.nextDouble() * 0.08;\n        archReach = 0.35 + rng.nextDouble() * 0.45;\n        subBlades = denseFoliage ? (6 + (i % 4)) : (3 + (i % 3));\n      } else if (heightRoll < 0.72) {\n\n        stalkHeight = 1.0 + rng.nextDouble() * 1.05;\n        stalkBaseWidth = (denseFoliage ? 0.15 : 0.12) + rng.nextDouble() * 0.07;\n        archReach = 0.55 + rng.nextDouble() * 0.65;\n        subBlades = denseFoliage ? (5 + (i % 4)) : (3 + (i % 3));\n      } else {\n\n        stalkHeight = 2.0 + rng.nextDouble() * 2.2;\n        stalkBaseWidth = (denseFoliage ? 0.14 : 0.11) + rng.nextDouble() * 0.08;\n        archReach = 0.75 + rng.nextDouble() * 0.95;\n        subBlades = denseFoliage ? (5 + (i % 3)) : (3 + (i % 3));\n      }\n\n      grassStalks.add(GrassStalk3D(\n        pos: pos,\n        height: stalkHeight,\n        baseWidth: stalkBaseWidth,\n        archAngle: rng.nextDouble() * math.pi * 2,\n        archReach: archReach,\n        swayPhase: rng.nextDouble() * math.pi * 2,\n        baseColor: pal.\$1,\n        midColor: pal.\$2,\n        tipColor: pal.\$3,\n        crownType: GrassCrownType.values[i % GrassCrownType.values.length],\n        subBlades: subBlades,\n      ));\n    }\n  }\n\n  void _spawnNpcAnts() {\n    npcAnts.clear();\n\n    npcAnts.add(NpcAnt(\n      id: _nextEntityId++,\n      name: 'Commander Khepri',\n      rank: 'Vanguard Commander',\n      title: \"Queen's Royal Scout\",\n      chitinColor: const Color(0xFF1E140C),\n      crestColor: const Color(0xFFE88A2D),\n      pos: const Vec2(56.0, 89.2),\n      angle: math.pi / 2,\n      missions: [\n        Mission(\n          id: 'khepri_1',\n          title: \"The Queen's Cavalry\",\n          description: 'Approach and mount any wild insect vehicle in the meadow.',\n          giverName: 'Commander Khepri',\n          type: MissionType.mountBug,\n          targetCount: 1,\n          scoreReward: 400,\n          introDialogue:\n              'Salute, sister! The Queen needs mounted riders to scout our expanding borders. Approach one of the great insect beasts of the meadow and mount it!',\n          inProgressDialogue:\n              'Walk close to any beetle, grasshopper, or hornet, and press MOUNT to take the reins.',\n          completionDialogue:\n              'Superb horsemanship! The colony sings praises of your mastery over the beasts. Here is your commendation!',\n        ),\n        Mission(\n          id: 'khepri_2',\n          title: 'Relic of the Giants',\n          description: 'Locate the massive Weathered Copper Penny resting near the southern trail.',\n          giverName: 'Commander Khepri',\n          type: MissionType.reachLocation,\n          targetLocation: const Vec2(53.0, 84.0),\n          targetRadius: 4.8,\n          targetLocationName: 'Weathered Copper Penny (1989)',\n          targetCount: 1,\n          scoreReward: 550,\n          introDialogue:\n              'Scouts report a colossal copper monolith dropped by human giants near our southern trail. Scout the landmark and verify its coordinates!',\n          inProgressDialogue:\n              'Head slightly northwest into the avenue to find the giant Weathered Copper Penny.',\n          completionDialogue:\n              'You found the giant disc! Our cartographers have marked the monument. Excellent work, rider!',\n        ),\n        Mission(\n          id: 'khepri_3',\n          title: 'Subdue the Wolf Spider',\n          description: 'Defeat a Giant Wolf Spider in combat to protect the anthill trails.',\n          giverName: 'Commander Khepri',\n          type: MissionType.defeatBug,\n          targetBug: BugVehicleType.wolfSpider,\n          targetCount: 1,\n          scoreReward: 850,\n          introDialogue:\n              'An 8-legged demon prowls the tall grass near our nursery trails! Mount a heavy beetle or strike with venom to drive back a Giant Wolf Spider!',\n          inProgressDialogue:\n              'Look for the dark chevrons of a Wolf Spider in the grass. Strike it until it retreats!',\n          completionDialogue:\n              'The spider is driven off! The Queen decorates you as Champion of the Anthill Mound!',\n        ),\n      ],\n    ));\n\n    npcAnts.add(NpcAnt(\n      id: _nextEntityId++,\n      name: 'Forager Rust',\n      rank: 'Harvest Overseer',\n      title: 'Master of Provisions',\n      chitinColor: const Color(0xFF382312),\n      crestColor: const Color(0xFFC9A23E),\n      pos: const Vec2(36.0, 74.0),\n      angle: 0.0,\n      missions: [\n        Mission(\n          id: 'rust_1',\n          title: 'Sweet Dew Harvest',\n          description: 'Forage 3 Morning Dewdrops or Golden Honeydews from the grass floor.',\n          giverName: 'Forager Rust',\n          type: MissionType.forageItem,\n          targetCount: 3,\n          scoreReward: 450,\n          introDialogue:\n              'Greetings, sister! The nursery pupae are parched, and our aphid partners need supplies. Venture under the dew-laden blades and gather 3 sweet forage items!',\n          inProgressDialogue:\n              'Scan the dirt floor for shimmering blue dewdrops or amber honeydew nectar droplets.',\n          completionDialogue:\n              'Glorious harvest! The nursery chambers will feast tonight thanks to your tireless foraging!',\n        ),\n        Mission(\n          id: 'rust_2',\n          title: 'Winter Granary',\n          description: 'Collect 2 dense Pine Nut Seeds or Bramble Berries for the winter stores.',\n          giverName: 'Forager Rust',\n          type: MissionType.forageItem,\n          targetCount: 2,\n          scoreReward: 600,\n          introDialogue:\n              'The nursery is refreshed, but cold winds will come. We need dense sustenance for the deep granary. Forage 2 seeds or berries!',\n          inProgressDialogue:\n              'Search the soil beneath the taller stalks for pine nut seeds and wild berries.',\n          completionDialogue:\n              'Magnificent! The winter granary swells with rich seed oil. Take your share of the colony nectar!',\n        ),\n      ],\n    ));\n\n    npcAnts.add(NpcAnt(\n      id: _nextEntityId++,\n      name: 'Warrior Thrak',\n      rank: 'Mandible Major',\n      title: 'Frontline Veteran',\n      chitinColor: const Color(0xFF19120F),\n      crestColor: const Color(0xFFD43828),\n      pos: const Vec2(80.0, 68.0),\n      angle: math.pi,\n      missions: [\n        Mission(\n          id: 'thrak_1',\n          title: 'Canopy Leap',\n          description: 'Mount a Meadow Grasshopper and launch high into the grass canopy.',\n          giverName: 'Warrior Thrak',\n          type: MissionType.leapAction,\n          targetCount: 1,\n          scoreReward: 500,\n          introDialogue:\n              'You think you have strong legs? Mount a Meadow Grasshopper and launch a massive canopy leap into the sky! Feel the wind across your antennae!',\n          inProgressDialogue:\n              'Find a green Meadow Grasshopper, mount it, and press LEAP while on the ground.',\n          completionDialogue:\n              'Hah! What a leap! You touched the very tips of the fescue blades. You have the heart of a true warrior!',\n        ),\n        Mission(\n          id: 'thrak_2',\n          title: 'Ruler of the Skies',\n          description: 'Mount a European Hornet and soar through the 3D meadow canopy.',\n          giverName: 'Warrior Thrak',\n          type: MissionType.mountBug,\n          targetBug: BugVehicleType.hornet,\n          targetCount: 1,\n          scoreReward: 750,\n          introDialogue:\n              'The dirt floor is for grubs; the true arena is the open sky! Tame an aerial European Hornet and conquer the third dimension!',\n          inProgressDialogue:\n              'Look above the fescue avenues for the buzzing yellow wings of a European Hornet.',\n          completionDialogue:\n              'Incredible! You rode the striped terror of the skies! Even the Wolf Spiders cower beneath your shadow!',\n        ),\n      ],\n    ));\n\n    npcAnts.add(NpcAnt(\n      id: _nextEntityId++,\n      name: 'Elder Atta',\n      rank: 'Royal Sage',\n      title: 'Keeper of the Lore',\n      chitinColor: const Color(0xFF332014),\n      crestColor: const Color(0xFFE5C07B),\n      pos: const Vec2(56.0, 32.0),\n      angle: math.pi / 2,\n      missions: [\n        Mission(\n          id: 'atta_1',\n          title: 'Northern Expanse',\n          description: 'Journey north to the sunny Dandelion Crown District.',\n          giverName: 'Elder Atta',\n          type: MissionType.reachLocation,\n          targetLocation: const Vec2(56.0, 16.0),\n          targetRadius: 6.0,\n          targetLocationName: 'Dandelion Crown District',\n          targetCount: 1,\n          scoreReward: 650,\n          introDialogue:\n              'Few workers ever venture beyond the dark fescue shadows into the north. Journey north to the Dandelion Crown District and gaze upon the sunlit yellow blooms!',\n          inProgressDialogue:\n              'Keep traveling north past the rainwater puddle toward the horizon haze.',\n          completionDialogue:\n              'You have walked the high golden plateaus! The colony records your journey in the sacred annals of Formica.',\n        ),\n        Mission(\n          id: 'atta_2',\n          title: 'The Brass Shed Key',\n          description: 'Locate the ancient Tarnished Brass Shed Key monolith in the northeast.',\n          giverName: 'Elder Atta',\n          type: MissionType.reachLocation,\n          targetLocation: const Vec2(74.0, 36.0),\n          targetRadius: 5.0,\n          targetLocationName: 'Tarnished Brass Shed Key',\n          targetCount: 1,\n          scoreReward: 800,\n          introDialogue:\n              'Legend speaks of a bronze monument carved with cryptic geometric teeth—the Shed Key. Seek out this mythical human relic in the northeast fescue groves!',\n          inProgressDialogue:\n              'Scout northeast of the crossroads into the tall grass to find the golden metal key.',\n          completionDialogue:\n              'The ancient Key of the Giants! You have recovered one of the greatest relics in insect history! All hail the Master Explorer!',\n        ),\n      ],\n    ));\n  }\n\n  void resetGame() {\n    _generateOpenWorldMap();\n\n    playerPos = const Vec2(56.0, 92.0);\n    playerAngle = -math.pi / 2;\n    bodyYaw = -math.pi / 2;\n    playerPitch = 0.08;\n    playerZ = 0.0;\n    playerVz = 0.0;\n    walkBobPhase = 0.0;\n    walkBobIntensity = 0.0;\n    mandiblePinchAnim = 0.0;\n\n    stamina = 100.0;\n    hydration = 100.0;\n    mountedVehicle = null;\n    mountedHealth = 100.0;\n    mountedMaxHealth = 100.0;\n    bugsRiddenCount = 0;\n    bugsDefeatedCount = 0;\n    forageCollected = 0;\n    score = 0;\n\n    dashCooldown = 0.0;\n    dashActiveTimer = 0.0;\n    attackAnim = 0.0;\n    screenShake = 0.0;\n\n    activeMission = null;\n    npcAnts.clear();\n    mountableBugs.clear();\n    realLifeProps.clear();\n    forageItems.clear();\n    particles.clear();\n    floatingNotes.clear();\n    fieldLog.clear();\n\n    _spawnCityOfGrass();\n    _spawnNpcAnts();\n    _spawnOpenWorldBugs();\n    _spawnRealLifeProps();\n    _spawnForageItems();\n    _updateThirdPersonCamera(1.0);\n  }\n\n  void addFieldLog(String msg, Color color) {\n    fieldLog.insert(0, FieldLogEntry(message: msg, color: color));\n    if (fieldLog.length > 3) {\n      fieldLog.removeLast();\n    }\n  }\n\n  void _spawnOpenWorldBugs() {\n\n    final initialBugs = <(BugVehicleType, Vec2, double)>[\n\n      (BugVehicleType.rhinoBeetle, const Vec2(56.0, 85.0), -1.57),\n      (BugVehicleType.grasshopper, const Vec2(48.0, 86.0), -2.1),\n      (BugVehicleType.stagBeetle, const Vec2(64.0, 86.0), -1.1),\n      (BugVehicleType.wolfSpider, const Vec2(56.0, 78.0), 1.57),\n      (BugVehicleType.hornet, const Vec2(46.0, 78.0), -0.8),\n\n      (BugVehicleType.rhinoBeetle, const Vec2(28.0, 72.0), 0.4),\n      (BugVehicleType.grasshopper, const Vec2(22.0, 64.0), 2.2),\n      (BugVehicleType.stagBeetle, const Vec2(34.0, 58.0), -1.8),\n      (BugVehicleType.hornet, const Vec2(26.0, 50.0), 1.2),\n      (BugVehicleType.wolfSpider, const Vec2(18.0, 68.0), -0.5),\n\n      (BugVehicleType.wolfSpider, const Vec2(88.0, 72.0), 3.1),\n      (BugVehicleType.stagBeetle, const Vec2(82.0, 58.0), -2.4),\n      (BugVehicleType.hornet, const Vec2(92.0, 52.0), -0.9),\n      (BugVehicleType.grasshopper, const Vec2(76.0, 52.0), 1.8),\n      (BugVehicleType.rhinoBeetle, const Vec2(90.0, 62.0), 0.7),\n\n      (BugVehicleType.wolfSpider, const Vec2(56.0, 64.0), -1.57),\n      (BugVehicleType.rhinoBeetle, const Vec2(48.0, 50.0), 2.6),\n      (BugVehicleType.stagBeetle, const Vec2(64.0, 50.0), -0.6),\n      (BugVehicleType.hornet, const Vec2(56.0, 44.0), 0.0),\n\n      (BugVehicleType.hornet, const Vec2(56.0, 20.0), 1.57),\n      (BugVehicleType.grasshopper, const Vec2(44.0, 22.0), 0.8),\n      (BugVehicleType.stagBeetle, const Vec2(68.0, 22.0), -2.2),\n      (BugVehicleType.wolfSpider, const Vec2(56.0, 12.0), -1.57),\n      (BugVehicleType.rhinoBeetle, const Vec2(32.0, 16.0), 0.3),\n      (BugVehicleType.wolfSpider, const Vec2(80.0, 16.0), 2.7),\n    ];\n\n    for (final v in initialBugs) {\n      mountableBugs.add(MountableBug(\n        id: _nextEntityId++,\n        type: v.\$1,\n        pos: v.\$2,\n        angle: v.\$3,\n        walkPhase: rng.nextDouble() * 6.28,\n      ));\n    }\n  }\n\n  void _spawnRealLifeProps() {\n    final curatedProps = <RealLifeProp3D>[\n\n      const RealLifeProp3D(\n        pos: Vec2(53.0, 84.0),\n        type: RealLifeObjectType.pennyCoin,\n        rotation: 0.4,\n        scale: 1.15,\n        label: 'Weathered Copper Penny (1989)',\n      ),\n      const RealLifeProp3D(\n        pos: Vec2(59.0, 84.5),\n        type: RealLifeObjectType.glassMarble,\n        rotation: 1.1,\n        scale: 1.1,\n        label: \"Cat's-Eye Glass Marble\",\n      ),\n      const RealLifeProp3D(\n        pos: Vec2(56.0, 80.0),\n        type: RealLifeObjectType.cloverBlossom,\n        rotation: 0.0,\n        scale: 1.25,\n        label: 'White Dutch Clover (Trifolium repens)',\n      ),\n      const RealLifeProp3D(\n        pos: Vec2(56.0, 74.0),\n        type: RealLifeObjectType.bottleCap,\n        rotation: 2.2,\n        scale: 1.1,\n        label: 'Crimped Metal Bottle Cap',\n      ),\n\n      const RealLifeProp3D(\n        pos: Vec2(56.0, 60.0),\n        type: RealLifeObjectType.rainPuddle,\n        rotation: 0.2,\n        scale: 2.2,\n        label: 'Rainwater Puddle',\n      ),\n      const RealLifeProp3D(\n        pos: Vec2(40.0, 52.0),\n        type: RealLifeObjectType.terracottaShard,\n        rotation: 0.8,\n        scale: 1.3,\n        label: 'Cracked Terracotta Pot Shard',\n      ),\n\n      const RealLifeProp3D(\n        pos: Vec2(74.0, 36.0),\n        type: RealLifeObjectType.gardenKey,\n        rotation: -0.7,\n        scale: 1.35,\n        label: 'Tarnished Brass Shed Key',\n      ),\n      const RealLifeProp3D(\n        pos: Vec2(56.0, 42.0),\n        type: RealLifeObjectType.glassMarble,\n        rotation: 0.3,\n        scale: 1.2,\n        label: 'Cobalt Swirl Glass Marble',\n      ),\n      const RealLifeProp3D(\n        pos: Vec2(44.0, 24.0),\n        type: RealLifeObjectType.pennyCoin,\n        rotation: 1.9,\n        scale: 1.15,\n        label: 'Patina Copper Coin',\n      ),\n    ];\n    realLifeProps.addAll(curatedProps);\n\n    final naturalTypes = [\n      (RealLifeObjectType.fallenOakLeaf, 'Fallen Oak Leaf'),\n      (RealLifeObjectType.riverPebble, 'Speckled Quartz Pebble'),\n      (RealLifeObjectType.cloverBlossom, 'Wild Clover Blossom'),\n      (RealLifeObjectType.pineCone, 'Fallen Pine Cone'),\n    ];\n    for (int i = 0; i < 90; i++) {\n      final pos = _findValidOpenPos();\n      final entry = naturalTypes[i % naturalTypes.length];\n      realLifeProps.add(RealLifeProp3D(\n        pos: pos,\n        type: entry.\$1,\n        rotation: rng.nextDouble() * math.pi * 2,\n        scale: 0.8 + rng.nextDouble() * 0.55,\n        label: entry.\$2,\n      ));\n    }\n  }\n\n  void _spawnForageItems() {\n    final spots = <(Vec2, ForageType)>[\n\n      (const Vec2(56.0, 86.0), ForageType.dewdrop),\n      (const Vec2(51.0, 81.0), ForageType.honeydewNectar),\n      (const Vec2(61.0, 81.0), ForageType.pineSeed),\n\n      (const Vec2(38.0, 76.0), ForageType.honeydewNectar),\n      (const Vec2(32.0, 70.0), ForageType.dewdrop),\n      (const Vec2(42.0, 64.0), ForageType.wildBerry),\n\n      (const Vec2(78.0, 70.0), ForageType.dewdrop),\n      (const Vec2(86.0, 64.0), ForageType.honeydewNectar),\n\n      (const Vec2(56.0, 65.0), ForageType.dewdrop),\n      (const Vec2(50.0, 52.0), ForageType.pineSeed),\n      (const Vec2(62.0, 52.0), ForageType.wildBerry),\n\n      (const Vec2(56.0, 36.0), ForageType.honeydewNectar),\n      (const Vec2(56.0, 18.0), ForageType.dewdrop),\n      (const Vec2(46.0, 16.0), ForageType.wildBerry),\n      (const Vec2(66.0, 16.0), ForageType.pineSeed),\n      (const Vec2(74.0, 30.0), ForageType.honeydewNectar),\n    ];\n    for (final s in spots) {\n      forageItems.add(ForageItem(\n        pos: s.\$1,\n        type: s.\$2,\n        shimmerPhase: rng.nextDouble() * math.pi * 2,\n      ));\n    }\n  }\n\n  bool isWallCell(int mx, int my) {\n    if (mx < 0 || mx >= mapWidth || my < 0 || my >= mapHeight) return true;\n    return grid[my][mx] > 0;\n  }\n\n  bool isWallAt(double x, double y, {double radius = 0.28}) {\n    final minX = (x - radius).floor();\n    final maxX = (x + radius).floor();\n    final minY = (y - radius).floor();\n    final maxY = (y + radius).floor();\n    for (int ty = minY; ty <= maxY; ty++) {\n      for (int tx = minX; tx <= maxX; tx++) {\n        if (isWallCell(tx, ty)) return true;\n      }\n    }\n    return false;\n  }\n\n  MountableBug? findNearbyMountableBug({double maxRange = 2.6}) {\n    MountableBug? closest;\n    double bestDist = maxRange;\n    for (final b in mountableBugs) {\n      final d = b.pos.distanceTo(playerPos);\n      if (d <= bestDist) {\n        bestDist = d;\n        closest = b;\n      }\n    }\n    return closest;\n  }\n\n  NpcAnt? findNearbyNpcAnt({double maxRange = 2.8}) {\n    NpcAnt? closest;\n    double bestDist = maxRange;\n    for (final npc in npcAnts) {\n      final d = npc.pos.distanceTo(playerPos);\n      if (d <= bestDist) {\n        bestDist = d;\n        closest = npc;\n      }\n    }\n    return closest;\n  }\n\n  void acceptMission(Mission mission) {\n    mission.status = MissionStatus.active;\n    activeMission = mission;\n    sound.playPickup();\n    addFieldLog('Accepted: \${mission.title}', const Color(0xFFD9A74A));\n    floatingNotes.add(FloatingNote3D(\n      pos: playerPos,\n      z: 0.35,\n      text: 'Accepted: \${mission.title}',\n      color: const Color(0xFFF5E6C8),\n    ));\n  }\n\n  void claimMissionReward(NpcAnt ant, Mission mission) {\n    mission.status = MissionStatus.claimed;\n    score += mission.scoreReward;\n    stamina = maxStamina;\n    hydration = maxHydration;\n    sound.playPickup();\n    addFieldLog(\n      'Completed: \${mission.title} (+\${mission.scoreReward} pts)',\n      const Color(0xFFA8E07B),\n    );\n    floatingNotes.add(FloatingNote3D(\n      pos: playerPos,\n      z: 0.45,\n      text: '+\${mission.scoreReward} PTS • MISSION COMPLETE!',\n      color: const Color(0xFFFFE066),\n    ));\n    _spawnNatureParticles(playerPos, const Color(0xFFFFD54F), 22);\n\n    ant.activeMissionIndex++;\n    if (activeMission?.id == mission.id) {\n      activeMission = null;\n    }\n  }\n\n  void checkMissionProgress(\n    MissionType type, {\n    BugVehicleType? bugType,\n    ForageType? forageType,\n    int amount = 1,\n  }) {\n    if (activeMission == null || activeMission!.status != MissionStatus.active) return;\n    final m = activeMission!;\n    if (m.type != type) return;\n\n    if (type == MissionType.mountBug && m.targetBug != null && m.targetBug != bugType) {\n      return;\n    }\n    if (type == MissionType.defeatBug && m.targetBug != null && m.targetBug != bugType) {\n      return;\n    }\n    if (type == MissionType.forageItem && m.targetForage != null && m.targetForage != forageType) {\n      return;\n    }\n\n    m.currentCount += amount;\n    if (m.isFinished) {\n      m.status = MissionStatus.completed;\n      sound.playPickup();\n      addFieldLog(\n        'Objective Complete: \${m.title}! Return to \${m.giverName}',\n        const Color(0xFFA8E07B),\n      );\n      floatingNotes.add(FloatingNote3D(\n        pos: playerPos,\n        z: 0.40,\n        text: 'OBJECTIVE COMPLETE! Return to \${m.giverName}',\n        color: const Color(0xFFA8E07B),\n      ));\n    }\n  }\n\n  void mountBugVehicle(BugVehicleType type, {double? initialHealth}) {\n    final spec = BugVehicleSpec.of(type);\n    mountedVehicle = type;\n    mountedMaxHealth = spec.maxHealth;\n    mountedHealth = initialHealth ?? spec.maxHealth;\n    playerZ = spec.rideElevation;\n    playerVz = 0.0;\n    bugsRiddenCount++;\n    sound.playPickup();\n    _updateThirdPersonCamera(1.0);\n    addFieldLog(\n      'Mounted \${spec.commonName} (\${spec.scientificName})',\n      spec.specularHighlight,\n    );\n    checkMissionProgress(MissionType.mountBug, bugType: type);\n  }\n\n  void interactOrToggleMount() {\n    if (mountedVehicle != null) {\n      final oldType = mountedVehicle!;\n      final forward = Vec2(math.cos(bodyYaw), math.sin(bodyYaw));\n      final parkPos = playerPos - forward * 0.75;\n\n      if (!isWallAt(parkPos.x, parkPos.y, radius: 0.3)) {\n        mountableBugs.add(MountableBug(\n          id: _nextEntityId++,\n          type: oldType,\n          pos: parkPos,\n          angle: bodyYaw,\n          currentHealth: mountedHealth,\n        ));\n      }\n\n      mountedVehicle = null;\n      playerZ = 0.0;\n      sound.playDash();\n      _updateThirdPersonCamera(1.0);\n      return;\n    }\n\n    final targetBug = findNearbyMountableBug();\n    if (targetBug != null) {\n      mountableBugs.remove(targetBug);\n      playerPos = targetBug.pos;\n      bodyYaw = targetBug.angle;\n      mountBugVehicle(targetBug.type, initialHealth: targetBug.health);\n      _spawnNatureParticles(playerPos, const Color(0xFFDCE3B8), 12);\n      floatingNotes.add(FloatingNote3D(\n        pos: playerPos,\n        z: 0.35,\n        text: 'Mounted \${targetBug.spec.commonName}',\n        color: const Color(0xFFF5E6C8),\n      ));\n    }\n  }\n\n  void triggerJumpOrAscend() {\n    if (mountedVehicle == BugVehicleType.hornet) {\n      if (playerZ < 3.2) {\n        playerVz = (playerVz + 2.4).clamp(1.8, 3.8);\n      }\n      sound.playDash();\n      return;\n    }\n    if (mountedVehicle == BugVehicleType.grasshopper) {\n      if (playerZ <= 0.20) {\n        playerVz = 4.8;\n        sound.playDash();\n        _spawnNatureParticles(playerPos, const Color(0xFF8C733E), 10);\n        checkMissionProgress(MissionType.leapAction);\n      }\n      return;\n    }\n    final groundZ = currentVehicleSpec?.rideElevation ?? 0.0;\n    if (playerZ <= groundZ + 0.04) {\n      playerVz = 2.6;\n      sound.playDash();\n    }\n  }\n\n  String get currentAttackName =>\n      currentVehicleSpec?.attackName ?? 'MANDIBLE BITE';\n\n  void triggerSpeciesAbility() {\n    if (dashCooldown > 0) return;\n    dashCooldown = maxDashCooldown;\n    dashActiveTimer = 0.22;\n    mandiblePinchAnim = 1.0;\n    attackAnim = 1.0;\n    sound.playDash();\n\n    final spec = currentVehicleSpec;\n    final attackRange = spec?.attackRange ?? 2.35;\n    final attackDamage = spec?.attackDamage ?? 25.0;\n    final attackLabel = currentAttackName;\n\n    if (mountedVehicle == BugVehicleType.wolfSpider) {\n      playerVz = 1.4;\n    } else if (mountedVehicle == BugVehicleType.rhinoBeetle) {\n      screenShake = 0.25;\n    }\n\n    final forward = Vec2(math.cos(playerAngle), math.sin(playerAngle));\n    final strikeOrigin = playerPos + forward * 0.65;\n    _spawnNatureParticles(\n      strikeOrigin,\n      spec?.specularHighlight ?? const Color(0xFFE86A38),\n      10,\n    );\n\n    bool hitAny = false;\n    for (int i = mountableBugs.length - 1; i >= 0; i--) {\n      final target = mountableBugs[i];\n      final toTarget = target.pos - playerPos;\n      final dist = toTarget.length;\n      if (dist <= attackRange) {\n        final dir = toTarget.normalized;\n        final facingDot = dir.dot(forward);\n\n        if (facingDot > -0.25 || dist < 1.55) {\n          hitAny = true;\n          target.health -= attackDamage;\n          target.hitFlashTimer = 0.30;\n          target.aggroTimer = 8.0;\n          target.angle = math.atan2(-toTarget.y, -toTarget.x);\n\n          final knockPos = target.pos + dir * 0.55;\n          if (!isWallAt(knockPos.x, knockPos.y, radius: 0.4)) {\n            target.pos = knockPos;\n          }\n\n          _spawnNatureParticles(target.pos, const Color(0xFFFF6B4A), 16);\n          floatingNotes.add(FloatingNote3D(\n            pos: target.pos,\n            z: 0.45,\n            text: '\$attackLabel -\${attackDamage.round()} HP',\n            color: const Color(0xFFFF8566),\n          ));\n\n          if (target.health <= 0) {\n            bugsDefeatedCount++;\n            score += 300;\n            checkMissionProgress(MissionType.defeatBug, bugType: target.type);\n            _spawnNatureParticles(target.pos, target.spec.specularHighlight, 26);\n            floatingNotes.add(FloatingNote3D(\n              pos: target.pos,\n              z: 0.65,\n              text: 'DEFEATED \${target.spec.commonName.toUpperCase()}!',\n              color: const Color(0xFFFFE066),\n            ));\n\n            forageItems.add(ForageItem(\n              pos: target.pos,\n              type: ForageType.honeydewNectar,\n            ));\n            final respawnType = target.type;\n            mountableBugs.removeAt(i);\n\n            mountableBugs.add(MountableBug(\n              id: _nextEntityId++,\n              type: respawnType,\n              pos: _findValidOpenPos(),\n              angle: rng.nextDouble() * math.pi * 2,\n            ));\n          }\n        }\n      }\n    }\n\n    if (hitAny) {\n      screenShake = 0.35;\n      sound.playHit();\n    }\n  }\n\n  void _spawnNatureParticles(Vec2 pos, Color color, int count) {\n    for (int i = 0; i < count; i++) {\n      final ang = rng.nextDouble() * math.pi * 2;\n      final spd = 0.6 + rng.nextDouble() * 2.5;\n      particles.add(NatureParticle3D(\n        pos: pos,\n        vel: Vec2(math.cos(ang) * spd, math.sin(ang) * spd),\n        z: (rng.nextDouble() - 0.3) * 0.25,\n        vz: 0.4 + rng.nextDouble() * 1.4,\n        life: 0.4 + rng.nextDouble() * 0.5,\n        color: color,\n        size: 0.03 + rng.nextDouble() * 0.04,\n      ));\n    }\n  }\n\n  void _updateThirdPersonCamera(double dt) {\n    final desiredDist = currentVehicleSpec?.cameraFollowDist ?? 1.12;\n\n    final zoomT = (dt * 5.5).clamp(0.0, 1.0);\n    cameraOrbitDist = cameraOrbitDist + (desiredDist - cameraOrbitDist) * zoomT;\n\n    final backAngle = playerAngle + math.pi;\n    final backHit = castRay(playerPos, backAngle);\n    final safeDist = math.min(cameraOrbitDist, math.max(0.32, backHit.distance - 0.22));\n\n    cameraPos = Vec2(\n      playerPos.x + math.cos(backAngle) * safeDist,\n      playerPos.y + math.sin(backAngle) * safeDist,\n    );\n    final mountElev = mountedVehicle != null ? 0.28 : 0.22;\n\n    final targetCameraZ = playerZ + mountElev;\n    final camZLerp = (dt * 18.0).clamp(0.0, 1.0);\n    cameraZ = cameraZ + (targetCameraZ - cameraZ) * camZLerp;\n  }\n\n  double _lerpAngle(double current, double target, double t) {\n    double diff = (target - current) % (math.pi * 2);\n    if (diff > math.pi) diff -= math.pi * 2;\n    if (diff < -math.pi) diff += math.pi * 2;\n    return current + diff * t.clamp(0.0, 1.0);\n  }\n\n  void update(\n    double dt, {\n    required double moveForward,\n    required double moveStrafe,\n    required double turnDelta,\n    required double pitchDelta,\n    required bool sprinting,\n    required bool actionPressed,\n  }) {\n    final clampedDt = dt.clamp(0.001, 0.05);\n    totalTime += clampedDt;\n\n    if (dashCooldown > 0) dashCooldown = math.max(0.0, dashCooldown - clampedDt);\n    if (dashActiveTimer > 0) dashActiveTimer = math.max(0.0, dashActiveTimer - clampedDt);\n    if (screenShake > 0) screenShake = math.max(0.0, screenShake - clampedDt * 2.4);\n    if (mandiblePinchAnim > 0) {\n      mandiblePinchAnim = math.max(0.0, mandiblePinchAnim - clampedDt * 3.5);\n    }\n    if (attackAnim > 0) {\n      attackAnim = math.max(0.0, attackAnim - clampedDt * 4.2);\n    }\n\n    if (!sprinting) {\n      stamina = math.min(maxStamina, stamina + clampedDt * 14.0);\n    } else {\n      stamina = math.max(10.0, stamina - clampedDt * 10.0);\n    }\n\n    playerAngle = (playerAngle + turnDelta) % (math.pi * 2);\n    playerPitch = (playerPitch + pitchDelta).clamp(-0.68, 0.72);\n\n    final targetGroundZ = currentVehicleSpec?.rideElevation ?? 0.0;\n    if (mountedVehicle == BugVehicleType.hornet) {\n      final hoverTarget = 0.42 + math.sin(totalTime * 4.2) * 0.035;\n      const maxFlightAltitude = 3.2;\n      playerZ = (playerZ + playerVz * clampedDt).clamp(hoverTarget, maxFlightAltitude);\n      playerVz -= 4.2 * clampedDt;\n      if (playerZ <= hoverTarget) {\n        playerZ = hoverTarget;\n        playerVz = 0.0;\n      }\n      if (playerZ >= maxFlightAltitude) {\n        playerVz = math.min(0.0, playerVz);\n      }\n    } else {\n      if (playerZ > targetGroundZ || playerVz != 0) {\n        playerZ += playerVz * clampedDt;\n        playerVz -= 6.8 * clampedDt;\n        if (playerZ <= targetGroundZ) {\n          playerZ = targetGroundZ;\n          playerVz = 0.0;\n        }\n      } else {\n        playerZ = targetGroundZ;\n      }\n    }\n\n    final forwardVec = Vec2(math.cos(playerAngle), math.sin(playerAngle));\n    final rightVec = Vec2(-math.sin(playerAngle), math.cos(playerAngle));\n    final inputVec = forwardVec * moveForward + rightVec * moveStrafe;\n    final inputMag = inputVec.length;\n\n    double moveSpeed;\n    if (mountedVehicle != null) {\n      final spec = currentVehicleSpec!;\n      moveSpeed = sprinting ? spec.sprintSpeed : spec.moveSpeed;\n    } else {\n      moveSpeed = sprinting ? 5.8 : 4.1;\n    }\n\n    if (dashActiveTimer > 0) {\n      moveSpeed = 11.5;\n    }\n\n    if (inputMag > 0.08 || dashActiveTimer > 0) {\n      final desiredVec = (inputMag > 0.08) ? inputVec : Vec2(math.cos(bodyYaw), math.sin(bodyYaw));\n      final desiredHeading = math.atan2(desiredVec.y, desiredVec.x);\n\n      final turnRate = mountedVehicle != null ? 14.0 : 18.0;\n      bodyYaw = _lerpAngle(bodyYaw, desiredHeading, clampedDt * turnRate);\n\n      var headingDiff = (desiredHeading - bodyYaw) % (math.pi * 2);\n      if (headingDiff > math.pi) headingDiff -= math.pi * 2;\n      if (headingDiff < -math.pi) headingDiff += math.pi * 2;\n      final forwardDrive = math.max(0.25, math.cos(headingDiff));\n\n      final forwardHeading = Vec2(math.cos(bodyYaw), math.sin(bodyYaw));\n      final effectiveSpeed = moveSpeed * math.min(1.0, inputMag > 0.08 ? inputMag : 1.0) * forwardDrive;\n      final step = forwardHeading * (effectiveSpeed * clampedDt);\n\n      final nextX = playerPos.x + step.x;\n      final nextY = playerPos.y + step.y;\n\n      if (!isWallAt(nextX, playerPos.y, radius: 0.28)) {\n        playerPos = Vec2(nextX, playerPos.y);\n      }\n      if (!isWallAt(playerPos.x, nextY, radius: 0.28)) {\n        playerPos = Vec2(playerPos.x, nextY);\n      }\n\n      walkBobPhase += clampedDt * (sprinting ? 16.0 : 11.0);\n      walkBobIntensity = (walkBobIntensity + clampedDt * 6.5).clamp(0.0, 1.0);\n    } else {\n\n      walkBobIntensity = (walkBobIntensity - clampedDt * 6.0).clamp(0.0, 1.0);\n    }\n\n    _updateThirdPersonCamera(clampedDt);\n\n    for (final mb in mountableBugs) {\n      if (mb.hitFlashTimer > 0) {\n        mb.hitFlashTimer = math.max(0.0, mb.hitFlashTimer - clampedDt);\n      }\n      if (mb.attackPhase > 0) {\n        mb.attackPhase = math.max(0.0, mb.attackPhase - clampedDt * 3.5);\n      }\n      if (mb.aiAttackCooldown > 0) {\n        mb.aiAttackCooldown = math.max(0.0, mb.aiAttackCooldown - clampedDt);\n      }\n      if (mb.aggroTimer > 0) {\n        mb.aggroTimer = math.max(0.0, mb.aggroTimer - clampedDt);\n\n        final toPlayer = playerPos - mb.pos;\n        final dist = toPlayer.length;\n        mb.angle = _lerpAngle(mb.angle, math.atan2(toPlayer.y, toPlayer.x), clampedDt * 6.0);\n        mb.isMoving = dist > 1.35;\n        if (dist <= 1.75 && mb.aiAttackCooldown <= 0) {\n          mb.aiAttackCooldown = 1.4;\n          mb.attackPhase = 1.0;\n          final retDmg = (mb.spec.attackDamage * 0.35).roundToDouble();\n          screenShake = 0.22;\n          _spawnNatureParticles(playerPos, const Color(0xFFFF7A52), 8);\n          floatingNotes.add(FloatingNote3D(\n            pos: playerPos,\n            z: 0.35,\n            text: '\${mb.spec.attackName} -\${retDmg.round()}',\n            color: const Color(0xFFFF9E80),\n          ));\n          if (mountedVehicle != null) {\n            mountedHealth = math.max(10.0, mountedHealth - retDmg);\n          }\n        }\n      } else {\n        mb.wanderTimer -= clampedDt;\n        if (mb.wanderTimer <= 0) {\n          mb.wanderTimer = 2.5 + rng.nextDouble() * 3.5;\n          mb.isMoving = rng.nextDouble() > 0.25;\n          mb.angle += (rng.nextDouble() - 0.5) * 1.2;\n        }\n      }\n\n      mb.walkPhase += clampedDt * (mb.aggroTimer > 0 ? 9.0 : 5.0);\n      if (mb.isMoving) {\n        final speed = mb.aggroTimer > 0 ? 1.15 : 0.50;\n        final dir = Vec2(math.cos(mb.angle), math.sin(mb.angle));\n        final nx = mb.pos.x + dir.x * speed * clampedDt;\n        final ny = mb.pos.y + dir.y * speed * clampedDt;\n        if (!isWallAt(nx, ny, radius: 0.45)) {\n          mb.pos = Vec2(nx, ny);\n        } else {\n          mb.angle += math.pi * 0.75;\n        }\n      }\n    }\n\n    for (int i = forageItems.length - 1; i >= 0; i--) {\n      final item = forageItems[i];\n      item.shimmerPhase += clampedDt * 3.0;\n      if (item.pos.distanceTo(playerPos) <= 0.78) {\n        sound.playPickup();\n        forageCollected++;\n        score += 150;\n        checkMissionProgress(MissionType.forageItem, forageType: item.type);\n        stamina = math.min(maxStamina, stamina + 35.0);\n        hydration = math.min(maxHydration, hydration + 35.0);\n        mandiblePinchAnim = 1.0;\n\n        floatingNotes.add(FloatingNote3D(\n          pos: item.pos,\n          z: 0.22,\n          text: item.label,\n          color: item.color,\n        ));\n        forageItems.removeAt(i);\n\n        if (forageItems.length < 8) {\n          forageItems.add(ForageItem(\n            pos: _findValidOpenPos(),\n            type: ForageType.values[rng.nextInt(ForageType.values.length)],\n          ));\n        }\n      }\n    }\n\n    _pollenSpawnTimer -= clampedDt;\n    if (_pollenSpawnTimer <= 0 && particles.length < 45) {\n      _pollenSpawnTimer = 0.16;\n      final angle = rng.nextDouble() * math.pi * 2;\n      final dist = 1.2 + rng.nextDouble() * 6.5;\n      particles.add(NatureParticle3D(\n        pos: playerPos + Vec2(math.cos(angle) * dist, math.sin(angle) * dist),\n        vel: Vec2((rng.nextDouble() - 0.5) * 0.3, (rng.nextDouble() - 0.5) * 0.3),\n        z: -0.05 + rng.nextDouble() * 1.1,\n        vz: 0.04 + rng.nextDouble() * 0.10,\n        life: 2.5 + rng.nextDouble() * 2.0,\n        color: const Color(0xFFF5E6B8),\n        size: 0.025 + rng.nextDouble() * 0.02,\n      ));\n    }\n\n    for (int i = particles.length - 1; i >= 0; i--) {\n      final pt = particles[i];\n      pt.life -= clampedDt;\n      if (pt.life <= 0) {\n        particles.removeAt(i);\n        continue;\n      }\n      pt.pos = pt.pos + pt.vel * clampedDt;\n      pt.z += pt.vz * clampedDt;\n    }\n\n    for (int i = floatingNotes.length - 1; i >= 0; i--) {\n      final fn = floatingNotes[i];\n      fn.life -= clampedDt;\n      fn.z += clampedDt * 0.25;\n      if (fn.life <= 0) {\n        floatingNotes.removeAt(i);\n      }\n    }\n\n    for (int i = fieldLog.length - 1; i >= 0; i--) {\n      fieldLog[i].life -= clampedDt;\n      if (fieldLog[i].life <= 0) {\n        fieldLog.removeAt(i);\n      }\n    }\n\n    if (activeMission != null &&\n        activeMission!.status == MissionStatus.active &&\n        activeMission!.type == MissionType.reachLocation &&\n        activeMission!.targetLocation != null) {\n      if (playerPos.distanceTo(activeMission!.targetLocation!) <= activeMission!.targetRadius) {\n        activeMission!.currentCount = activeMission!.targetCount;\n        activeMission!.status = MissionStatus.completed;\n        sound.playPickup();\n        addFieldLog(\n          'Discovered \${activeMission!.targetLocationName}! Return to \${activeMission!.giverName}',\n          const Color(0xFFA8E07B),\n        );\n        floatingNotes.add(FloatingNote3D(\n          pos: playerPos,\n          z: 0.40,\n          text: 'DISCOVERED \${activeMission!.targetLocationName!.toUpperCase()}!',\n          color: const Color(0xFFA8E07B),\n        ));\n      }\n    }\n\n    for (final npc in npcAnts) {\n      npc.walkPhase += clampedDt * 2.5;\n      npc.antennaeTwitchTimer += clampedDt;\n    }\n  }\n\n  Vec2 _findValidOpenPos() {\n    for (int attempt = 0; attempt < 50; attempt++) {\n      final x = 2.0 + rng.nextDouble() * (mapWidth - 4.0);\n      final y = 2.0 + rng.nextDouble() * (mapHeight - 4.0);\n      if (!isWallAt(x, y, radius: 0.45)) {\n        return Vec2(x, y);\n      }\n    }\n    return const Vec2(18.0, 20.0);\n  }\n\n  RayHit castRay(Vec2 origin, double rayAngle) {\n    final rayDirX = math.cos(rayAngle);\n    final rayDirY = math.sin(rayAngle);\n\n    int mapX = origin.x.floor();\n    int mapY = origin.y.floor();\n\n    final deltaDistX = rayDirX.abs() < 1e-8 ? 1e30 : (1.0 / rayDirX).abs();\n    final deltaDistY = rayDirY.abs() < 1e-8 ? 1e30 : (1.0 / rayDirY).abs();\n\n    int stepX;\n    int stepY;\n    double sideDistX;\n    double sideDistY;\n\n    if (rayDirX < 0) {\n      stepX = -1;\n      sideDistX = (origin.x - mapX) * deltaDistX;\n    } else {\n      stepX = 1;\n      sideDistX = (mapX + 1.0 - origin.x) * deltaDistX;\n    }\n\n    if (rayDirY < 0) {\n      stepY = -1;\n      sideDistY = (origin.y - mapY) * deltaDistY;\n    } else {\n      stepY = 1;\n      sideDistY = (mapY + 1.0 - origin.y) * deltaDistY;\n    }\n\n    bool hitVertical = false;\n    int wallType = 1;\n\n    for (int steps = 0; steps < 80; steps++) {\n      if (sideDistX < sideDistY) {\n        sideDistX += deltaDistX;\n        mapX += stepX;\n        hitVertical = true;\n      } else {\n        sideDistY += deltaDistY;\n        mapY += stepY;\n        hitVertical = false;\n      }\n\n      if (mapX < 0 || mapX >= mapWidth || mapY < 0 || mapY >= mapHeight) {\n        wallType = 1;\n        break;\n      }\n\n      final currentDist =\n          hitVertical ? (sideDistX - deltaDistX) : (sideDistY - deltaDistY);\n      if (currentDist > 36.0) {\n        wallType = 1;\n        break;\n      }\n\n      final cell = grid[mapY][mapX];\n      if (cell > 0) {\n        wallType = cell;\n        break;\n      }\n    }\n\n    double perpWallDist;\n    if (hitVertical) {\n      perpWallDist = sideDistX - deltaDistX;\n    } else {\n      perpWallDist = sideDistY - deltaDistY;\n    }\n    if (perpWallDist < 0.02) perpWallDist = 0.02;\n\n    double wallX;\n    if (hitVertical) {\n      wallX = origin.y + perpWallDist * rayDirY;\n    } else {\n      wallX = origin.x + perpWallDist * rayDirX;\n    }\n    wallX -= wallX.floor();\n\n    return RayHit(\n      distance: perpWallDist,\n      wallType: wallType,\n      hitVertical: hitVertical,\n      wallX: wallX,\n      mapX: mapX,\n      mapY: mapY,\n    );\n  }\n}",
  "lib/apps/grand_theft_ant/game/sound.dart": "export 'sound_stub.dart' if (dart.library.js_interop) 'sound_web.dart';",
  "lib/apps/grand_theft_ant/game/sound_web.dart": "import 'dart:js_interop';\nimport 'dart:js_interop_unsafe';\n\n@JS('window')\nexternal JSObject get _window;\n\nclass CyberSound {\n  bool enabled = true;\n\n  void _callJs(String method) {\n    if (!enabled) return;\n    try {\n      final synth = _window['cyberSynth'];\n      if (synth != null && synth.isA<JSObject>()) {\n        (synth as JSObject).callMethod(method.toJS);\n      }\n    } catch (_) {}\n  }\n\n  void init() => _callJs('init');\n  void playLaser() => _callJs('laser');\n  void playShotgun() => _callJs('shotgun');\n  void playRailgun() => _callJs('railgun');\n  void playHit() => _callJs('hit');\n  void playExplosion() => _callJs('explosion');\n  void playPickup() => _callJs('pickup');\n  void playDash() => _callJs('dash');\n  void playPlayerDamage() => _callJs('damage');\n}",
  "lib/apps/grand_theft_ant/game/mini_map.dart": "import 'dart:math' as math;\nimport 'package:flutter/material.dart';\nimport 'models.dart';\nimport 'world.dart';\n\nclass MiniMapRadar extends StatelessWidget {\n  final CyberWorld world;\n  final VoidCallback onToggleExpand;\n  final double size;\n\n  const MiniMapRadar({\n    super.key,\n    required this.world,\n    required this.onToggleExpand,\n    this.size = 104.0,\n  });\n\n  @override\n  Widget build(BuildContext context) {\n    return InkWell(\n      key: const ValueKey('mini_map_radar'),\n      onTap: onToggleExpand,\n      borderRadius: BorderRadius.circular(size / 2),\n      child: Container(\n        width: size,\n        height: size,\n        decoration: BoxDecoration(\n          shape: BoxShape.circle,\n          color: const Color(0xE616110B),\n          border: Border.all(\n            color: const Color(0xFFD9C398).withValues(alpha: 0.50),\n            width: 1.5,\n          ),\n          boxShadow: const [\n            BoxShadow(\n              color: Colors.black54,\n              blurRadius: 10,\n              offset: Offset(0, 3),\n            ),\n          ],\n        ),\n        child: Stack(\n          children: [\n\n            Positioned.fill(\n              child: CustomPaint(\n                painter: MiniMapRadarPainter(world: world),\n              ),\n            ),\n\n            Positioned(\n              right: 4,\n              bottom: 4,\n              child: Container(\n                padding: const EdgeInsets.symmetric(horizontal: 4, vertical: 1.5),\n                decoration: BoxDecoration(\n                  color: const Color(0x992B1D12),\n                  border: Border.all(\n                    color: const Color(0xFFD9C398).withValues(alpha: 0.35),\n                    width: 0.8,\n                  ),\n                  borderRadius: BorderRadius.circular(6),\n                ),\n                child: const Text(\n                  'MAP',\n                  style: TextStyle(\n                    color: Color(0xFFD9C398),\n                    fontSize: 7.5,\n                    fontWeight: FontWeight.w900,\n                    letterSpacing: 0.6,\n                  ),\n                ),\n              ),\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n}\n\nclass MiniMapRadarPainter extends CustomPainter {\n  final CyberWorld world;\n  static const double radarRange = 28.0;\n\n  MiniMapRadarPainter({required this.world});\n\n  @override\n  void paint(Canvas canvas, Size size) {\n    final cx = size.width / 2;\n    final cy = size.height / 2;\n    final r = (size.width / 2) - 3.5;\n\n    canvas.save();\n    canvas.clipPath(Path()..addOval(Rect.fromCircle(center: Offset(cx, cy), radius: r)));\n\n    final bgPaint = Paint()..color = const Color(0xF2140F09);\n    canvas.drawCircle(Offset(cx, cy), r, bgPaint);\n\n    final ringPaint = Paint()\n      ..color = const Color(0xFFD9C398).withValues(alpha: 0.12)\n      ..style = PaintingStyle.stroke\n      ..strokeWidth = 1.0;\n    canvas.drawCircle(Offset(cx, cy), r * (10.0 / radarRange), ringPaint);\n    canvas.drawCircle(Offset(cx, cy), r * (20.0 / radarRange), ringPaint);\n\n    final crosshairPaint = Paint()\n      ..color = const Color(0xFFD9C398).withValues(alpha: 0.08)\n      ..strokeWidth = 1.0;\n    canvas.drawLine(Offset(cx, cy - r), Offset(cx, cy + r), crosshairPaint);\n    canvas.drawLine(Offset(cx - r, cy), Offset(cx + r, cy), crosshairPaint);\n\n    final playerPos = world.playerPos;\n\n    for (final prop in world.realLifeProps) {\n      final dx = prop.pos.x - playerPos.x;\n      final dy = prop.pos.y - playerPos.y;\n      final dist = math.sqrt(dx * dx + dy * dy);\n      if (dist <= radarRange) {\n        final px = cx + (dx / radarRange) * r;\n        final py = cy + (dy / radarRange) * r;\n        _drawDiamond(canvas, px, py, 3.2, const Color(0xFFE5A93C));\n      }\n    }\n\n    for (final bug in world.mountableBugs) {\n      final dx = bug.pos.x - playerPos.x;\n      final dy = bug.pos.y - playerPos.y;\n      final dist = math.sqrt(dx * dx + dy * dy);\n      if (dist <= radarRange) {\n        final px = cx + (dx / radarRange) * r;\n        final py = cy + (dy / radarRange) * r;\n        Color bugColor;\n        switch (bug.type) {\n          case BugVehicleType.wolfSpider:\n            bugColor = const Color(0xFFE54B4B);\n            break;\n          case BugVehicleType.hornet:\n            bugColor = const Color(0xFFFFD152);\n            break;\n          case BugVehicleType.grasshopper:\n            bugColor = const Color(0xFF8CE04F);\n            break;\n          case BugVehicleType.rhinoBeetle:\n          case BugVehicleType.stagBeetle:\n            bugColor = const Color(0xFFD49E5E);\n            break;\n        }\n        canvas.drawCircle(Offset(px, py), 2.2, Paint()..color = bugColor);\n      }\n    }\n\n    for (final npc in world.npcAnts) {\n      final dx = npc.pos.x - playerPos.x;\n      final dy = npc.pos.y - playerPos.y;\n      final dist = math.sqrt(dx * dx + dy * dy);\n      if (dist <= radarRange) {\n        final px = cx + (dx / radarRange) * r;\n        final py = cy + (dy / radarRange) * r;\n\n        canvas.drawCircle(Offset(px, py), 3.8, Paint()..color = npc.crestColor);\n        canvas.drawCircle(\n          Offset(px, py),\n          3.8,\n          Paint()\n            ..color = Colors.white70\n            ..style = PaintingStyle.stroke\n            ..strokeWidth = 0.8,\n        );\n\n        if (npc.hasClaimableMission) {\n          canvas.drawCircle(Offset(px, py - 4.5), 2.4, Paint()..color = const Color(0xFFA8E07B));\n        } else if (npc.hasAvailableMission) {\n          canvas.drawCircle(Offset(px, py - 4.5), 2.4, Paint()..color = const Color(0xFFFFD54F));\n        }\n      }\n    }\n\n    final active = world.activeMission;\n    if (active != null) {\n      Vec2? targetPos = active.targetLocation;\n\n      if (active.status == MissionStatus.completed) {\n        final giver = world.npcAnts.where((n) => n.name == active.giverName).firstOrNull;\n        if (giver != null) {\n          targetPos = giver.pos;\n        }\n      }\n\n      if (targetPos != null) {\n        final tx = targetPos.x - playerPos.x;\n        final ty = targetPos.y - playerPos.y;\n        final tDist = math.sqrt(tx * tx + ty * ty);\n\n        if (tDist <= radarRange) {\n          final px = cx + (tx / radarRange) * r;\n          final py = cy + (ty / radarRange) * r;\n\n          final pulse = (math.sin(world.totalTime * 4.0) * 0.5 + 0.5);\n          canvas.drawCircle(\n            Offset(px, py),\n            4.0 + pulse * 3.0,\n            Paint()\n              ..color = const Color(0xFFFFD54F).withValues(alpha: 0.35)\n              ..style = PaintingStyle.stroke\n              ..strokeWidth = 1.2,\n          );\n          canvas.drawCircle(Offset(px, py), 3.5, Paint()..color = const Color(0xFFFFD54F));\n        } else {\n\n          final angle = math.atan2(ty, tx);\n          final edgeX = cx + math.cos(angle) * (r - 7.0);\n          final edgeY = cy + math.sin(angle) * (r - 7.0);\n\n          final arrowPath = Path();\n          final tip = Offset(edgeX, edgeY);\n          final left = Offset(\n            edgeX - math.cos(angle - 0.45) * 6.5,\n            edgeY - math.sin(angle - 0.45) * 6.5,\n          );\n          final right = Offset(\n            edgeX - math.cos(angle + 0.45) * 6.5,\n            edgeY - math.sin(angle + 0.45) * 6.5,\n          );\n          arrowPath.moveTo(tip.dx, tip.dy);\n          arrowPath.lineTo(left.dx, left.dy);\n          arrowPath.lineTo(right.dx, right.dy);\n          arrowPath.close();\n\n          canvas.drawPath(\n            arrowPath,\n            Paint()..color = active.isFinished ? const Color(0xFFA8E07B) : const Color(0xFFFFD54F),\n          );\n        }\n      }\n    }\n\n    final camAngle = world.playerAngle;\n    final fovArc = Path()\n      ..moveTo(cx, cy)\n      ..arcTo(\n        Rect.fromCircle(center: Offset(cx, cy), radius: r * 0.72),\n        camAngle - 0.42,\n        0.84,\n        false,\n      )\n      ..close();\n    canvas.drawPath(\n      fovArc,\n      Paint()\n        ..shader = RadialGradient(\n          colors: [\n            const Color(0xFF9AC94B).withValues(alpha: 0.28),\n            const Color(0xFF9AC94B).withValues(alpha: 0.0),\n          ],\n        ).createShader(Rect.fromCircle(center: Offset(cx, cy), radius: r * 0.72)),\n    );\n\n    final heading = world.playerAngle;\n    final pTip = Offset(cx + math.cos(heading) * 6.5, cy + math.sin(heading) * 6.5);\n    final pLeft = Offset(\n      cx + math.cos(heading + 2.45) * 5.0,\n      cy + math.sin(heading + 2.45) * 5.0,\n    );\n    final pRight = Offset(\n      cx + math.cos(heading - 2.45) * 5.0,\n      cy + math.sin(heading - 2.45) * 5.0,\n    );\n    final playerChevron = Path()\n      ..moveTo(pTip.dx, pTip.dy)\n      ..lineTo(pLeft.dx, pLeft.dy)\n      ..lineTo(cx, cy)\n      ..lineTo(pRight.dx, pRight.dy)\n      ..close();\n\n    canvas.drawPath(playerChevron, Paint()..color = const Color(0xFFB4E64D));\n    canvas.drawPath(\n      playerChevron,\n      Paint()\n        ..color = const Color(0xFF140F08)\n        ..style = PaintingStyle.stroke\n        ..strokeWidth = 1.0,\n    );\n\n    canvas.restore();\n\n    final rimPaint = Paint()\n      ..color = const Color(0xFFD9C398).withValues(alpha: 0.65)\n      ..style = PaintingStyle.stroke\n      ..strokeWidth = 1.6;\n    canvas.drawCircle(Offset(cx, cy), r, rimPaint);\n\n    _drawText(\n      canvas,\n      'N',\n      Offset(cx, cy - r + 6.0),\n      const TextStyle(\n        color: Color(0xFFFFD54F),\n        fontSize: 9.0,\n        fontWeight: FontWeight.w900,\n        letterSpacing: 0.5,\n      ),\n    );\n  }\n\n  void _drawDiamond(Canvas canvas, double x, double y, double size, Color color) {\n    final path = Path()\n      ..moveTo(x, y - size)\n      ..lineTo(x + size, y)\n      ..lineTo(x, y + size)\n      ..lineTo(x - size, y)\n      ..close();\n    canvas.drawPath(path, Paint()..color = color);\n    canvas.drawPath(\n      path,\n      Paint()\n        ..color = Colors.white70\n        ..style = PaintingStyle.stroke\n        ..strokeWidth = 0.6,\n    );\n  }\n\n  void _drawText(Canvas canvas, String text, Offset center, TextStyle style) {\n    final tp = TextPainter(\n      text: TextSpan(text: text, style: style),\n      textDirection: TextDirection.ltr,\n    )..layout();\n    tp.paint(canvas, Offset(center.dx - tp.width / 2, center.dy - tp.height / 2));\n  }\n\n  @override\n  bool shouldRepaint(covariant MiniMapRadarPainter oldDelegate) => true;\n}\n\nclass FullMeadowTacticalMapModal extends StatelessWidget {\n  final CyberWorld world;\n  final VoidCallback onClose;\n\n  const FullMeadowTacticalMapModal({\n    super.key,\n    required this.world,\n    required this.onClose,\n  });\n\n  @override\n  Widget build(BuildContext context) {\n    return Container(\n      color: const Color(0xCC0D0A07),\n      alignment: Alignment.center,\n      child: SingleChildScrollView(\n        child: Container(\n          constraints: const BoxConstraints(maxWidth: 440),\n          margin: const EdgeInsets.symmetric(horizontal: 16, vertical: 20),\n          padding: const EdgeInsets.all(18),\n          decoration: BoxDecoration(\n            color: const Color(0xF21C160F),\n            border: Border.all(\n              color: const Color(0xFFD9C398).withValues(alpha: 0.85),\n              width: 1.5,\n            ),\n            borderRadius: BorderRadius.circular(16),\n            boxShadow: const [\n              BoxShadow(\n                color: Colors.black87,\n                blurRadius: 32,\n                offset: Offset(0, 8),\n              ),\n            ],\n          ),\n          child: Column(\n            mainAxisSize: MainAxisSize.min,\n            crossAxisAlignment: CrossAxisAlignment.stretch,\n            children: [\n\n              Row(\n                children: [\n                  Container(\n                    padding: const EdgeInsets.all(6),\n                    decoration: BoxDecoration(\n                      color: const Color(0xFF382312),\n                      shape: BoxShape.circle,\n                      border: Border.all(color: const Color(0xFFD9C398), width: 1.2),\n                    ),\n                    child: const Icon(Icons.map, size: 20, color: Color(0xFFD9C398)),\n                  ),\n                  const SizedBox(width: 10),\n                  Expanded(\n                    child: Column(\n                      crossAxisAlignment: CrossAxisAlignment.start,\n                      children: [\n                        const Text(\n                          'MEADOW TACTICAL MAP',\n                          style: TextStyle(\n                            color: Color(0xFFF5EBD6),\n                            fontSize: 16,\n                            fontWeight: FontWeight.w800,\n                            letterSpacing: 1.2,\n                          ),\n                        ),\n                        const SizedBox(height: 2),\n                        Text(\n                          '112×112 Units • \${world.currentBiomeName}',\n                          style: const TextStyle(\n                            color: Color(0xFFD9A74A),\n                            fontSize: 10.5,\n                            fontWeight: FontWeight.w700,\n                          ),\n                        ),\n                      ],\n                    ),\n                  ),\n                  IconButton(\n                    key: const ValueKey('close_map_button'),\n                    icon: const Icon(Icons.close, color: Color(0xFFD9C398), size: 22),\n                    onPressed: onClose,\n                  ),\n                ],\n              ),\n              const SizedBox(height: 12),\n\n              Center(\n                child: AspectRatio(\n                  aspectRatio: 1.0,\n                  child: Container(\n                    decoration: BoxDecoration(\n                      color: const Color(0xFF140F09),\n                      border: Border.all(\n                        color: const Color(0xFFD9C398).withValues(alpha: 0.40),\n                        width: 1.2,\n                      ),\n                      borderRadius: BorderRadius.circular(12),\n                    ),\n                    child: ClipRRect(\n                      borderRadius: BorderRadius.circular(11),\n                      child: CustomPaint(\n                        painter: FullMeadowMapPainter(world: world),\n                      ),\n                    ),\n                  ),\n                ),\n              ),\n\n              const SizedBox(height: 12),\n\n              Container(\n                padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 8),\n                decoration: BoxDecoration(\n                  color: const Color(0xFF140F0A),\n                  border: Border.all(color: Colors.white12),\n                  borderRadius: BorderRadius.circular(8),\n                ),\n                child: const Wrap(\n                  spacing: 12,\n                  runSpacing: 4,\n                  alignment: WrapAlignment.spaceAround,\n                  children: [\n                    _LegendChip(icon: Icons.navigation, color: Color(0xFFB4E64D), label: 'You'),\n                    _LegendChip(icon: Icons.shield, color: Color(0xFFE88A2D), label: 'Officers'),\n                    _LegendChip(icon: Icons.star, color: Color(0xFFFFD54F), label: 'Objective'),\n                    _LegendChip(icon: Icons.diamond, color: Color(0xFFE5A93C), label: 'Relics'),\n                    _LegendChip(icon: Icons.circle, color: Color(0xFF8CE04F), label: 'Insects'),\n                  ],\n                ),\n              ),\n\n              const SizedBox(height: 12),\n\n              SizedBox(\n                width: double.infinity,\n                height: 42,\n                child: OutlinedButton(\n                  style: OutlinedButton.styleFrom(\n                    foregroundColor: const Color(0xFFD9C398),\n                    side: const BorderSide(color: Color(0xFFD9C398)),\n                    shape: RoundedRectangleBorder(\n                      borderRadius: BorderRadius.circular(8),\n                    ),\n                  ),\n                  onPressed: onClose,\n                  child: const Text(\n                    'CLOSE MAP [M]',\n                    style: TextStyle(\n                      fontWeight: FontWeight.w800,\n                      fontSize: 12,\n                      letterSpacing: 0.8,\n                    ),\n                  ),\n                ),\n              ),\n            ],\n          ),\n        ),\n      ),\n    );\n  }\n}\n\nclass _LegendChip extends StatelessWidget {\n  final IconData icon;\n  final Color color;\n  final String label;\n\n  const _LegendChip({\n    required this.icon,\n    required this.color,\n    required this.label,\n  });\n\n  @override\n  Widget build(BuildContext context) {\n    return Row(\n      mainAxisSize: MainAxisSize.min,\n      children: [\n        Icon(icon, size: 12, color: color),\n        const SizedBox(width: 4),\n        Text(\n          label,\n          style: const TextStyle(\n            color: Color(0xFFD9C398),\n            fontSize: 10,\n            fontWeight: FontWeight.w700,\n          ),\n        ),\n      ],\n    );\n  }\n}\n\nclass FullMeadowMapPainter extends CustomPainter {\n  final CyberWorld world;\n\n  FullMeadowMapPainter({required this.world});\n\n  @override\n  void paint(Canvas canvas, Size size) {\n    final scale = size.width / CyberWorld.mapWidth;\n\n    canvas.drawRect(\n      Rect.fromLTRB(0, 74.0 * scale, size.width, size.height),\n      Paint()..color = const Color(0xFF1B2E15),\n    );\n\n    canvas.drawRect(\n      Rect.fromLTRB(0, 32.0 * scale, 48.0 * scale, 74.0 * scale),\n      Paint()..color = const Color(0xFF1E381C),\n    );\n\n    canvas.drawRect(\n      Rect.fromLTRB(72.0 * scale, 32.0 * scale, size.width, 74.0 * scale),\n      Paint()..color = const Color(0xFF132B1A),\n    );\n\n    canvas.drawRect(\n      Rect.fromLTRB(0, 0, size.width, 32.0 * scale),\n      Paint()..color = const Color(0xFF2B3315),\n    );\n\n    canvas.drawRect(\n      Rect.fromLTRB(48.0 * scale, 32.0 * scale, 72.0 * scale, 74.0 * scale),\n      Paint()..color = const Color(0xFF261D14),\n    );\n\n    final gridPaint = Paint()\n      ..color = const Color(0xFFD9C398).withValues(alpha: 0.10)\n      ..strokeWidth = 0.8;\n    for (double g = 16.0; g < CyberWorld.mapWidth; g += 16.0) {\n      canvas.drawLine(Offset(g * scale, 0), Offset(g * scale, size.height), gridPaint);\n      canvas.drawLine(Offset(0, g * scale), Offset(size.width, g * scale), gridPaint);\n    }\n\n    _drawBiomeLabel(canvas, 'DANDELION CROWN', Offset(size.width * 0.5, 16.0 * scale));\n    _drawBiomeLabel(canvas, 'CLOVER PLAZA', Offset(24.0 * scale, 53.0 * scale));\n    _drawBiomeLabel(canvas, 'CROSSROADS', Offset(60.0 * scale, 53.0 * scale));\n    _drawBiomeLabel(canvas, 'TALL FESCUE', Offset(92.0 * scale, 53.0 * scale));\n    _drawBiomeLabel(canvas, 'ANTHILL OUTPOST', Offset(size.width * 0.5, 93.0 * scale));\n\n    for (final prop in world.realLifeProps) {\n      final px = prop.pos.x * scale;\n      final py = prop.pos.y * scale;\n      final diamond = Path()\n        ..moveTo(px, py - 3.5)\n        ..lineTo(px + 3.5, py)\n        ..lineTo(px, py + 3.5)\n        ..lineTo(px - 3.5, py)\n        ..close();\n      canvas.drawPath(diamond, Paint()..color = const Color(0xFFE5A93C));\n    }\n\n    for (final bug in world.mountableBugs) {\n      final px = bug.pos.x * scale;\n      final py = bug.pos.y * scale;\n      Color bugColor;\n      switch (bug.type) {\n        case BugVehicleType.wolfSpider:\n          bugColor = const Color(0xFFE54B4B);\n          break;\n        case BugVehicleType.hornet:\n          bugColor = const Color(0xFFFFD152);\n          break;\n        case BugVehicleType.grasshopper:\n          bugColor = const Color(0xFF8CE04F);\n          break;\n        case BugVehicleType.rhinoBeetle:\n        case BugVehicleType.stagBeetle:\n          bugColor = const Color(0xFFD49E5E);\n          break;\n      }\n      canvas.drawCircle(Offset(px, py), 2.0, Paint()..color = bugColor);\n    }\n\n    for (final npc in world.npcAnts) {\n      final px = npc.pos.x * scale;\n      final py = npc.pos.y * scale;\n\n      canvas.drawCircle(Offset(px, py), 4.5, Paint()..color = npc.crestColor);\n      canvas.drawCircle(\n        Offset(px, py),\n        4.5,\n        Paint()\n          ..color = Colors.white\n          ..style = PaintingStyle.stroke\n          ..strokeWidth = 1.0,\n      );\n\n      if (npc.hasClaimableMission) {\n        canvas.drawCircle(Offset(px, py - 5.0), 3.0, Paint()..color = const Color(0xFFA8E07B));\n      } else if (npc.hasAvailableMission) {\n        canvas.drawCircle(Offset(px, py - 5.0), 3.0, Paint()..color = const Color(0xFFFFD54F));\n      }\n    }\n\n    final active = world.activeMission;\n    if (active != null) {\n      Vec2? target = active.targetLocation;\n      if (active.status == MissionStatus.completed) {\n        final giver = world.npcAnts.where((n) => n.name == active.giverName).firstOrNull;\n        if (giver != null) target = giver.pos;\n      }\n\n      if (target != null) {\n        final px = target.x * scale;\n        final py = target.y * scale;\n        final pulse = math.sin(world.totalTime * 4.0) * 0.5 + 0.5;\n\n        canvas.drawCircle(\n          Offset(px, py),\n          6.0 + pulse * 4.0,\n          Paint()\n            ..color = const Color(0xFFFFD54F).withValues(alpha: 0.45)\n            ..style = PaintingStyle.stroke\n            ..strokeWidth = 1.5,\n        );\n        canvas.drawCircle(Offset(px, py), 4.0, Paint()..color = const Color(0xFFFFD54F));\n      }\n    }\n\n    final px = world.playerPos.x * scale;\n    final py = world.playerPos.y * scale;\n    final heading = world.playerAngle;\n\n    canvas.drawCircle(\n      Offset(px, py),\n      6.0,\n      Paint()\n        ..color = const Color(0xFFB4E64D).withValues(alpha: 0.35)\n        ..style = PaintingStyle.stroke\n        ..strokeWidth = 1.2,\n    );\n\n    final tip = Offset(px + math.cos(heading) * 7.5, py + math.sin(heading) * 7.5);\n    final left = Offset(px + math.cos(heading + 2.5) * 5.5, py + math.sin(heading + 2.5) * 5.5);\n    final right = Offset(px + math.cos(heading - 2.5) * 5.5, py + math.sin(heading - 2.5) * 5.5);\n    final playerPath = Path()\n      ..moveTo(tip.dx, tip.dy)\n      ..lineTo(left.dx, left.dy)\n      ..lineTo(px, py)\n      ..lineTo(right.dx, right.dy)\n      ..close();\n\n    canvas.drawPath(playerPath, Paint()..color = const Color(0xFFB4E64D));\n    canvas.drawPath(\n      playerPath,\n      Paint()\n        ..color = const Color(0xFF140F08)\n        ..style = PaintingStyle.stroke\n        ..strokeWidth = 1.0,\n    );\n  }\n\n  void _drawBiomeLabel(Canvas canvas, String label, Offset center) {\n    final tp = TextPainter(\n      text: TextSpan(\n        text: label,\n        style: TextStyle(\n          color: const Color(0xFFD9C398).withValues(alpha: 0.35),\n          fontSize: 8.5,\n          fontWeight: FontWeight.w800,\n          letterSpacing: 1.0,\n        ),\n      ),\n      textDirection: TextDirection.ltr,\n    )..layout();\n    tp.paint(canvas, Offset(center.dx - tp.width / 2, center.dy - tp.height / 2));\n  }\n\n  @override\n  bool shouldRepaint(covariant FullMeadowMapPainter oldDelegate) => true;\n}",
