& 7];\n    final g01 = _grad2[_perm[a + 1] & 7];\n    final g11 = _grad2[_perm[b + 1] & 7];\n\n    final d00 = g00[0] * xf + g00[1] * yf;\n    final d10 = g10[0] * (xf - 1.0) + g10[1] * yf;\n    final d01 = g01[0] * xf + g01[1] * (yf - 1.0);\n    final d11 = g11[0] * (xf - 1.0) + g11[1] * (yf - 1.0);\n\n    final x1 = d00 + u * (d10 - d00);\n    final x2 = d01 + u * (d11 - d01);\n    return (x1 + v * (x2 - x1)).clamp(-1.0, 1.0);\n  }\n\n  static double sampleFbm(\n    double x,\n    double y, {\n    int octaves = 3,\n    double lacunarity = 2.05,\n    double gain = 0.5,\n  }) {\n    double total = 0.0;\n    double freq = 1.0;\n    double amp = 1.0;\n    double maxAmp = 0.0;\n\n    for (int i = 0; i < octaves; i++) {\n      total += _rawNoise(x * freq, y * freq) * amp;\n      maxAmp += amp;\n      freq *= lacunarity;\n      amp *= gain;\n    }\n    return (total / maxAmp + 1.0) * 0.5;\n  }\n\n  void _initNoiseGrids() {\n    soilNoiseGrid = List<double>.filled(noiseGridSize * noiseGridSize, 0.0);\n    mossNoiseGrid = List<double>.filled(noiseGridSize * noiseGridSize, 0.0);\n\n    for (int y = 0; y < noiseGridSize; y++) {\n      final ny = y / noiseGridSize;\n      for (int x = 0; x < noiseGridSize; x++) {\n        final nx = x / noiseGridSize;\n        final idx = y * noiseGridSize + x;\n\n        soilNoiseGrid[idx] = sampleFbm(nx * 10.0, ny * 10.0, octaves: 3);\n\n        mossNoiseGrid[idx] = sampleFbm((nx + 7.3) * 18.0, (ny + 11.8) * 18.0, octaves: 3);\n      }\n    }\n  }\n\n  double getSoilNoise(double worldX, double worldY) {\n    final u = (worldX * 4.0) % noiseGridSize;\n    final v = (worldY * 4.0) % noiseGridSize;\n    final su = u < 0 ? u + noiseGridSize : u;\n    final sv = v < 0 ? v + noiseGridSize : v;\n\n    final x0 = su.floor();\n    final y0 = sv.floor();\n    final x1 = (x0 + 1) % noiseGridSize;\n    final y1 = (y0 + 1) % noiseGridSize;\n    final fx = su - x0;\n    final fy = sv - y0;\n\n    final n00 = soilNoiseGrid[y0 * noiseGridSize + x0];\n    final n10 = soilNoiseGrid[y0 * noiseGridSize + x1];\n    final n01 = soilNoiseGrid[y1 * noiseGridSize + x0];\n    final n11 = soilNoiseGrid[y1 * noiseGridSize + x1];\n\n    final top = n00 + fx * (n10 - n00);\n    final bot = n01 + fx * (n11 - n01);\n    return top + fy * (bot - top);\n  }\n\n  double getMossNoise(double worldX, double worldY) {\n    final u = (worldX * 4.0) % noiseGridSize;\n    final v = (worldY * 4.0) % noiseGridSize;\n    final su = u < 0 ? u + noiseGridSize : u;\n    final sv = v < 0 ? v + noiseGridSize : v;\n\n    final x0 = su.floor();\n    final y0 = sv.floor();\n    final x1 = (x0 + 1) % noiseGridSize;\n    final y1 = (y0 + 1) % noiseGridSize;\n    final fx = su - x0;\n    final fy = sv - y0;\n\n    final n00 = mossNoiseGrid[y0 * noiseGridSize + x0];\n    final n10 = mossNoiseGrid[y0 * noiseGridSize + x1];\n    final n01 = mossNoiseGrid[y1 * noiseGridSize + x0];\n    final n11 = mossNoiseGrid[y1 * noiseGridSize + x1];\n\n    final top = n00 + fx * (n10 - n00);\n    final bot = n01 + fx * (n11 - n01);\n    return top + fy * (bot - top);\n  }\n\n  void _generateMicroDebris() {\n    microDebris.clear();\n    final rng = math.Random(1907);\n\n    const pebblePalettes = [\n      (Color(0xFF5A524A), Color(0xFF2C2723), Color(0xFF8E847A)),\n      (Color(0xFF423C36), Color(0xFF1E1B18), Color(0xFF6B6259)),\n      (Color(0xFF6E5642), Color(0xFF38291D), Color(0xFF9E8166)),\n      (Color(0xFF4A4438), Color(0xFF242018), Color(0xFF7A705E)),\n    ];\n\n    const leafPalettes = [\n      (Color(0xFF6B361B), Color(0xFF38190B), Color(0xFF9E542C)),\n      (Color(0xFF542814), Color(0xFF281107), Color(0xFF7C3E20)),\n      (Color(0xFF46301A), Color(0xFF201509), Color(0xFF6E4F2E)),\n      (Color(0xFF75451D), Color(0xFF3E220D), Color(0xFFAA6B34)),\n    ];\n\n    const clodPalettes = [\n      (Color(0xFF2E2014), Color(0xFF160E08), Color(0xFF483524)),\n      (Color(0xFF3D2C1E), Color(0xFF1F150D), Color(0xFF5E4632)),\n      (Color(0xFF261D12), Color(0xFF120C06), Color(0xFF3E2F20)),\n    ];\n\n    const int count = 750;\n    for (int i = 0; i < count; i++) {\n\n      final wx = 2.5 + rng.nextDouble() * 107.0;\n      final wy = 2.5 + rng.nextDouble() * 107.0;\n\n      if (math.sqrt(math.pow(wx - 28.0, 2) + math.pow(wy - 46.0, 2)) < 1.4) continue;\n      if (math.sqrt(math.pow(wx - 56.0, 2) + math.pow(wy - 92.0, 2)) < 1.4) continue;\n\n      final typeRoll = rng.nextDouble();\n      MicroDebrisType type;\n      Color pCol;\n      Color sCol;\n      Color hCol;\n      double scale;\n\n      if (typeRoll < 0.32) {\n\n        type = MicroDebrisType.pebble;\n        final pal = pebblePalettes[rng.nextInt(pebblePalettes.length)];\n        pCol = pal.\$1;\n        sCol = pal.\$2;\n        hCol = pal.\$3;\n        scale = 0.08 + rng.nextDouble() * 0.16;\n      } else if (typeRoll < 0.58) {\n\n        type = MicroDebrisType.twig;\n        pCol = const Color(0xFF3A2416);\n        sCol = const Color(0xFF1D1109);\n        hCol = const Color(0xFF785236);\n        scale = 0.14 + rng.nextDouble() * 0.22;\n      } else if (typeRoll < 0.82) {\n\n        type = MicroDebrisType.deadLeaf;\n        final pal = leafPalettes[rng.nextInt(leafPalettes.length)];\n        pCol = pal.\$1;\n        sCol = pal.\$2;\n        hCol = pal.\$3;\n        scale = 0.12 + rng.nextDouble() * 0.18;\n      } else {\n\n        type = MicroDebrisType.dirtClod;\n        final pal = clodPalettes[rng.nextInt(clodPalettes.length)];\n        pCol = pal.\$1;\n        sCol = pal.\$2;\n        hCol = pal.\$3;\n        scale = 0.10 + rng.nextDouble() * 0.15;\n      }\n\n      microDebris.add(MicroDebrisItem(\n        pos: Vec2(wx, wy),\n        type: type,\n        rotation: rng.nextDouble() * math.pi * 2,\n        scale: scale,\n        variant: rng.nextInt(6),\n        primaryColor: pCol,\n        secondaryColor: sCol,\n        highlightColor: hCol,\n      ));\n    }\n  }\n}",
  "lib/apps/grand_theft_ant/game/models.dart": "import 'dart:math' as math;\nimport 'package:flutter/material.dart';\n\nclass Vec2 {\n  final double x;\n  final double y;\n\n  const Vec2(this.x, this.y);\n\n  Vec2 operator +(Vec2 other) => Vec2(x + other.x, y + other.y);\n  Vec2 operator -(Vec2 other) => Vec2(x - other.x, y - other.y);\n  Vec2 operator *(double s) => Vec2(x * s, y * s);\n\n  double get length => math.sqrt(x * x + y * y);\n  double get lengthSquared => x * x + y * y;\n\n  Vec2 get normalized {\n    final len = length;\n    if (len < 1e-8) return const Vec2(1, 0);\n    return Vec2(x / len, y / len);\n  }\n\n  double distanceTo(Vec2 other) => (this - other).length;\n  double dot(Vec2 other) => x * other.x + y * other.y;\n\n  Vec2 rotated(double radians) {\n    final c = math.cos(radians);\n    final s = math.sin(radians);\n    return Vec2(x * c - y * s, x * s + y * c);\n  }\n}\n\nenum BugVehicleType {\n  rhinoBeetle,\n  grasshopper,\n  hornet,\n  stagBeetle,\n  wolfSpider,\n}\n\nclass BugVehicleSpec {\n  final BugVehicleType type;\n  final String commonName;\n  final String scientificName;\n  final String role;\n  final String traitDescription;\n  final String attackName;\n  final double attackDamage;\n  final double attackRange;\n  final double maxHealth;\n  final double sizeMultiplier;\n  final double moveSpeed;\n  final double sprintSpeed;\n  final double rideElevation;\n  final double cameraFollowDist;\n  final bool canFly;\n  final bool canClearObstacles;\n  final Color carapacePrimary;\n  final Color carapaceSecondary;\n  final Color specularHighlight;\n\n  const BugVehicleSpec({\n    required this.type,\n    required this.commonName,\n    required this.scientificName,\n    required this.role,\n    required this.traitDescription,\n    required this.attackName,\n    required this.attackDamage,\n    required this.attackRange,\n    required this.maxHealth,\n    required this.sizeMultiplier,\n    required this.moveSpeed,\n    required this.sprintSpeed,\n    required this.rideElevation,\n    required this.cameraFollowDist,\n    this.canFly = false,\n    this.canClearObstacles = false,\n    required this.carapacePrimary,\n    required this.carapaceSecondary,\n    required this.specularHighlight,\n  });\n\n  static const Map<BugVehicleType, BugVehicleSpec> specs = {\n    BugVehicleType.rhinoBeetle: BugVehicleSpec(\n      type: BugVehicleType.rhinoBeetle,\n      commonName: 'Hercules Rhino Beetle',\n      scientificName: 'Dynastes hercules',\n      role: 'Heavy Juggernaut',\n      traitDescription: 'Colossal thoracic horn gores and flips rival bugs',\n      attackName: 'HORN GORE',\n      attackDamage: 55.0,\n      attackRange: 2.9,\n      maxHealth: 180.0,\n      sizeMultiplier: 1.18,\n      moveSpeed: 3.9,\n      sprintSpeed: 6.4,\n      rideElevation: 0.14,\n      cameraFollowDist: 1.82,\n      canClearObstacles: true,\n      carapacePrimary: Color(0xFF6B7342),\n      carapaceSecondary: Color(0xFF2B1D14),\n      specularHighlight: Color(0xFFDCE3B8),\n    ),\n    BugVehicleType.grasshopper: BugVehicleSpec(\n      type: BugVehicleType.grasshopper,\n      commonName: 'Meadow Grasshopper',\n      scientificName: 'Chorthippus parallelus',\n      role: 'Canopy Leaper',\n      traitDescription: 'Spined hind-leg raking kick & high canopy leap',\n      attackName: 'SPINED KICK',\n      attackDamage: 36.0,\n      attackRange: 2.6,\n      maxHealth: 110.0,\n      sizeMultiplier: 0.96,\n      moveSpeed: 5.8,\n      sprintSpeed: 8.6,\n      rideElevation: 0.08,\n      cameraFollowDist: 1.54,\n      carapacePrimary: Color(0xFF567D35),\n      carapaceSecondary: Color(0xFF8C733E),\n      specularHighlight: Color(0xFFC8E09B),\n    ),\n    BugVehicleType.hornet: BugVehicleSpec(\n      type: BugVehicleType.hornet,\n      commonName: 'European Hornet',\n      scientificName: 'Vespa crabro',\n      role: 'Aerial Striker',\n      traitDescription: 'Venomous barbed stinger dive & 3D flight',\n      attackName: 'VENOM STING',\n      attackDamage: 46.0,\n      attackRange: 2.8,\n      maxHealth: 120.0,\n      sizeMultiplier: 0.95,\n      moveSpeed: 6.6,\n      sprintSpeed: 9.5,\n      rideElevation: 0.42,\n      cameraFollowDist: 1.58,\n      canFly: true,\n      carapacePrimary: Color(0xFFC47D1B),\n      carapaceSecondary: Color(0xFF2E1A0F),\n      specularHighlight: Color(0xFFF5D799),\n    ),\n    BugVehicleType.stagBeetle: BugVehicleSpec(\n      type: BugVehicleType.stagBeetle,\n      commonName: 'Greater Stag Beetle',\n      scientificName: 'Lucanus cervus',\n      role: 'Armored Crusher',\n      traitDescription: 'Serrated antler mandibles crush rival chitin',\n      attackName: 'ANTLER CRUSH',\n      attackDamage: 50.0,\n      attackRange: 2.8,\n      maxHealth: 160.0,\n      sizeMultiplier: 1.12,\n      moveSpeed: 4.6,\n      sprintSpeed: 6.8,\n      rideElevation: 0.11,\n      cameraFollowDist: 1.74,\n      canClearObstacles: true,\n      carapacePrimary: Color(0xFF592316),\n      carapaceSecondary: Color(0xFF1F1614),\n      specularHighlight: Color(0xFFC98A76),\n    ),\n    BugVehicleType.wolfSpider: BugVehicleSpec(\n      type: BugVehicleType.wolfSpider,\n      commonName: 'Giant Wolf Spider',\n      scientificName: 'Hogna carolinensis',\n      role: 'Apex Arachnid',\n      traitDescription: '8-legged ambush pounce & venomous chelicerae fangs',\n      attackName: 'FANG POUNCE',\n      attackDamage: 48.0,\n      attackRange: 2.8,\n      maxHealth: 145.0,\n      sizeMultiplier: 1.10,\n      moveSpeed: 6.2,\n      sprintSpeed: 9.2,\n      rideElevation: 0.10,\n      cameraFollowDist: 1.76,\n      carapacePrimary: Color(0xFF4A3828),\n      carapaceSecondary: Color(0xFF1F1610),\n      specularHighlight: Color(0xFFC4AD8D),\n    ),\n  };\n\n  static BugVehicleSpec of(BugVehicleType type) => specs[type]!;\n}\n\nclass MountableBug {\n  final int id;\n  final BugVehicleType type;\n  Vec2 pos;\n  double angle;\n  double wanderTimer = 2.0;\n  double walkPhase = 0.0;\n  bool isMoving = true;\n\n  late double health;\n  late final double maxHealth;\n  double hitFlashTimer = 0.0;\n  double attackPhase = 0.0;\n  double aiAttackCooldown = 0.0;\n  double aggroTimer = 0.0;\n\n  MountableBug({\n    required this.id,\n    required this.type,\n    required this.pos,\n    required this.angle,\n    this.walkPhase = 0.0,\n    double? currentHealth,\n  }) {\n    maxHealth = BugVehicleSpec.of(type).maxHealth;\n    health = currentHealth ?? maxHealth;\n  }\n\n  BugVehicleSpec get spec => BugVehicleSpec.of(type);\n}\n\nenum GrassCrownType {\n  archingBlade,\n  seedPanicle,\n  cloverUmbrella,\n  dandelionTower,\n  dewdropBlade,\n}\n\nclass GrassStalk3D {\n  final Vec2 pos;\n  final double height;\n  final double baseWidth;\n  final double archAngle;\n  final double archReach;\n  final double swayPhase;\n  final Color baseColor;\n  final Color midColor;\n  final Color tipColor;\n  final GrassCrownType crownType;\n  final int subBlades;\n\n  const GrassStalk3D({\n    required this.pos,\n    required this.height,\n    required this.baseWidth,\n    required this.archAngle,\n    required this.archReach,\n    required this.swayPhase,\n    required this.baseColor,\n    required this.midColor,\n    required this.tipColor,\n    required this.crownType,\n    this.subBlades = 3,\n  });\n}\n\nenum RealLifeObjectType {\n  pennyCoin,\n  glassMarble,\n  bottleCap,\n  terracottaShard,\n  gardenKey,\n  fallenOakLeaf,\n  riverPebble,\n  cloverBlossom,\n  pineCone,\n  rainPuddle,\n}\n\nclass RealLifeProp3D {\n  final Vec2 pos;\n  final RealLifeObjectType type;\n  final double rotation;\n  final double scale;\n  final String label;\n\n  const RealLifeProp3D({\n    required this.pos,\n    required this.type,\n    this.rotation = 0.0,\n    this.scale = 1.0,\n    required this.label,\n  });\n}\n\nenum ForageType {\n  dewdrop,\n  honeydewNectar,\n  pineSeed,\n  wildBerry,\n}\n\nclass ForageItem {\n  Vec2 pos;\n  final ForageType type;\n  double shimmerPhase;\n\n  ForageItem({\n    required this.pos,\n    required this.type,\n    this.shimmerPhase = 0.0,\n  });\n\n  Color get color {\n    switch (type) {\n      case ForageType.dewdrop:\n        return const Color(0xFFB8E2F2);\n      case ForageType.honeydewNectar:\n        return const Color(0xFFE8A838);\n      case ForageType.pineSeed:\n        return const Color(0xFF8C6239);\n      case ForageType.wildBerry:\n        return const Color(0xFF9E2A3B);\n    }\n  }\n\n  String get label {\n    switch (type) {\n      case ForageType.dewdrop:\n        return 'Morning Dewdrop';\n      case ForageType.honeydewNectar:\n        return 'Golden Honeydew';\n      case ForageType.pineSeed:\n        return 'Pine Nut Seed';\n      case ForageType.wildBerry:\n        return 'Wild Bramble Berry';\n    }\n  }\n}\n\nclass NatureParticle3D {\n  Vec2 pos;\n  Vec2 vel;\n  double z;\n  double vz;\n  double life;\n  final double maxLife;\n  final Color color;\n  final double size;\n\n  NatureParticle3D({\n    required this.pos,\n    required this.vel,\n    required this.z,\n    required this.vz,\n    required this.life,\n    required this.color,\n    this.size = 0.04,\n  }) : maxLife = life;\n}\n\nclass FloatingNote3D {\n  Vec2 pos;\n  double z;\n  final String text;\n  final Color color;\n  double life;\n  final double maxLife;\n\n  FloatingNote3D({\n    required this.pos,\n    required this.z,\n    required this.text,\n    required this.color,\n    this.life = 1.2,\n  }) : maxLife = life;\n}\n\nclass FieldLogEntry {\n  final String message;\n  final Color color;\n  double life;\n\n  FieldLogEntry({\n    required this.message,\n    required this.color,\n    this.life = 5.5,\n  });\n}\n\nenum MissionType {\n  mountBug,\n  defeatBug,\n  forageItem,\n  reachLocation,\n  leapAction,\n}\n\nenum MissionStatus {\n  available,\n  active,\n  completed,\n  claimed,\n}\n\nclass Mission {\n  final String id;\n  final String title;\n  final String description;\n  final String giverName;\n  final MissionType type;\n  final BugVehicleType? targetBug;\n  final ForageType? targetForage;\n  final Vec2? targetLocation;\n  final double targetRadius;\n  final String? targetLocationName;\n  final int targetCount;\n  int currentCount;\n  final int scoreReward;\n  final String introDialogue;\n  final String inProgressDialogue;\n  final String completionDialogue;\n  MissionStatus status;\n\n  Mission({\n    required this.id,\n    required this.title,\n    required this.description,\n    required this.giverName,\n    required this.type,\n    this.targetBug,\n    this.targetForage,\n    this.targetLocation,\n    this.targetRadius = 5.0,\n    this.targetLocationName,\n    this.targetCount = 1,\n    this.currentCount = 0,\n    required this.scoreReward,\n    required this.introDialogue,\n    required this.inProgressDialogue,\n    required this.completionDialogue,\n    this.status = MissionStatus.available,\n  });\n\n  bool get isFinished => currentCount >= targetCount;\n  double get progressRatio =>\n      targetCount > 0 ? (currentCount / targetCount).clamp(0.0, 1.0) : 0.0;\n}\n\nclass NpcAnt {\n  final int id;\n  final String name;\n  final String rank;\n  final String title;\n  final Color chitinColor;\n  final Color crestColor;\n  Vec2 pos;\n  double angle;\n  final List<Mission> missions;\n  int activeMissionIndex;\n  double walkPhase;\n  double antennaeTwitchTimer;\n\n  NpcAnt({\n    required this.id,\n    required this.name,\n    required this.rank,\n    required this.title,\n    required this.chitinColor,\n    required this.crestColor,\n    required this.pos,\n    required this.angle,\n    required this.missions,\n    this.activeMissionIndex = 0,\n    this.walkPhase = 0.0,\n    this.antennaeTwitchTimer = 0.0,\n  });\n\n  Mission? get currentMission {\n    if (activeMissionIndex >= 0 && activeMissionIndex < missions.length) {\n      return missions[activeMissionIndex];\n    }\n    return null;\n  }\n\n  bool get hasClaimableMission {\n    final m = currentMission;\n    return m != null && m.status == MissionStatus.completed;\n  }\n\n  bool get hasAvailableMission {\n    final m = currentMission;\n    return m != null && m.status == MissionStatus.available;\n  }\n\n  bool get hasActiveMission {\n    final m = currentMission;\n    return m != null && m.status == MissionStatus.active;\n  }\n\n  bool get allMissionsClaimed => activeMissionIndex >= missions.length;\n}",
  "lib/apps/grand_theft_ant/game/gamepad_state.dart": "enum ControllerPreset {\n  standard,\n  bumperJumper,\n  actionCombat,\n}\n\nclass ControllerMapping {\n  ControllerPreset preset;\n  int jumpButton;\n  int attackButton;\n  int mountButton;\n  int sprintButton;\n  int pauseButton;\n  double deadzone;\n  double lookSensitivity;\n  bool invertLookY;\n\n  ControllerMapping({\n    this.preset = ControllerPreset.standard,\n    this.jumpButton = 0,\n    this.attackButton = 7,\n    this.mountButton = 2,\n    this.sprintButton = 1,\n    this.pauseButton = 9,\n    this.deadzone = 0.14,\n    this.lookSensitivity = 1.0,\n    this.invertLookY = false,\n  });\n\n  void applyPreset(ControllerPreset newPreset) {\n    preset = newPreset;\n    switch (newPreset) {\n      case ControllerPreset.standard:\n        jumpButton = 0;\n        attackButton = 7;\n        mountButton = 2;\n        sprintButton = 1;\n        pauseButton = 9;\n        break;\n      case ControllerPreset.bumperJumper:\n        jumpButton = 4;\n        attackButton = 5;\n        mountButton = 2;\n        sprintButton = 0;\n        pauseButton = 9;\n        break;\n      case ControllerPreset.actionCombat:\n        jumpButton = 0;\n        attackButton = 3;\n        mountButton = 2;\n        sprintButton = 5;\n        pauseButton = 9;\n        break;\n    }\n  }\n\n  String get presetName {\n    switch (preset) {\n      case ControllerPreset.standard:\n        return 'Standard (A=Leap, RT=Attack, X=Mount)';\n      case ControllerPreset.bumperJumper:\n        return 'Bumper Jumper (LB=Leap, RB=Attack, X=Mount)';\n      case ControllerPreset.actionCombat:\n        return 'Action Combat (A=Leap, Y=Attack, RB=Sprint)';\n    }\n  }\n}\n\nclass GamepadSnapshot {\n  final bool isConnected;\n  final String id;\n  final double moveForward;\n  final double moveStrafe;\n  final double lookX;\n  final double lookY;\n  final bool jump;\n  final bool attack;\n  final bool mount;\n  final bool sprint;\n  final bool pause;\n\n  const GamepadSnapshot({\n    this.isConnected = false,\n    this.id = '',\n    this.moveForward = 0.0,\n    this.moveStrafe = 0.0,\n    this.lookX = 0.0,\n    this.lookY = 0.0,\n    this.jump = false,\n    this.attack = false,\n    this.mount = false,\n    this.sprint = false,\n    this.pause = false,\n  });\n\n  static const empty = GamepadSnapshot();\n}",
  "lib/apps/grand_theft_ant/grand_theft_ant_app.dart": "import 'dart:math' as math;\nimport 'package:flutter/foundation.dart';\nimport 'package:flutter/material.dart';\nimport 'package:flutter/scheduler.dart';\nimport 'package:flutter/services.dart';\nimport 'game/gamepad.dart';\nimport 'game/mini_map.dart';\nimport 'game/models.dart';\nimport 'game/renderer.dart';\nimport 'game/world.dart';\n\nbool get isDesktopPlatform {\n  return defaultTargetPlatform == TargetPlatform.windows ||\n      defaultTargetPlatform == TargetPlatform.macOS ||\n      defaultTargetPlatform == TargetPlatform.linux;\n}\n\nclass GrandTheftAntApp extends StatelessWidget {\n  const GrandTheftAntApp({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    return Theme(\n      data: ThemeData.dark().copyWith(\n        scaffoldBackgroundColor: const Color(0xFF1A140E),\n        colorScheme: const ColorScheme.dark(\n          primary: Color(0xFF7FA650),\n          secondary: Color(0xFFD9A74A),\n          surface: Color(0xFF241C14),\n        ),\n      ),\n      child: const CyberFpsGameScreen(),\n    );\n  }\n}\n\nclass CyberFpsGameScreen extends StatefulWidget {\n  const CyberFpsGameScreen({super.key});\n\n  @override\n  State<CyberFpsGameScreen> createState() => _CyberFpsGameScreenState();\n}\n\nclass _CyberFpsGameScreenState extends State<CyberFpsGameScreen>\n    with SingleTickerProviderStateMixin {\n  late final CyberWorld world;\n  late final Ticker _ticker;\n  final FocusNode _focusNode = FocusNode();\n\n  final Set<LogicalKeyboardKey> _pressedKeys = {};\n  Duration _lastTick = Duration.zero;\n\n  bool _inMenu = true;\n  bool _isPaused = false;\n  bool _invertLookY = false;\n  double _lookSensitivity = 1.0;\n  late bool _showTouchJoysticks;\n  NpcAnt? _talkingToNpc;\n  bool _showMiniMap = true;\n  bool _miniMapExpanded = false;\n\n  final GamepadService _gamepadService = GamepadService();\n  bool _lastGpJump = false;\n  bool _lastGpAttack = false;\n  bool _lastGpMount = false;\n  bool _lastGpPause = false;\n  GamepadSnapshot _currentGamepad = GamepadSnapshot.empty;\n\n  Offset _leftJoystickVector = Offset.zero;\n  Offset _rightJoystickVector = Offset.zero;\n\n  @override\n  void initState() {\n    super.initState();\n    world = CyberWorld(denseFoliage: isDesktopPlatform);\n    _gamepadService.init();\n    _showTouchJoysticks = !isDesktopPlatform;\n    _ticker = createTicker(_onTick)..start();\n  }\n\n  @override\n  void dispose() {\n    _ticker.dispose();\n    _focusNode.dispose();\n    super.dispose();\n  }\n\n  void _startGame() {\n    world.sound.init();\n    setState(() {\n      _inMenu = false;\n      _isPaused = false;\n      _talkingToNpc = null;\n    });\n    _focusNode.requestFocus();\n  }\n\n  void _onTick(Duration elapsed) {\n    if (_lastTick == Duration.zero) {\n      _lastTick = elapsed;\n      return;\n    }\n    final dt = (elapsed - _lastTick).inMicroseconds / 1e6;\n    _lastTick = elapsed;\n\n    final gp = _gamepadService.poll();\n    _currentGamepad = gp;\n\n    if (_inMenu || _isPaused || _talkingToNpc != null) {\n\n      if (gp.isConnected && gp.pause && !_lastGpPause && !_inMenu) {\n        if (_talkingToNpc != null) {\n          setState(() => _talkingToNpc = null);\n        } else {\n          setState(() => _isPaused = false);\n        }\n      }\n      _lastGpPause = gp.pause;\n      return;\n    }\n\n    double moveForward = -_leftJoystickVector.dy;\n    double moveStrafe = _leftJoystickVector.dx;\n\n    if (gp.isConnected) {\n      moveForward += gp.moveForward;\n      moveStrafe += gp.moveStrafe;\n    }\n\n    final pitchDirection = _invertLookY ? 1.0 : -1.0;\n    double turnDelta = _rightJoystickVector.dx * 2.65 * _lookSensitivity * dt;\n    double pitchDelta =\n        pitchDirection * _rightJoystickVector.dy * 1.55 * _lookSensitivity * dt;\n\n    if (gp.isConnected) {\n      turnDelta += gp.lookX * 2.85 * _lookSensitivity * dt;\n      pitchDelta += pitchDirection * gp.lookY * 1.85 * _lookSensitivity * dt;\n\n      if (gp.jump && !_lastGpJump) {\n        world.triggerJumpOrAscend();\n      }\n      if (gp.attack && !_lastGpAttack) {\n        world.triggerSpeciesAbility();\n      }\n      if (gp.mount && !_lastGpMount) {\n        final nearbyNpc = world.findNearbyNpcAnt();\n        final nearbyBug = world.findNearbyMountableBug();\n        if (nearbyNpc != null && nearbyBug == null && world.mountedVehicle == null) {\n          setState(() => _talkingToNpc = nearbyNpc);\n        } else {\n          world.interactOrToggleMount();\n        }\n      }\n      if (gp.pause && !_lastGpPause) {\n        setState(() => _isPaused = true);\n      }\n      _lastGpJump = gp.jump;\n      _lastGpAttack = gp.attack;\n      _lastGpMount = gp.mount;\n      _lastGpPause = gp.pause;\n    }\n\n    if (_pressedKeys.contains(LogicalKeyboardKey.keyW) ||\n        _pressedKeys.contains(LogicalKeyboardKey.arrowUp)) {\n      moveForward += 1.0;\n    }\n    if (_pressedKeys.contains(LogicalKeyboardKey.keyS) ||\n        _pressedKeys.contains(LogicalKeyboardKey.arrowDown)) {\n      moveForward -= 1.0;\n    }\n    if (_pressedKeys.contains(LogicalKeyboardKey.keyA)) {\n      moveStrafe -= 1.0;\n    }\n    if (_pressedKeys.contains(LogicalKeyboardKey.keyD)) {\n      moveStrafe += 1.0;\n    }\n    if (_pressedKeys.contains(LogicalKeyboardKey.arrowLeft) ||\n        _pressedKeys.contains(LogicalKeyboardKey.keyQ)) {\n      turnDelta -= 2.4 * dt;\n    }\n    if (_pressedKeys.contains(LogicalKeyboardKey.arrowRight)) {\n      turnDelta += 2.4 * dt;\n    }\n\n    moveForward = moveForward.clamp(-1.0, 1.0);\n    moveStrafe = moveStrafe.clamp(-1.0, 1.0);\n\n    final sprinting = _pressedKeys.contains(LogicalKeyboardKey.shiftLeft) ||\n        _pressedKeys.contains(LogicalKeyboardKey.shiftRight) ||\n        _leftJoystickVector.distance > 0.78 ||\n        (gp.isConnected && gp.sprint);\n\n    world.update(\n      dt,\n      moveForward: moveForward,\n      moveStrafe: moveStrafe,\n      turnDelta: turnDelta,\n      pitchDelta: pitchDelta,\n      sprinting: sprinting,\n      actionPressed: false,\n    );\n\n    if (mounted) {\n      setState(() {});\n    }\n  }\n\n  String _compassHeadingText(double angle) {\n    final deg = ((angle * 180 / math.pi) % 360 + 360) % 360;\n    if (deg >= 337.5 || deg < 22.5) return 'EAST (\${deg.round()}°)';\n    if (deg >= 22.5 && deg < 67.5) return 'SE (\${deg.round()}°)';\n    if (deg >= 67.5 && deg < 112.5) return 'SOUTH (\${deg.round()}°)';\n    if (deg >= 112.5 && deg < 157.5) return 'SW (\${deg.round()}°)';\n    if (deg >= 157.5 && deg < 202.5) return 'WEST (\${deg.round()}°)';\n    if (deg >= 202.5 && deg < 247.5) return 'NW (\${deg.round()}°)';\n    if (deg >= 247.5 && deg < 292.5) return 'NORTH (\${deg.round()}°)';\n    return 'NE (\${deg.round()}°)';\n  }\n\n  KeyEventResult _handleKeyEvent(FocusNode node, KeyEvent event) {\n    final key = event.logicalKey;\n    if (event is KeyDownEvent) {\n      _pressedKeys.add(key);\n\n      if (key == LogicalKeyboardKey.keyM) {\n        if (!_inMenu && !_isPaused) {\n          setState(() => _miniMapExpanded = !_miniMapExpanded);\n        }\n      } else if (key == LogicalKeyboardKey.keyT) {\n        if (_talkingToNpc != null) {\n          setState(() => _talkingToNpc = null);\n        } else {\n          final nearbyNpc = world.findNearbyNpcAnt();\n          if (nearbyNpc != null) {\n            setState(() => _talkingToNpc = nearbyNpc);\n          }\n        }\n      } else if (key == LogicalKeyboardKey.keyE) {\n        final nearbyNpc = world.findNearbyNpcAnt();\n        final nearbyBug = world.findNearbyMountableBug();\n        if (nearbyNpc != null && nearbyBug == null && world.mountedVehicle == null) {\n          setState(() => _talkingToNpc = nearbyNpc);\n        } else {\n          world.interactOrToggleMount();\n        }\n      } else if (key == LogicalKeyboardKey.space ||\n          key == LogicalKeyboardKey.keyC) {\n        world.triggerJumpOrAscend();\n      } else if (key == LogicalKeyboardKey.keyF) {\n        world.triggerSpeciesAbility();\n      } else if (key == LogicalKeyboardKey.escape ||\n          key == LogicalKeyboardKey.keyP) {\n        if (_miniMapExpanded) {\n          setState(() => _miniMapExpanded = false);\n        } else if (_talkingToNpc != null) {\n          setState(() => _talkingToNpc = null);\n        } else if (!_inMenu) {\n          setState(() {\n            _isPaused = !_isPaused;\n          });\n        }\n      }\n    } else if (event is KeyUpEvent) {\n      _pressedKeys.remove(key);\n    }\n    return KeyEventResult.handled;\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      body: Focus(\n        focusNode: _focusNode,\n        autofocus: true,\n        onKeyEvent: _handleKeyEvent,\n        child: GestureDetector(\n          behavior: HitTestBehavior.translucent,\n          onTapDown: (_) {\n            if (!_focusNode.hasFocus) {\n              _focusNode.requestFocus();\n            }\n          },\n          child: Stack(\n            fit: StackFit.expand,\n          children: [\n\n            RepaintBoundary(\n              child: CustomPaint(\n                painter: CyberRenderer(world: world),\n                size: Size.infinite,\n              ),\n            ),\n\n            if (!_inMenu) _buildSimplifiedPortraitHud(context),\n\n            if (_inMenu) _buildTitleScreen(),\n            if (_isPaused && !_inMenu) _buildPauseOverlay(),\n            if (_talkingToNpc != null && !_inMenu)\n              _buildDialogueModal(_talkingToNpc!),\n            if (_miniMapExpanded && !_inMenu)\n              FullMeadowTacticalMapModal(\n                world: world,\n                onClose: () => setState(() => _miniMapExpanded = false),\n              ),\n          ],\n        ),\n      ),\n    ),\n  );\n  }\n\n  Widget _buildSimplifiedPortraitHud(BuildContext context) {\n    final vehicleSpec = world.currentVehicleSpec;\n    final nearbyBug = world.findNearbyMountableBug(