        const SizedBox(height: 10),\n\n              Container(\n                padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 6),\n                decoration: BoxDecoration(\n                  color: const Color(0xFF17120C),\n                  border: Border.all(color: Colors.white12),\n                  borderRadius: BorderRadius.circular(8),\n                ),\n                child: Row(\n                  mainAxisAlignment: MainAxisAlignment.spaceBetween,\n                  children: [\n                    const Expanded(\n                      child: Text(\n                        'INVERT UP / DOWN LOOK',\n                        style: TextStyle(\n                          color: Color(0xFFF5EBD6),\n                          fontSize: 12.0,\n                          fontWeight: FontWeight.w700,\n                        ),\n                      ),\n                    ),\n                    Switch(\n                      key: const ValueKey('invert_look_y_switch'),\n                      value: _invertLookY,\n                      activeThumbColor: const Color(0xFF8AB858),\n                      onChanged: (val) => setState(() => _invertLookY = val),\n                    ),\n                  ],\n                ),\n              ),\n              const SizedBox(height: 8),\n\n              Row(\n                children: [\n                  const Text(\n                    'LOOK SPEED',\n                    style: TextStyle(\n                      color: Colors.white70,\n                      fontSize: 11.5,\n                      fontWeight: FontWeight.bold,\n                    ),\n                  ),\n                  Expanded(\n                    child: Slider(\n                      key: const ValueKey('look_sensitivity_slider'),\n                      value: _lookSensitivity,\n                      min: 0.4,\n                      max: 2.0,\n                      activeColor: const Color(0xFF8AB858),\n                      onChanged: (v) => setState(() => _lookSensitivity = v),\n                    ),\n                  ),\n                ],\n              ),\n              const SizedBox(height: 10),\n\n              ElevatedButton(\n                style: ElevatedButton.styleFrom(\n                  backgroundColor: const Color(0xFF6B8E3D),\n                  foregroundColor: Colors.white,\n                  padding: const EdgeInsets.symmetric(vertical: 12),\n                ),\n                onPressed: () {\n                  setState(() => _isPaused = false);\n                  _focusNode.requestFocus();\n                },\n                child: const Text(\n                  'RESUME EXPLORATION',\n                  style: TextStyle(fontWeight: FontWeight.w800, letterSpacing: 1.1),\n                ),\n              ),\n              const SizedBox(height: 8),\n\n              OutlinedButton(\n                style: OutlinedButton.styleFrom(\n                  foregroundColor: const Color(0xFFD9C398),\n                  side: const BorderSide(color: Color(0xFFD9C398)),\n                  padding: const EdgeInsets.symmetric(vertical: 12),\n                ),\n                onPressed: () {\n                  world.resetGame();\n                  setState(() => _isPaused = false);\n                  _focusNode.requestFocus();\n                },\n                child: const Text(\n                  'RETURN TO ANTHILL MOUND',\n                  style: TextStyle(fontWeight: FontWeight.w800, letterSpacing: 1.1),\n                ),\n              ),\n            ],\n          ),\n        ),\n      ),\n    );\n  }\n}\n\nclass VirtualJoystick extends StatefulWidget {\n  final String label;\n  final double size;\n  final Color accentColor;\n  final ValueChanged<Offset> onChanged;\n\n  const VirtualJoystick({\n    super.key,\n    required this.label,\n    required this.size,\n    required this.accentColor,\n    required this.onChanged,\n  });\n\n  @override\n  State<VirtualJoystick> createState() => _VirtualJoystickState();\n}\n\nclass _VirtualJoystickState extends State<VirtualJoystick> {\n  Offset _knobOffset = Offset.zero;\n  int? _activePointer;\n\n  void _updateFromLocalPosition(Offset localPos) {\n    final radius = widget.size * 0.5;\n    final maxKnobDist = radius * 0.68;\n    final center = Offset(radius, radius);\n    final delta = localPos - center;\n    final dist = delta.distance;\n    final clampedDelta = dist > maxKnobDist\n        ? Offset.fromDirection(delta.direction, maxKnobDist)\n        : delta;\n\n    setState(() {\n      _knobOffset = clampedDelta;\n    });\n\n    final normalized = Offset(\n      (clampedDelta.dx / maxKnobDist).clamp(-1.0, 1.0),\n      (clampedDelta.dy / maxKnobDist).clamp(-1.0, 1.0),\n    );\n    widget.onChanged(normalized);\n  }\n\n  void _resetJoystick() {\n    setState(() {\n      _knobOffset = Offset.zero;\n      _activePointer = null;\n    });\n    widget.onChanged(Offset.zero);\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final radius = widget.size * 0.5;\n    final knobRadius = widget.size * 0.22;\n\n    return Column(\n      mainAxisSize: MainAxisSize.min,\n      children: [\n        Listener(\n          behavior: HitTestBehavior.opaque,\n          onPointerDown: (e) {\n            if (_activePointer == null) {\n              _activePointer = e.pointer;\n              _updateFromLocalPosition(e.localPosition);\n            }\n          },\n          onPointerMove: (e) {\n            if (e.pointer == _activePointer) {\n              _updateFromLocalPosition(e.localPosition);\n            }\n          },\n          onPointerUp: (e) {\n            if (e.pointer == _activePointer) {\n              _resetJoystick();\n            }\n          },\n          onPointerCancel: (e) {\n            if (e.pointer == _activePointer) {\n              _resetJoystick();\n            }\n          },\n          child: SizedBox(\n            width: widget.size,\n            height: widget.size,\n            child: CustomPaint(\n              painter: _JoystickPainter(\n                knobOffset: _knobOffset,\n                knobRadius: knobRadius,\n                baseRadius: radius,\n                accentColor: widget.accentColor,\n                isActive: _activePointer != null,\n              ),\n            ),\n          ),\n        ),\n        const SizedBox(height: 3),\n        Text(\n          widget.label,\n          style: TextStyle(\n            color: widget.accentColor.withValues(alpha: 0.35),\n            fontSize: 9.0,\n            fontWeight: FontWeight.w800,\n            letterSpacing: 0.8,\n          ),\n        ),\n      ],\n    );\n  }\n}\n\nclass _JoystickPainter extends CustomPainter {\n  final Offset knobOffset;\n  final double knobRadius;\n  final double baseRadius;\n  final Color accentColor;\n  final bool isActive;\n\n  _JoystickPainter({\n    required this.knobOffset,\n    required this.knobRadius,\n    required this.baseRadius,\n    required this.accentColor,\n    required this.isActive,\n  });\n\n  @override\n  void paint(Canvas canvas, Size size) {\n    final center = Offset(baseRadius, baseRadius);\n\n    canvas.drawCircle(\n      center,\n      baseRadius - 2,\n      Paint()..color = const Color(0x1516110B),\n    );\n    canvas.drawCircle(\n      center,\n      baseRadius - 2,\n      Paint()\n        ..color = accentColor.withValues(alpha: isActive ? 0.35 : 0.15)\n        ..style = PaintingStyle.stroke\n        ..strokeWidth = isActive ? 1.8 : 1.2,\n    );\n\n    final tickPaint = Paint()\n      ..color = accentColor.withValues(alpha: 0.10)\n      ..strokeWidth = 1.0;\n    canvas.drawLine(\n      Offset(center.dx - baseRadius * 0.55, center.dy),\n      Offset(center.dx + baseRadius * 0.55, center.dy),\n      tickPaint,\n    );\n    canvas.drawLine(\n      Offset(center.dx, center.dy - baseRadius * 0.55),\n      Offset(center.dx, center.dy + baseRadius * 0.55),\n      tickPaint,\n    );\n\n    final knobCenter = center + knobOffset;\n    final knobRect = Rect.fromCircle(center: knobCenter, radius: knobRadius);\n    canvas.drawCircle(\n      knobCenter + const Offset(0, 1.5),\n      knobRadius,\n      Paint()..color = Colors.black.withValues(alpha: 0.12),\n    );\n    canvas.drawCircle(\n      knobCenter,\n      knobRadius,\n      Paint()\n        ..shader = RadialGradient(\n          center: const Alignment(-0.3, -0.3),\n          colors: [\n            Colors.white.withValues(alpha: isActive ? 0.40 : 0.22),\n            accentColor.withValues(alpha: isActive ? 0.35 : 0.18),\n            Color.lerp(accentColor, Colors.black, 0.6)!\n                .withValues(alpha: isActive ? 0.40 : 0.20),\n          ],\n        ).createShader(knobRect),\n    );\n    canvas.drawCircle(\n      knobCenter,\n      knobRadius,\n      Paint()\n        ..color = accentColor.withValues(alpha: isActive ? 0.45 : 0.22)\n        ..style = PaintingStyle.stroke\n        ..strokeWidth = 1.0,\n    );\n  }\n\n  @override\n  bool shouldRepaint(covariant _JoystickPainter oldDelegate) =>\n      oldDelegate.knobOffset != knobOffset || oldDelegate.isActive != isActive;\n}\n\nclass _ControlRow extends StatelessWidget {\n  final String keys;\n  final String desc;\n\n  const _ControlRow(this.keys, this.desc);\n\n  @override\n  Widget build(BuildContext context) {\n    return Padding(\n      padding: const EdgeInsets.symmetric(vertical: 4.0),\n      child: Row(\n        mainAxisAlignment: MainAxisAlignment.spaceBetween,\n        children: [\n          Text(\n            keys,\n            style: const TextStyle(\n              color: Color(0xFFD9C398),\n              fontWeight: FontWeight.w800,\n              fontSize: 11.0,\n            ),\n          ),\n          const SizedBox(width: 10),\n          Flexible(\n            child: Text(\n              desc,\n              textAlign: TextAlign.right,\n              style: const TextStyle(\n                color: Colors.white70,\n                fontSize: 11.0,\n              ),\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n}",
  "lib/apps/resume_app.dart": "import 'package:flutter/material.dart';\nimport 'package:flutter/foundation.dart';\nimport 'package:google_fonts/google_fonts.dart';\nimport 'package:provider/provider.dart';\nimport 'package:pdf/pdf.dart';\nimport 'package:pdf/widgets.dart' as pw;\nimport 'package:printing/printing.dart';\nimport 'package:universal_html/html.dart' as html;\nimport '../models/config_model.dart';\n\nclass ResumeApp extends StatelessWidget {\n  const ResumeApp({super.key});\n\n  Future<void> _generatePdf(AppConfig config) async {\n    final pdf = pw.Document();\n\n    final font = await PdfGoogleFonts.interRegular();\n    final boldFont = await PdfGoogleFonts.interBold();\n    final italicFont = await PdfGoogleFonts.interItalic();\n\n    final theme = pw.ThemeData.withFont(\n      base: font,\n      bold: boldFont,\n      italic: italicFont,\n    );\n\n    final primaryColor = PdfColor.fromHex('#4B0082');\n    final textColor = PdfColors.grey800;\n\n    pdf.addPage(\n      pw.MultiPage(\n        pageTheme: pw.PageTheme(\n          theme: theme,\n          margin: const pw.EdgeInsets.all(40),\n        ),\n        build: (pw.Context context) {\n          return [\n\n            pw.Container(\n              padding: const pw.EdgeInsets.only(bottom: 40),\n              child: pw.Row(\n                crossAxisAlignment: pw.CrossAxisAlignment.center,\n                children: [\n                  pw.Expanded(\n                    child: pw.Column(\n                      crossAxisAlignment: pw.CrossAxisAlignment.start,\n                      children: [\n                        pw.Text(\n                          config.profile.name,\n                          style: pw.TextStyle(\n                            fontSize: 32,\n                            fontWeight: pw.FontWeight.bold,\n                            color: primaryColor,\n                            letterSpacing: 2,\n                          ),\n                        ),\n                        pw.SizedBox(height: 8),\n                        pw.Text(\n                          config.profile.title,\n                          style: pw.TextStyle(\n                            fontSize: 18,\n                            color: PdfColors.grey700,\n                          ),\n                        ),\n                      ],\n                    ),\n                  ),\n                  pw.Column(\n                    crossAxisAlignment: pw.CrossAxisAlignment.end,\n                    children: [\n                      if (config.profile.email.isNotEmpty) ...[\n                        pw.Text(\n                          config.profile.email,\n                          style: pw.TextStyle(\n                            color: primaryColor,\n                            fontSize: 12,\n                          ),\n                        ),\n                        pw.SizedBox(height: 4),\n                      ],\n                      if (config.profile.location.isNotEmpty) ...[\n                        pw.Text(\n                          config.profile.location,\n                          style: pw.TextStyle(\n                            color: primaryColor,\n                            fontSize: 12,\n                          ),\n                        ),\n                        pw.SizedBox(height: 4),\n                      ],\n                      pw.Text(\n                        'github.com/archieBTW',\n                        style: pw.TextStyle(color: primaryColor, fontSize: 12),\n                      ),\n                    ],\n                  ),\n                ],\n              ),\n            ),\n\n            pw.Row(\n              crossAxisAlignment: pw.CrossAxisAlignment.start,\n              children: [\n\n                pw.Expanded(\n                  flex: 2,\n                  child: pw.Column(\n                    crossAxisAlignment: pw.CrossAxisAlignment.start,\n                    children: [\n                      pw.Text(\n                        'PROFESSIONAL EXPERIENCE',\n                        style: pw.TextStyle(\n                          fontWeight: pw.FontWeight.bold,\n                          fontSize: 11,\n                          color: primaryColor,\n                        ),\n                      ),\n                      pw.SizedBox(height: 12),\n                      ...config.experience\n                          .map(\n                            (e) => pw.Column(\n                              crossAxisAlignment: pw.CrossAxisAlignment.start,\n                              children: [\n                                pw.Text(\n                                  e.role,\n                                  style: pw.TextStyle(\n                                    fontWeight: pw.FontWeight.bold,\n                                    fontSize: 11,\n                                    color: PdfColors.black,\n                                  ),\n                                ),\n                                pw.SizedBox(height: 2),\n                                pw.Row(\n                                  mainAxisAlignment:\n                                      pw.MainAxisAlignment.spaceBetween,\n                                  children: [\n                                    pw.Text(\n                                      e.company,\n                                      style: pw.TextStyle(\n                                        fontStyle: pw.FontStyle.italic,\n                                        color: PdfColors.grey700,\n                                        fontSize: 11,\n                                      ),\n                                    ),\n                                    pw.Text(\n                                      e.period,\n                                      style: pw.TextStyle(\n                                        color: primaryColor,\n                                        fontSize: 10,\n                                      ),\n                                    ),\n                                  ],\n                                ),\n                                pw.SizedBox(height: 6),\n                                pw.Text(\n                                  e.description,\n                                  style: pw.TextStyle(\n                                    fontSize: 11,\n                                    color: textColor,\n                                    lineSpacing: 1.5,\n                                  ),\n                                ),\n                                pw.SizedBox(height: 20),\n                              ],\n                            ),\n                          )\n                          .toList(),\n\n                      pw.SizedBox(height: 10),\n                      pw.Text(\n                        'EDUCATION',\n                        style: pw.TextStyle(\n                          fontWeight: pw.FontWeight.bold,\n                          fontSize: 11,\n                          color: primaryColor,\n                        ),\n                      ),\n                      pw.SizedBox(height: 12),\n                      ...config.education\n                          .map(\n                            (e) => pw.Column(\n                              crossAxisAlignment: pw.CrossAxisAlignment.start,\n                              children: [\n                                pw.Row(\n                                  mainAxisAlignment:\n                                      pw.MainAxisAlignment.spaceBetween,\n                                  children: [\n                                    pw.Text(\n                                      e.school,\n                                      style: pw.TextStyle(\n                                        fontWeight: pw.FontWeight.bold,\n                                        fontSize: 12,\n                                      ),\n                                    ),\n                                    pw.Text(\n                                      e.period,\n                                      style: pw.TextStyle(\n                                        color: primaryColor,\n                                        fontSize: 11,\n                                      ),\n                                    ),\n                                  ],\n                                ),\n                                if (e.degree.isNotEmpty) ...[\n                                  pw.SizedBox(height: 2),\n                                  pw.Text(\n                                    e.degree,\n                                    style: pw.TextStyle(\n                                      fontStyle: pw.FontStyle.italic,\n                                      color: PdfColors.grey700,\n                                      fontSize: 11,\n                                    ),\n                                  ),\n                                ],\n                                pw.SizedBox(height: 16),\n                              ],\n                            ),\n                          )\n                          .toList(),\n                    ],\n                  ),\n                ),\n\n                pw.SizedBox(width: 40),\n\n                pw.Expanded(\n                  flex: 1,\n                  child: pw.Column(\n                    crossAxisAlignment: pw.CrossAxisAlignment.start,\n                    children: [\n                      ...config.skills\n                          .map(\n                            (skillGroup) => pw.Column(\n                              crossAxisAlignment: pw.CrossAxisAlignment.start,\n                              children: [\n                                pw.Text(\n                                  skillGroup.category.toUpperCase(),\n                                  style: pw.TextStyle(\n                                    fontWeight: pw.FontWeight.bold,\n                                    fontSize: 11,\n                                    color: primaryColor,\n                                  ),\n                                ),\n                                pw.SizedBox(height: 6),\n                                pw.Wrap(\n                                  spacing: 6,\n                                  runSpacing: 6,\n                                  children: skillGroup.items\n                                      .map(\n                                        (s) => pw.Text(\n                                          s,\n                                          style: pw.TextStyle(\n                                            fontSize: 10,\n                                            color: PdfColors.grey800,\n                                          ),\n                                        ),\n                                      )\n                                      .toList(),\n                                ),\n                                pw.SizedBox(height: 16),\n                              ],\n                            ),\n                          )\n                          .toList(),\n\n                      if (config.certifications.isNotEmpty) ...[\n                        pw.SizedBox(height: 10),\n                        pw.Text(\n                          'CERTIFICATIONS',\n                          style: pw.TextStyle(\n                            fontWeight: pw.FontWeight.bold,\n                            fontSize: 11,\n                            color: primaryColor,\n                          ),\n                        ),\n                        pw.SizedBox(height: 12),\n                        pw.Wrap(\n                          spacing: 6,\n                          runSpacing: 6,\n                          children: config.certifications\n                              .map(\n                                (c) => pw.Text(\n                                  c,\n                                  style: pw.TextStyle(\n                                    fontSize: 10,\n                                    color: PdfColors.grey800,\n                                  ),\n                                ),\n                              )\n                              .toList(),\n                        ),\n                      ],\n                    ],\n                  ),\n                ),\n              ],\n            ),\n          ];\n        },\n      ),\n    );\n\n    final bytes = await pdf.save();\n    final filename =\n        '\${config.profile.name.toLowerCase().replaceAll(' ', '_')}_resume.pdf';\n\n    if (kIsWeb) {\n      final blob = html.Blob([bytes], 'application/pdf');\n      final url = html.Url.createObjectUrlFromBlob(blob);\n      final anchor = html.document.createElement('a') as html.AnchorElement\n        ..href = url\n        ..style.display = 'none'\n        ..download = filename;\n      html.document.body?.children.add(anchor);\n      anchor.click();\n      html.document.body?.children.remove(anchor);\n      html.Url.revokeObjectUrl(url);\n    } else {\n      await Printing.sharePdf(bytes: bytes, filename: filename);\n    }\n  }\n\n  pw.Widget _buildSectionHeader(String title, PdfColor color) {\n    return pw.Column(\n      crossAxisAlignment: pw.CrossAxisAlignment.start,\n      children: [\n        pw.Text(\n          title,\n          style: pw.TextStyle(\n            fontSize: 14,\n            fontWeight: pw.FontWeight.bold,\n            color: color,\n            letterSpacing: 1.2,\n          ),\n        ),\n        pw.SizedBox(height: 4),\n        pw.Container(height: 2, width: 30, color: color),\n        pw.SizedBox(height: 16),\n      ],\n    );\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final config = context.watch<AppConfig>();\n\n    final List<Color> categoryColors = [\n      const Color(0xFFE6E6FA),\n      const Color(0xFFD4F1F4),\n      const Color(0xFFE2F0CB),\n      const Color(0xFFFFDAB9),\n      const Color(0xFFFDE8E9),\n    ];\n\n    return Scaffold(\n      backgroundColor: Colors.transparent,\n      floatingActionButton: FloatingActionButton(\n        onPressed: () => _generatePdf(config),\n        tooltip: 'Download PDF',\n        child: const Icon(Icons.picture_as_pdf),\n      ),\n      body: SingleChildScrollView(\n        padding: const EdgeInsets.all(40),\n        child: Column(\n          crossAxisAlignment: CrossAxisAlignment.start,\n          children: [\n            Row(\n              children: [\n                CircleAvatar(\n                  radius: 40,\n                  backgroundImage: AssetImage(config.profile.profilePic),\n                ),\n                const SizedBox(width: 24),\n                Expanded(\n                  child: Column(\n                    crossAxisAlignment: CrossAxisAlignment.start,\n                    children: [\n                      Text(\n                        config.profile.name,\n                        style: GoogleFonts.outfit(\n                          color: Theme.of(context).colorScheme.onSurface,\n                          fontSize: 32,\n                          fontWeight: FontWeight.bold,\n                        ),\n                      ),\n                      Text(\n                        config.profile.title,\n                        style: GoogleFonts.inter(\n                          color: Theme.of(\n                            context,\n                          ).colorScheme.onSurface.withValues(alpha: 0.7),\n                          fontSize: 16,\n                        ),\n                      ),\n                    ],\n                  ),\n                ),\n              ],\n            ),\n            const SizedBox(height: 40),\n            _Section(\n              title: 'Experience',\n              children: config.experience\n                  .map(\n                    (item) => _ExperienceItem(\n                      company: item.company,\n                      role: item.role,\n                      period: item.period,\n                      description: item.description,\n                    ),\n                  )\n                  .toList(),\n            ),\n            const SizedBox(height: 32),\n            if (config.education.isNotEmpty) ...[\n              _Section(\n                title: 'Education',\n                children: config.education\n                    .map(\n                      (item) => _EducationItem(\n                        school: item.school,\n                        degree: item.degree,\n                        period: item.period,\n                      ),\n                    )\n                    .toList(),\n              ),\n              const SizedBox(height: 32),\n            ],\n            if (config.certifications.isNotEmpty) ...[\n              _Section(\n                title: 'Certifications',\n                children: [\n                  Wrap(\n                    spacing: 12,\n                    runSpacing: 12,\n                    children: config.certifications\n                        .map(\n                          (cert) => _SkillChip(\n                            label: cert,\n                            outlineColor: Theme.of(\n                              context,\n                            ).colorScheme.onSurface.withValues(alpha: 0.2),\n                          ),\n                        )\n                        .toList(),\n                  ),\n                ],\n              ),\n              const SizedBox(height: 32),\n            ],\n            _Section(\n              title: 'Skills',\n              children: config.skills.asMap().entries.map((entry) {\n                final index = entry.key;\n                final skillGroup = entry.value;\n                final color = categoryColors[index % categoryColors.length];\n\n                return Padding(\n                  padding: const EdgeInsets.only(bottom: 16),\n                  child: Column(\n                    crossAxisAlignment: CrossAxisAlignment.start,\n                    children: [\n                      Text(\n                        skillGroup.category,\n                        style: GoogleFonts.inter(\n                          color: Theme.of(context).colorScheme.onSurface,\n                          fontSize: 14,\n                          fontWeight: FontWeight.w600,\n                        ),\n                      ),\n                      const SizedBox(height: 8),\n                      Wrap(\n                        spacing: 8,\n                        runSpacing: 8,\n                        children: skillGroup.items\n                            .map(\n                              (skill) =>\n                                  _SkillChip(label: skill, outlineColor: color),\n                            )\n                            .toList(),\n                      ),\n                    ],\n                  ),\n                );\n              }).toList(),\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n}\n\nclass _Section extends StatelessWidget {\n  final String title;\n  final List<Widget> children;\n\n  const _Section({required this.title, required this.children});\n\n  @override\n  Widget build(BuildContext context) {\n    return Column(\n      crossAxisAlignment: CrossAxisAlignment.start,\n      children: [\n        Text(\n          title.toUpperCase(),\n          style: GoogleFonts.inter(\n            color: Theme.of(context).colorScheme.primary,\n            fontSize: 14,\n            fontWeight: FontWeight.bold,\n            letterSpacing: 1.2,\n          ),\n        ),\n        Divider(\n          color: Theme.of(context).colorScheme.onSurface.withValues(alpha: 0.1),\n          height: 24,\n        ),\n        ...children,\n      ],\n    );\n  }\n}\n\nclass _ExperienceItem extends StatelessWidget {\n  final String company;\n  final String role;\n  final String period;\n  final String description;\n\n  const _ExperienceItem({\n    required this.company,\n    required this.role,\n    required this.period,\n    required this.description,\n  });\n\n  @override\n  Widget build(BuildContext context) {\n    return Padding(\n      padding: const EdgeInsets.only(bottom: 24),\n      child: Column(\n        crossAxisAlignment: CrossAxisAlignment.start,\n        children: [\n          Row(\n            mainAxisAlignment: MainAxisAlignment.spaceBetween,\n            crossAxisAlignment: CrossAxisAlignment.start,\n            children: [\n              Expanded(\n                child: Text(\n                  role,\n                  style: GoogleFonts.inter(\n                    color: Theme.of(context).colorScheme.onSurface,\n                    fontSize: 18,\n                    fontWeight: FontWeight.bold,\n                  ),\n                ),\n              ),\n              const SizedBox(width: 8),\n              Text(\n                period,\n                style: GoogleFonts.inter(\n                  color: Theme.of(\n                    context,\n                  ).colorScheme.onSurface.withValues(alpha: 0.5),\n                  fontSize: 14,\n                ),\n              ),\n            ],\n          ),\n          Text(\n            company,\n            style: GoogleFonts.inter(\n              color: Theme.of(\n                context,\n              ).colorScheme.onSurface.withValues(alpha: 0.7),\n              fontSize: 16,\n            ),\n          ),\n          const SizedBox(height: 8),\n          Text(\n            description,\n            style: GoogleFonts.inter(\n              color: Theme.of(\n                context,\n              ).colorScheme.onSurface.withValues(alpha: 0.5),\n              fontSize: 14,\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n}\n\nclass _SkillChip extends StatelessWidget {\n  final String label;\n  final Color outlineColor;\n\n  const _SkillChip({\n    required this.label,\n    this.outlineColor = const Color.fromARGB(255, 114, 64, 127),\n  });\n\n  @override\n  Widget build(BuildContext context) {\n    return Container(\n      padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 8),\n      decoration: BoxDecoration(\n        color: Theme.of(context).colorScheme.onSurface.withValues(alpha: 0.05),\n        borderRadius: BorderRadius.circular(20),\n        border: Border.all(\n          color: Color.fromARGB(255, 114, 64, 127),\n          width: 0.5,\n        ),\n      ),\n      child: Text(\n        label,\n        style: GoogleFonts.inter(\n          color: Theme.of(context).colorScheme.onSurface.withValues(alpha: 0.7),\n          fontSize: 14,\n          fontWeight: FontWeight.w500,\n        ),\n      ),\n    );\n  }\n}\n\nclass _EducationItem extends StatelessWidget {\n  final String school;\n  final String degree;\n  final String period;\n\n  const _EducationItem({\n    required this.school,\n    required this.degree,\n    required this.period,\n  });\n\n  @override\n  Widget build(BuildContext context) {\n    return Padding(\n      padding: const EdgeInsets.only(bottom: 24),\n      child: Column(\n        crossAxisAlignment: CrossAxisAlignment.start,\n        children: [\n          Row(\n            mainAxisAlignment: MainAxisAlignment.spaceBetween,\n            crossAxisAlignment: CrossAxisAlignment.start,\n            children: [\n              Expanded(\n                child: Text(\n                  school,\n                  style: GoogleFonts.inter(\n                    color: Theme.of(context).colorScheme.onSurface,\n                    fontSize: 18,\n                    fontWeight: FontWeight.bold,\n                  ),\n                ),\n              ),\n              const SizedBox(width: 8),\n              Text(\n                period,\n                style: GoogleFonts.inter(\n                  color: Theme.of(\n                    context,\n                  ).colorScheme.onSurface.withValues(alpha: 0.5),\n                  fontSize: 14,\n                ),\n              ),\n            ],\n          ),\n          if (degree.isNotEmpty) ...[\n            const SizedBox(height: 4),\n            Text(\n              degree,\n              style: GoogleFonts.inter(\n                color: Theme.of(\n                  context,\n                ).colorScheme.onSurface.withValues(alpha: 0.7),\n                fontSize: 16,\n              ),\n            ),\n          ],\n        ],\n      ),\n    );\n  }\n}",
  "lib/apps/browser_app.dart": "import 'package:flutter/material.dart';\nimport 'package:google_fonts/google_fonts.dart';\nimport 'dart:ui_web' as ui;\nimport 'dart:html' as html;\n\nclass BrowserApp extends StatefulWidget {\n  final String url;\n  const BrowserApp({super.key, required this.url});\n\n  @override\n  State<BrowserApp> createState() => _BrowserAppState();\n}\n\nclass _BrowserAppState extends State<BrowserApp> {\n  late String _viewId;\n\n  @override\n  void initState() {\n    super.initState();\n    _viewId = 'iframe-\${widget.url.hashCode}';\n\n    ui.platformViewRegistry.registerViewFactory(\n      _viewId,\n      (int viewId) => html.IFrameElement()\n        ..src = widget.url\n        ..style.border = 'none'\n        ..style.width = '100%'\n        ..style.height = '100%',\n    );\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return Column(\n      children: [\n        Container(\n          padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),\n          color: Colors.black45,\n          child: Row(\n            children: [\n              const Icon(Icons.lock, size: 14, color: Colors.green),\n              const SizedBox(width: 8),\n              Expanded(\n                child: Container(\n                  padding: const EdgeInsets.symmetric(\n                    horizontal: 8,\n                    vertical: 4,\n                  ),\n                  decoration: BoxDecoration(\n                    color: Colors.white10,\n                    borderRadius: BorderRadius.circular(4),\n                  ),\n                  child: Text(\n                    widget.url,\n                    style: GoogleFonts.inter(\n                      color: Colors.white70,\n                      fontSize: 12,\n                    ),\n                  ),\n                ),\n              ),\n              const SizedBox(width: 8),\n              const Icon(Icons.refresh, size: 16, color: Colors.white54),\n            ],\n          ),\n        ),\n\n        Expanded(child: HtmlElementView(viewType: _viewId)),\n      ],\n    );\n  }\n}",
  "lib/apps/code_editor_app.dart": "import 'package:flutter/material.dart';\nimport 'package:google_fonts/google_fonts.dart';\nimport 'package:flutter_highlight/flutter_highlight.dart';\nimport 'package:flutter_highlight/themes/vs2015.dart';\nimport '../generated/source_code.dart';\n\nclass FileNode {\n  final String name;\n  final String? fullPath;\n  final List<FileNode> children;\n\n  FileNode({required this.name, this.fullPath, List<FileNode>? children})\n    : children = children ?? [];\n\n  bool get isFile => fullPath != null;\n}\n\nclass CodeEditorApp extends StatefulWidget {\n  const CodeEditorApp({super.key});\n\n  @override\n  State<CodeEditorApp> createState() => _CodeEditorAppState();\n}\n\nclass _CodeEditorAppState extends State<CodeEditorApp> {\n  String? _selectedFile = 'lib/main.dart';\n\n  String _detectLanguage(String? path) {\n    if (path == null) return 'dart';\n    final lower = path.toLowerCase();\n    if (lower.endsWith('.yaml') || lower.endsWith('.yml')) return 'yaml';\n    if (lower.endsWith('.json')) return 'json';\n    if (lower.endsWith('.tf')) return 'yaml';\n    if (lower.endsWith('.conf') || lower.endsWith('.j2')) return 'nginx';\n    if (lower.endsWith('.sh') || lower.endsWith('.bash')) return 'bash';\n    return 'dart';\n  }\n\n  Widget _buildCodeViewer(String content, bool isDesktop) {\n    final lines = content.split('\\n');\n    final double fontSize = isDesktop ? 13 : 11;\n\n    return SelectionArea(\n      child: SingleChildScrollView(\n        padding: const EdgeInsets.all(16.0),\n        child: SingleChildScrollView(\n          scrollDirection: Axis.horizontal,\n          child: Row(\n            crossAxisAlignment: CrossAxisAlignment.start,\n            children: [\n\n              SelectionContainer.disabled(\n                child: Column(\n                  crossAxisAlignment: CrossAxisAlignment.end,\n                  children: List.generate(lines.length, (index) {\n                    return Text(\n                      '\${index + 1}',\n                      style: GoogleFonts.jetBrainsMono(\n                        fontSize: fontSize,\n                        color: Colors.white38,\n                        height: 1.5,\n                      ),\n                    );\n                  }),\n                ),\n              ),\n              const SizedBox(width: 16),\n\n              HighlightView(\n                content,\n                language: _detectLanguage(_selectedFile),\n                theme: vs2015Theme,\n                padding: EdgeInsets.zero,\n                textStyle: GoogleFonts.jetBrainsMono(\n                  fontSize: fontSize,\n                  height: 1.5,\n                ),\n              ),\n            ],\n          ),\n        ),\n      ),\n    );\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final screenWidth = MediaQuery.of(context).size.width;\n    final isDesktop = screenWidth >= 768.0;\n\n    final fileTreeWidget = _FileTreeWidget(\n      files: sourceCodeFiles,\n      selectedFile: _selectedFile,\n      onFileSelected: (path) {\n        setState(() {\n          _selectedFile = path;\n        });\n      },\n    );\n\n    final String? fileName = _selectedFile?.split('/').last;\n    final content = _selectedFile != null\n        ? sourceCodeFiles[_selectedFile!]\n        : null;\n\n    final codeViewerWidget = Container(\n      color: const Color(0xFF1E1E1E),\n      width: double.infinity,\n      height: double.infinity,\n      child: Column(\n        crossAxisAlignment: CrossAxisAlignment.start,\n        children: [\n          if (fileName != null)\n            Container(\n              color: const Color(0xFF252526),\n              child: Row(\n                children: [\n                  Container(\n                    padding: const EdgeInsets.symmetric(\n                      horizontal: 16,\n                      vertical: 8,\n                    ),\n                    decoration: const BoxDecoration(\n                      color: Color(0xFF1E1E1E),\n                      border: Border(\n                        top: BorderSide(color: Colors.blueAccent, width: 2),\n                      ),\n                    ),\n                    child: Row(\n                      children: [\n                        Text(\n                          fileName,\n                          style: GoogleFonts.jetBrainsMono(\n                            color: Colors.white,\n                            fontSize: 13,\n                          ),\n                        ),\n                        const SizedBox(width: 8),\n                        const Icon(\n                          Icons.close,\n                          size: 14,\n                          color: Colors.white54,\n                        ),\n                      ],\n                    ),\n                  ),\n                ],\n              ),\n            ),\n          Expanded(\n            child: content == null\n                ? Center(\n                    child: Text(\n                      'Select a file to view its source code.',\n                      style: GoogleFonts.jetBrainsMono(color: Colors.white54),\n                    ),\n                  )\n                : _buildCodeViewer(content, isDesktop),\n          ),\n        ],\n      ),\n    );\n\n    return Scaffold(\n      backgroundColor: const Color(0xFF1E1E1E),\n      body: isDesktop\n          ? Row(\n              crossAxisAlignment: CrossAxisAlignment.start,\n              children: [\n                SizedBox(width: 250, child: fileTreeWidget),\n                Expanded(child: codeViewerWidget),\n              ],\n            )\n          : Column(\n              children: [\n                Theme(\n                  data: Theme.of(\n                    context,\n                  ).copyWith(dividerColor: Colors.transparent),\n                  child: ExpansionTile(\n                    title: Text(\n                      'Explorer: \$_selectedFile',\n                      style: GoogleFonts.jetBrainsMono(\n                        color: Colors.white70,\n                        fontSize: 12,\n                      ),\n                      maxLines: 1,\n                      overflow: TextOverflow.ellipsis,\n                    ),\n                    iconColor: Colors.white70,\n                    collapsedIconColor: Colors.white70,\n                    backgroundColor: const Color(0xFF252526),\n                    collapsedBackgroundColor: const Color(0xFF252526),\n                    children: [\n                      ConstrainedBox(\n                        constraints: BoxConstraints(\n                          maxHeight: MediaQuery.of(context).size.height * 0.4,\n                        ),\n                        child: _FileTreeWidget(\n                          files: sourceCodeFiles,\n                          selectedFile: _selectedFile,\n                          hideTitle: true,\n                          onFileSelected: (path) {\n                            setState(() {\n                              _selectedFile = path;\n                            });\n                          },\n                        ),\n                      ),\n                    ],\n                  ),\n                ),\n                Expanded(child: codeViewerWidget),\n              ],\n            ),\n    );\n  }\n}\n\nclass _FileTreeWidget extends StatelessWidget {\n  final Map<String, String> files;\n  final String? selectedFile;\n  final ValueChanged<String> onFileSelected;\n  final bool hideTitle;\n\n  const _FileTreeWidget({\n    required this.files,\n    this.selectedFile,\n    required this.onFileSelected,\n    this.hideTitle = false,\n  });\n\n  FileNode _buildTree() {\n    final root = FileNode(name: 'fyrWeb');\n    final libNode = FileNode(name: 'lib');\n    root.children.add(libNode);\n\n    for (final path in files.keys) {\n      final cleanPath = path.startsWith('lib/') ? path.substring(4) : path;\n      final parts = cleanPath.split('/');\n      var current = libNode;\n      for (var i = 0; i < parts.length; i++) {\n        final part = parts[i];\n        final isFile = i == parts.length - 1;\n\n        var child = current.children.cast<FileNode?>().firstWhere(\n          (n) => n!.name == part,\n          orElse: () => null,\n        );\n        if (child == null) {\n          child = FileNode(name: part, fullPath: isFile ? path : null);\n          current.children.add(child);\n        }\n        current = child;\n      }\n    }\n\n    _sortNode(libNode);\n    return root;\n  }\n\n  void _sortNode(FileNode node) {\n    node.children.sort((a, b) {\n      if (a.isFile && !b.isFile) return 1;\n      if (!a.isFile && b.isFile) return -1;\n      return a.name.compareTo(b.name);\n    });\n    for (final child in node.children) {\n      _sortNode(child);\n    }\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final root = _buildTree();\n    return Container(\n      color: const Color(0xFF252526),\n      child: Column(\n        crossAxisAlignment: CrossAxisAlignment.start,\n        children: [\n          if (!hideTitle)\n            Padding(\n              padding: const EdgeInsets.fromLTRB(16, 12, 16, 8),\n              child: Text(\n                'EXPLORER',\n                style: GoogleFonts.jetBrainsMono(\n                  fontSize: 11,\n                  color: Colors.white54,\n                  letterSpacing: 1.2,\n                  fontWeight: FontWeight.bold,\n                ),\n              ),\n            ),\n          Expanded(\n            child: ListView(\n              padding: EdgeInsets.zero,\n              children: [\n                _TreeNodeWidget(\n                  node: root,\n                  level: 0,\n                  selectedFile: selectedFile,\n                  onFileSelected: onFileSelected,\n                  initiallyExpanded: true,\n                ),\n              ],\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n}\n\nclass _TreeNodeWidget extends StatefulWidget {\n  final FileNode node;\n  final int level;\n  final String? selectedFile;\n  final ValueChanged<String> onFileSelected;\n  final bool initiallyExpanded;\n\n  const _TreeNodeWidget({\n    required this.node,\n    required this.level,\n    required this.selectedFile,\n    required this.onFileSelected,\n    this.initiallyExpanded = false,\n  });\n\n  @override\n  State<_TreeNodeWidget> createState() => _TreeNodeWidgetState();\n}\n\nclass _TreeNodeWidgetState extends State<_TreeNodeWidget> {\n  late bool _isExpanded;\n\n  @override\n  void initState() {\n    super.initState();\n    _isExpanded = widget.initiallyExpanded || widget.level <= 1;\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    if (widget.node.isFile) {\n      final isSelected = widget.node.fullPath == widget.selectedFile;\n      return InkWell(\n        onTap: () => widget.onFileSelected(widget.node.fullPath!),\n        child: Container(\n          color: isSelected\n              ? Colors.white.withOpacity(0.1)\n              : Colors.transparent,\n          padding: EdgeInsets.only(\n            left: 16.0 + (widget.level * 12.0),\n            top: 4,\n            bottom: 4,\n            right: 8,\n          ),\n          child: Row(\n            children: [\n              const Icon(\n                Icons.insert_drive_file,\n                size: 14,\n                color: Colors.white70,\n              ),\n              const SizedBox(width: 6),\n              Expanded(\n                child: Text(\n                  widget.node.name,\n                  style: GoogleFonts.jetBrainsMono(\n                    fontSize: 13,\n                    color: isSelected ? Colors.white : Colors.white70,\n                  ),\n                  overflow: TextOverflow.ellipsis,\n                ),\n              ),\n            ],\n          ),\n        ),\n      );\n    } else {\n      return Column(\n        crossAxisAlignment: CrossAxisAlignment.start,\n        children: [\n          InkWell(\n            onTap: () {\n              setState(() {\n                _isExpanded = !_isExpanded;\n              });\n            },\n            child: Container(\n              padding: EdgeInsets.only(\n                left: 8.0 + (widget.level * 12.0),\n                top: 4,\n                bottom: 4,\n                right: 8,\n              ),\n              child: Row(\n                children: [\n                  Icon(\n                    _isExpanded\n                        ? Icons.keyboard_arrow_down\n                        : Icons.keyboard_arrow_right,\n                    size: 16,\n                    color: Colors.white54,\n                  ),\n                  const SizedBox(width: 2),\n                  const Icon(\n                    Icons.folder,\n                    size: 14,\n                    color: Color(0xFF9E75FF),\n                  ),\n                  const SizedBox(width: 6),\n                  Expanded(\n                    child: Text(\n                      widget.node.name,\n                      style: GoogleFonts.jetBrainsMono(\n                        fontSize: 13,\n                        color: Colors.white,\n                        fontWeight: FontWeight.w500,\n                      ),\n                      overflow: TextOverflow.ellipsis,\n                    ),\n                  ),\n                ],\n              ),\n            ),\n          ),\n          if (_isExpanded)\n            ...widget.node.children.map(\n              (child) => _TreeNodeWidget(\n                node: child,\n                level: widget.level + 1,\n                selectedFile: widget.selectedFile,\n                onFileSelected: widget.onFileSelected,\n              ),\n            ),\n        ],\n      );\n    }\n  }\n}",
  "lib/apps/terminal_app.dart": "import 'package:flutter/material.dart';\nimport 'package:google_fonts/google_fonts.dart';\nimport 'package:provider/provider.dart';\nimport '../models/config_model.dart';\n\nclass _FileNode {\n  final String name;\n  final String? content;\n  final bool isDirectory;\n  final Map<String, _FileNode>? children;\n  _FileNode? parent;\n\n  _FileNode({\n    required this.name,\n    this.content,\n    this.isDirectory = false,\n    this.children,\n  }) {\n    children?.values.forEach((child) => child.parent = this);\n  }\n}\n\nclass TerminalApp extends StatefulWidget {\n  const TerminalApp({super.key});\n\n  @override\n  State<TerminalApp> createState() => _TerminalAppState();\n}\n\nclass _TerminalAppState extends State<TerminalApp> {\n  final List<String> _history = [];\n  final TextEditingController _controller = TextEditingController();\n  final ScrollController _scrollController = ScrollController();\n  final FocusNode _focusNode = FocusNode();\n\n  late _FileNode _root;\n  late _FileNode _currentDir;\n\n  @override\n  void initState() {\n    super.initState();\n    _initFileSystem();\n\n    final config = context.read<AppConfig>();\n    _history.addAll([\n      '\${config.profile.systemName} v1.0.0 (tty1) [Debian GNU/Linux 12 x86_64]',\n      'Welcome \${config.profile.terminalName}. Type \"help\" to see available development, SysAdmin & DevOps commands.',\n      '',\n    ]);\n\n    WidgetsBinding.instance.addPostFrameCallback((_) {\n      if (MediaQuery.of(context).size.width >= 600) {\n        _showNeofetch();\n        if (mounted) setState(() {});\n      }\n    });\n  }\n\n  void _initFileSystem() {\n    final config = context.read<AppConfig>();\n    _root = _FileNode(\n      name: '/',\n      isDirectory: true,\n      children: {\n        'home': _FileNode(\n          name: 'home',\n          isDirectory: true,\n          children: {\n            config.profile.terminalName: _FileNode(\n              name: config.profile.terminalName,\n              isDirectory: true,\n              children: {\n                'resume.txt': _FileNode(\n                  name: 'resume.txt',\n                  content:\n                      'Name: \${config.profile.name}\\nTitle: \${config.profile.title}\\nContact: \${config.profile.email}\\nCertifications: LPIC-1, SUSE CLA, Linux+, Network+, A+',\n                ),\n                'notes.txt': _FileNode(\n                  name: 'notes.txt',\n                  content: 'SysAdmin roots -> Full-Stack Developer -> Cloud & DevOps Engineer.',\n                ),\n                'projects': _FileNode(\n                  name: 'projects',\n                  isDirectory: true,\n                  children: {\n                    'stack.txt': _FileNode(\n                      name: 'stack.txt',\n                      content: 'GCP e2-micro, Terraform, Ansible, Docker Compose, Nginx, UFW, Fail2ban, Flutter Web, Go.',\n                    ),\n                  },\n                ),\n              },\n            ),\n          },\n        ),\n        'etc': _FileNode(\n          name: 'etc',\n          isDirectory: true,\n          children: {\n            'sysctl.d': _FileNode(\n              name: 'sysctl.d',\n              isDirectory: true,\n              children: {\n                '99-performance.conf': _FileNode(\n                  name: '99-performance.conf',\n                  content: 'vm.swappiness = 20\\nvm.vfs_cache_pressure = 50\\nnet.ipv4.tcp_syncookies = 1\\nnet.ipv4.conf.all.rp_filter = 1\\nnet.ipv4.conf.all.accept_source_route = 0',\n                ),\n              },\n            ),\n            'nginx': _FileNode(\n              name: 'nginx',\n              isDirectory: true,\n              children: {\n                'nginx.conf': _FileNode(\n                  name: 'nginx.conf',\n                  content: 'events { worker_connections 1024; }\\nhttp {\\n  limit_req_zone \\\$binary_remote_addr zone=static_site:10m rate=30r/s;\\n  limit_req_zone \\\$binary_remote_addr zone=api_zone:10m rate=20r/s;\\n  limit_conn_zone \\\$binary_remote_addr zone=addr:10m;\\n}',\n                ),\n                'sites-available': _FileNode(\n                  name: 'sites-available',\n                  isDirectory: true,\n                  children: {\n                    'bybl.dev.conf': _FileNode(\n                      name: 'bybl.dev.conf',\n                      content: 'server {\\n  server_name bybl.dev www.bybl.dev;\\n  root /var/www/bybl.dev/html;\\n  limit_req zone=static_site burst=50 nodelay;\\n  ssl_protocols TLSv1.2 TLSv1.3;\\n}',\n                    ),\n                    'api.bybl.dev.conf': _FileNode(\n                      name: 'api.bybl.dev.conf',\n                      content: 'server {\\n  server_name api.bybl.dev;\\n  limit_req zone=api_zone burst=30 nodelay;\\n  location / {\\n    proxy_pass http://127.0.0.1:8080;\\n    proxy_set_header Host \\\$host;\\n    proxy_set_header X-Real-IP \\\$remote_addr;\\n  }\\n}',\n                    ),\n                  },\n                ),\n              },\n            ),\n            'fail2ban': _FileNode(\n              name: 'fail2ban',\n              isDirectory: true,\n              children: {\n                'jail.local': _FileNode(\n                  name: 'jail.local',\n                  content: '[sshd]\\nenabled = true\\nmaxretry = 4\\nbantime = 2h\\n\\n[nginx-limit-req]\\nenabled = true\\nport = http,https\\nlogpath = /var/log/nginx/error.log\\nfindtime = 2m\\nmaxretry = 10\\nbantime = 1h\\n\\n[nginx-botsearch]\\nenabled = true\\nport = http,https\\nlogpath = /var/log/nginx/error.log\\nmaxretry = 3\\nbantime = 24h',\n                ),\n              },\n            ),\n          },\n        ),\n        'opt': _FileNode(\n          name: 'opt',\n          isDirectory: true,\n          children: {\n            'WE-IAC': _FileNode(\n              name: 'WE-IAC',\n              isDirectory: true,\n              children: {\n                'architecture.txt': _FileNode(\n                  name: 'architecture.txt',\n                  content: 'Cloudflare DNS -> GCP Firewall -> Host UFW + Fail2ban -> Nginx (Rate Limited) -> Docker Bridge (172.20.0.0/16)',\n                ),\n              },\n            ),\n            'bybl': _FileNode(\n              name: 'bybl',\n              isDirectory: true,\n              children: {\n                'docker-compose.yml': _FileNode(\n                  name: 'docker-compose.yml',\n                  content: 'version: \"3.8\"\\nservices:\\n  bybl-db:\\n    image: postgres:16-alpine\\n    networks:\\n      - app-network\\n    # ZERO HOST PORTS MAPPED (Strict Zero-Trust)\\n  bybl-api:\\n    image: bybl-api:latest\\n    ports:\\n      - \"127.0.0.1:8080:8080\"\\n      - \"127.0.0.1:8081:8081\"\\n    networks:\\n      - app-network',\n                ),\n              },\n            ),\n          },\n        ),\n      },\n    );\n\n    _root.children!['home']!.parent = _root;\n    _root.children!['etc']!.parent = _root;\n    _root.children!['opt']!.parent = _root;\n\n    _currentDir =\n        _root.children!['home']!.children![config.profile.terminalName]!;\n  }\n\n  _FileNode? _getNode(String path) {\n    if (path.isEmpty) return _currentDir;\n\n    _FileNode current = path.startsWith('/') ? _root : _currentDir;\n    final parts = path.split('/').where((p) => p.isNotEmpty).toList();\n\n    for (final part in parts) {\n      if (part == '.') continue;\n      if (part == '~') {\n        final config = context.read<AppConfig>();\n        current =\n            _root.children!['home']!.children![config.profile.terminalName]!;\n        continue;\n      }\n      if (part == '..') {\n        current = current.parent ?? current;\n      } else {\n        if (!current.isDirectory ||\n            current.children == null ||\n            !current.children!.containsKey(part)) {\n          return null;\n        }\n        current = current.children![part]!;\n      }\n    }\n    return current;\n  }\n\n  String _getAbsolutePath(_FileNode node) {\n    if (node == _root) return '/';\n    final List<String> parts = [];\n    _FileNode? current = node;\n    while (current != null && current != _root) {\n      parts.insert(0, current.name);\n      current = current.parent;\n    }\n    return '/\${parts.join('/')}';\n  }\n\n  void _showNeofetch() {\n    final config = context.read<AppConfig>();\n    _history.addAll([\n      '                  %                         \${config.profile.terminalName}@\${config.profile.systemName}',\n      '                  %%%                       ----------------------------------------',\n      '                  % %%%                     OS: Debian GNU/Linux 12 (Bookworm) x86_64',\n      '                 %% %%%                     Host: Google Cloud Compute Engine (e2-micro)',\n      '                %%% %%%  %%                 Kernel: 5.15.0-generic (LPIC-1 Hardened)',\n      '              %%%  %%% %%%                  Uptime: 52 days, 18 hours, 32 mins',\n      '            %%%   %%%%% %                   Packages: 1420 (dpkg), 2 (docker containers)',\n      '           %%%   %% %%  %%                  Shell: zsh 5.9',\n      '          %%%%          %%%                 DE: \${config.profile.systemName}-DE (Flutter Web Shell)',\n      '          %%%%#   % %. %%%%%                WM: fyrWM',\n      '         %%%%% %% % %%%%%%%%%               Firewall: UFW (Default DENY) + Fail2ban',\n      '         %%%%% %% % %%%%%%%%%               Reverse Proxy: Nginx 1.22 (TLS 1.3, Rate-Limited)',\n      '          %%%% %%%% %%%%%%%%%               IaC Engine: Terraform + Ansible (WE-IAC)',\n      '          %%%%%%%%%%%%%%%%%%                CPU: Virtual Core (2) @ 2.20GHz',\n      '            %%%        %%%                  Memory: 718MiB / 1024MiB (RAM) + 224MiB / 2048MiB (Swap)',\n      '               %%%%%%%                      Disk: 8.4G / 20G (pd-balanced rootfs)',\n    ]);\n  }\n\n  void _handleCommand(String input) {\n    final config = context.read<AppConfig>();\n    final promptPath = _getAbsolutePath(\n      _currentDir,\n    ).replaceFirst('/home/\${config.profile.terminalName}', '~');\n\n    setState(() {\n      _history.add(\n        '\${config.profile.terminalName}@\${config.profile.systemName}:\$promptPath\\\$ \$input',\n      );\n\n      final trimmed = input.trim();\n      final parts = trimmed.split(' ').where((s) => s.isNotEmpty).toList();\n      final cmd = parts.isNotEmpty ? parts[0].toLowerCase() : '';\n      final args = parts.length > 1 ? parts.sublist(1) : <String>[];\n\n      switch (cmd) {\n        case 'neofetch':\n          _showNeofetch();\n          break;\n        case 'help':\n          _history.addAll([\n            '=== Built-in Shell & System Commands ===',\n            '  help, clear, whoami, date, uname, uptime, pwd, ls, cd, cat, free, df',\n            '',\n            '=== SysAdmin & Linux Diagnostics ===',\n            '  systemctl status <service>  (e.g. nginx, fail2ban, ufw, docker)',\n            '  ufw status [verbose]        (Inspect host firewall ruleset)',\n            '  htop / top                  (Display real-time process table & load)',\n            '  sysctl -p                   (Inspect kernel memory & socket tuning)',\n            '',\n            '=== DevOps & Cloud Infrastructure ===',\n            '  docker ps                   (List zero-trust containers & port bindings)',\n            '  docker stats                (Inspect container memory/CPU metrics)',\n            '  terraform show              (Inspect managed GCP compute & Cloudflare DNS)',\n            '  ansible-playbook <playbook> (Simulate multi-site deployment orchestration)',\n            '  curl <endpoint>             (Probe internal or external service health)',\n          ]);\n          break;\n        case 'clear':\n          _history.clear();\n          return;\n        case 'pwd':\n          _history.add(_getAbsolutePath(_currentDir));\n          break;\n        case 'ls':\n          final targetPath = args.isNotEmpty ? args[0] : '';\n          final node = _getNode(targetPath);\n          if (node == null) {\n            _history.add('ls: cannot access \\'\$targetPath\\': No such file or directory');\n          } else if (!node.isDirectory) {\n            _history.add(node.name);\n          } else {\n            if (node.children == null || node.children!.isEmpty) {\n\n            } else {\n              final files = node.children!.values\n                  .map((c) => c.isDirectory ? '\${c.name}/' : c.name)\n                  .join('  ');\n              _history.add(files);\n            }\n          }\n          break;\n        case 'cd':\n          final targetPath = args.isNotEmpty ? args[0] : '~';\n          final node = _getNode(targetPath);\n          if (node == null) {\n            _history.add('cd: \$targetPath: No such file or directory');\n          } else if (!node.isDirectory) {\n            _history.add('cd: \$targetPath: Not a directory');\n          } else {\n            _currentDir = node;\n          }\n          break;\n        case 'cat':\n          if (args.isEmpty) {\n            _history.add('cat: missing operand');\n          } else {\n            final node = _getNode(args[0]);\n            if (node == null) {\n              _history.add('cat: \${args[0]}: No such file or directory');\n            } else if (node.isDirectory) {\n              _history.add('cat: \${args[0]}: Is a directory');\n            } else {\n              _history.addAll(node.content?.split('\\n') ?? []);\n            }\n          }\n          break;\n        case 'whoami':\n          _history.add(config.profile.terminalName);\n          break;\n        case 'date':\n          _history.add(DateTime.now().toUtc().toString());\n          break;\n        case 'uname':\n          _history.add('Linux gcp-production-us-central1 5.15.0-generic #1 SMP Debian x86_64 GNU/Linux');\n          break;\n        case 'uptime':\n          _history.add(' 18:54:10 up 52 days, 18:32,  1 user,  load average: 0.18, 0.22, 0.19');\n          break;\n        case 'free':\n        case 'free -h':\n        case 'free -m':\n          _history.addAll([\n            '               total        used        free      shared  buff/cache   available',\n            'Mem:           992Mi       718Mi       184Mi        12Mi        90Mi       262Mi',\n            'Swap:         2047Mi       224Mi      1823Mi',\n          ]);\n          break;\n        case 'df':\n        case 'df -h':\n          _history.addAll([\n            'Filesystem      Size  Used Avail Use% Mounted on',\n            '/dev/root        20G  8.4G   11G  42% /',\n            'tmpfs           496M     0  496M   0% /dev/shm',\n            'tmpfs           199M  1.1M  198M   1% /run',\n          ]);\n          break;\n        case 'sysctl':\n        case 'sysctl -p':\n          _history.addAll([\n            'vm.swappiness = 20',\n            'vm.vfs_cache_pressure = 50',\n            'net.ipv4.tcp_syncookies = 1',\n            'net.ipv4.conf.all.rp_filter = 1',\n            'net.ipv4.conf.all.accept_source_route = 0',\n          ]);\n          break;\n        case 'docker':\n          final sub = args.isNotEmpty ? args[0] : '';\n          if (sub == 'ps') {\n            _history.addAll([\n              'CONTAINER ID   IMAGE                          COMMAND                  CREATED        STATUS                   PORTS                                            NAMES',\n              'f8b21c4e90a1   friendly-social-backend:latest \"java -jar app.jar\"      2 days ago     Up 2 days (healthy)      127.0.0.1:8070->8070/tcp                         friendly-social-backend',\n              'c3d9014f77b2   postgres:16-alpine             \"docker-entrypoint.s…\"   2 days ago     Up 2 days (healthy)      5432/tcp [friendly-social-network bridge only]   friendly-social-postgres',\n              'a4f891b2c3d1   bybl-api:latest                \"/app/bybl-api\"          4 days ago     Up 4 days (healthy)      127.0.0.1:8080->8080/tcp, 127.0.0.1:8081->8081   bybl-api',\n              'e7c9103a228f   postgres:15-alpine             \"docker-entrypoint.s…\"   4 days ago     Up 4 days (healthy)      5432/tcp [app-network bridge only]               bybl-db',\n            ]);\n          } else if (sub == 'stats') {\n            _history.addAll([\n              'CONTAINER ID   NAME       CPU %     MEM USAGE / LIMIT     MEM %     NET I/O           BLOCK I/O         PIDS',\n              'a4f891b2c3d1   bybl-api   0.45%     84.2MiB / 992MiB      8.48%     142MB / 1.1GB     12.4MB / 4.2MB    12',\n              'e7c9103a228f   bybl-db    0.12%     142.1MiB / 992MiB     14.32%    1.1GB / 142MB     68.1MB / 180MB    9',\n            ]);\n          } else if (sub == 'images') {\n            _history.addAll([\n              'REPOSITORY           TAG       IMAGE ID       CREATED        SIZE',\n              'bybl-api             latest    a4f891b2c3d1   4 days ago     64.2MB',\n              'postgres             15-alpine e7c9103a228f   2 weeks ago    88.5MB',\n            ]);\n          } else {\n            _history.add('Usage: docker [ps | stats | images]');\n          }\n          break;\n        case 'systemctl':\n          final sub = args.isNotEmpty ? args[0] : '';\n          final unit = args.length > 1 ? args[1] : '';\n          if (sub == 'status') {\n            if (unit.contains('nginx')) {\n              _history.addAll([\n                '● nginx.service - A high performance web server and a reverse proxy server',\n                '     Loaded: loaded (/lib/systemd/system/nginx.service; enabled; vendor preset: enabled)',\n                '     Active: active (running) since Sun 2026-10-18 04:12:08 UTC; 19 days ago',\n                '   Main PID: 1824 (nginx)',\n                '      Tasks: 3 (limit: 1146)',\n                '     Memory: 28.4M',\n                '        CPU: 18min 42.102s',\n                '     CGroup: /system.slice/nginx.service',\n                '             ├─1824 nginx: master process /usr/sbin/nginx -g daemon on; master_process on;',\n                '             ├─1825 nginx: worker process (static_site zone active: 30r/s)',\n                '             └─1826 nginx: worker process (api_zone active: 20r/s)',\n              ]);\n            } else if (unit.contains('fail2ban')) {\n              _history.addAll([\n                '● fail2ban.service - Fail2Ban Service',\n                '     Loaded: loaded (/lib/systemd/system/fail2ban.service; enabled; vendor preset: enabled)',\n                '     Active: active (running) since Sun 2026-10-18 04:11:15 UTC; 19 days ago',\n                '   Jails (3): sshd, nginx-limit-req, nginx-botsearch',\n                '   Currently banned IPs: 0 (total banned: 42)',\n              ]);\n            } else if (unit.contains('ufw')) {\n              _history.addAll([\n                '● ufw.service - Uncomplicated firewall',\n                '     Loaded: loaded (/lib/systemd/system/ufw.service; enabled; vendor preset: enabled)',\n                '     Active: active (exited) since Sun 2026-10-18 04:10:40 UTC; 19 days ago',\n                '     Status: Firewalled with Netfilter iptables (Default DENY)',\n              ]);\n            } else if (unit.contains('docker')) {\n              _history.addAll([\n                '● docker.service - Docker Application Container Engine',\n                '     Loaded: loaded (/lib/systemd/system/docker.service; enabled; vendor preset: enabled)',\n                '     Active: active (running) since Sun 2026-10-18 04:11:02 UTC; 19 days ago',\n                '   Network: app-network (172.20.0.0/16)',\n              ]);\n            } else {\n              _history.add('Unit \$unit is active (running)');\n            }\n          } else {\n            _history.add('Usage: systemctl status <nginx | fail2ban | ufw | docker>');\n          }\n          break;\n        case 'ufw':\n          _history.addAll([\n            'Status: active',\n            'Logging: on (low)',\n            'Default: deny (incoming), allow (outgoing), disabled (routed)',\n            'New profiles: skip',\n            '',\n            'To                         Action      From',\n            '--                         ------      ----',\n            '22/tcp                     LIMIT IN    Anywhere                   # sshd rate-limited',\n            '80/tcp                     ALLOW IN    Anywhere                   # Certbot ACME & HTTP',\n            '443/tcp                    ALLOW IN    Anywhere                   # HTTPS TLS 1.3',\n            '5432                       DENY IN     Anywhere                   # Postgres host isolation',\n            '8080-8081                 DENY IN     Anywhere                   # Backend local proxy only',\n          ]);\n          break;\n        case 'terraform':\n          final sub = args.isNotEmpty ? args[0] : '';\n          if (sub == 'show' || sub == 'state' || sub.isEmpty) {\n            _history.addAll([\n              '# Managed by Terraform (WE-IAC)',\n              'google_compute_address.static_ip: (34.174.x.x reserved)',\n              'google_compute_instance.web_server: (e2-micro in us-central1-a, pd-balanced 20GB)',\n              'cloudflare_record.bybl_a: (A -> 34.174.x.x, proxied = false)',\n              'cloudflare_record.api_bybl: (A -> 34.174.x.x, proxied = false)',\n              'cloudflare_record.archbtw: (A -> 34.174.x.x, proxied = false)',\n              'cloudflare_record.libretrac: (A -> 34.174.x.x, proxied = false)',\n              'cloudflare_record.archerwoods: (A -> 34.174.x.x, proxied = false)',\n              'Outputs: instance_public_ip = \"34.174.x.x\", inventory_path = \"../ansible/inventory.ini\"',\n            ]);\n          } else {\n            _history.add('Usage: terraform show');\n          }\n          break;\n        case 'ansible-playbook':\n          _history.addAll([\n            'PLAY [Provision and Deploy Web Infrastructure] *********************************',\n            '',\n            'TASK [Gathering Facts] *********************************************************',\n            'ok: [gcp-web]',\n            '',\n            'TASK [common : Configure 2GB swap space and kernel sysctl] *********************',\n            'ok: [gcp-web]',\n            '',\n            'TASK [firewall : Configure UFW rules & Fail2ban jails] *************************',\n            'ok: [gcp-web]',\n            '',\n            'TASK [docker : Ensure Docker engine & internal app-network exist] **************',\n            'ok: [gcp-web]',\n            '',\n            'TASK [nginx : Deploy virtualhost configs with rate-limiting zones] *************',\n            'changed: [gcp-web]',\n            '',\n            'TASK [static_sites : Synchronize compiled web artifacts] **********************',\n            'changed: [gcp-web]',\n            '',\n            'PLAY RECAP *********************************************************************',\n            'gcp-web                    : ok=28   changed=2    unreachable=0    failed=0    skipped=3',\n          ]);\n          break;\n        case 'htop':\n        case 'top':\n          _history.addAll([\n            'top - 18:54:30 up 52 days, 18:32,  1 user,  load average: 0.18, 0.22, 0.19',\n            'Tasks:  78 total,   1 running,  77 sleeping,   0 stopped,   0 zombie',\n            '%Cpu(s):  2.1 us,  1.4 sy,  0.0 ni, 96.2 id,  0.3 wa,  0.0 hi,  0.0 si',\n            'MiB Mem :    992.0 total,    184.2 free,    718.0 used,     89.8 buff/cache',\n            'MiB Swap:   2048.0 total,   1824.0 free,    224.0 used.    262.0 avail Mem',\n            '',\n            '  PID USER      PR  NI    VIRT    RES    SHR S  %CPU  %MEM     TIME+ COMMAND',\n            ' 1824 www-data  20   0  142104  28412  11200 S   1.8   2.8  18:42.10 nginx',\n            ' 2401 root      20   0  712400  84210  32104 S   0.9   8.5  42:15.30 bybl-api',\n            ' 2390 postgres  20   0  384120 142110  28900 S   0.4  14.3  14:02.12 postgres',\n            ' 1120 root      20   0   48120  14200   8120 S   0.1   1.4   4:10.15 fail2ban-server',\n          ]);\n          break;\n        case 'curl':\n          final target = args.isNotEmpty ? args[0] : '';\n          _history.addAll([\n            'HTTP/2 200 OK',\n            'server: nginx/1.22.1',\n            'date: \${DateTime.now().toUtc()}',\n            'content-type: application/json; charset=utf-8',\n            'strict-transport-security: max-age=31536000; includeSubDomains',\n            'x-rate-limit: active (static: 30r/s, api: 20r/s)',\n            '',\n            '{\"status\":\"healthy\",\"target\":\"\$target\",\"service\":\"operational\",\"env\":\"production\"}',\n          ]);\n          break;\n        case '':\n          break;\n        default:\n          _history.add('Command not found: \$cmd. Type \"help\" to see available commands.');\n      }\n      _history.add('');\n    });\n\n    _controller.clear();\n    _focusNode.requestFocus();\n    Future.delayed(const Duration(milliseconds: 100), () {\n      if (_scrollController.hasClients) {\n        _scrollController.animateTo(\n          _scrollController.position.maxScrollExtent,\n          duration: const Duration(milliseconds: 200),\n          curve: Curves.easeOut,\n        );\n      }\n    });\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final isDark = Theme.of(context).brightness == Brightness.dark;\n    final config = context.watch<AppConfig>();\n    final promptPath = _getAbsolutePath(\n      _currentDir,\n    ).replaceFirst('/home/\${config.profile.terminalName}', '~');\n\n    return GestureDetector(\n      onTap: () => _focusNode.requestFocus(),\n      child: Container(\n        color: isDark ? const Color(0xFF0C0E12) : Colors.black87,\n        padding: const EdgeInsets.all(14),\n        child: SingleChildScrollView(\n          controller: _scrollController,\n          child: Column(\n            crossAxisAlignment: CrossAxisAlignment.start,\n            children: [\n              ..._history.map(\n                (line) => Text(\n                  line,\n                  style: GoogleFonts.jetBrainsMono(\n                    color: line.startsWith('PLAY RECAP') || line.contains('HEALTHY') || line.contains('ok=')\n                        ? Colors.greenAccent\n                        : line.contains('changed:') || line.contains('changed=')\n                            ? Colors.amberAccent\n                            : line.contains('failed=') && !line.contains('failed=0')\n                                ? Colors.redAccent\n                                : line.startsWith('===')\n                                    ? const Color(0xFF00B0FF)\n                                    : Colors.greenAccent.withValues(alpha: 0.9),\n                    fontSize: 13,\n                    height: 1.4,\n                  ),\n                ),\n              ),\n              Row(\n                children: [\n                  Text(\n                    '\${config.profile.terminalName}@\${config.profile.systemName}:\$promptPath\\\$ ',\n                    style: GoogleFonts.jetBrainsMono(\n                      color: const Color(0xFF00B0FF),\n                      fontSize: 13,\n                      fontWeight: FontWeight.bold,\n                    ),\n                  ),\n                  Expanded(\n                    child: TextField(\n                      controller: _controller,\n                      focusNode: _focusNode,\n                      autofocus: true,\n                      cursorColor: Colors.greenAccent,\n                      style: GoogleFonts.jetBrainsMono(\n                        color: Colors.white,\n                        fontSize: 13,\n                      ),\n                      decoration: const InputDecoration(\n                        border: InputBorder.none,\n                        isDense: true,\n                        contentPadding: EdgeInsets.zero,\n                      ),\n                      onSubmitted: _handleCommand,\n                    ),\n                  ),\n                ],\n              ),\n            ],\n          ),\n        ),\n      ),\n    );\n  }\n}",
  "lib/apps/contact_app.dart": "import 'package:flutter/material.dart';\nimport 'package:google_fonts/google_fonts.dart';\nimport 'package:provider/provider.dart';\nimport '../models/config_model.dart';\n\nclass ContactApp extends StatelessWidget {\n  const ContactApp({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    final config = context.watch<AppConfig>();\n\n    return Padding(\n      padding: const EdgeInsets.all(48.0),\n      child: Center(\n        child: Column(\n          mainAxisAlignment: MainAxisAlignment.center,\n          children: [\n            Text(\n              'Get in Touch',\n              style: GoogleFonts.outfit(\n                color: Colors.white,\n                fontSize: 36,\n                fontWeight: FontWeight.bold,\n              ),\n            ),\n            const SizedBox(height: 16),\n            Text(\n              \"I'm currently open to new opportunities and collaborations.\",\n              textAlign: TextAlign.center,\n              style: GoogleFonts.inter(color: Colors.white70, fontSize: 18),\n            ),\n            const SizedBox(height: 48),\n            Container(\n              constraints: const BoxConstraints(maxWidth: 500),\n              padding: const EdgeInsets.all(24),\n              decoration: BoxDecoration(\n                color: Colors.white.withOpacity(0.05),\n                borderRadius: BorderRadius.circular(20),\n                border: Border.all(color: Colors.white10),\n              ),\n              child: Column(\n                children: [\n                  _ContactField(label: 'Email', value: config.profile.email),\n                  const Divider(color: Colors.white10, height: 32),\n                  _ContactField(\n                    label: 'Location',\n                    value: config.profile.location,\n                  ),\n                ],\n              ),\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n}\n\nclass _ContactField extends StatelessWidget {\n  final String label;\n  final String value;\n\n  const _ContactField({required this.label, required this.value});\n\n  @override\n  Widget build(BuildContext context) {\n    return Row(\n      mainAxisAlignment: MainAxisAlignment.spaceBetween,\n      children: [\n        Text(\n          label,\n          style: GoogleFonts.inter(color: Colors.white38, fontSize: 16),\n        ),\n        Text(\n          value,\n          style: GoogleFonts.inter(\n            color: Colors.white,\n            fontSize: 16,\n            fontWeight: FontWeight.w500,\n          ),\n        ),\n      ],\n    );\n  }\n}",
  "lib/apps/settings_app.dart": "import 'package:flutter/material.dart';\nimport 'package:file_picker/file_picker.dart';\nimport 'package:google_fonts/google_fonts.dart';\nimport 'package:provider/provider.dart';\nimport '../system_settings.dart';\n\nclass SettingsApp extends StatefulWidget {\n  const SettingsApp({super.key});\n\n  @override\n  State<SettingsApp> createState() => _SettingsAppState();\n}\n\nclass _SettingsAppState extends State<SettingsApp> {\n  int _selectedSection = 0;\n  final TextEditingController _urlController = TextEditingController();\n  final TextEditingController _hexColorController = TextEditingController();\n  bool _isUploading = false;\n\n  final List<Map<String, dynamic>> _sections = [\n    {'title': 'Appearance', 'icon': Icons.palette_outlined},\n    {'title': 'Wallpaper', 'icon': Icons.wallpaper_rounded},\n    {'title': 'Desktop & Dock', 'icon': Icons.desktop_windows_outlined},\n    {'title': 'Time & Sound', 'icon': Icons.access_time_rounded},\n    {'title': 'About fyrOS', 'icon': Icons.info_outline_rounded},\n  ];\n\n  final List<Map<String, String>> _presets = [\n    {'name': 'Cyberpunk Neon', 'path': 'assets/wallpaper.jpg'},\n    {\n      'name': 'Alpine Sunset',\n      'path':\n          'https://images.unsplash.com/photo-1477346611705-65d1883cee1e?q=80&w=1920',\n    },\n    {\n      'name': 'Deep Space',\n      'path':\n          'https://images.unsplash.com/photo-1506703719100-a0f3a48c0f86?q=80&w=1920',\n    },\n    {\n      'name': 'Cyber Grid',\n      'path':\n          'https://images.unsplash.com/photo-1518770660439-4636190af475?q=80&w=1920',\n    },\n    {\n      'name': 'Mountain Fog',\n      'path':\n          'https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?q=80&w=1920',\n    },\n  ];\n\n  final List<Map<String, dynamic>> _accentPalette = [\n    {'name': 'Cyber Purple', 'color': Color(0xFF9C27B0)},\n    {'name': 'Neon Cyan', 'color': Color(0xFF00B0FF)},\n    {'name': 'Matrix Green', 'color': Color(0xFF00E676)},\n    {'name': 'Sunset Orange', 'color': Color(0xFFFF9100)},\n    {'name': 'Vapor Pink', 'color': Color(0xFFF50057)},\n    {'name': 'Amber Gold', 'color': Color(0xFFFFD600)},\n    {'name': 'Crimson Red', 'color': Color(0xFFFF1744)},\n  ];\n\n  @override\n  void dispose() {\n    _urlController.dispose();\n    _hexColorController.dispose();\n    super.dispose();\n  }\n\n  Future<void> _pickWallpaper(SystemSettings settings) async {\n    setState(() => _isUploading = true);\n    try {\n      final result = await FilePicker.pickFiles(\n        type: FileType.image,\n        allowMultiple: false,\n        withData: true,\n      );\n\n      if (result != null && result.files.first.bytes != null) {\n        final file = result.files.first;\n        final bytes = file.bytes!;\n        final ext = (file.extension ?? 'png').toLowerCase();\n        final mimeType = (ext == 'jpg' || ext == 'jpeg')\n            ? 'image/jpeg'\n            : 'image/png';\n\n        await settings.setCustomWallpaperFromBytes(bytes, mimeType: mimeType);\n\n        if (mounted) {\n          ScaffoldMessenger.of(context).showSnackBar(\n            SnackBar(\n              content: Row(\n                children: [\n                  const Icon(\n                    Icons.check_circle_rounded,\n                    color: Colors.greenAccent,\n                    size: 18,\n                  ),\n                  const SizedBox(width: 10),\n                  Text(\n                    'Custom wallpaper saved locally (IndexedDB)!',\n                    style: GoogleFonts.inter(\n                      color: Colors.white,\n                      fontWeight: FontWeight.w500,\n                    ),\n                  ),\n                ],\n              ),\n              backgroundColor: const Color(0xFF1F2430),\n              behavior: SnackBarBehavior.floating,\n              duration: const Duration(seconds: 3),\n            ),\n          );\n        }\n      }\n    } catch (e) {\n      debugPrint('Error picking wallpaper: \$e');\n    } finally {\n      if (mounted) setState(() => _isUploading = false);\n    }\n  }\n\n  void _applyCustomUrl(SystemSettings settings) {\n    final url = _urlController.text.trim();\n    if (url.isNotEmpty &&\n        (url.startsWith('http://') || url.startsWith('https://'))) {\n      settings.setWallpaper(url);\n      _urlController.clear();\n      FocusScope.of(context).unfocus();\n      ScaffoldMessenger.of(context).showSnackBar(\n        SnackBar(\n          content: Text(\n            'Custom background URL applied & saved!',\n            style: GoogleFonts.inter(color: Colors.white),\n          ),\n          backgroundColor: const Color(0xFF1F2430),\n          behavior: SnackBarBehavior.floating,\n        ),\n      );\n    }\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final settings = context.watch<SystemSettings>();\n    final onSurfaceColor = Theme.of(context).colorScheme.onSurface;\n    final isDark = settings.isDarkMode;\n\n    return LayoutBuilder(\n      builder: (context, constraints) {\n        final isNarrow = constraints.maxWidth < 640;\n\n        return Container(\n          color: isDark ? const Color(0xFF101216) : const Color(0xFFF7F8FA),\n          child: isNarrow\n              ? Column(\n                  children: [\n                    _buildNarrowNav(settings),\n                    Expanded(\n                      child: _buildSectionContent(\n                        settings,\n                        onSurfaceColor,\n                        isNarrow,\n                      ),\n                    ),\n                  ],\n                )\n              : Row(\n                  children: [\n                    _buildSidebar(settings, onSurfaceColor),\n                    Container(\n                      width: 1,\n                      color: onSurfaceColor.withValues(alpha: 0.08),\n                    ),\n                    Expanded(\n                      child: _buildSectionContent(\n                        settings,\n                        onSurfaceColor,\n                        isNarrow,\n                      ),\n                    ),\n                  ],\n                ),\n        );\n      },\n    );\n  }\n\n  Widget _buildNarrowNav(SystemSettings settings) {\n    return Container(\n      height: 48,\n      decoration: BoxDecoration(\n        color: Theme.of(context).colorScheme.surface,\n        border: Border(\n          bottom: BorderSide(\n            color: Theme.of(\n              context,\n            ).colorScheme.onSurface.withValues(alpha: 0.08),\n          ),\n        ),\n      ),\n      child: ListView.builder(\n        scrollDirection: Axis.horizontal,\n        padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 6),\n        itemCount: _sections.length,\n        itemBuilder: (context, i) {\n          final isSelected = _selectedSection == i;\n          return Padding(\n            padding: const EdgeInsets.only(right: 6),\n            child: ChoiceChip(\n              label: Text(_sections[i]['title'] as String),\n              selected: isSelected,\n              selectedColor: settings.accentColor.withValues(alpha: 0.2),\n              onSelected: (_) => setState(() => _selectedSection = i),\n              labelStyle: GoogleFonts.inter(\n                fontSize: 12,\n                fontWeight: isSelected ? FontWeight.bold : FontWeight.normal,\n                color: isSelected\n                    ? settings.accentColor\n                    : Theme.of(context).colorScheme.onSurface,\n              ),\n            ),\n          );\n        },\n      ),\n    );\n  }\n\n  Widget _buildSidebar(SystemSettings settings, Color onSurfaceColor) {\n    return Container(\n      width: 200,\n      padding: const EdgeInsets.symmetric(vertical: 24, horizontal: 12),\n      child: Column(\n        crossAxisAlignment: CrossAxisAlignment.start,\n        children: [\n          Padding(\n            padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),\n            child: Row(\n              children: [\n                Icon(\n                  Icons.settings_suggest_rounded,\n                  color: settings.accentColor,\n                  size: 20,\n                ),\n                const SizedBox(width: 8),\n                Text(\n                  'Settings',\n                  style: GoogleFonts.outfit(\n                    color: onSurfaceColor,\n                    fontSize: 18,\n                    fontWeight: FontWeight.bold,\n                  ),\n                ),\n              ],\n            ),\n          ),\n          const SizedBox(height: 16),\n          Expanded(\n            child: ListView.separated(\n              itemCount: _sections.length,\n              separatorBuilder: (_, _) => const SizedBox(height: 4),\n              itemBuilder: (context, index) {\n                final item = _sections[index];\n                final isSelected = _selectedSection == index;\n\n                return InkWell(\n                  onTap: () => setState(() => _selectedSection = index),\n                  borderRadius: BorderRadius.circular(10),\n                  child: Container(\n                    padding: const EdgeInsets.symmetric(\n                      horizontal: 12,\n                      vertical: 10,\n                    ),\n                    decoration: BoxDecoration(\n                      color: isSelected\n                          ? settings.accentColor.withValues(alpha: 0.15)\n                          : Colors.transparent,\n                      borderRadius: BorderRadius.circular(10),\n                    ),\n                    child: Row(\n                      children: [\n                        Icon(\n                          item['icon'] as IconData,\n                          size: 18,\n                          color: isSelected\n                              ? settings.accentColor\n                              : onSurfaceColor.withValues(alpha: 0.6),\n                        ),\n                        const SizedBox(width: 12),\n                        Expanded(\n                          child: Text(\n                            item['title'] as String,\n                            style: GoogleFonts.inter(\n                              color: isSelected\n                                  ? settings.accentColor\n                                  : onSurfaceColor.withValues(alpha: 0.85),\n                              fontSize: 13,\n                              fontWeight: isSelected\n                                  ? FontWeight.w600\n                                  : FontWeight.w400,\n                            ),\n                          ),\n                        ),\n                      ],\n                    ),\n                  ),\n                );\n              },\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n\n  Widget _buildSectionContent(\n    SystemSettings settings,\n    Color onSurfaceColor,\n    bool isNarrow,\n  ) {\n    switch (_selectedSection) {\n      case 0:\n        return _buildAppearanceSection(settings, onSurfaceColor, isNarrow);\n      case 1:\n        return _buildWallpaperSection(settings, onSurfaceColor, isNarrow);\n      case 2:\n        return _buildDesktopDockSection(settings, onSurfaceColor, isNarrow);\n      case 3:\n        return _buildTimeSoundSection(settings, onSurfaceColor, isNarrow);\n      case 4:\n        return _buildAboutSection(settings, onSurfaceColor, isNarrow);\n      default:\n        return _buildAppearanceSection(settings, onSurfaceColor, isNarrow);\n    }\n  }\n\n  Widget _buildAppearanceSection(\n    SystemSettings settings,\n    Color onSurfaceColor,\n    bool isNarrow,\n  ) {\n    return SingleChildScrollView(\n      padding: EdgeInsets.all(isNarrow ? 16 : 28),\n      child: Column(\n        crossAxisAlignment: CrossAxisAlignment.start,\n        children: [\n          _buildHeading(\n            'Appearance',\n            'Customize system theme mode, UI colors, and glass effects.',\n            onSurfaceColor,\n          ),\n          SizedBox(height: isNarrow ? 18 : 28),\n\n          _SettingCard(\n            title: 'Theme Mode',\n            description: 'Select dark or light interface theme for the system.',\n            isNarrow: isNarrow,\n            child: Row(\n              children: [\n                Expanded(\n                  child: _ThemeCard(\n                    label: 'Dark Mode',\n                    icon: Icons.dark_mode_rounded,\n                    isSelected: settings.isDarkMode,\n                    accentColor: settings.accentColor,\n                    onTap: () => settings.setDarkMode(true),\n                    isDark: true,\n                    isNarrow: isNarrow,\n                  ),\n                ),\n                SizedBox(width: isNarrow ? 10 : 16),\n                Expanded(\n                  child: _ThemeCard(\n                    label: 'Light Mode',\n                    icon: Icons.light_mode_rounded,\n                    isSelected: !settings.isDarkMode,\n                    accentColor: settings.accentColor,\n                    onTap: () => settings.setDarkMode(false),\n                    isDark: false,\n                    isNarrow: isNarrow,\n                  ),\n                ),\n              ],\n            ),\n          ),\n          SizedBox(height: isNarrow ? 16 : 24),\n\n          _SettingCard(\n            title: 'System Accent Color',\n            description:\n                'Controls highlight tint across window headers, buttons, dock, and indicators.',\n            isNarrow: isNarrow,\n            child: Wrap(\n              spacing: isNarrow ? 10 : 14,\n              runSpacing: isNarrow ? 10 : 14,\n              crossAxisAlignment: WrapCrossAlignment.center,\n              children: [\n                ..._accentPalette.map((palette) {\n                  final col = palette['color'] as Color;\n                  final isSelected =\n                      settings.accentColor.toARGB32() == col.toARGB32();\n                  final dotSize = isNarrow ? 32.0 : 36.0;\n                  return Tooltip(\n                    message: palette['name'] as String,\n                    child: GestureDetector(\n                      onTap: () => settings.setAccentColor(col),\n                      child: AnimatedContainer(\n                        duration: const Duration(milliseconds: 200),\n                        width: dotSize,\n                        height: dotSize,\n                        decoration: BoxDecoration(\n                          color: col,\n                          shape: BoxShape.circle,\n                          border: Border.all(\n                            color: isSelected\n                                ? Colors.white\n                                : Colors.transparent,\n                            width: 3,\n                          ),\n                          boxShadow: [\n                            if (isSelected)\n                              BoxShadow(\n                                color: col.withValues(alpha: 0.6),\n                                blurRadius: 10,\n                                spreadRadius: 2,\n                              ),\n                          ],\n                        ),\n                        child: isSelected\n                            ? Icon(\n                                Icons.check,\n                                size: isNarrow ? 16 : 18,\n                                color: Colors.white,\n                              )\n                            : null,\n                      ),\n                    ),\n                  );\n                }),\n              ],\n            ),\n          ),\n          SizedBox(height: isNarrow ? 16 : 24),\n\n          _SettingCard(\n            title: 'Window Glassmorphism & Blur',\n            description:\n                'Enable backdrop filters and frosted glass effects on windows and dock.',\n            isNarrow: isNarrow,\n            child: SwitchListTile(\n              contentPadding: EdgeInsets.zero,\n              title: Text(\n                'Enable Frosted Glass Blur',\n                style: GoogleFonts.inter(\n                  color: onSurfaceColor,\n                  fontSize: 14,\n                  fontWeight: FontWeight.w500,\n                ),\n              ),\n              subtitle: Text(\n                'Uses GPU hardware-accelerated background filters',\n                style: GoogleFonts.inter(\n                  color: onSurfaceColor.withValues(alpha: 0.5),\n                  fontSize: 12,\n                ),\n              ),\n              value: settings.enableGlassEffects,\n              activeTrackColor: settings.accentColor,\n              onChanged: (val) => settings.setEnableGlassEffects(val),\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n\n  Widget _buildWallpaperSection(\n    SystemSettings settings,\n    Color onSurfaceColor,\n    bool isNarrow,\n  ) {\n    return SingleChildScrollView(\n      padding: EdgeInsets.all(isNarrow ? 16 : 28),\n      child: Column(\n        crossAxisAlignment: CrossAxisAlignment.start,\n        children: [\n          _buildHeading(\n            'Desktop Wallpaper',\n            'Set custom wallpapers, choose presets, or paste web image URLs. All changes persist locally.',\n            onSurfaceColor,\n          ),\n          SizedBox(height: isNarrow ? 18 : 28),\n\n          _buildActiveWallpaperCard(settings, onSurfaceColor, isNarrow),\n          SizedBox(height: isNarrow ? 16 : 24),\n\n          _SettingCard(\n            title: 'Choose Wallpaper',\n            description:\n                'Pick a curated preset or upload your own image from your computer.',\n            isNarrow: isNarrow,\n            child: Wrap(\n              spacing: isNarrow ? 10 : 14,\n              runSpacing: isNarrow ? 10 : 14,\n              children: [\n\n                ..._presets.map((preset) {\n                  final path = preset['path']!;\n                  final name = preset['name']!;\n                  final isSelected =\n                      !settings.isCustomWallpaper &&\n                      settings.wallpaperPath == path;\n\n                  return _WallpaperPreviewCard(\n                    path: path,\n                    title: name,\n                    isSelected: isSelected,\n                    accentColor: settings.accentColor,\n                    onTap: () => settings.setWallpaper(path),\n                    isNarrow: isNarrow,\n                  );\n                }),\n\n                InkWell(\n                  onTap: _isUploading ? null : () => _pickWallpaper(settings),\n                  borderRadius: BorderRadius.circular(12),\n                  child: Container(\n                    width: isNarrow ? 130 : 150,\n                    height: isNarrow ? 85 : 100,\n                    decoration: BoxDecoration(\n                      color: settings.accentColor.withValues(alpha: 0.08),\n                      borderRadius: BorderRadius.circular(12),\n                      border: Border.all(\n                        color: settings.accentColor.withValues(alpha: 0.4),\n                        width: 1.5,\n                        style: BorderStyle.solid,\n                      ),\n                    ),\n                    child: Column(\n                      mainAxisAlignment: MainAxisAlignment.center,\n                      children: [\n                        if (_isUploading)\n                          SizedBox(\n                            width: 24,\n                            height: 24,\n                            child: CircularProgressIndicator(\n                              strokeWidth: 2.5,\n                              color: settings.accentColor,\n                            ),\n                          )\n                        else\n                          Icon(\n                            Icons.cloud_upload_rounded,\n                            color: settings.accentColor,\n                            size: isNarrow ? 22 : 26,\n                          ),\n                        const SizedBox(height: 6),\n                        Text(\n                          _isUploading ? 'Optimizing...' : 'Upload Image',\n                          style: GoogleFonts.inter(\n                            color: settings.accentColor,\n                            fontSize: isNarrow ? 11 : 12,\n                            fontWeight: FontWeight.w600,\n                          ),\n                        ),\n                        Text(\n                          'IndexedDB Persistent',\n                          style: GoogleFonts.inter(\n                            color: onSurfaceColor.withValues(alpha: 0.4),\n                            fontSize: 9,\n                          ),\n                        ),\n                      ],\n                    ),\n                  ),\n                ),\n              ],\n            ),\n          ),\n          SizedBox(height: isNarrow ? 16 : 24),\n\n          _SettingCard(\n            title: 'Set from Image URL',\n            description:\n                'Paste any direct image link (Unsplash, Imgur, GitHub, etc.) to set as wallpaper.',\n            isNarrow: isNarrow,\n            child: isNarrow\n                ? Column(\n                    crossAxisAlignment: CrossAxisAlignment.stretch,\n                    children: [\n                      TextField(\n                        controller: _urlController,\n                        style: GoogleFonts.inter(\n                          fontSize: 13,\n                          color: onSurfaceColor,\n                        ),\n                        decoration: InputDecoration(\n                          hintText: 'https://images.unsplash.com/...',\n                          hintStyle: GoogleFonts.inter(\n                            fontSize: 13,\n                            color: onSurfaceColor.withValues(alpha: 0.35),\n                          ),\n                          prefixIcon: const Icon(Icons.link_rounded, size: 18),\n                          filled: true,\n                          fillColor: onSurfaceColor.withValues(alpha: 0.04),\n                          contentPadding: const EdgeInsets.symmetric(\n                            horizontal: 14,\n                            vertical: 12,\n                          ),\n                          border: OutlineInputBorder(\n                            borderRadius: BorderRadius.circular(8),\n                            borderSide: BorderSide(\n                              color: onSurfaceColor.withValues(alpha: 0.15),\n                            ),\n                          ),\n                          enabledBorder: OutlineInputBorder(\n                            borderRadius: BorderRadius.circular(8),\n                            borderSide: BorderSide(\n                              color: onSurfaceColor.withValues(alpha: 0.15),\n                            ),\n                          ),\n                          focusedBorder: OutlineInputBorder(\n                            borderRadius: BorderRadius.circular(8),\n                            borderSide: BorderSide(\n                              color: settings.accentColor,\n                              width: 1.5,\n                            ),\n                          ),\n                        ),\n                        onSubmitted: (_) => _applyCustomUrl(settings),\n                      ),\n                      const SizedBox(height: 10),\n                      Align(\n                        alignment: Alignment.centerRight,\n                        child: ElevatedButton(\n                          onPressed: () => _applyCustomUrl(settings),\n                          style: ElevatedButton.styleFrom(\n                      