       vertical: 12,\n                            ),\n                            border: OutlineInputBorder(\n                              borderRadius: BorderRadius.circular(8),\n                              borderSide: BorderSide(\n                                color: onSurfaceColor.withValues(alpha: 0.15),\n                              ),\n                            ),\n                            enabledBorder: OutlineInputBorder(\n                              borderRadius: BorderRadius.circular(8),\n                              borderSide: BorderSide(\n                                color: onSurfaceColor.withValues(alpha: 0.15),\n                              ),\n                            ),\n                            focusedBorder: OutlineInputBorder(\n                              borderRadius: BorderRadius.circular(8),\n                              borderSide: BorderSide(\n                                color: settings.accentColor,\n                                width: 1.5,\n                              ),\n                            ),\n                          ),\n                          onSubmitted: (_) => _applyCustomUrl(settings),\n                        ),\n                      ),\n                      const SizedBox(width: 12),\n                      ElevatedButton(\n                        onPressed: () => _applyCustomUrl(settings),\n                        style: ElevatedButton.styleFrom(\n                          backgroundColor: settings.accentColor,\n                          foregroundColor: Colors.white,\n                          padding: const EdgeInsets.symmetric(\n                            horizontal: 18,\n                            vertical: 16,\n                          ),\n                          shape: RoundedRectangleBorder(\n                            borderRadius: BorderRadius.circular(8),\n                          ),\n                        ),\n                        child: Text(\n                          'Apply URL',\n                          style: GoogleFonts.inter(fontWeight: FontWeight.w600),\n                        ),\n                      ),\n                    ],\n                  ),\n          ),\n          SizedBox(height: isNarrow ? 16 : 24),\n\n          _SettingCard(\n            title: 'Desktop Background Adjustments',\n            description:\n                'Fine-tune desktop contrast and blur to keep app windows easily readable.',\n            isNarrow: isNarrow,\n            child: Column(\n              children: [\n                Row(\n                  children: [\n                    Icon(\n                      Icons.blur_on_rounded,\n                      size: 20,\n                      color: onSurfaceColor.withValues(alpha: 0.6),\n                    ),\n                    const SizedBox(width: 12),\n                    Expanded(\n                      child: Column(\n                        crossAxisAlignment: CrossAxisAlignment.start,\n                        children: [\n                          Row(\n                            mainAxisAlignment: MainAxisAlignment.spaceBetween,\n                            children: [\n                              Text(\n                                'Background Blur',\n                                style: GoogleFonts.inter(\n                                  fontSize: 13,\n                                  fontWeight: FontWeight.w500,\n                                  color: onSurfaceColor,\n                                ),\n                              ),\n                              Text(\n                                '\${settings.wallpaperBlur.toStringAsFixed(0)} px',\n                                style: GoogleFonts.inter(\n                                  fontSize: 12,\n                                  color: settings.accentColor,\n                                  fontWeight: FontWeight.bold,\n                                ),\n                              ),\n                            ],\n                          ),\n                          Slider(\n                            value: settings.wallpaperBlur,\n                            min: 0.0,\n                            max: 20.0,\n                            divisions: 20,\n                            activeColor: settings.accentColor,\n                            onChanged: (v) => settings.setWallpaperBlur(v),\n                          ),\n                        ],\n                      ),\n                    ),\n                  ],\n                ),\n                const SizedBox(height: 12),\n                Row(\n                  children: [\n                    Icon(\n                      Icons.brightness_medium_rounded,\n                      size: 20,\n                      color: onSurfaceColor.withValues(alpha: 0.6),\n                    ),\n                    const SizedBox(width: 12),\n                    Expanded(\n                      child: Column(\n                        crossAxisAlignment: CrossAxisAlignment.start,\n                        children: [\n                          Row(\n                            mainAxisAlignment: MainAxisAlignment.spaceBetween,\n                            children: [\n                              Text(\n                                'Background Dimming',\n                                style: GoogleFonts.inter(\n                                  fontSize: 13,\n                                  fontWeight: FontWeight.w500,\n                                  color: onSurfaceColor,\n                                ),\n                              ),\n                              Text(\n                                '\${(settings.wallpaperDim * 100).toStringAsFixed(0)}%',\n                                style: GoogleFonts.inter(\n                                  fontSize: 12,\n                                  color: settings.accentColor,\n                                  fontWeight: FontWeight.bold,\n                                ),\n                              ),\n                            ],\n                          ),\n                          Slider(\n                            value: settings.wallpaperDim,\n                            min: 0.0,\n                            max: 0.6,\n                            divisions: 12,\n                            activeColor: settings.accentColor,\n                            onChanged: (v) => settings.setWallpaperDim(v),\n                          ),\n                        ],\n                      ),\n                    ),\n                  ],\n                ),\n              ],\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n\n  Widget _buildActiveWallpaperCard(\n    SystemSettings settings,\n    Color onSurfaceColor,\n    bool isNarrow,\n  ) {\n    final isCustom = settings.isCustomWallpaper;\n    final isPreset = !isCustom && settings.wallpaperPath.startsWith('assets');\n    final isWebUrl = !isCustom && !isPreset;\n\n    String statusLabel = 'Preset Wallpaper';\n    if (isCustom) {\n      statusLabel = 'Custom Upload (IndexedDB Persistent)';\n    } else if (isWebUrl) {\n      statusLabel = 'Web URL Background';\n    }\n\n    final thumbnailWidget = ClipRRect(\n      borderRadius: BorderRadius.circular(10),\n      child: SizedBox(\n        width: isNarrow ? 96 : 120,\n        height: isNarrow ? 60 : 72,\n        child: settings.wallpaperBytes != null\n            ? Image.memory(settings.wallpaperBytes!, fit: BoxFit.cover)\n            : settings.wallpaperPath.startsWith('assets')\n            ? Image.asset(settings.wallpaperPath, fit: BoxFit.cover)\n            : Image.network(\n                settings.wallpaperPath,\n                fit: BoxFit.cover,\n                errorBuilder: (ctx, err, stack) =>\n                    Image.asset('assets/wallpaper.jpg', fit: BoxFit.cover),\n              ),\n      ),\n    );\n\n    final detailsColumn = Column(\n      crossAxisAlignment: CrossAxisAlignment.start,\n      children: [\n        Row(\n          children: [\n            Container(\n              padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),\n              decoration: BoxDecoration(\n                color: settings.accentColor.withValues(alpha: 0.15),\n                borderRadius: BorderRadius.circular(6),\n              ),\n              child: Text(\n                'ACTIVE',\n                style: GoogleFonts.inter(\n                  color: settings.accentColor,\n                  fontSize: 10,\n                  fontWeight: FontWeight.bold,\n                ),\n              ),\n            ),\n            const SizedBox(width: 8),\n            Expanded(\n              child: Text(\n                statusLabel,\n                style: GoogleFonts.inter(\n                  color: onSurfaceColor,\n                  fontSize: isNarrow ? 12 : 13,\n                  fontWeight: FontWeight.w600,\n                ),\n                overflow: TextOverflow.ellipsis,\n              ),\n            ),\n          ],\n        ),\n        const SizedBox(height: 6),\n        Text(\n          isCustom\n              ? 'Stored safely in browser storage across sessions.'\n              : (isWebUrl ? settings.wallpaperPath : 'Default fyrOS Neon City'),\n          style: GoogleFonts.inter(\n            color: onSurfaceColor.withValues(alpha: 0.5),\n            fontSize: 11,\n          ),\n          maxLines: 1,\n          overflow: TextOverflow.ellipsis,\n        ),\n      ],\n    );\n\n    final resetButton = OutlinedButton.icon(\n      onPressed: () => settings.resetWallpaper(),\n      icon: const Icon(Icons.refresh_rounded, size: 16),\n      label: const Text('Reset Default'),\n      style: OutlinedButton.styleFrom(\n        foregroundColor: onSurfaceColor.withValues(alpha: 0.8),\n        side: BorderSide(color: onSurfaceColor.withValues(alpha: 0.2)),\n        padding: EdgeInsets.symmetric(\n          horizontal: isNarrow ? 12 : 16,\n          vertical: isNarrow ? 8 : 12,\n        ),\n        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(8)),\n      ),\n    );\n\n    return Container(\n      padding: EdgeInsets.all(isNarrow ? 12 : 16),\n      decoration: BoxDecoration(\n        color: onSurfaceColor.withValues(alpha: 0.04),\n        borderRadius: BorderRadius.circular(14),\n        border: Border.all(color: onSurfaceColor.withValues(alpha: 0.08)),\n      ),\n      child: isNarrow\n          ? Column(\n              crossAxisAlignment: CrossAxisAlignment.start,\n              children: [\n                Row(\n                  children: [\n                    thumbnailWidget,\n                    const SizedBox(width: 12),\n                    Expanded(child: detailsColumn),\n                  ],\n                ),\n                const SizedBox(height: 10),\n                Align(alignment: Alignment.centerRight, child: resetButton),\n              ],\n            )\n          : Row(\n              children: [\n                thumbnailWidget,\n                const SizedBox(width: 16),\n                Expanded(child: detailsColumn),\n                const SizedBox(width: 12),\n                resetButton,\n              ],\n            ),\n    );\n  }\n\n  Widget _buildDesktopDockSection(\n    SystemSettings settings,\n    Color onSurfaceColor,\n    bool isNarrow,\n  ) {\n    return SingleChildScrollView(\n      padding: EdgeInsets.all(isNarrow ? 16 : 28),\n      child: Column(\n        crossAxisAlignment: CrossAxisAlignment.start,\n        children: [\n          _buildHeading(\n            'Desktop & Dock',\n            'Configure desktop behavior, dock auto-hiding, and icon scaling.',\n            onSurfaceColor,\n          ),\n          SizedBox(height: isNarrow ? 18 : 28),\n\n          _SettingCard(\n            title: 'Dock Auto-Hide',\n            description:\n                'Automatically hides the dock when windows overlap or when not hovered.',\n            isNarrow: isNarrow,\n            child: SwitchListTile(\n              contentPadding: EdgeInsets.zero,\n              title: Text(\n                'Auto-Hide Dock',\n                style: GoogleFonts.inter(\n                  color: onSurfaceColor,\n                  fontSize: 14,\n                  fontWeight: FontWeight.w500,\n                ),\n              ),\n              subtitle: Text(\n                'Move mouse to bottom edge of screen to reveal dock',\n                style: GoogleFonts.inter(\n                  color: onSurfaceColor.withValues(alpha: 0.5),\n                  fontSize: 12,\n                ),\n              ),\n              value: settings.dockAutoHide,\n              activeTrackColor: settings.accentColor,\n              onChanged: (val) => settings.setDockAutoHide(val),\n            ),\n          ),\n          SizedBox(height: isNarrow ? 16 : 24),\n\n          _SettingCard(\n            title: 'Dock Icon Scale',\n            description:\n                'Adjust the sizing of icons and height of the desktop dock.',\n            isNarrow: isNarrow,\n            child: Column(\n              crossAxisAlignment: CrossAxisAlignment.start,\n              children: [\n                Row(\n                  mainAxisAlignment: MainAxisAlignment.spaceBetween,\n                  children: [\n                    Text(\n                      'Scale: \${(settings.dockScale * 100).toStringAsFixed(0)}%',\n                      style: GoogleFonts.inter(\n                        fontSize: 13,\n                        fontWeight: FontWeight.w600,\n                        color: settings.accentColor,\n                      ),\n                    ),\n                    Text(\n                      settings.dockScale < 0.95\n                          ? 'Compact'\n                          : (settings.dockScale > 1.1 ? 'Large' : 'Standard'),\n                      style: GoogleFonts.inter(\n                        fontSize: 12,\n                        color: onSurfaceColor.withValues(alpha: 0.5),\n                      ),\n                    ),\n                  ],\n                ),\n                Slider(\n                  value: settings.dockScale,\n                  min: 0.8,\n                  max: 1.25,\n                  divisions: 9,\n                  activeColor: settings.accentColor,\n                  onChanged: (v) => settings.setDockScale(v),\n                ),\n              ],\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n\n  Widget _buildTimeSoundSection(\n    SystemSettings settings,\n    Color onSurfaceColor,\n    bool isNarrow,\n  ) {\n    return SingleChildScrollView(\n      padding: EdgeInsets.all(isNarrow ? 16 : 28),\n      child: Column(\n        crossAxisAlignment: CrossAxisAlignment.start,\n        children: [\n          _buildHeading(\n            'Time & Audio',\n            'Configure top bar clock formats, system audio volume, and game synthesizer effects.',\n            onSurfaceColor,\n          ),\n          SizedBox(height: isNarrow ? 18 : 28),\n\n          _SettingCard(\n            title: 'Top Bar Clock Format',\n            description:\n                'Select between 12-hour AM/PM and 24-hour military clock display.',\n            isNarrow: isNarrow,\n            child: Column(\n              children: [\n                SwitchListTile(\n                  contentPadding: EdgeInsets.zero,\n                  title: Text(\n                    '24-Hour Clock (Military Time)',\n                    style: GoogleFonts.inter(\n                      color: onSurfaceColor,\n                      fontSize: 14,\n                      fontWeight: FontWeight.w500,\n                    ),\n                  ),\n                  subtitle: Text(\n                    settings.use24HourClock\n                        ? 'Display format: 14:30'\n                        : 'Display format: 2:30 PM',\n                    style: GoogleFonts.inter(\n                      color: onSurfaceColor.withValues(alpha: 0.5),\n                      fontSize: 12,\n                    ),\n                  ),\n                  value: settings.use24HourClock,\n                  activeTrackColor: settings.accentColor,\n                  onChanged: (val) => settings.setUse24HourClock(val),\n                ),\n                const Divider(height: 20),\n                SwitchListTile(\n                  contentPadding: EdgeInsets.zero,\n                  title: Text(\n                    'Display Clock Seconds',\n                    style: GoogleFonts.inter(\n                      color: onSurfaceColor,\n                      fontSize: 14,\n                      fontWeight: FontWeight.w500,\n                    ),\n                  ),\n                  subtitle: Text(\n                    'Shows live seconds in top system bar',\n                    style: GoogleFonts.inter(\n                      color: onSurfaceColor.withValues(alpha: 0.5),\n                      fontSize: 12,\n                    ),\n                  ),\n                  value: settings.showClockSeconds,\n                  activeTrackColor: settings.accentColor,\n                  onChanged: (val) => settings.setShowClockSeconds(val),\n                ),\n              ],\n            ),\n          ),\n          SizedBox(height: isNarrow ? 16 : 24),\n\n          _SettingCard(\n            title: 'Audio & Sound Effects',\n            description:\n                'Controls system volume level and retro synthesizer effects.',\n            isNarrow: isNarrow,\n            child: Column(\n              children: [\n                Row(\n                  children: [\n                    Icon(\n                      settings.soundVolume == 0\n                          ? Icons.volume_off_rounded\n                          : Icons.volume_up_rounded,\n                      size: 22,\n                      color: onSurfaceColor.withValues(alpha: 0.6),\n                    ),\n                    const SizedBox(width: 12),\n                    Expanded(\n                      child: Column(\n                        crossAxisAlignment: CrossAxisAlignment.start,\n                        children: [\n                          Row(\n                            mainAxisAlignment: MainAxisAlignment.spaceBetween,\n                            children: [\n                              Text(\n                                'Master Volume',\n                                style: GoogleFonts.inter(\n                                  fontSize: 13,\n                                  fontWeight: FontWeight.w500,\n                                  color: onSurfaceColor,\n                                ),\n                              ),\n                              Text(\n                                '\${(settings.soundVolume * 100).toStringAsFixed(0)}%',\n                                style: GoogleFonts.inter(\n                                  fontSize: 12,\n                                  color: settings.accentColor,\n                                  fontWeight: FontWeight.bold,\n                                ),\n                              ),\n                            ],\n                          ),\n                          Slider(\n                            value: settings.soundVolume,\n                            min: 0.0,\n                            max: 1.0,\n                            activeColor: settings.accentColor,\n                            onChanged: (v) => settings.setSoundVolume(v),\n                          ),\n                        ],\n                      ),\n                    ),\n                  ],\n                ),\n                const Divider(height: 24),\n                SwitchListTile(\n                  contentPadding: EdgeInsets.zero,\n                  title: Text(\n                    'Audio & Synthesizer Effects',\n                    style: GoogleFonts.inter(\n                      color: onSurfaceColor,\n                      fontSize: 14,\n                      fontWeight: FontWeight.w500,\n                    ),\n                  ),\n                  subtitle: Text(\n                    'Enables game audio, laser synth, and sound cues',\n                    style: GoogleFonts.inter(\n                      color: onSurfaceColor.withValues(alpha: 0.5),\n                      fontSize: 12,\n                    ),\n                  ),\n                  value: settings.soundEffectsEnabled,\n                  activeTrackColor: settings.accentColor,\n                  onChanged: (val) => settings.setSoundEffectsEnabled(val),\n                ),\n              ],\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n\n  Widget _buildAboutSection(\n    SystemSettings settings,\n    Color onSurfaceColor,\n    bool isNarrow,\n  ) {\n    return SingleChildScrollView(\n      padding: EdgeInsets.all(isNarrow ? 16 : 28),\n      child: Column(\n        crossAxisAlignment: CrossAxisAlignment.start,\n        children: [\n          _buildHeading(\n            'About fyrOS',\n            'System telemetry, hardened kernel configuration, and developer environment info.',\n            onSurfaceColor,\n          ),\n          SizedBox(height: isNarrow ? 18 : 28),\n\n          _SettingCard(\n            title: 'System Information',\n            description:\n                'Running live on Google Cloud Platform (us-central1) with automated Ansible/Terraform orchestration.',\n            isNarrow: isNarrow,\n            child: Column(\n              children: [\n                _buildInfoRow(\n                  'Operating System',\n                  'fyrOS 2.4.0-hardened (Debian 12)',\n                  onSurfaceColor,\n                ),\n                _buildInfoRow(\n                  'Orchestration',\n                  'WE-IAC (Terraform 1.7 + Ansible 9.2)',\n                  onSurfaceColor,\n                ),\n                _buildInfoRow(\n                  'Host Specs',\n                  'GCP e2-medium (2 vCPU, 4GB RAM, 30GB SSD)',\n                  onSurfaceColor,\n                ),\n                _buildInfoRow(\n                  'Kernel Version',\n                  'Linux 6.1.0-28-cloud-amd64',\n                  onSurfaceColor,\n                ),\n                _buildInfoRow(\n                  'Swappiness Tuning',\n                  'vm.swappiness = 20',\n                  onSurfaceColor,\n                ),\n                _buildInfoRow(\n                  'Zero-Trust Network',\n                  'Docker Bridge (172.28.0.0/16)',\n                  onSurfaceColor,\n                ),\n                _buildInfoRow(\n                  'Firewall',\n                  'UFW Active (22, 80, 443)',\n                  onSurfaceColor,\n                ),\n                _buildInfoRow(\n                  'Web Engine',\n                  'Flutter Web (CanvasKit / WebGL)',\n                  onSurfaceColor,\n                ),\n              ],\n            ),\n          ),\n          SizedBox(height: isNarrow ? 16 : 24),\n\n          _SettingCard(\n            title: 'Reset Preferences',\n            description:\n                'Clear all customized wallpapers, themes, and dock configurations back to system defaults.',\n            isNarrow: isNarrow,\n            child: Align(\n              alignment: Alignment.centerLeft,\n              child: ElevatedButton.icon(\n                onPressed: () => _confirmResetAll(settings),\n                icon: const Icon(Icons.restore_rounded, size: 18),\n                label: const Text('Reset All Settings to Defaults'),\n                style: ElevatedButton.styleFrom(\n                  backgroundColor: Colors.redAccent.withValues(alpha: 0.15),\n                  foregroundColor: Colors.redAccent,\n                  elevation: 0,\n                  padding: EdgeInsets.symmetric(\n                    horizontal: isNarrow ? 14 : 20,\n                    vertical: isNarrow ? 10 : 14,\n                  ),\n                  shape: RoundedRectangleBorder(\n                    borderRadius: BorderRadius.circular(8),\n                    side: BorderSide(\n                      color: Colors.redAccent.withValues(alpha: 0.4),\n                    ),\n                  ),\n                ),\n              ),\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n\n  Widget _buildInfoRow(String label, String value, Color onSurfaceColor) {\n    return Padding(\n      padding: const EdgeInsets.symmetric(vertical: 7),\n      child: Row(\n        crossAxisAlignment: CrossAxisAlignment.start,\n        children: [\n          Expanded(\n            flex: 2,\n            child: Text(\n              label,\n              style: GoogleFonts.inter(\n                color: onSurfaceColor.withValues(alpha: 0.6),\n                fontSize: 12,\n              ),\n            ),\n          ),\n          const SizedBox(width: 8),\n          Expanded(\n            flex: 3,\n            child: Text(\n              value,\n              textAlign: TextAlign.right,\n              style: GoogleFonts.jetBrainsMono(\n                color: onSurfaceColor,\n                fontSize: 11,\n                fontWeight: FontWeight.w600,\n              ),\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n\n  void _confirmResetAll(SystemSettings settings) {\n    showDialog(\n      context: context,\n      builder: (ctx) => AlertDialog(\n        backgroundColor: const Color(0xFF1E212B),\n        title: Text(\n          'Reset All Settings?',\n          style: GoogleFonts.outfit(\n            color: Colors.white,\n            fontWeight: FontWeight.bold,\n          ),\n        ),\n        content: Text(\n          'This will reset all theme options, wallpapers, dock scales, and audio volume back to factory defaults. Custom uploaded wallpapers will be cleared.',\n          style: GoogleFonts.inter(color: Colors.white70, fontSize: 13),\n        ),\n        actions: [\n          TextButton(\n            onPressed: () => Navigator.of(ctx).pop(),\n            child: const Text('Cancel'),\n          ),\n          ElevatedButton(\n            onPressed: () {\n              Navigator.of(ctx).pop();\n              settings.resetAllSettings();\n              ScaffoldMessenger.of(context).showSnackBar(\n                const SnackBar(\n                  content: Text('All settings restored to defaults.'),\n                  backgroundColor: Color(0xFF2A2D39),\n                  behavior: SnackBarBehavior.floating,\n                ),\n              );\n            },\n            style: ElevatedButton.styleFrom(backgroundColor: Colors.redAccent),\n            child: const Text('Reset', style: TextStyle(color: Colors.white)),\n          ),\n        ],\n      ),\n    );\n  }\n\n  Widget _buildHeading(String title, String subtitle, Color onSurfaceColor) {\n    return Column(\n      crossAxisAlignment: CrossAxisAlignment.start,\n      children: [\n        Text(\n          title,\n          style: GoogleFonts.outfit(\n            color: onSurfaceColor,\n            fontSize: 26,\n            fontWeight: FontWeight.bold,\n          ),\n        ),\n        const SizedBox(height: 6),\n        Text(\n          subtitle,\n          style: GoogleFonts.inter(\n            color: onSurfaceColor.withValues(alpha: 0.55),\n            fontSize: 13,\n          ),\n        ),\n      ],\n    );\n  }\n}\n\nclass _SettingCard extends StatelessWidget {\n  final String title;\n  final String description;\n  final Widget child;\n  final bool isNarrow;\n\n  const _SettingCard({\n    required this.title,\n    required this.description,\n    required this.child,\n    this.isNarrow = false,\n  });\n\n  @override\n  Widget build(BuildContext context) {\n    final onSurfaceColor = Theme.of(context).colorScheme.onSurface;\n\n    return Container(\n      width: double.infinity,\n      padding: EdgeInsets.all(isNarrow ? 14 : 20),\n      decoration: BoxDecoration(\n        color: onSurfaceColor.withValues(alpha: 0.03),\n        borderRadius: BorderRadius.circular(16),\n        border: Border.all(color: onSurfaceColor.withValues(alpha: 0.08)),\n      ),\n      child: Column(\n        crossAxisAlignment: CrossAxisAlignment.start,\n        children: [\n          Text(\n            title,\n            style: GoogleFonts.inter(\n              color: onSurfaceColor,\n              fontSize: 15,\n              fontWeight: FontWeight.bold,\n            ),\n          ),\n          const SizedBox(height: 4),\n          Text(\n            description,\n            style: GoogleFonts.inter(\n              color: onSurfaceColor.withValues(alpha: 0.5),\n              fontSize: 12,\n            ),\n          ),\n          const SizedBox(height: 16),\n          child,\n        ],\n      ),\n    );\n  }\n}\n\nclass _ThemeCard extends StatelessWidget {\n  final String label;\n  final IconData icon;\n  final bool isSelected;\n  final Color accentColor;\n  final VoidCallback onTap;\n  final bool isDark;\n  final bool isNarrow;\n\n  const _ThemeCard({\n    required this.label,\n    required this.icon,\n    required this.isSelected,\n    required this.accentColor,\n    required this.onTap,\n    required this.isDark,\n    this.isNarrow = false,\n  });\n\n  @override\n  Widget build(BuildContext context) {\n    final onSurfaceColor = Theme.of(context).colorScheme.onSurface;\n\n    return GestureDetector(\n      onTap: onTap,\n      child: AnimatedContainer(\n        duration: const Duration(milliseconds: 200),\n        padding: EdgeInsets.symmetric(\n          horizontal: isNarrow ? 10 : 16,\n          vertical: isNarrow ? 12 : 16,\n        ),\n        decoration: BoxDecoration(\n          color: isDark ? const Color(0xFF16181E) : Colors.white,\n          borderRadius: BorderRadius.circular(14),\n          border: Border.all(\n            color: isSelected\n                ? accentColor\n                : onSurfaceColor.withValues(alpha: 0.15),\n            width: isSelected ? 2.5 : 1,\n          ),\n          boxShadow: [\n            if (isSelected)\n              BoxShadow(\n                color: accentColor.withValues(alpha: 0.3),\n                blurRadius: 10,\n                offset: const Offset(0, 4),\n              ),\n          ],\n        ),\n        child: Column(\n          mainAxisSize: MainAxisSize.min,\n          children: [\n            Icon(\n              icon,\n              size: isNarrow ? 26 : 32,\n              color: isSelected\n                  ? accentColor\n                  : (isDark ? Colors.white70 : Colors.black87),\n            ),\n            SizedBox(height: isNarrow ? 6 : 10),\n            Text(\n              label,\n              textAlign: TextAlign.center,\n              style: GoogleFonts.inter(\n                color: isDark ? Colors.white : Colors.black87,\n                fontSize: isNarrow ? 12 : 13,\n                fontWeight: isSelected ? FontWeight.bold : FontWeight.w500,\n              ),\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n}\n\nclass _WallpaperPreviewCard extends StatelessWidget {\n  final String path;\n  final String title;\n  final bool isSelected;\n  final Color accentColor;\n  final VoidCallback onTap;\n  final bool isNarrow;\n\n  const _WallpaperPreviewCard({\n    required this.path,\n    required this.title,\n    required this.isSelected,\n    required this.accentColor,\n    required this.onTap,\n    this.isNarrow = false,\n  });\n\n  @override\n  Widget build(BuildContext context) {\n    final cardW = isNarrow ? 130.0 : 150.0;\n    final cardH = isNarrow ? 85.0 : 100.0;\n\n    return GestureDetector(\n      onTap: onTap,\n      child: Column(\n        crossAxisAlignment: CrossAxisAlignment.start,\n        children: [\n          AnimatedContainer(\n            duration: const Duration(milliseconds: 200),\n            width: cardW,\n            height: cardH,\n            decoration: BoxDecoration(\n              borderRadius: BorderRadius.circular(12),\n              border: Border.all(\n                color: isSelected ? accentColor : Colors.transparent,\n                width: 3,\n              ),\n              boxShadow: [\n                if (isSelected)\n                  BoxShadow(\n                    color: accentColor.withValues(alpha: 0.4),\n                    blurRadius: 10,\n                    spreadRadius: 1,\n                  ),\n              ],\n              image: DecorationImage(\n                image: path.startsWith('assets')\n                    ? AssetImage(path) as ImageProvider\n                    : NetworkImage(path),\n                fit: BoxFit.cover,\n              ),\n            ),\n          ),\n          const SizedBox(height: 6),\n          SizedBox(\n            width: cardW,\n            child: Text(\n              title,\n              style: GoogleFonts.inter(\n                fontSize: 11,\n                fontWeight: isSelected ? FontWeight.bold : FontWeight.w500,\n                color: isSelected\n                    ? accentColor\n                    : Theme.of(context).colorScheme.onSurface,\n              ),\n              maxLines: 1,\n              overflow: TextOverflow.ellipsis,\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n}",
  "lib/apps/infra_monitor_app.dart": "import 'dart:async';\nimport 'dart:math';\nimport 'package:flutter/material.dart';\nimport 'package:google_fonts/google_fonts.dart';\n\nclass InfraMonitorApp extends StatefulWidget {\n  const InfraMonitorApp({super.key});\n\n  @override\n  State<InfraMonitorApp> createState() => _InfraMonitorAppState();\n}\n\nclass _InfraMonitorAppState extends State<InfraMonitorApp>\n    with SingleTickerProviderStateMixin {\n  late TabController _tabController;\n  bool _isProbing = false;\n\n  final List<Map<String, dynamic>> _endpoints = [\n    {\n      'domain': 'archerwoods.dev',\n      'type': 'Static Flutter Web',\n      'rateLimit': '30 r/s',\n      'latency': 32,\n      'status': 200,\n    },\n    {\n      'domain': 'friendly.archerwoods.dev',\n      'type': 'Blazor WASM SPA',\n      'rateLimit': '30 r/s',\n      'latency': 34,\n      'status': 200,\n    },\n    {\n      'domain': 'api.friendly.archerwoods.dev',\n      'type': 'Spring Boot Proxy (:8070)',\n      'rateLimit': '20 r/s',\n      'latency': 29,\n      'status': 200,\n    },\n    {\n      'domain': 'bybl.dev',\n      'type': 'Static Flutter Web',\n      'rateLimit': '30 r/s',\n      'latency': 41,\n      'status': 200,\n    },\n    {\n      'domain': 'api.bybl.dev',\n      'type': 'Go REST Proxy (:8080)',\n      'rateLimit': '20 r/s',\n      'latency': 28,\n      'status': 200,\n    },\n    {\n      'domain': 'gofyr.bybl.dev',\n      'type': 'Go Admin Proxy (:8081)',\n      'rateLimit': '20 r/s',\n      'latency': 35,\n      'status': 200,\n    },\n    {\n      'domain': 'archbtw.sh',\n      'type': 'Static Flutter Web',\n      'rateLimit': '30 r/s',\n      'latency': 38,\n      'status': 200,\n    },\n    {\n      'domain': 'libretrac.site',\n      'type': 'Static Flutter Web',\n      'rateLimit': '30 r/s',\n      'latency': 44,\n      'status': 200,\n    },\n    {\n      'domain': 'theolivebranch.press',\n      'type': 'Static + RSS Proxy',\n      'rateLimit': '30 r/s',\n      'latency': 48,\n      'status': 200,\n    },\n    {\n      'domain': 'carlyleauto.online',\n      'type': 'Static Flutter Web',\n      'rateLimit': '30 r/s',\n      'latency': 39,\n      'status': 200,\n    },\n    {\n      'domain': 'welledumacated.dev',\n      'type': 'Static Flutter Web',\n      'rateLimit': '30 r/s',\n      'latency': 42,\n      'status': 200,\n    },\n    {\n      'domain': 'fyr.software',\n      'type': 'Static Flutter Web',\n      'rateLimit': '30 r/s',\n      'latency': 46,\n      'status': 200,\n    },\n  ];\n\n  @override\n  void initState() {\n    super.initState();\n    _tabController = TabController(length: 3, vsync: this);\n  }\n\n  @override\n  void dispose() {\n    _tabController.dispose();\n    super.dispose();\n  }\n\n  void _probeEndpoints() {\n    if (_isProbing) return;\n    setState(() => _isProbing = true);\n\n    Timer(const Duration(milliseconds: 900), () {\n      if (!mounted) return;\n      final rng = Random();\n      setState(() {\n        for (var ep in _endpoints) {\n          ep['latency'] = 22 + rng.nextInt(35);\n        }\n        _isProbing = false;\n      });\n    });\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return Container(\n      color: const Color(0xFF14171C),\n      child: Column(\n        children: [\n          _buildHeader(),\n          _buildTabBar(),\n          Expanded(\n            child: TabBarView(\n              controller: _tabController,\n              children: [\n                _buildOverviewTab(),\n                _buildServicesTab(),\n                _buildNetworkAndSecurityTab(),\n              ],\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n\n  Widget _buildHeader() {\n    return Container(\n      padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),\n      decoration: const BoxDecoration(\n        color: Color(0xFF1A1F26),\n        border: Border(bottom: BorderSide(color: Colors.white10)),\n      ),\n      child: LayoutBuilder(\n        builder: (context, constraints) {\n          final isNarrow = constraints.maxWidth < 620;\n\n          final probeButton = OutlinedButton.icon(\n            onPressed: _isProbing ? null : _probeEndpoints,\n            icon: _isProbing\n                ? const SizedBox(\n                    width: 14,\n                    height: 14,\n                    child: CircularProgressIndicator(\n                      strokeWidth: 2,\n                      color: Color(0xFF00B0FF),\n                    ),\n                  )\n                : const Icon(Icons.refresh, size: 15),\n            label: Text(\n              _isProbing ? 'Probing...' : (isNarrow ? 'Probe' : 'Probe Live'),\n            ),\n            style: OutlinedButton.styleFrom(\n              foregroundColor: const Color(0xFF00B0FF),\n              side: const BorderSide(color: Color(0xFF00B0FF)),\n              padding: EdgeInsets.symmetric(\n                horizontal: isNarrow ? 10 : 12,\n                vertical: isNarrow ? 6 : 8,\n              ),\n              textStyle: GoogleFonts.inter(\n                fontSize: 12,\n                fontWeight: FontWeight.w600,\n              ),\n            ),\n          );\n\n          if (isNarrow) {\n            return Column(\n              crossAxisAlignment: CrossAxisAlignment.start,\n              children: [\n                Row(\n                  children: [\n                    Container(\n                      padding: const EdgeInsets.all(7),\n                      decoration: BoxDecoration(\n                        color: const Color(0xFF00B0FF).withValues(alpha: 0.15),\n                        borderRadius: BorderRadius.circular(8),\n                      ),\n                      child: const Icon(\n                        Icons.dns_rounded,\n                        color: Color(0xFF00B0FF),\n                        size: 18,\n                      ),\n                    ),\n                    const SizedBox(width: 8),\n                    Expanded(\n                      child: Row(\n                        children: [\n                          Flexible(\n                            child: Text(\n                              'gcp-production-us-central1',\n                              style: GoogleFonts.jetBrainsMono(\n                                color: Colors.white,\n                                fontWeight: FontWeight.bold,\n                                fontSize: 13,\n                              ),\n                              overflow: TextOverflow.ellipsis,\n                            ),\n                          ),\n                          const SizedBox(width: 6),\n                          Container(\n                            padding: const EdgeInsets.symmetric(\n                              horizontal: 5,\n                              vertical: 2,\n                            ),\n                            decoration: BoxDecoration(\n                              color: Colors.greenAccent.withValues(alpha: 0.2),\n                              borderRadius: BorderRadius.circular(4),\n                              border: Border.all(\n                                color: Colors.greenAccent.withValues(\n                                  alpha: 0.4,\n                                ),\n                              ),\n                            ),\n                            child: Text(\n                              'HEALTHY',\n                              style: GoogleFonts.jetBrainsMono(\n                                color: Colors.greenAccent,\n                                fontSize: 9,\n                                fontWeight: FontWeight.bold,\n                              ),\n                            ),\n                          ),\n                        ],\n                      ),\n                    ),\n                    const SizedBox(width: 8),\n                    probeButton,\n                  ],\n                ),\n                const SizedBox(height: 4),\n                Text(\n                  'Debian 12 • GCP e2-micro • Terraform & Ansible Managed',\n                  style: GoogleFonts.inter(color: Colors.white54, fontSize: 10),\n                  overflow: TextOverflow.ellipsis,\n                ),\n              ],\n            );\n          }\n\n          return Row(\n            children: [\n              Container(\n                padding: const EdgeInsets.all(8),\n                decoration: BoxDecoration(\n                  color: const Color(0xFF00B0FF).withValues(alpha: 0.15),\n                  borderRadius: BorderRadius.circular(8),\n                ),\n                child: const Icon(\n                  Icons.dns_rounded,\n                  color: Color(0xFF00B0FF),\n                  size: 22,\n                ),\n              ),\n              const SizedBox(width: 12),\n              Expanded(\n                child: Column(\n                  crossAxisAlignment: CrossAxisAlignment.start,\n                  children: [\n                    Row(\n                      children: [\n                        Text(\n                          'gcp-production-us-central1',\n                          style: GoogleFonts.jetBrainsMono(\n                            color: Colors.white,\n                            fontWeight: FontWeight.bold,\n                            fontSize: 15,\n                          ),\n                        ),\n                        const SizedBox(width: 8),\n                        Container(\n                          padding: const EdgeInsets.symmetric(\n                            horizontal: 6,\n                            vertical: 2,\n                          ),\n                          decoration: BoxDecoration(\n                            color: Colors.greenAccent.withValues(alpha: 0.2),\n                            borderRadius: BorderRadius.circular(4),\n                            border: Border.all(\n                              color: Colors.greenAccent.withValues(alpha: 0.4),\n                            ),\n                          ),\n                          child: Text(\n                            'HEALTHY',\n                            style: GoogleFonts.jetBrainsMono(\n                              color: Colors.greenAccent,\n                              fontSize: 10,\n                              fontWeight: FontWeight.bold,\n                            ),\n                          ),\n                        ),\n                      ],\n                    ),\n                    const SizedBox(height: 2),\n                    Text(\n                      'Debian GNU/Linux 12 (Bookworm) • Linux 5.15.0-generic • GCP e2-micro • Terraform & Ansible Managed',\n                      style: GoogleFonts.inter(\n                        color: Colors.white54,\n                        fontSize: 11,\n                      ),\n                      overflow: TextOverflow.ellipsis,\n                    ),\n                  ],\n                ),\n              ),\n              probeButton,\n            ],\n          );\n        },\n      ),\n    );\n  }\n\n  Widget _buildTabBar() {\n    return Container(\n      color: const Color(0xFF181C23),\n      child: LayoutBuilder(\n        builder: (context, constraints) {\n          final width = constraints.maxWidth;\n          final isCompact = width < 440;\n          final isMedium = width >= 440 && width < 620;\n\n          final String telemetryLabel;\n          final String servicesLabel;\n          final String zeroTrustLabel;\n\n          if (isCompact) {\n            telemetryLabel = 'Telemetry';\n            servicesLabel = 'Services';\n            zeroTrustLabel = 'Zero-Trust';\n          } else if (isMedium) {\n            telemetryLabel = 'Telemetry & RAM';\n            servicesLabel = 'Services';\n            zeroTrustLabel = 'Zero-Trust & Net';\n          } else {\n            telemetryLabel = 'Telemetry & Resources';\n            servicesLabel = 'Services & Containers';\n            zeroTrustLabel = 'Zero-Trust & Endpoints';\n          }\n\n          return TabBar(\n            controller: _tabController,\n            isScrollable: false,\n            labelColor: const Color(0xFF00B0FF),\n            unselectedLabelColor: Colors.white60,\n            indicatorColor: const Color(0xFF00B0FF),\n            indicatorSize: TabBarIndicatorSize.tab,\n            indicatorWeight: 3.0,\n            labelStyle: GoogleFonts.inter(\n              fontSize: isCompact ? 12 : 13,\n              fontWeight: FontWeight.w600,\n            ),\n            tabs: [\n              Tab(\n                child: FittedBox(\n                  fit: BoxFit.scaleDown,\n                  child: Row(\n                    mainAxisAlignment: MainAxisAlignment.center,\n                    mainAxisSize: MainAxisSize.min,\n                    children: [\n                      Icon(Icons.speed, size: isCompact ? 14 : 16),\n                      SizedBox(width: isCompact ? 4 : 6),\n                      Text(telemetryLabel),\n                    ],\n                  ),\n                ),\n              ),\n              Tab(\n                child: FittedBox(\n                  fit: BoxFit.scaleDown,\n                  child: Row(\n                    mainAxisAlignment: MainAxisAlignment.center,\n                    mainAxisSize: MainAxisSize.min,\n                    children: [\n                      Icon(Icons.layers, size: isCompact ? 14 : 16),\n                      SizedBox(width: isCompact ? 4 : 6),\n                      Text(servicesLabel),\n                    ],\n                  ),\n                ),\n              ),\n              Tab(\n                child: FittedBox(\n                  fit: BoxFit.scaleDown,\n                  child: Row(\n                    mainAxisAlignment: MainAxisAlignment.center,\n                    mainAxisSize: MainAxisSize.min,\n                    children: [\n                      Icon(Icons.shield_outlined, size: isCompact ? 14 : 16),\n                      SizedBox(width: isCompact ? 4 : 6),\n                      Text(zeroTrustLabel),\n                    ],\n                  ),\n                ),\n              ),\n            ],\n          );\n        },\n      ),\n    );\n  }\n\n  Widget _buildOverviewTab() {\n    return LayoutBuilder(\n      builder: (context, constraints) {\n        final isNarrow = constraints.maxWidth < 680;\n        final horizontalPadding = isNarrow ? 14.0 : 20.0;\n\n        final cpuCard = _buildMetricCard(\n          title: 'CPU UTILIZATION',\n          value: '14.2%',\n          detail: '2 vCPUs (GCP e2-micro)',\n          subdetail: 'Load: 0.18, 0.22, 0.19',\n          percent: 0.142,\n          color: Colors.blueAccent,\n          icon: Icons.memory,\n        );\n\n        final ramCard = _buildMetricCard(\n          title: 'PHYSICAL RAM',\n          value: '718 MB / 1024 MB',\n          detail: '70% Allocated',\n          subdetail: 'Free: 306 MB | Buffers: 84 MB',\n          percent: 0.70,\n          color: Colors.amberAccent,\n          icon: Icons.storage,\n        );\n\n        final swapCard = _buildMetricCard(\n          title: 'SWAP MEMORY (SysAdmin)',\n          value: '224 MB / 2048 MB',\n          detail: 'Tuned: vm.swappiness=20',\n          subdetail: 'OOM Prevention on 1GB RAM',\n          percent: 0.11,\n          color: Colors.tealAccent,\n          icon: Icons.cached,\n        );\n\n        final diskCard = _buildMetricCard(\n          title: 'PERSISTENT DISK',\n          value: '8.4 GB / 20.0 GB',\n          detail: 'pd-balanced rootfs',\n          subdetail: '11.6 GB available (42%)',\n          percent: 0.42,\n          color: Colors.purpleAccent,\n          icon: Icons.disc_full,\n        );\n\n        return ListView(\n          padding: EdgeInsets.all(horizontalPadding),\n          children: [\n\n            if (isNarrow)\n              Column(\n                children: [\n                  Row(\n                    children: [\n                      Expanded(child: cpuCard),\n                      const SizedBox(width: 10),\n                      Expanded(child: ramCard),\n                    ],\n                  ),\n                  const SizedBox(height: 10),\n                  Row(\n                    children: [\n                      Expanded(child: swapCard),\n                      const SizedBox(width: 10),\n                      Expanded(child: diskCard),\n                    ],\n                  ),\n                ],\n              )\n            else\n              Row(\n                children: [\n                  Expanded(child: cpuCard),\n                  const SizedBox(width: 12),\n                  Expanded(child: ramCard),\n                  const SizedBox(width: 12),\n                  Expanded(child: swapCard),\n                  const SizedBox(width: 12),\n                  Expanded(child: diskCard),\n                ],\n              ),\n            const SizedBox(height: 20),\n\n            Container(\n              padding: const EdgeInsets.all(16),\n              decoration: BoxDecoration(\n                color: const Color(0xFF1A1F26),\n                borderRadius: BorderRadius.circular(10),\n                border: Border.all(color: Colors.white10),\n              ),\n              child: Column(\n                crossAxisAlignment: CrossAxisAlignment.start,\n                children: [\n                  Row(\n                    children: [\n                      const Icon(\n                        Icons.tune,\n                        color: Color(0xFF00B0FF),\n                        size: 18,\n                      ),\n                      const SizedBox(width: 8),\n                      Expanded(\n                        child: Text(\n                          'SysAdmin Kernel & Memory Optimization Matrix',\n                          style: GoogleFonts.inter(\n                            color: Colors.white,\n                            fontWeight: FontWeight.bold,\n                            fontSize: 14,\n                          ),\n                        ),\n                      ),\n                    ],\n                  ),\n                  const SizedBox(height: 12),\n                  Wrap(\n                    spacing: 12,\n                    runSpacing: 10,\n                    children: [\n                      _buildSysctlTag(\n                        'vm.swappiness = 20',\n                        'Prioritize RAM, prevent aggressive swapping (roles/common)',\n                      ),\n                      _buildSysctlTag(\n                        'vm.vfs_cache_pressure = 50',\n                        'Retain inode/dentry caches for disk I/O performance',\n                      ),\n                      _buildSysctlTag(\n                        'net.ipv4.tcp_syncookies = 1',\n                        'SYN flood denial-of-service kernel protection',\n                      ),\n                      _buildSysctlTag(\n                        'net.ipv4.conf.all.rp_filter = 1',\n                        'Strict reverse path filtering IP spoofing protection',\n                      ),\n                      _buildSysctlTag(\n                        'net.ipv4.conf.all.accept_source_route = 0',\n                        'Disable malicious packet source routing',\n                      ),\n                    ],\n                  ),\n                ],\n              ),\n            ),\n            const SizedBox(height: 20),\n\n            Text(\n              'Managed Hosted Services (WE-IAC Topology)',\n              style: GoogleFonts.inter(\n                color: Colors.white,\n                fontWeight: FontWeight.bold,\n                fontSize: 15,\n              ),\n            ),\n            const SizedBox(height: 10),\n            _buildEndpointsTable(),\n          ],\n        );\n      },\n    );\n  }\n\n  Widget _buildMetricCard({\n    required String title,\n    required String value,\n    required String detail,\n    required String subdetail,\n    required double percent,\n    required Color color,\n    required IconData icon,\n  }) {\n    return Container(\n      padding: const EdgeInsets.all(14),\n      decoration: BoxDecoration(\n        color: const Color(0xFF1A1F26),\n        borderRadius: BorderRadius.circular(10),\n        border: Border.all(color: Colors.white10),\n      ),\n      child: Column(\n        crossAxisAlignment: CrossAxisAlignment.start,\n        children: [\n          Row(\n            mainAxisAlignment: MainAxisAlignment.spaceBetween,\n            children: [\n              Text(\n                title,\n                style: GoogleFonts.inter(\n                  color: Colors.white54,\n                  fontSize: 10,\n                  fontWeight: FontWeight.bold,\n                ),\n              ),\n              Icon(icon, color: color, size: 16),\n            ],\n          ),\n          const SizedBox(height: 8),\n          Text(\n            value,\n            style: GoogleFonts.jetBrainsMono(\n              color: Colors.white,\n              fontSize: 16,\n              fontWeight: FontWeight.bold,\n            ),\n          ),\n          const SizedBox(height: 6),\n          ClipRRect(\n            borderRadius: BorderRadius.circular(4),\n            child: LinearProgressIndicator(\n              value: percent,\n              backgroundColor: Colors.white10,\n              valueColor: AlwaysStoppedAnimation<Color>(color),\n              minHeight: 5,\n            ),\n          ),\n          const SizedBox(height: 8),\n          Text(\n            detail,\n            style: GoogleFonts.inter(\n              color: Colors.white70,\n              fontSize: 11,\n              fontWeight: FontWeight.w500,\n            ),\n          ),\n          Text(\n            subdetail,\n            style: GoogleFonts.jetBrainsMono(\n              color: Colors.white38,\n              fontSize: 9,\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n\n  Widget _buildSysctlTag(String cmd, String desc) {\n    return Container(\n      padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 6),\n      decoration: BoxDecoration(\n        color: const Color(0xFF232A34),\n        borderRadius: BorderRadius.circular(6),\n        border: Border.all(color: Colors.white12),\n      ),\n      child: Column(\n        crossAxisAlignment: CrossAxisAlignment.start,\n        children: [\n          Text(\n            cmd,\n            style: GoogleFonts.jetBrainsMono(\n              color: Colors.greenAccent,\n              fontSize: 11,\n              fontWeight: FontWeight.bold,\n            ),\n          ),\n          const SizedBox(height: 2),\n          Text(\n            desc,\n            style: GoogleFonts.inter(color: Colors.white60, fontSize: 10),\n          ),\n        ],\n      ),\n    );\n  }\n\n  Widget _buildServicesTab() {\n    final services = [\n      {\n        'name': 'nginx.service',\n        'type': 'systemd unit',\n        'status': 'active (running)',\n        'description':\n            'Reverse proxy, TLS 1.3 termination, leaky-bucket rate limiting',\n        'ports': '80/tcp, 443/tcp',\n        'icon': Icons.public,\n        'color': Colors.greenAccent,\n      },\n      {\n        'name': 'fail2ban.service',\n        'type': 'systemd unit',\n        'status': 'active (running)',\n        'description':\n            'Intrusion prevention: sshd (4 retries), nginx-limit-req (2h ban)',\n        'ports': 'iptables hooks',\n        'icon': Icons.gavel,\n        'color': Colors.greenAccent,\n      },\n      {\n        'name': 'ufw.service',\n        'type': 'systemd unit',\n        'status': 'active (running)',\n        'description':\n            'Default DENY incoming; allows 22 (rate-limited), 80, 443 only',\n        'ports': 'Netfilter / UFW',\n        'icon': Icons.security,\n        'color': Colors.greenAccent,\n      },\n      {\n        'name': 'docker.service',\n        'type': 'systemd unit',\n        'status': 'active (running)',\n        'description':\n            'Docker engine daemon hosting isolated container bridge networks',\n        'ports': 'unix:///var/run/docker.sock',\n        'icon': Icons.inventory_2,\n        'color': Colors.blueAccent,\n      },\n      {\n        'name': 'certbot.timer',\n        'type': 'systemd timer',\n        'status': 'active (waiting)',\n        'description':\n            'Twice-daily Let\\'s Encrypt certificate auto-renewal cron',\n        'ports': 'ACME HTTP-01',\n        'icon': Icons.lock_clock,\n        'color': Colors.tealAccent,\n      },\n      {\n        'name': 'systemd-journald',\n        'type': 'systemd unit',\n        'status': 'active (running)',\n        'description': 'Centralized journal storage with 200MB max disk quota',\n        'ports': 'kernel ring buffer',\n        'icon': Icons.receipt_long,\n        'color': Colors.white70,\n      },\n    ];\n\n    final containers = [\n      {\n        'name': 'friendly-social-backend',\n        'image': 'friendly-social-backend:latest',\n        'network': 'friendly-social-network (bridge)',\n        'internal_ip': '172.28.0.2',\n        'ports': '127.0.0.1:8070->8070 (Spring Boot 3 API)',\n        'health': 'Healthy (HTTP 200 /actuator/health)',\n        'security':\n            'Localhost-only reverse proxy binding; zero external direct port exposure.',\n      },\n      {\n        'name': 'friendly-social-postgres',\n        'image': 'postgres:16-alpine',\n        'network': 'friendly-social-network (bridge)',\n        'internal_ip': '172.28.0.3',\n        'ports': '5432/tcp (Internal Docker bridge only; port 5433 local dev)',\n        'health': 'Healthy (pg_isready)',\n        'security':\n            'Zero-Trust container boundary. Database access restricted to backend container.',\n      },\n      {\n        'name': 'bybl-api',\n        'image': 'bybl-api:latest',\n        'network': 'app-network (bridge)',\n        'internal_ip': '172.20.0.2',\n        'ports': '127.0.0.1:8080 (API), 127.0.0.1:8081 (Admin)',\n        'health': 'Healthy (HTTP 200)',\n        'security':\n            'Localhost-only proxy bindings; zero direct external access.',\n      },\n      {\n        'name': 'bybl-db',\n        'image': 'postgres:15-alpine',\n        'network': 'app-network (bridge)',\n        'internal_ip': '172.20.0.3',\n        'ports': 'ZERO host ports exposed (5432 internal bridge only)',\n        'health': 'Healthy (pg_isready)',\n        'security':\n            'Strict Zero-Trust isolation. Direct database connections from host or internet are impossible.',\n      },\n    ];\n\n    return ListView(\n      padding: const EdgeInsets.all(20),\n      children: [\n        Text(\n          'Core System Daemons (systemd)',\n          style: GoogleFonts.inter(\n            color: Colors.white,\n            fontWeight: FontWeight.bold,\n            fontSize: 15,\n          ),\n        ),\n        const SizedBox(height: 12),\n        ...services.map((svc) => _buildServiceRow(svc)),\n        const SizedBox(height: 24),\n        Text(\n          'Containerized Production Stack (Docker Engine)',\n          style: GoogleFonts.inter(\n            color: Colors.white,\n            fontWeight: FontWeight.bold,\n            fontSize: 15,\n          ),\n        ),\n        const SizedBox(height: 12),\n        ...containers.map((c) => _buildContainerCard(c)),\n      ],\n    );\n  }\n\n  Widget _buildServiceRow(Map<String, dynamic> svc) {\n    return Container(\n      margin: const EdgeInsets.only(bottom: 8),\n      padding: const EdgeInsets.all(12),\n      decoration: BoxDecoration(\n        color: const Color(0xFF1A1F26),\n        borderRadius: BorderRadius.circular(8),\n        border: Border.all(color: Colors.white10),\n      ),\n      child: Row(\n        children: [\n          Icon(svc['icon'] as IconData, color: svc['color'] as Color, size: 20),\n          const SizedBox(width: 12),\n          Expanded(\n            child: Column(\n              crossAxisAlignment: CrossAxisAlignment.start,\n              children: [\n                Row(\n                  children: [\n                    Text(\n                      svc['name'] as String,\n                      style: GoogleFonts.jetBrainsMono(\n                        color: Colors.white,\n                        fontWeight: FontWeight.bold,\n                        fontSize: 13,\n                      ),\n                    ),\n                    const SizedBox(width: 8),\n                    Container(\n                      padding: const EdgeInsets.symmetric(\n                        horizontal: 6,\n                        vertical: 1,\n                      ),\n                      decoration: BoxDecoration(\n                        color: Colors.greenAccent.withValues(alpha: 0.15),\n                        borderRadius: BorderRadius.circular(4),\n                      ),\n                      child: Text(\n                        svc['status'] as String,\n                        style: GoogleFonts.jetBrainsMono(\n                          color: Colors.greenAccent,\n                          fontSize: 9,\n                        ),\n                      ),\n                    ),\n                  ],\n                ),\n                const SizedBox(height: 2),\n                Text(\n                  svc['description'] as String,\n                  style: GoogleFonts.inter(color: Colors.white60, fontSize: 11),\n                ),\n              ],\n            ),\n          ),\n          Text(\n            svc['ports'] as String,\n            style: GoogleFonts.jetBrainsMono(\n              color: Colors.white38,\n              fontSize: 10,\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n\n  Widget _buildContainerCard(Map<String, dynamic> c) {\n    return Container(\n      margin: const EdgeInsets.only(bottom: 12),\n      padding: const EdgeInsets.all(14),\n      decoration: BoxDecoration(\n        color: const Color(0xFF1A1F26),\n        borderRadius: BorderRadius.circular(8),\n        border: Border.all(\n          color: const Color(0xFF00B0FF).withValues(alpha: 0.3),\n        ),\n      ),\n      child: Column(\n        crossAxisAlignment: CrossAxisAlignment.start,\n        children: [\n          Wrap(\n            spacing: 8,\n            runSpacing: 6,\n            crossAxisAlignment: WrapCrossAlignment.center,\n            alignment: WrapAlignment.spaceBetween,\n            children: [\n              Row(\n                mainAxisSize: MainAxisSize.min,\n                children: [\n                  const Icon(\n                    Icons.view_in_ar,\n                    color: Color(0xFF00B0FF),\n                    size: 18,\n                  ),\n                  const SizedBox(width: 8),\n                  Text(\n                    c['name'] as String,\n                    style: GoogleFonts.jetBrainsMono(\n                      color: Colors.white,\n                      fontWeight: FontWeight.bold,\n                      fontSize: 13,\n                    ),\n                  ),\n                ],\n              ),\n              Text(\n                '(\${c['image']})',\n                style: GoogleFonts.jetBrainsMono(\n                  color: Colors.white54,\n                  fontSize: 11,\n                ),\n              ),\n              Container(\n                padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 2),\n                decoration: BoxDecoration(\n                  color: Colors.greenAccent.withValues(alpha: 0.15),\n                  borderRadius: BorderRadius.circular(4),\n                ),\n                child: Text(\n                  c['health'] as String,\n                  style: GoogleFonts.jetBrainsMono(\n                    color: Colors.greenAccent,\n                    fontSize: 10,\n                  ),\n                ),\n              ),\n            ],\n          ),\n          const SizedBox(height: 10),\n          Row(\n            crossAxisAlignment: CrossAxisAlignment.start,\n            children: [\n              Text(\n                'Network Binding: ',\n                style: GoogleFonts.inter(color: Colors.white54, fontSize: 11),\n              ),\n              Expanded(\n                child: Text(\n                  c['ports'] as String,\n                  style: GoogleFonts.jetBrainsMono(\n                    color: Colors.amberAccent,\n                    fontSize: 11,\n                  ),\n                ),\n              ),\n            ],\n          ),\n          const SizedBox(height: 4),\n          Row(\n            crossAxisAlignment: CrossAxisAlignment.start,\n            children: [\n              Text(\n                'Zero-Trust Architecture: ',\n                style: GoogleFonts.inter(color: Colors.white54, fontSize: 11),\n              ),\n              Expanded(\n                child: Text(\n                  c['security'] as String,\n                  style: GoogleFonts.inter(color: Colors.white70, fontSize: 11),\n                ),\n              ),\n            ],\n          ),\n        ],\n      ),\n    );\n  }\n\n  Widget _buildNetworkAndSecurityTab() {\n    return ListView(\n      padding: const EdgeInsets.all(20),\n      children: [\n\n        Container(\n          padding: const EdgeInsets.all(16),\n          decoration: BoxDecoration(\n            color: const Color(0xFF1A1F26),\n            borderRadius: BorderRadius.circular(10),\n            border: Border.all(color: Colors.white10),\n          ),\n          child: Column(\n            crossAxisAlignment: CrossAxisAlignment.start,\n            children: [\n              Row(\n                children: [\n                  const Icon(Icons.hub, color: Color(0xFF00B0FF), size: 18),\n                  const SizedBox(width: 8),\n                  Text(\n                    'Multi-Layer Defense & Routing Topology',\n                    style: GoogleFonts.inter(\n                      color: Colors.white,\n                      fontWeight: FontWeight.bold,\n                      fontSize: 14,\n                    ),\n                  ),\n                ],\n              ),\n              const SizedBox(height: 14),\n              SingleChildScrollView(\n                scrollDirection: Axis.horizontal,\n                child: Row(\n                  children: [\n                    _buildTopologyNode(\n                      'Internet Clients',\n                      'Global HTTPS Traffic',\n                      Icons.language,\n                      Colors.blue,\n                    ),\n                    _buildTopologyArrow(),\n                    _buildTopologyNode(\n                      'Cloudflare DNS',\n                      'Automated A-Records via Terraform',\n                      Icons.cloud_queue,\n                      Colors.orange,\n                    ),\n                    _buildTopologyArrow(),\n                    _buildTopologyNode(\n                      'GCP Cloud Firewall',\n                      'Ingress Ports 80, 443, 22 only',\n                      Icons.security,\n                      Colors.amber,\n                    ),\n                    _buildTopologyArrow(),\n                    _buildTopologyNode(\n                      'Host UFW + Fail2ban',\n                      'Rate-limiting & IP Jails',\n                      Icons.lock,\n                      Colors.redAccent,\n                    ),\n                    _buildTopologyArrow(),\n                    _buildTopologyNode(\n                      'Nginx Reverse Proxy',\n                      'TLS 1.3 & Static/API Zones',\n                      Icons.alt_route,\n                      Colors.green,\n                    ),\n                    _buildTopologyArrow(),\n                    _buildTopologyNode(\n                      'Docker Bridge / Webroot',\n                      'Isolated 172.20.0.0/16 Network',\n                      Icons.layers,\n                      Colors.purpleAccent,\n                    ),\n                  ],\n                ),\n              ),\n            ],\n          ),\n        ),\n        const SizedBox(height: 20),\n\n        Text(\n          'UFW Host Firewall Ruleset',\n          style: GoogleFonts.inter(\n            color: Colors.white,\n            fontWeight: FontWeight.bold,\n            fontSize: 15,\n          ),\n        ),\n        const SizedBox(height: 10),\n        Container(\n          padding: const EdgeInsets.all(14),\n          decoration: BoxDecoration(\n            color: const Color(0xFF1A1F26),\n            borderRadius: BorderRadius.circular(8),\n            border: Border.all(color: Colors.white10),\n          ),\n          child: Column(\n            children: [\n              _buildFirewallRuleRow(\n                '22/tcp',\n                'LIMIT IN',\n                'Anywhere',\n                'sshd brute-force prevention',\n              ),\n              const Divider(color: Colors.white10),\n              _buildFirewallRuleRow(\n                '80/tcp',\n                'ALLOW IN',\n                'Anywhere',\n                'HTTP Certbot challenges & 301 redirects',\n              ),\n              const Divider(color: Colors.white10),\n              _buildFirewallRuleRow(\n                '443/tcp',\n                'ALLOW IN',\n                'Anywhere',\n                'HTTPS TLS 1.3 production traffic',\n              ),\n              const Divider(color: Colors.white10),\n              _buildFirewallRuleRow(\n                '5432/tcp',\n                'DENY IN',\n                'Anywhere',\n                'PostgreSQL database host lockdown',\n              ),\n              const Divider(color: Colors.white10),\n              _buildFirewallRuleRow(\n                '8080-8081',\n                'DENY IN',\n                'Anywhere',\n                'Backend API direct port shielding',\n              ),\n            ],\n          ),\n        ),\n      ],\n    );\n  }\n\n  Widget _buildTopologyNode(\n    String title,\n    String subtitle,\n    IconData icon,\n    Color color,\n  ) {\n    return Container(\n      width: 150,\n      padding: const EdgeInsets.all(12),\n      decoration: BoxDecoration(\n        color: const Color(0xFF222832),\n        borderRadius: BorderRadius.circular(8),\n        border: Border.all(color: color.withValues(alpha: 0.4)),\n      ),\n      child: Column(\n        children: [\n          Icon(icon, color: color, size: 24),\n          const SizedBox(height: 8),\n          Text(\n            title,\n            textAlign: TextAlign.center,\n            style: GoogleFonts.inter(\n              color: Colors.white,\n              fontWeight: FontWeight.bold,\n              fontSize: 11,\n            ),\n          ),\n          const SizedBox(height: 4),\n          Text(\n            subtitle,\n            textAlign: TextAlign.center,\n            style: GoogleFonts.inter(color: Colors.white54, fontSize: 9),\n          ),\n        ],\n      ),\n    );\n  }\n\n  Widget _buildTopologyArrow() {\n    return const Padding(\n      padding: EdgeInsets.symmetric(horizontal: 8),\n      child: Icon(Icons.arrow_forward, color: Colors.white30, size: 16),\n    );\n  }\n\n  Widget _buildFirewallRuleRow(\n    String port,\n    String action,\n    String from,\n    String reason,\n  ) {\n    final isAllow = action.contains('ALLOW');\n    final isLimit = action.contains('LIMIT');\n\n    return Padding(\n      padding: const EdgeInsets.symmetric(vertical: 5),\n      child: LayoutBuilder(\n        builder: (context, constraints) {\n          final isNarrow = constraints.maxWidth < 480;\n          if (isNarrow) {\n            return Column(\n              crossAxisAlignment: CrossAxisAlignment.start,\n              children: [\n                Row(\n                  children: [\n                    SizedBox(\n                      width: 75,\n                      child: Text(\n                        port,\n                        style: GoogleFonts.jetBrainsMono(\n                          color: Colors.white,\n                          fontSize: 12,\n                          fontWeight: FontWeight.bold,\n                        ),\n                      ),\n                    ),\n                    Container(\n                      padding: const EdgeInsets.symmetric(\n                        horizontal: 6,\n                        vertical: 2,\n                      ),\n                      decoration: BoxDecoration(\n                        color: isAllow\n                            ? Colors.greenAccent.withValues(alpha: 0.15)\n                            : isLimit\n                            ? Colors.amberAccent.withValues(alpha: 0.15)\n                            : Colors.redAccent.withValues(alpha: 0.15),\n                        borderRadius: BorderRadius.circular(4),\n                      ),\n                      child: Text(\n                        action,\n                        style: GoogleFonts.jetBrainsMono(\n                          color: isAllow\n                              ? Colors.greenAccent\n                              : isLimit\n                              ? Colors.amberAccent\n                              : Colors.redAccent,\n                          fontSize: 10,\n                          fontWeight: FontWeight.bold,\n                        ),\n                      ),\n                    ),\n                    const SizedBox(width: 8),\n                    Text(\n                      from,\n                      style: GoogleFonts.inter(\n                        color: Colors.white54,\n                        fontSize: 11,\n                      ),\n                    ),\n                  ],\n                ),\n                const SizedBox(height: 3),\n                Text(\n                  reason,\n                  style: GoogleFonts.inter(color: Colors.white70, fontSize: 11),\n                ),\n              ],\n            );\n          }\n          return Row(\n            children: [\n              SizedBox(\n                width: 80,\n                child: Text(\n                  port,\n                  style: GoogleFonts.jetBrainsMono(\n                    color: Colors.white,\n                    fontSize: 12,\n                    fontWeight: FontWeight.bold,\n                  ),\n                ),\n              ),\n              Container(\n                padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2),\n                decoration: BoxDecoration(\n                  color: isAllow\n                      ? Colors.greenAccent.withValues(alpha: 0.15)\n                      : isLimit\n                      ? Colors.amberAccent.withValues(alpha: 0.15)\n                      : Colors.redAccent.withValues(alpha: 0.15),\n                  borderRadius: BorderRadius.circular(4),\n                ),\n                child: Text(\n                  action,\n                  style: GoogleFonts.jetBrainsMono(\n                    color: isAllow\n                        ? Colors.greenAccent\n                        : isLimit\n                        ? Colors.amberAccent\n                        : Colors.redAccent,\n                    fontSize: 10,\n                    fontWeight: FontWeight.bold,\n                  ),\n                ),\n              ),\n              const SizedBox(width: 14),\n              SizedBox(\n                width: 80,\n                child: Text(\n                  from,\n                  style: GoogleFonts.inter(color: Colors.white54, fontSize: 11),\n                ),\n              ),\n              Expanded(\n                child: Text(\n                  reason,\n                  style: GoogleFonts.inter(color: Colors.white70, fontSize: 11),\n                ),\n              ),\n            ],\n          );\n        },\n      ),\n    );\n  }\n\n  Widget _buildEndpointsTable() {\n    return Container(\n      decoration: BoxDecoration(\n        color: const Color(0xFF1A1F26),\n        borderRadius: BorderRadius.circular(8),\n        border: Border.all(color: Colors.white10),\n      ),\n      child: SingleChildScrollView(\n        scrollDirection: Axis.horizontal,\n        child: ConstrainedBox(\n          constraints: const BoxConstraints(minWidth: 580),\n          child: Table(\n            columnWidths: const {\n              0: FlexColumnWidth(2.5),\n              1: FlexColumnWidth(2),\n              2: FlexColumnWidth(1.2),\n              3: FlexColumnWidth(1.2),\n              4: FlexColumnWidth(1.2),\n            },\n            children: [\n              TableRow(\n                decoration: const BoxDecoration(\n                  border: Border(bottom: BorderSide(color: Colors.white12)),\n                ),\n                children: [\n                  _buildTableHeaderCell('DOMAIN'),\n                  _buildTableHeaderCell('TYPE'),\n                  _buildTableHeaderCell('RATE LIMIT'),\n                  _buildTableHeaderCell('STATUS'),\n                  _buildTableHeaderCell('LATENCY'),\n                ],\n              ),\n              ..._endpoints.map((ep) {\n                return TableRow(\n                  decoration: const BoxDecoration(\n                    border: Border(bottom: BorderSide(color: Colors.white10)),\n                  ),\n                  children: [\n                    Padding(\n                      padding: const EdgeInsets.symmetric(\n                        horizontal: 12,\n                        vertical: 10,\n                      ),\n                      child: Text(\n                        ep['domain'] as String,\n                        style: GoogleFonts.jetBrainsMono(\n                          color: Colors.white,\n                          fontSize: 12,\n                          fontWeight: FontWeight.w600,\n                        ),\n                      ),\n                    ),\n                    Padding(\n                      padding: const EdgeInsets.symmetric(\n                        horizontal: 12,\n                        vertical: 10,\n                      ),\n                      child: Text(\n                        ep['type'] as String,\n                        style: GoogleFonts.inter(\n                          color: Colors.white60,\n                          fontSize: 11,\n                        ),\n                      ),\n                    ),\n                    Padding(\n                      padding: const EdgeInsets.symmetric(\n                        horizontal: 12,\n                        vertical: 10,\n                      ),\n                      child: Text(\n                        ep['rateLimit'] as String,\n                        style: GoogleFonts.jetBrainsMono(\n                          color: Colors.amberAccent,\n                          fontSize: 11,\n                        ),\n                      ),\n                    ),\n                    Padding(\n                      padding: const EdgeInsets.symmetric(\n                        horizontal: 12,\n                        vertical: 10,\n                      ),\n                      child: Row(\n                        children: [\n                          const Icon(\n                            Icons.check_circle,\n                            color: Colors.greenAccent,\n                            size: 14,\n                          ),\n                          const SizedBox(width: 4),\n                          Text(\n                            '\${ep['status']}',\n                            style: GoogleFonts.jetBrainsMono(\n                              color: Colors.greenAccent,\n                              fontSize: 11,\n                              fontWeight: FontWeight.bold,\n                            ),\n                          ),\n                        ],\n                      ),\n                    ),\n                    Padding(\n                      padding: const EdgeInsets.symmetric(\n                        horizontal: 12,\n                        vertical: 10,\n                      ),\n                      child: Text(\n                        '\${ep['latency']} ms',\n                        style: GoogleFonts.jetBrainsMono(\n                          color: const Color(0xFF00B0FF),\n                          fontSize: 11,\n                        ),\n                      ),\n                    ),\n                  ],\n                );\n              }),\n            ],\n          ),\n        ),\n      ),\n    );\n  }\n\n  Widget _buildTableHeaderCell(String label) {\n    return Padding(\n      padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 10),\n      child: Text(\n        label,\n        style: GoogleFonts.inter(\n          color: Colors.white38,\n          fontSize: 10,\n          fontWeight: FontWeight.bold,\n        ),\n      ),\n    );\n  }\n}",
  "lib/apps/music_player_app.dart": "import 'dart:async';\nimport 'package:flutter/material.dart';\nimport 'package:flutter/services.dart';\nimport 'package:audioplayers/audioplayers.dart';\nimport 'package:google_fonts/google_fonts.dart';\nimport 'package:provider/provider.dart';\nimport '../system_settings.dart';\n\nclass MusicPlayerApp extends StatefulWidget {\n  const MusicPlayerApp({super.key});\n\n  @override\n  State<MusicPlayerApp> createState() => _MusicPlayerAppState();\n}\n\nclass _MusicPlayerAppState extends State<MusicPlayerApp> {\n  late Future<List<String>> _tracksFuture;\n  List<String> _tracks = [];\n\n  late AudioPlayer _audioPlayer;\n  int _currentTrackIndex = 0;\n  bool _isPlaying = false;\n  Duration _duration = Duration.zero;\n  Duration _position = Duration.zero;\n\n  StreamSubscription? _durationSubscription;\n  StreamSubscription? _positionSubscription;\n  StreamSubscription? _playerCompleteSubscription;\n  StreamSubscription? _playerStateSubscription;\n\n  @override\n  void initState() {\n    super.initState();\n    _audioPlayer = AudioPlayer();\n    _setupAudioListeners();\n    _tracksFuture = _loadTracks();\n  }\n\n  Future<List<String>> _loadTracks() async {\n    final assetManifest = await AssetManifest.loadFromAssetBundle(rootBundle);\n    final tracks = assetManifest\n        .listAssets()\n        .where((key) => key.startsWith('assets/music/') && key.endsWith('.wav'))\n        .toList();\n\n    tracks.sort();\n\n    if (tracks.isNotEmpty && mounted) {\n      setState(() {\n        _tracks = tracks;\n      });\n    }\n    return tracks;\n  }\n\n  void _setupAudioListeners() {\n    _durationSubscription = _audioPlayer.onDurationChanged.listen((d) {\n      if (mounted) setState(() => _duration = d);\n    });\n\n    _positionSubscription = _audioPlayer.onPositionChanged.listen((p) {\n      if (mounted) setState(() => _position = p);\n    });\n\n    _playerCompleteSubscription = _audioPlayer.onPlayerComplete.listen((event) {\n      if (mounted) _next();\n    });\n\n    _playerStateSubscription = _audioPlayer.onPlayerStateChanged.listen((state) {\n      if (mounted) {\n        setState(() {\n          _isPlaying = state == PlayerState.playing;\n        });\n      }\n    });\n  }\n\n  @override\n  void dispose() {\n    _durationSubscription?.cancel();\n    _positionSubscription?.cancel();\n    _playerCompleteSubscription?.cancel();\n    _playerStateSubscription?.cancel();\n    _audioPlayer.dispose();\n    super.dispose();\n  }\n\n  Future<void> _playPause() async {\n    if (_tracks.isEmpty) return;\n\n    if (_isPlaying) {\n      await _audioPlayer.pause();\n    } else {\n      if (_position == Duration.zero && _duration == Duration.zero) {\n        await _playTrack();\n      } else {\n        await _audioPlayer.resume();\n      }\n    }\n  }\n\n  Future<void> _playTrack() async {\n    if (_tracks.isEmpty) return;\n\n    final trackPath = _tracks[_currentTrackIndex];\n\n    final relativePath = trackPath.replaceFirst('assets/', '');\n\n    await _audioPlayer.setSource(AssetSource(relativePath));\n    await _audioPlayer.resume();\n  }\n\n  Future<void> _next() async {\n    if (_tracks.isEmpty) return;\n    setState(() {\n      _currentTrackIndex = (_currentTrackIndex + 1) % _tracks.length;\n    });\n    await _playTrack();\n  }\n\n  Future<void> _previous() async {\n    if (_tracks.isEmpty) return;\n    setState(() {\n      _currentTrackIndex = (_currentTrackIndex - 1 + _tracks.length) % _tracks.length;\n    });\n    await _playTrack();\n  }\n\n  String _formatDuration(Duration duration) {\n    String twoDigits(int n) => n.toString().padLeft(2, \"0\");\n    String twoDigitMinutes = twoDigits(duration.inMinutes.remainder(60));\n    String twoDigitSeconds = twoDigits(duration.inSeconds.remainder(60));\n    return \"\$twoDigitMinutes:\$twoDigitSeconds\";\n  }\n\n  String _cleanTrackName(String name) {\n\n    final fileName = name.split('/').last;\n    return fileName.replaceAll('.wav', '').replaceAll('.m4a', '').replaceAll('_', ' ');\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final settings = context.watch<SystemSettings>();\n    final accentColor = settings.accentColor;\n    final onSurfaceColor = Theme.of(context).colorScheme.onSurface;\n\n    return FutureBuilder<List<String>>(\n      future: _tracksFuture,\n      builder: (context, snapshot) {\n        if (snapshot.connectionState == ConnectionState.waiting) {\n          return const Center(child: CircularProgressIndicator());\n        }\n\n        if (_tracks.isEmpty) {\n          return Center(\n            child: Text(\n              'No music found in assets/music/',\n              style: GoogleFonts.inter(\n                color: onSurfaceColor.withOpacity(0.5),\n              ),\n            ),\n          );\n        }\n\n        return Padding(\n          padding: const EdgeInsets.all(32.0),\n          child: Column(\n            crossAxisAlignment: CrossAxisAlignment.start,\n            children: [\n              Text(\n                'Now Playing',\n                style: GoogleFonts.outfit(\n                  color: onSurfaceColor,\n                  fontSize: 28,\n                  fontWeight: FontWeight.bold,\n                ),\n              ),\n              const SizedBox(height: 24),\n              _buildPlayerControls(accentColor, onSurfaceColor),\n              const SizedBox(height: 32),\n              Expanded(\n                child: _buildTracklist(accentColor, onSurfaceColor),\n              ),\n            ],\n          ),\n        );\n      },\n    );\n  }\n\n  Widget _buildPlayerControls(Color accentColor, Color onSurfaceColor) {\n    final trackName = _tracks.isNotEmpty ? _cleanTrackName(_tracks[_currentTrackIndex]) : 'Unknown';\n\n    return Container(\n      padding: const EdgeInsets.all(24),\n      decoration: BoxDecoration(\n        color: onSurfaceColor.withOpacity(0.05),\n        borderRadius: BorderRadius.circular(16),\n        border: Border.all(\n          color: onSurfaceColor.withOpacity(0.1),\n        ),\n      ),\n      child: Column(\n        children: [\n          Text(\n            trackName.toUpperCase(),\n            style: GoogleFonts.inter(\n              color: onSurfaceColor,\n              fontSize: 18,\n              fontWeight: FontWeight.bold,\n              letterSpacing: 1.2,\n            ),\n            textAlign: TextAlign.center,\n            maxLines: 1,\n            overflow: TextOverflow.ellipsis,\n          ),\n          const SizedBox(height: 24),\n          Row(\n            children: [\n              Text(\n                _formatDuration(_position),\n                style: GoogleFonts.jetBrainsMono(\n                  color: onSurfaceColor.withOpacity(0.5),\n                  fontSize: 12,\n                ),\n              ),\n              Expanded(\n                child: SliderTheme(\n                  data: SliderThemeData(\n                    trackHeight: 2,\n                    activeTrackColor: accentColor,\n                    inactiveTrackColor: onSurfaceColor.withOpacity(0.1),\n                    thumbColor: accentColor,\n                    thumbShape: const RoundSliderThumbShape(enabledThumbRadius: 6),\n                    overlayShape: const RoundSliderOverlayShape(overlayRadius: 14),\n                  ),\n                  child: Slider(\n                    value: _position.inMilliseconds.toDouble(),\n                    max: _duration.inMilliseconds.toDouble() > 0\n                        ? _duration.inMilliseconds.toDouble()\n                        : 1.0,\n                    onChanged: (value) {\n                      _audioPlayer.seek(Duration(milliseconds: value.toInt()));\n                    },\n                  ),\n                ),\n              ),\n              Text(\n                _formatDuration(_duration),\n                style: GoogleFonts.jetBrainsMono(\n                  color: onSurfaceColor.withOpacity(0.5),\n                  fontSize: 12,\n                ),\n              ),\n            ],\n          ),\n          const SizedBox(height: 16),\n          Row(\n            mainAxisAlignment: MainAxisAlignment.center,\n            children: [\n              IconButton(\n                icon: const Icon(Icons.skip_previous),\n                color: onSurfaceColor,\n                iconSize: 32,\n                onPressed: _previous,\n              ),\n              const SizedBox(width: 16),\n              Container(\n                decoration: BoxDecoration(\n                  color: accentColor,\n                  shape: BoxShape.circle,\n                ),\n                child: IconButton(\n                  icon: Icon(_isPlaying ? Icons.pause : Icons.play_arrow),\n                  color: Colors.white,\n                  iconSize: 40,\n                  onPressed: _playPause,\n                ),\n              ),\n              const SizedBox(width: 16),\n              IconButton(\n                icon: const Icon(Icons.skip_next),\n                color: onSurfaceColor,\n                iconSize: 32,\n                onPressed: _next,\n              ),\n            ],\n          ),\n        ],\n      ),\n    );\n  }\n\n  Widget _buildTracklist(Color accentColor, Color onSurfaceColor) {\n    return Column(\n      crossAxisAlignment: CrossAxisAlignment.start,\n      children: [\n        Text(\n          'Tracks',\n          style: GoogleFonts.inter(\n            color: onSurfaceColor.withOpacity(0.5),\n            fontSize: 14,\n            fontWeight: FontWeight.bold,\n          ),\n        ),\n        const SizedBox(height: 16),\n        Expanded(\n          child: ListView.builder(\n            itemCount: _tracks.length,\n            itemBuilder: (context, index) {\n              final track = _tracks[index];\n              final isCurrent = index == _currentTrackIndex;\n              final trackName = _cleanTrackName(track);\n\n              return ListTile(\n                contentPadding: const EdgeInsets.symmetric(horizontal: 16, vertical: 4),\n                shape: RoundedRectangleBorder(\n                  borderRadius: BorderRadius.circular(12),\n                ),\n                tileColor: isCurrent ? accentColor.withOpacity(0.1) : Colors.transparent,\n                leading: isCurrent && _isPlaying\n                    ? _buildPlayingIndicator(accentColor)\n                    : Icon(\n                        Icons.music_note,\n                        color: isCurrent ? accentColor : onSurfaceColor.withOpacity(0.3),\n                      ),\n                title: Text(\n                  trackName.toUpperCase(),\n                  style: GoogleFonts.inter(\n                    color: isCurrent ? accentColor : onSurfaceColor,\n                    fontWeight: isCurrent ? FontWeight.bold : FontWeight.normal,\n                    fontSize: 14,\n                  ),\n                ),\n                onTap: () {\n                  setState(() => _currentTrackIndex = index);\n                  _playTrack();\n                },\n              );\n            },\n          ),\n        ),\n      ],\n    );\n  }\n\n  Widget _buildPlayingIndicator(Color color) {\n    return SizedBox(\n      height: 16,\n      width: 24,\n      child: Row(\n        mainAxisAlignment: MainAxisAlignment.spaceEvenly,\n        crossAxisAlignment: CrossAxisAlignment.end,\n        children: List.generate(\n          3,\n          (i) => _PlayingBar(color: color, delay: i * 200),\n        ),\n      ),\n    );\n  }\n}\n\nclass _PlayingBar extends StatefulWidget {\n  final Color color;\n  final int delay;\n  const _PlayingBar({required this.color, required this.delay});\n\n  @override\n  State<_PlayingBar> createState() => _PlayingBarState();\n}\n\nclass _PlayingBarState extends State<_PlayingBar> with SingleTickerProviderStateMixin {\n  late AnimationController _controller;\n\n  @override\n  void initState() {\n    super.initState();\n    _controller = AnimationController(\n      vsync: this,\n      duration: const Duration(milliseconds: 600),\n    );\n    Future.delayed(Duration(milliseconds: widget.delay), () {\n      if (mounted) _controller.repeat(reverse: true);\n    });\n  }\n\n  @override\n  void dispose() {\n    _controller.dispose();\n    super.dispose();\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return AnimatedBuilder(\n      animation: _controller,\n      builder: (context, child) {\n        return Container(\n          width: 3,\n          height: 4 + (12 * _controller.value),\n          decoration: BoxDecoration(\n             color: widget.color,\n             borderRadius: BorderRadius.circular(2),\n          ),\n        );\n      },\n    );\n  }\n}",
  "lib/apps/file_explorer_app.dart": "import 'package:flutter/material.dart';\nimport 'package:google_fonts/google_fonts.dart';\nimport 'package:provider/provider.dart';\nimport '../system_controller.dart';\nimport 'resume_app.dart';\nimport 'infra_monitor_app.dart';\nimport 'code_editor_app.dart';\nimport 'grand_theft_ant/grand_theft_ant_app.dart';\n\nclass FileExplorerApp extends StatefulWidget {\n  const FileExplorerApp({super.key});\n\n  @override\n  State<FileExplorerApp> createState() => _FileExplorerAppState();\n}\n\nclass _FileExplorerAppState extends State<FileExplorerApp> {\n  String _currentPath = 'Home';\n\n  final Map<String, List<Map<String, dynamic>>> _folders = {\n    'Home': [\n      {\n        'name': 'Projects',\n        'icon': Icons.folder,\n        'color': Colors.blue,\n        'isFolder': true,\n      },\n      {\n        'name': 'Infrastructure',\n        'icon': Icons.folder,\n        'color': Colors.cyan,\n        'isFolder': true,\n      },\n      {\n        'name': 'Music',\n        'icon': Icons.folder,\n        'color': Colors.purpleAccent,\n        'isFolder': true,\n      },\n      {\n        'name': 'resume.pdf',\n        'icon': Icons.picture_as_pdf,\n        'color': Colors.red,\n        'isFolder': false,\n      },\n    ],\n    'Projects': [\n      {\n        'name': 'friend.ly.html',\n        'icon': Icons.html,\n        'color': Colors.cyanAccent,\n        'isFolder': false,\n        'url': 'https://friendly.archerwoods.dev',\n        'external': true,\n      },\n      {\n        'name': 'grand_theft_ant.game',\n        'icon': Icons.sports_esports_rounded,\n        'color': const Color(0xFF7FA650),\n        'isFolder': false,\n        'openGame': true,\n      },\n      {\n        'name': 'libretrac.html',\n        'icon': Icons.html,\n        'color': Colors.orange,\n        'isFolder': false,\n        'url': 'https://libretrac.site',\n        'external': true,\n      },\n      {\n        'name': 'welledumacated.html',\n        'icon': Icons.html,\n        'color': Colors.orange,\n        'isFolder': false,\n        'url': 'https://welledumacated.dev',\n        'external': true,\n      },\n      {\n        'name': 'bybl.html',\n        'icon': Icons.html,\n        'color': Colors.orange,\n        'isFolder': false,\n        'url': 'https://bybl.dev',\n        'external': true,\n      },\n      {\n        'name': 'theolivebranch.html',\n        'icon': Icons.html,\n        'color': Colors.orange,\n        'isFolder': false,\n        'url': 'https://theolivebranch.press',\n        'external': true,\n      },\n      {\n        'name': 'fyr.html',\n        'icon': Icons.html,\n        'color': Colors.orange,\n        'isFolder': false,\n        'url': 'https://fyr.software',\n        'external': true,\n      },\n    ],\n    'Infrastructure': [\n      {\n        'name': 'WE-IAC-Terraform',\n        'icon': Icons.cloud_outlined,\n        'color': Colors.purpleAccent,\n        'isFolder': false,\n        'openCode': true,\n      },\n      {\n        'name': 'Ansible-Deploy',\n        'icon': Icons.bolt,\n        'color': Colors.greenAccent,\n        'isFolder': false,\n        'openCode': true,\n      },\n      {\n        'name': 'Docker-Compose',\n        'icon': Icons.view_in_ar,\n        'color': Colors.blueAccent,\n        'isFolder': false,\n        'openCode': true,\n      },\n      {\n        'name': 'Infra-Monitor.app',\n        'icon': Icons.dns_rounded,\n        'color': Colors.cyanAccent,\n        'isFolder': false,\n        'openInfra': true,\n      },\n    ],\n    'Music': [\n      {\n        'name': 'archbtw.wav',\n        'icon': Icons.music_note,\n        'color': Colors.purple,\n        'isFolder': false,\n        'url': 'https://archBTW.sh',\n        'external': true,\n      },\n      {\n        'name': 'violetapparition.mp3',\n        'icon': Icons.music_note,\n        'color': Colors.purple,\n        'isFolder': false,\n        'url': 'https://violetapparition.com',\n        'external': true,\n      },\n    ],\n  };\n\n  void _navigateTo(String folder) {\n    if (_folders.containsKey(folder)) {\n      setState(() {\n        _currentPath = folder;\n      });\n    }\n  }\n\n  void _goBack() {\n    if (_currentPath != 'Home') {\n      setState(() {\n        _currentPath = 'Home';\n      });\n    }\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final files = _folders[_currentPath] ?? [];\n    final isMobile = MediaQuery.of(context).size.width < 600;\n\n    return Material(\n      color: Colors.transparent,\n      child: Column(\n        children: [\n          Container(\n            padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 8),\n            color: Colors.white.withValues(alpha: 0.05),\n            child: Row(\n              children: [\n                IconButton(\n                  icon: const Icon(\n                    Icons.arrow_back,\n                    size: 18,\n                    color: Colors.white54,\n                  ),\n                  onPressed: _currentPath == 'Home' ? null : _goBack,\n                ),\n                const SizedBox(width: 8),\n                const Icon(\n                  Icons.arrow_forward,\n                  size: 18,\n                  color: Colors.white54,\n                ),\n                const SizedBox(width: 24),\n                Text(\n                  'Home > \$_currentPath',\n                  style: GoogleFonts.inter(color: Colors.white70, fontSize: 13),\n                ),\n                const Spacer(),\n                const Icon(Icons.search, size: 18, color: Colors.white54),\n                const SizedBox(width: 16),\n                const Icon(Icons.view_module, size: 18, color: Colors.white54),\n              ],\n            ),\n          ),\n\n          Expanded(\n            child: GridView.builder(\n              padding: const EdgeInsets.all(24),\n              gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(\n                crossAxisCount: isMobile ? 3 : 6,\n                crossAxisSpacing: 20,\n                mainAxisSpacing: 20,\n              ),\n              itemCount: files.length,\n              itemBuilder: (context, index) {\n                final file = files[index];\n                return InkWell(\n                  onTap: () {\n                    if (file['isFolder'] == true) {\n                      _navigateTo(file['name'] as String);\n                    } else if (file['name'] == 'resume.pdf') {\n                      context.read<SystemController>().openApp(\n                        'resume',\n                        'Resume',\n                        const ResumeApp(),\n                        Icons.picture_as_pdf,\n                      );\n                    } else if (file['openGame'] == true) {\n                      context.read<SystemController>().openApp(\n                        'grand_theft_ant',\n                        'Grand Theft Ant',\n                        const GrandTheftAntApp(),\n                        Icons.sports_esports_rounded,\n                      );\n                    } else if (file['openInfra'] == true) {\n                      context.read<SystemController>().openApp(\n                        'infra_monitor',\n                        'Infra Monitor',\n                        const InfraMonitorApp(),\n                        Icons.dns_rounded,\n                      );\n                    } else if (file['openCode'] == true) {\n                      context.read<SystemController>().openApp(\n                        'code',\n                        'Source Code',\n                        const CodeEditorApp(),\n                        Icons.code,\n                      );\n                    } else if (file['url'] != null) {\n                      final url = file['url'] as String;\n                      context.read<SystemController>().openApp(\n                        file['name'] as String,\n                        file['name'] as String,\n                        null,\n                        null,\n                        url: url,\n                      );\n                    }\n                  },\n                  child: Column(\n                    children: [\n                      Icon(\n                        file['icon'] as IconData,\n                        color: file['color'] as Color,\n                        size: 48,\n                      ),\n                      const SizedBox(height: 8),\n                      Text(\n                        file['name'] as String,\n                        style: GoogleFonts.inter(\n                          color: Colors.white70,\n                          fontSize: 12,\n                        ),\n                        textAlign: TextAlign.center,\n                        maxLines: 1,\n                        overflow: TextOverflow.ellipsis,\n                      ),\n                    ],\n                  ),\n                );\n              },\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n}",
  "lib/apps/case_study_app.dart": "import 'package:flutter/material.dart';\nimport 'package:google_fonts/google_fonts.dart';\nimport 'package:url_launcher/url_launcher.dart';\nimport '../models/config_model.dart';\n\nclass CaseStudyApp extends StatefulWidget {\n  final CustomApp app;\n\n  const CaseStudyApp({super.key, required this.app});\n\n  @override\n  State<CaseStudyApp> createState() => _CaseStudyAppState();\n}\n\nclass _CaseStudyAppState extends State<CaseStudyApp>\n    with SingleTickerProviderStateMixin {\n  late TabController _tabController;\n\n  @override\n  void initState() {\n    super.initState();\n    _tabController = TabController(length: 3, vsync: this);\n  }\n\n  @override\n  void dispose() {\n    _tabController.dispose();\n    super.dispose();\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final app = widget.app;\n    final primaryColor = Color(int.parse(app.color));\n\n    return Container(\n      color: const Color(0xFF14171C),\n      child: Column(\n        crossAxisAlignment: CrossAxisAlignment.start,\n        children: [\n\n          _buildHeader(app, primaryColor),\n\n          Container(\n            color: const Color(0xFF181C23),\n            child: LayoutBuilder(\n              builder: (context, constraints) {\n                final width = constraints.maxWidth;\n                final bool isCompact = width < 440;\n                final bool isMedium = width >= 440 && width < 620;\n\n                final String devLabel;\n                final String devopsLabel;\n                final String sysadminLabel;\n\n                if (isCompact) {\n                  devLabel = 'Dev';\n                  devopsLabel = 'DevOps';\n                  sysadminLabel = 'SysAdmin';\n                } else if (isMedium) {\n                  devLabel = 'Software Dev';\n                  devopsLabel = 'DevOps';\n                  sysadminLabel = 'SysAdmin';\n                } else {\n                  devLabel = 'Software Architecture';\n                  devopsLabel = 'DevOps & CI/CD';\n                  sysadminLabel = 'SysAdmin & Security';\n                }\n\n                return TabBar(\n                  controller: _tabController,\n                  isScrollable: false,\n                  labelColor: primaryColor,\n                  unselectedLabelColor: Colors.white60,\n                  indicatorColor: primaryColor,\n                  indicatorSize: TabBarIndicatorSize.tab,\n                  indicatorWeight: 3.0,\n                  labelStyle: GoogleFonts.inter(\n                    fontSize: isCompact ? 12 : 13,\n                    fontWeight: FontWeight.w600,\n                  ),\n                  tabs: [\n                    Tab(\n                      child: FittedBox(\n                        fit: BoxFit.scaleDown,\n                        child: Row(\n                          mainAxisAlignment: MainAxisAlignment.center,\n                          mainAxisSize: MainAxisSize.min,\n                          children: [\n                            Icon(Icons.code, size: isCompact ? 14 : 16),\n                            SizedBox(width: isCompact ? 4 : 6),\n                            Text(devLabel),\n                          ],\n                        ),\n                      ),\n                    ),\n                    Tab(\n                      child: FittedBox(\n                        fit: BoxFit.scaleDown,\n                        child: Row(\n                          mainAxisAlignment: MainAxisAlignment.center,\n                          mainAxisSize: MainAxisSize.min,\n                          children: [\n                            Icon(\n                              Icons.cloud_sync_outlined,\n                              size: isCompact ? 14 : 16,\n                            ),\n                            SizedBox(width: isCompact ? 4 : 6),\n                            Text(devopsLabel),\n                          ],\n                        ),\n                      ),\n                    ),\n                    Tab(\n                      child: FittedBox(\n                        fit: BoxFit.scaleDown,\n                        child: Row(\n                          mainAxisAlignment: MainAxisAlignment.center,\n                          mainAxisSize: MainAxisSize.min,\n                          children: [\n                            Icon(\n                              Icons.shield_outlined,\n                              size: isCompact ? 14 : 16,\n                            ),\n                            SizedBox(width: isCompact ? 4 : 6),\n                            Text(sysadminLabel),\n                          ],\n                        ),\n                      ),\n                    ),\n                  ],\n                );\n              },\n            ),\n          ),\n\n          Expanded(\n            child: TabBarView(\n              controller: _tabController,\n              children: [\n                _buildPointList(\n                  app.caseStudy,\n                  'Application Engineering Highlights',\n                  Icons.developer_mode,\n                  primaryColor,\n                ),\n                _buildDevOpsTab(app, primaryColor),\n                _buildSysAdminTab(app, primaryColor),\n              ],\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n\n  Widget _buildPointList(\n    List<String>? points,\n    String sectionTitle,\n    IconData icon,\n    Color accentColor,\n  ) {\n    if (points == null || points.isEmpty) {\n      return Center(\n        child: Text(\n          'No specific points recorded.',\n          style: GoogleFonts.inter(color: Colors.white38, fontSize: 14),\n        ),\n      );\n    }\n\n    return LayoutBuilder(\n      builder: (context, constraints) {\n        final isCompact = constraints.maxWidth < 480;\n\n        return ListView(\n          padding: EdgeInsets.symmetric(\n            horizontal: isCompact ? 16.0 : 24.0,\n            vertical: 18.0,\n          ),\n          children: [\n            Row(\n              children: [\n                Icon(icon, color: accentColor, size: 18),\n                const SizedBox(width: 8),\n                Expanded(\n                  child: Text(\n                    sectionTitle,\n                    style: GoogleFonts.inter(\n                      color: Colors.white,\n                      fontWeight: FontWeight.bold,\n                      fontSize: isCompact ? 15 : 16,\n                    ),\n                  ),\n                ),\n              ],\n            ),\n            const SizedBox(height: 16),\n            ...points.map((point) => _buildPointCard(point, accentColor)),\n          ],\n        );\n      },\n    );\n  }\n\n  Widget _buildDevOpsTab(CustomApp app, Color accentColor) {\n    final devopsPoints =\n        app.devopsStudy ??\n        [\n          'Terraform Infrastructure: Provisioned compute resources on Google Cloud Platform with automated Cloudflare DNS A-record mapping.',\n          'Ansible Automation: Continuous configuration management and automated site distribution orchestrated via WE-IAC repository.',\n          'Reverse Proxy & Rate Limiting: Nginx leaky-bucket traffic zones configured for 30 requests/second static burst protection.',\n        ];\n\n    return LayoutBuilder(\n      builder: (context, constraints) {\n        final isCompact = constraints.maxWidth < 480;\n\n        return ListView(\n          padding: EdgeInsets.symmetric(\n            horizontal: isCompact ? 16.0 : 24.0,\n            vertical: 18.0,\n          ),\n          children: [\n            Row(\n              children: [\n                Icon(Icons.cloud_sync_outlined, color: accentColor, size: 18),\n                const SizedBox(width: 8),\n                Expanded(\n                  child: Text(\n                    'Infrastructure as Code & Deployment Pipeline',\n                    style: GoogleFonts.inter(\n                      color: Colors.white,\n                      fontWeight: FontWeight.bold,\n                      fontSize: isCompact ? 15 : 16,\n                    ),\n                  ),\n                ),\n              ],\n            ),\n            const SizedBox(height: 14),\n\n            Container(\n              padding: const EdgeInsets.all(12),\n              decoration: BoxDecoration(\n                color: const Color(0xFF1E232B),\n                borderRadius: BorderRadius.circular(8),\n                border: Border.all(color: Colors.white12),\n              ),\n              child: isCompact\n                  ? Column(\n                      crossAxisAlignment: CrossAxisAlignment.start,\n                      children: [\n                        Row(\n                          children: [\n                            const Icon(\n                              Icons.terminal,\n                              color: Colors.greenAccent,\n                              size: 16,\n                            ),\n                            const SizedBox(width: 8),\n                            Text(\n                              'Deployment Orchestration (WE-IAC):',\n                              style: GoogleFonts.inter(\n                                color: Colors.white60,\n                                fontSize: 11,\n                                fontWeight: FontWeight.bold,\n                              ),\n                            ),\n                          ],\n                        ),\n                        const SizedBox(height: 6),\n                        SelectableText(\n                          'ansible-playbook -i inventory.ini deploy-sites.yml -e site=\${app.id}',\n                          style: GoogleFonts.jetBrainsMono(\n                            color: Colors.greenAccent,\n                            fontSize: 11,\n                          ),\n                        ),\n                      ],\n                    )\n                  : Row(\n                      children: [\n                        const Icon(\n                          Icons.terminal,\n                          color: Colors.greenAccent,\n                          size: 16,\n                        ),\n                        const SizedBox(width: 8),\n                        Text(\n                          'Deployment Orchestration (WE-IAC):',\n                          style: GoogleFonts.inter(\n                            color: Colors.white60,\n                            fontSize: 11,\n                            fontWeight: FontWeight.bold,\n                          ),\n                        ),\n                        const SizedBox(width: 8),\n                        Expanded(\n                          child: SelectableText(\n                            'ansible-playbook -i inventory.ini deploy-sites.yml -e site=\${app.id}',\n                            style: GoogleFonts.jetBrainsMono(\n                              color: Colors.greenAccent,\n                              fontSize: 11,\n                            ),\n                          ),\n                        ),\n                      ],\n                    ),\n            ),\n            const SizedBox(height: 16),\n\n            ...devopsPoints.map((point) => _buildPointCard(point, accentColor)),\n          ],\n        );\n      },\n    );\n  }\n\n  Widget _buildSysAdminTab(CustomApp app, Color accentColor) {\n    final sysadminPoints =\n        app.sysadminStudy ??\n        [\n          'Host Firewall Hardening: Netfilter/UFW default DENY policy; rate-limited SSH (22) and production TLS (443) only.',\n          'Intrusion Prevention: Fail2ban active jails monitoring sshd brute-force and nginx-limit-req with automated IP bans.',\n          'Resource & Kernel Tuning: e2-micro host optimized with 2GB swap space, vm.swappiness=10, and adjusted vfs_cache_pressure.',\n          'Zero-Trust Container Isolation: Database and internal APIs mapped strictly to isolated Docker bridge networks.',\n        ];\n\n    return LayoutBuilder(\n      builder: (context, constraints) {\n        final isCompact = constraints.maxWidth < 480;\n\n        return ListView(\n          padding: EdgeInsets.symmetric(\n            horizontal: isCompact ? 16.0 : 24.0,\n            vertical: 18.0,\n          ),\n          children: [\n            Row(\n              children: [\n                Icon(Icons.security, color: accentColor, size: 18),\n                const SizedBox(width: 8),\n                Expanded(\n                  child: Text(\n                    'Host Hardening, Zero-Trust & Systems Administration',\n                    style: GoogleFonts.inter(\n                      color: Colors.white,\n                      fontWeight: FontWeight.bold,\n                      fontSize: isCompact ? 15 : 16,\n                    ),\n                  ),\n                ),\n              ],\n            ),\n            const SizedBox(height: 14),\n\n            Wrap(\n              spacing: 8,\n              runSpacing: 8,\n              children: [\n                _buildSecurityPill(\n                  'TLS 1.3 Certbot Auto',\n                  Icons.lock,\n                  Colors.tealAccent,\n                ),\n                _buildSecurityPill(\n                  'UFW Default DENY',\n                  Icons.shield,\n                  Colors.amberAccent,\n                ),\n                _buildSecurityPill(\n                  'Fail2ban Multi-Jail',\n                  Icons.gavel,\n                  Colors.greenAccent,\n                ),\n                _buildSecurityPill(\n                  'Zero Public DB Port',\n                  Icons.visibility_off,\n                  Colors.blueAccent,\n                ),\n                _buildSecurityPill(\n                  '2GB Swap / 1GB RAM Tuning',\n                  Icons.memory,\n                  Colors.purpleAccent,\n                ),\n              ],\n            ),\n            const SizedBox(height: 16),\n\n            ...sysadminPoints.map(\n              (point) => _buildPointCard(point, accentColor),\n            ),\n          ],\n        );\n      },\n    );\n  }\n\n  Widget _buildSecurityPill(String label, IconData icon, Color color) {\n    return Container(\n      padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 5),\n      decoration: BoxDecoration(\n        color: const Color(0xFF1E232B),\n        borderRadius: BorderRadius.circular(6),\n        border: Border.all(color: color.withValues(alpha: 0.3)),\n      ),\n      child: Row(\n        mainAxisSize: MainAxisSize.min,\n        children: [\n          Icon(icon, color: color, size: 13),\n          const SizedBox(width: 6),\n          Text(\n            label,\n            style: GoogleFonts.inter(\n              color: Colors.white70,\n              fontSize: 11,\n              fontWeight: FontWeight.w500,\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n\n  Widget _buildPointCard(String point, Color accentColor) {\n    final parts = point.split(':');\n    final hasPrefix = parts.length > 1;\n\n    return Container(\n      margin: const EdgeInsets.only(bottom: 12.0),\n      padding: const EdgeInsets.all(14.0),\n      decoration: BoxDecoration(\n        color: const Color(0xFF1A1F26),\n        borderRadius: BorderRadius.circular(8),\n        border: Border.all(color: Colors.white10),\n      ),\n      child: Row(\n        crossAxisAlignment: CrossAxisAlignment.start,\n        children: [\n          Container(\n            margin: const EdgeInsets.only(top: 4),\n            width: 8,\n            height: 8,\n            decoration: BoxDecoration(\n              color: accentColor,\n              shape: BoxShape.circle,\n            ),\n          ),\n          const SizedBox(width: 12),\n          Expanded(\n            child: hasPrefix\n                ? RichText(\n                    text: TextSpan(\n                      style: GoogleFonts.inter(\n                        color: Colors.white70,\n                        fontSize: 14,\n                        height: 1.5,\n                      ),\n                      children: [\n                        TextSpan(\n                          text: '\${parts[0]}: ',\n                          style: GoogleFonts.inter(\n                            fontWeight: FontWeight.bold,\n                            color: Colors.white,\n                          ),\n                        ),\n                        TextSpan(text: parts.sublist(1).join(':').trim()),\n                      ],\n                    ),\n                  )\n                : Text(\n                    point,\n                    style: GoogleFonts.inter(\n                      color: Colors.white70,\n                      fontSize: 14,\n                      height: 1.5,\n                    ),\n                  ),\n          ),\n        ],\n      ),\n    );\n  }\n\n  Widget _buildHeader(CustomApp app, Color primaryColor) {\n    final hasLiveUrl = app.url.isNotEmpty && !app.url.startsWith('internal://');\n    final badgeItems = app.architectureBadge != null\n        ? app.architectureBadge!\n              .split('•')\n              .map((s) => s.trim())\n              .where((s) => s.isNotEmpty)\n              .toList()\n        : <String>[];\n\n    final badgeChips = badgeItems.map((badge) {\n      return Container(\n        padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),\n        decoration: BoxDecoration(\n          color: Colors.blueGrey.withValues(alpha: 0.25),\n          borderRadius: BorderRadius.circular(6),\n          border: Border.all(color: Colors.white24),\n        ),\n        child: Text(\n          badge,\n          style: GoogleFonts.jetBrainsMono(\n            color: Colors.white70,\n            fontSize: 10,\n            fontWeight: FontWeight.w500,\n          ),\n        ),\n      );\n    }).toList();\n\n    return Container(\n      padding: const EdgeInsets.symmetric(horizontal: 20.0, vertical: 16.0),\n      decoration: const BoxDecoration(\n        color: Color(0xFF1A1F26),\n        border: Border(bottom: BorderSide(color: Colors.white10)),\n      ),\n      child: LayoutBuilder(\n        builder: (context, constraints) {\n          final isNarrow = constraints.maxWidth < 620;\n\n          if (isNarrow) {\n            return Column(\n              crossAxisAlignment: CrossAxisAlignment.start,\n              children: [\n                Row(\n                  crossAxisAlignment: CrossAxisAlignment.center,\n                  children: [\n                    Container(\n                      padding: const EdgeInsets.all(10),\n                      decoration: BoxDecoration(\n                        color: primaryColor.withValues(alpha: 0.2),\n                        borderRadius: BorderRadius.circular(10),\n                        border: Border.all(\n                          color: primaryColor.withValues(alpha: 0.4),\n                        ),\n                      ),\n                      child: Icon(\n                        Icons.cases_rounded,\n                        color: primaryColor,\n                        size: 24,\n                      ),\n                    ),\n                    const SizedBox(width: 12),\n                    Expanded(\n                      child: Column(\n                        crossAxisAlignment: CrossAxisAlignment.start,\n                        children: [\n                          Text(\n                            app.title,\n                            style: GoogleFonts.outfit(\n                              color: Colors.white,\n                              fontSize: 22,\n                              fontWeight: FontWeight.bold,\n                            ),\n                          ),\n                          if (app.subtitle != null &&\n                              app.subtitle!.isNotEmpty) ...[\n                            const SizedBox(height: 2),\n                            Text(\n                              app.subtitle!,\n                              style: GoogleFonts.inter(\n                                color: Colors.white70,\n                                fontSize: 12,\n                                fontWeight: FontWeight.w400,\n                              ),\n                              maxLines: 2,\n                              overflow: TextOverflow.ellipsis,\n                            ),\n                          ],\n                        ],\n                      ),\n                    ),\n                    if (hasLiveUrl) ...[\n                      const SizedBox(width: 10),\n                      _buildLiveButton(primaryColor, compact: true),\n                    ],\n                  ],\n                ),\n                if (badgeChips.isNotEmpty) ...[\n                  const SizedBox(height: 12),\n                  Wrap(spacing: 6, runSpacing: 6, children: badgeChips),\n                ],\n              ],\n            );\n          }\n\n          return Row(\n            crossAxisAlignment: CrossAxisAlignment.center,\n            children: [\n              Container(\n                padding: const EdgeInsets.all(12),\n                decoration: BoxDecoration(\n                  color: primaryColor.withValues(alpha: 0.2),\n                  borderRadius: BorderRadius.circular(12),\n                  border: Border.all(\n                    color: primaryColor.withValues(alpha: 0.4),\n                  ),\n                ),\n                child: Icon(Icons.cases_rounded, color: primaryColor, size: 28),\n              ),\n              const SizedBox(width: 16),\n              Expanded(\n                child: Column(\n                  crossAxisAlignment: CrossAxisAlignment.start,\n                  children: [\n                    Wrap(\n                      spacing: 8,\n                      runSpacing: 6,\n                      crossAxisAlignment: WrapCrossAlignment.center,\n                      children: [\n                        Text(\n                          app.title,\n                          style: GoogleFonts.outfit(\n                            color: Colors.white,\n                            fontSize: 24,\n                            fontWeight: FontWeight.bold,\n                          ),\n                        ),\n                        ...badgeChips,\n                      ],\n                    ),\n                    if (app.subtitle != null && app.subtitle!.isNotEmpty) ...[\n                      const SizedBox(height: 4),\n                      Text(\n                        app.subtitle!,\n                        style: GoogleFonts.inter(\n                          color: Colors.white70,\n                          fontSize: 14,\n                          fontWeight: FontWeight.w500,\n                        ),\n                      ),\n                    ],\n                  ],\n                ),\n              ),\n              if (hasLiveUrl) ...[\n                const SizedBox(width: 16),\n                _buildLiveButton(primaryColor, compact: false),\n              ],\n            ],\n          );\n        },\n      ),\n    );\n  }\n\n  Widget _buildLiveButton(Color primaryColor, {bool compact = false}) {\n    return ElevatedButton.icon(\n      onPressed: () async {\n        final Uri uri = Uri.parse(widget.app.url);\n        await launchUrl(uri, mode: LaunchMode.externalApplication);\n      },\n      icon: Icon(Icons.open_in_new, size: compact ? 14 : 16),\n      label: const Text('Live Site'),\n      style: ElevatedButton.styleFrom(\n        backgroundColor: primaryColor,\n        foregroundColor: Colors.white,\n        padding: EdgeInsets.symmetric(\n          horizontal: compact ? 12 : 16,\n          vertical: compact ? 8 : 12,\n        ),\n        textStyle: GoogleFonts.inter(\n          fontSize: compact ? 12 : 13,\n          fontWeight: FontWeight.bold,\n        ),\n        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(8)),\n        elevation: 0,\n      ),\n    );\n  }\n}",
  "lib/apps/photo_album_app.dart": "import 'package:flutter/material.dart';\nimport 'package:flutter/services.dart';\nimport 'package:google_fonts/google_fonts.dart';\n\nclass PhotoAlbumApp extends StatefulWidget {\n  const PhotoAlbumApp({super.key});\n\n  @override\n  State<PhotoAlbumApp> createState() => _PhotoAlbumAppState();\n}\n\nclass _PhotoAlbumAppState extends State<PhotoAlbumApp> {\n  late Future<List<String>> _photosFuture;\n\n  @override\n  void initState() {\n    super.initState();\n    _photosFuture = _loadPhotos();\n  }\n\n  Future<List<String>> _loadPhotos() async {\n    final assetManifest = await AssetManifest.loadFromAssetBundle(rootBundle);\n\n    final photoPaths = assetManifest\n        .listAssets()\n        .where(\n          (key) =>\n              key.startsWith('assets/photos/') &&\n              (key.endsWith('.png') ||\n                  key.endsWith('.jpg') ||\n                  key.endsWith('.jpeg')),\n        )\n        .toList();\n\n    return photoPaths;\n  }\n\n  void _showFullImage(BuildContext context, String imagePath) {\n    showDialog(\n      context: context,\n      builder: (BuildContext context) {\n        return Dialog(\n          backgroundColor: Colors.transparent,\n          insetPadding: const EdgeInsets.all(32),\n          child: Stack(\n            clipBehavior: Clip.none,\n            alignment: Alignment.center,\n            children: [\n              InteractiveViewer(\n                child: ClipRRect(\n                  borderRadius: BorderRadius.circular(12),\n                  child: Image.asset(imagePath, fit: BoxFit.contain),\n                ),\n              ),\n              Positioned(\n                top: -16,\n                right: -16,\n                child: GestureDetector(\n                  onTap: () => Navigator.of(context).pop(),\n                  child: Container(\n                    padding: const EdgeInsets.all(8),\n                    decoration: const BoxDecoration(\n                      color: Colors.white,\n                      shape: BoxShape.circle,\n                      boxShadow: [\n                        BoxShadow(\n                          color: Colors.black26,\n                          blurRadius: 10,\n                          offset: Offset(0, 4),\n                        ),\n                      ],\n                    ),\n                    child: const Icon(\n                      Icons.close,\n                      color: Colors.black,\n                      size: 24,\n                    ),\n                  ),\n                ),\n              ),\n            ],\n          ),\n        );\n      },\n    );\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final onSurfaceColor = Theme.of(context).colorScheme.onSurface;\n\n    return Column(\n      crossAxisAlignment: CrossAxisAlignment.start,\n      children: [\n        Expanded(\n          child: FutureBuilder<List<String>>(\n            future: _photosFuture,\n            builder: (context, snapshot) {\n              if (snapshot.connectionState == ConnectionState.waiting) {\n                return const Center(child: CircularProgressIndicator());\n              } else if (snapshot.hasError) {\n                return Center(\n                  child: Text(\n                    'Error loading photos: \${snapshot.error}',\n                    style: GoogleFonts.inter(color: Colors.red),\n                  ),\n                );\n              } else if (!snapshot.hasData || snapshot.data!.isEmpty) {\n                return Center(\n                  child: Text(\n                    'No photos found in assets/photos/',\n                    style: GoogleFonts.inter(\n                      color: onSurfaceColor.withOpacity(0.5),\n                    ),\n                  ),\n                );\n              }\n\n              final photos = snapshot.data!;\n              return GridView.builder(\n                padding: const EdgeInsets.fromLTRB(24, 0, 24, 24),\n                gridDelegate: const SliverGridDelegateWithMaxCrossAxisExtent(\n                  maxCrossAxisExtent: 200,\n                  crossAxisSpacing: 16,\n                  mainAxisSpacing: 16,\n                ),\n                itemCount: photos.length,\n                itemBuilder: (context, index) {\n                  final path = photos[index];\n                  return GestureDetector(\n                    onTap: () => _showFullImage(context, path),\n                    child: Container(\n                      decoration: BoxDecoration(\n                        borderRadius: BorderRadius.circular(12),\n                        boxShadow: [\n                          BoxShadow(\n                            color: Colors.black.withOpacity(0.1),\n                            blurRadius: 8,\n                            offset: const Offset(0, 4),\n                          ),\n                        ],\n                      ),\n                      child: ClipRRect(\n                        borderRadius: BorderRadius.circular(12),\n                        child: Image.asset(path, fit: BoxFit.cover),\n                      ),\n                    ),\n                  );\n                },\n              );\n            },\n          ),\n        ),\n      ],\n    );\n  }\n}",
  "lib/services/wallpaper_storage/wallpaper_storage_stub.dart": "class WallpaperStorageService {\n  Future<bool> saveWallpaper(String base64Data) async => false;\n  Future<String?> loadWallpaper() async => null;\n  Future<bool> clearWallpaper() async => false;\n  Future<String> compressImage(\n    String dataUrl, {\n    int maxDim = 1920,\n    double quality = 0.85,\n  }) async => dataUrl;\n}",
  "lib/services/wallpaper_storage/wallpaper_storage_web.dart": "import 'dart:async';\nimport 'dart:js_interop';\nimport 'dart:js_interop_unsafe';\n\n@JS('window')\nexternal JSObject get _window;\n\nclass WallpaperStorageService {\n  Future<bool> saveWallpaper(String base64Data) {\n    final completer = Completer<bool>();\n    try {\n      final storage = _window['fyrWallpaperStorage'];\n      if (storage != null && storage.isA<JSObject>()) {\n        final jsStorage = storage as JSObject;\n        final jsCallback = ((JSBoolean success) {\n          completer.complete(success.toDart);\n        }).toJS;\n        jsStorage.callMethod('save'.toJS, base64Data.toJS, jsCallback);\n      } else {\n        completer.complete(false);\n      }\n    } catch (_) {\n      completer.complete(false);\n    }\n    return completer.future;\n  }\n\n  Future<String?> loadWallpaper() {\n    final completer = Completer<String?>();\n    try {\n      final storage = _window['fyrWallpaperStorage'];\n      if (storage != null && storage.isA<JSObject>()) {\n        final jsStorage = storage as JSObject;\n        final jsCallback = ((JSAny? data) {\n          if (data != null && data.isA<JSString>()) {\n            completer.complete((data as JSString).toDart);\n          } else {\n            completer.complete(null);\n          }\n        }).toJS;\n        jsStorage.callMethod('load'.toJS, jsCallback);\n      } else {\n        completer.complete(null);\n      }\n    } catch (_) {\n      completer.complete(null);\n    }\n    return completer.future;\n  }\n\n  Future<bool> clearWallpaper() {\n    final completer = Completer<bool>();\n    try {\n      final storage = _window['fyrWallpaperStorage'];\n      if (storage != null && storage.isA<JSObject>()) {\n        final jsStorage = storage as JSObject;\n        final jsCallback = ((JSBoolean success) {\n          completer.complete(success.toDart);\n        }).toJS;\n        jsStorage.callMethod('clear'.toJS, jsCallback);\n      } else {\n        completer.complete(false);\n      }\n    } catch (_) {\n      completer.complete(false);\n    }\n    return completer.future;\n  }\n\n  Future<String> compressImage(\n    String dataUrl, {\n    int maxDim = 1920,\n    double quality = 0.85,\n  }) {\n    final completer = Completer<String>();\n    try {\n      final compressFn = _window['fyrCompressImage'];\n      if (compressFn != null && compressFn.isA<JSFunction>()) {\n        final fn = compressFn as JSFunction;\n        final jsCallback = ((JSString result) {\n          completer.complete(result.toDart);\n        }).toJS;\n        fn.callAsFunction(\n          null,\n          dataUrl.toJS,\n          maxDim.toJS,\n          quality.toJS,\n          jsCallback,\n        );\n      } else {\n        completer.complete(dataUrl);\n      }\n    } catch (_) {\n      completer.complete(dataUrl);\n    }\n    return completer.future;\n  }\n}",
  "lib/services/wallpaper_storage/wallpaper_storage.dart": "export 'wallpaper_storage_stub.dart'\n    if (dart.library.js_interop) 'wallpaper_storage_web.dart';",
  "infra/terraform/main.tf": "resource \"google_compute_address\" \"static_ip\" {\n  name        = \"\${var.instance_name}-static-ip\"\n  region      = var.gcp_region\n  description = \"Static external IP for all hosted web services and bybl backend\"\n}\n\nresource \"google_compute_instance\" \"web_server\" {\n  name         = var.instance_name\n  machine_type = var.machine_type\n  zone         = var.gcp_zone\n\n  tags = [\"web-server\", \"http-server\", \"https-server\"]\n\n  boot_disk {\n    auto_delete = true\n    initialize_params {\n      size  = var.boot_disk_size_gb\n      type  = \"pd-balanced\"\n      image = var.boot_disk_image\n      labels = {\n        managed_by = \"terraform\"\n        tier       = \"production\"\n      }\n    }\n  }\n\n  network_interface {\n    network = \"default\"\n\n    access_config {\n      nat_ip       = google_compute_address.static_ip.address\n      network_tier = \"PREMIUM\"\n    }\n  }\n\n  metadata = {\n    ssh-keys               = \"\${var.ssh_user}:\${file(pathexpand(var.ssh_public_key_path))}\"\n    enable-oslogin         = \"FALSE\"\n    block-project-ssh-keys = \"FALSE\"\n  }\n\n  scheduling {\n    automatic_restart   = true\n    on_host_maintenance = \"MIGRATE\"\n    preemptible         = false\n  }\n\n  shielded_instance_config {\n    enable_secure_boot          = true\n    enable_vtpm                 = true\n    enable_integrity_monitoring = true\n  }\n\n  labels = {\n    environment = \"production\"\n    managed_by  = \"terraform\"\n    project     = \"we-iac\"\n  }\n}\n\nresource \"google_compute_firewall\" \"allow_http_https\" {\n  name    = \"\${var.instance_name}-allow-http-https\"\n  network = \"default\"\n\n  allow {\n    protocol = \"tcp\"\n    ports    = [\"80\", \"443\"]\n  }\n\n  source_ranges = [\"0.0.0.0/0\"]\n  target_tags   = [\"web-server\"]\n  description   = \"Allow incoming public HTTP and HTTPS traffic\"\n}\n\nresource \"google_compute_firewall\" \"allow_ssh\" {\n  name    = \"\${var.instance_name}-allow-ssh\"\n  network = \"default\"\n\n  allow {\n    protocol = \"tcp\"\n    ports    = [\"22\"]\n  }\n\n  source_ranges = var.ssh_allowed_cidrs\n  target_tags   = [\"web-server\"]\n  description   = \"Allow incoming SSH traffic (further hardened on host by fail2ban and UFW rate limiting)\"\n}\n\nresource \"google_compute_firewall\" \"deny_internal_ports\" {\n  name     = \"\${var.instance_name}-deny-internal-ports\"\n  network  = \"default\"\n  priority = 900\n\n  deny {\n    protocol = \"tcp\"\n    ports    = [\"5432\", \"8080\", \"8081\"]\n  }\n\n  source_ranges = [\"0.0.0.0/0\"]\n  target_tags   = [\"web-server\"]\n  description   = \"Block external access to Postgres (5432), API (8080), and gofyr (8081). Postgres is strictly isolated within Docker bridge network.\"\n}\n\nresource \"local_file\" \"ansible_inventory\" {\n  content = templatefile(\"\${path.module}/templates/inventory.ini.tpl\", {\n    ip_address           = google_compute_address.static_ip.address\n    ssh_user             = var.ssh_user\n    ssh_private_key_path = replace(var.ssh_public_key_path, \".pub\", \"\")\n  })\n  filename        = \"\${path.module}/../ansible/inventory.ini\"\n  file_permission = \"0644\"\n}",
  "infra/terraform/cloudflare.tf": "data \"cloudflare_zone\" \"archbtw\" {\n  count = var.enable_cloudflare_records ? 1 : 0\n  name  = \"archbtw.sh\"\n}\n\ndata \"cloudflare_zone\" \"bybl\" {\n  count = var.enable_cloudflare_records ? 1 : 0\n  name  = \"bybl.dev\"\n}\n\ndata \"cloudflare_zone\" \"archerwoods\" {\n  count = var.enable_cloudflare_records ? 1 : 0\n  name  = \"archerwoods.dev\"\n}\n\ndata \"cloudflare_zone\" \"libretrac\" {\n  count = var.enable_cloudflare_records ? 1 : 0\n  name  = \"libretrac.site\"\n}\n\ndata \"cloudflare_zone\" \"theolivebranch\" {\n  count = var.enable_cloudflare_records ? 1 : 0\n  name  = \"theolivebranch.press\"\n}\n\ndata \"cloudflare_zone\" \"welledumacated\" {\n  count = var.enable_cloudflare_records ? 1 : 0\n  name  = \"welledumacated.dev\"\n}\n\ndata \"cloudflare_zone\" \"fyr_software\" {\n  count = var.enable_cloudflare_records ? 1 : 0\n  name  = \"fyr.software\"\n}\n\nresource \"cloudflare_record\" \"archbtw_root\" {\n  count           = var.enable_cloudflare_records ? 1 : 0\n  zone_id         = data.cloudflare_zone.archbtw[0].id\n  name            = \"@\"\n  value           = google_compute_address.static_ip.address\n  type            = \"A\"\n  proxied         = var.cloudflare_proxied\n  ttl             = var.cloudflare_proxied ? 1 : 300\n  allow_overwrite = true\n}\n\nresource \"cloudflare_record\" \"archbtw_www\" {\n  count           = var.enable_cloudflare_records ? 1 : 0\n  zone_id         = data.cloudflare_zone.archbtw[0].id\n  name            = \"www\"\n  value           = google_compute_address.static_ip.address\n  type            = \"A\"\n  proxied         = var.cloudflare_proxied\n  ttl             = var.cloudflare_proxied ? 1 : 300\n  allow_overwrite = true\n}\n\nresource \"cloudflare_record\" \"bybl_root\" {\n  count           = var.enable_cloudflare_records ? 1 : 0\n  zone_id         = data.cloudflare_zone.bybl[0].id\n  name            = \"@\"\n  value           = google_compute_address.static_ip.address\n  type            = \"A\"\n  proxied         = var.cloudflare_proxied\n  ttl             = var.cloudflare_proxied ? 1 : 300\n  allow_overwrite = true\n}\n\nresource \"cloudflare_record\" \"bybl_www\" {\n  count           = var.enable_cloudflare_records ? 1 : 0\n  zone_id         = data.cloudflare_zone.bybl[0].id\n  name            = \"www\"\n  value           = google_compute_address.static_ip.address\n  type            = \"A\"\n  proxied         = var.cloudflare_proxied\n  ttl             = var.cloudflare_proxied ? 1 : 300\n  allow_overwrite = true\n}\n\nresource \"cloudflare_record\" \"bybl_api\" {\n  count           = var.enable_cloudflare_records ? 1 : 0\n  zone_id         = data.cloudflare_zone.bybl[0].id\n  name            = \"api\"\n  value           = google_compute_address.static_ip.address\n  type            = \"A\"\n  proxied         = var.cloudflare_proxied\n  ttl             = var.cloudflare_proxied ? 1 : 300\n  allow_overwrite = true\n}\n\nresource \"cloudflare_record\" \"bybl_gofyr\" {\n  count           = var.enable_cloudflare_records ? 1 : 0\n  zone_id         = data.cloudflare_zone.bybl[0].id\n  name            = \"gofyr\"\n  value           = google_compute_address.static_ip.address\n  type            = \"A\"\n  proxied         = var.cloudflare_proxied\n  ttl             = var.cloudflare_proxied ? 1 : 300\n  allow_overwrite = true\n}\n\nresource \"cloudflare_record\" \"archerwoods_root\" {\n  count           = var.enable_cloudflare_records ? 1 : 0\n  zone_id         = data.cloudflare_zone.archerwoods[0].id\n  name            = \"@\"\n  value           = google_compute_address.static_ip.address\n  type            = \"A\"\n  proxied         = var.cloudflare_proxied\n  ttl             = var.cloudflare_proxied ? 1 : 300\n  allow_overwrite = true\n}\n\nresource \"cloudflare_record\" \"archerwoods_www\" {\n  count           = var.enable_cloudflare_records ? 1 : 0\n  zone_id         = data.cloudflare_zone.archerwoods[0].id\n  name            = \"www\"\n  va