 ? 1 : 0\n  zone_id         = data.cloudflare_zone.theolivebranch[0].id\n  name            = \"www\"\n  value           = google_compute_address.static_ip.address\n  type            = \"A\"\n  proxied         = var.cloudflare_proxied\n  ttl             = var.cloudflare_proxied ? 1 : 300\n  allow_overwrite = true\n}\n\nresource \"cloudflare_record\" \"welledumacated_root\" {\n  count           = var.enable_cloudflare_records ? 1 : 0\n  zone_id         = data.cloudflare_zone.welledumacated[0].id\n  name            = \"@\"\n  value           = google_compute_address.static_ip.address\n  type            = \"A\"\n  proxied         = var.cloudflare_proxied\n  ttl             = var.cloudflare_proxied ? 1 : 300\n  allow_overwrite = true\n}\n\nresource \"cloudflare_record\" \"welledumacated_www\" {\n  count           = var.enable_cloudflare_records ? 1 : 0\n  zone_id         = data.cloudflare_zone.welledumacated[0].id\n  name            = \"www\"\n  value           = google_compute_address.static_ip.address\n  type            = \"A\"\n  proxied         = var.cloudflare_proxied\n  ttl             = var.cloudflare_proxied ? 1 : 300\n  allow_overwrite = true\n}\n\nresource \"cloudflare_record\" \"fyr_software_root\" {\n  count           = var.enable_cloudflare_records ? 1 : 0\n  zone_id         = data.cloudflare_zone.fyr_software[0].id\n  name            = \"@\"\n  value           = google_compute_address.static_ip.address\n  type            = \"A\"\n  proxied         = var.cloudflare_proxied\n  ttl             = var.cloudflare_proxied ? 1 : 300\n  allow_overwrite = true\n}\n\nresource \"cloudflare_record\" \"fyr_software_www\" {\n  count           = var.enable_cloudflare_records ? 1 : 0\n  zone_id         = data.cloudflare_zone.fyr_software[0].id\n  name            = \"www\"\n  value           = google_compute_address.static_ip.address\n  type            = \"A\"\n  proxied         = var.cloudflare_proxied\n  ttl             = var.cloudflare_proxied ? 1 : 300\n  allow_overwrite = true\n}\n\ndata \"cloudflare_zone\" \"carlyle\" {\n  count = (var.enable_cloudflare_records && var.enable_carlyle_cloudflare) ? 1 : 0\n  name  = \"carlyleauto.online\"\n}\n\nresource \"cloudflare_record\" \"carlyle_root\" {\n  count           = (var.enable_cloudflare_records && var.enable_carlyle_cloudflare) ? 1 : 0\n  zone_id         = data.cloudflare_zone.carlyle[0].id\n  name            = \"@\"\n  value           = google_compute_address.static_ip.address\n  type            = \"A\"\n  proxied         = var.cloudflare_proxied\n  ttl             = var.cloudflare_proxied ? 1 : 300\n  allow_overwrite = true\n}\n\nresource \"cloudflare_record\" \"carlyle_www\" {\n  count           = (var.enable_cloudflare_records && var.enable_carlyle_cloudflare) ? 1 : 0\n  zone_id         = data.cloudflare_zone.carlyle[0].id\n  name            = \"www\"\n  value           = google_compute_address.static_ip.address\n  type            = \"A\"\n  proxied         = var.cloudflare_proxied\n  ttl             = var.cloudflare_proxied ? 1 : 300\n  allow_overwrite = true\n}",
  "infra/ansible/deploy-sites.yml": "---\n\n- name: Sync and Deploy Web Apps\n  hosts: web_servers\n  become: yes\n  vars_files:\n    - \"group_vars/all/vars.yml\"\n    - [ \"group_vars/all/vault.yml\", \"group_vars/all/vault.yml.example\" ]\n  vars:\n    _cli_site: \"{{ site | default(target_site | default('')) | string | trim | lower }}\"\n    _cli_sites: \"{{ _cli_site.split(',') | map('trim') | select() | list }}\"\n    _include_bybl_backend: >-\n      {{\n        (_cli_sites | intersect(['bybl', 'bybl_backend', 'bybl_api', 'bybl_gofyr']) | length > 0) or\n        (_cli_site == '' and ('all' not in ansible_run_tags) and (ansible_run_tags | intersect(['bybl', 'bybl_backend', 'bybl_api', 'bybl_gofyr', 'backend']) | length > 0))\n      }}\n\n  roles:\n    - role: bybl_backend\n      tags: [bybl, bybl_backend, bybl_api, bybl_gofyr, backend]\n      when: _include_bybl_backend | bool\n\n    - role: static_sites\n      tags:\n        - static_sites\n        - deploy\n        - archbtw\n        - bybl\n        - bybl_web\n        - bybl_frontend\n        - archerwoods\n        - fyrweb\n        - folja\n        - libretrac\n        - theolivebranch\n        - welledumacated\n        - fyr_software\n        - fyr\n        - fyrwebsite\n        - carlyleauto\n        - carlyle\n        - bcd_landing\n      when: \"_cli_site == '' or (_cli_sites | difference(['bybl_backend', 'bybl_api', 'bybl_gofyr']) | length > 0)\"\n\n  post_tasks:\n    - name: Reload Nginx to flush any cached assets\n      service:\n        name: nginx\n        state: reloaded\n      when:\n        - selected_static_sites is defined\n        - selected_static_sites | length > 0\n      tags:\n        - static_sites\n        - deploy\n        - archbtw\n        - bybl\n        - bybl_web\n        - bybl_frontend\n        - archerwoods\n        - fyrweb\n        - folja\n        - libretrac\n        - theolivebranch\n        - welledumacated\n        - fyr_software\n        - fyr\n        - fyrwebsite\n        - carlyleauto\n        - carlyle\n        - bcd_landing",
  "infra/ansible/roles/nginx/templates/site.conf.j2": "{% if cert_stat.stat.exists %}\n\nserver {\n    listen 80;\n    listen [::]:80;\n    server_name {{ site.domain }}{% for alias in site.aliases %} {{ alias }}{% endfor %};\n\n    location ^~ /.well-known/acme-challenge/ {\n        root /var/www/letsencrypt;\n        default_type \"text/plain\";\n    }\n\n    location / {\n        return 301 https://\$host\$request_uri;\n    }\n}\n\nserver {\n    listen 443 ssl http2;\n    listen [::]:443 ssl http2;\n    server_name {{ site.domain }}{% for alias in site.aliases %} {{ alias }}{% endfor %};\n\n    ssl_certificate /etc/letsencrypt/live/{{ site.domain }}/fullchain.pem;\n    ssl_certificate_key /etc/letsencrypt/live/{{ site.domain }}/privkey.pem;\n\n    limit_req zone={{ site.rate_limit_zone }} burst={{ site.rate_limit_burst }} nodelay;\n    limit_conn addr_conn {{ nginx_conn_limit }};\n\n{% if site.type == 'static' %}\n    root {{ site.web_root }};\n    index index.html index.htm;\n\n{% if site.custom_nginx_location is defined %}\n{{ site.custom_nginx_location }}\n{% endif %}\n\n    location / {\n        try_files \$uri \$uri/ /index.html;\n    }\n\n    location ~* \\.(?:css|js|wasm|json|png|jpg|jpeg|gif|ico|svg|woff|woff2|ttf|eot)\$ {\n        expires 30d;\n        add_header Cache-Control \"public, no-transform\";\n    }\n{% elif site.type == 'proxy' %}\n    client_max_body_size 50M;\n\n    location / {\n        proxy_pass {{ site.proxy_pass }};\n        proxy_http_version 1.1;\n        proxy_set_header Upgrade \$http_upgrade;\n        proxy_set_header Connection \"upgrade\";\n        proxy_set_header Host \$host;\n        proxy_set_header X-Real-IP \$remote_addr;\n        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;\n        proxy_set_header X-Forwarded-Proto \$scheme;\n        proxy_connect_timeout 60s;\n        proxy_send_timeout 60s;\n        proxy_read_timeout 60s;\n    }\n{% endif %}\n}\n{% else %}\n\nserver {\n    listen 80;\n    listen [::]:80;\n    server_name {{ site.domain }}{% for alias in site.aliases %} {{ alias }}{% endfor %};\n\n    location ^~ /.well-known/acme-challenge/ {\n        root /var/www/letsencrypt;\n        default_type \"text/plain\";\n    }\n\n    limit_req zone={{ site.rate_limit_zone }} burst={{ site.rate_limit_burst }} nodelay;\n    limit_conn addr_conn {{ nginx_conn_limit }};\n\n{% if site.type == 'static' %}\n    root {{ site.web_root }};\n    index index.html index.htm;\n\n{% if site.custom_nginx_location is defined %}\n{{ site.custom_nginx_location }}\n{% endif %}\n\n    location / {\n        try_files \$uri \$uri/ /index.html;\n    }\n{% elif site.type == 'proxy' %}\n    client_max_body_size 50M;\n\n    location / {\n        proxy_pass {{ site.proxy_pass }};\n        proxy_http_version 1.1;\n        proxy_set_header Upgrade \$http_upgrade;\n        proxy_set_header Connection \"upgrade\";\n        proxy_set_header Host \$host;\n        proxy_set_header X-Real-IP \$remote_addr;\n        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;\n        proxy_set_header X-Forwarded-Proto \$scheme;\n    }\n{% endif %}\n}\n{% endif %}",
  "infra/ansible/roles/bybl_backend/templates/docker-compose.yml.j2": "services:\n  db:\n    image: postgres:15-alpine\n    container_name: bybl-db\n    restart: unless-stopped\n    env_file:\n      - .env\n\n    healthcheck:\n      test: [\"CMD-SHELL\", \"pg_isready -U {{ vault_postgres_user | default('bybl_user') }} -d {{ vault_postgres_db | default('bybl_db') }}\"]\n      interval: 5s\n      timeout: 5s\n      retries: 10\n    networks:\n      - app-network\n    volumes:\n      - db-data:/var/lib/postgresql/data\n\n  api:\n    build:\n      context: .\n      dockerfile: Backend/Dockerfile\n    container_name: bybl-api\n    restart: unless-stopped\n    env_file:\n      - .env\n    depends_on:\n      db:\n        condition: service_healthy\n    networks:\n      - app-network\n\n    ports:\n      - \"127.0.0.1:8080:8080\"\n      - \"127.0.0.1:8081:8081\"\n    volumes:\n      - ./Backend/uploads:/app/uploads\n\nnetworks:\n  app-network:\n    driver: bridge\n\nvolumes:\n  db-data:",
  "infra/scripts/deploy_all.sh": "set -e\n\nSCRIPT_DIR=\"\$(cd \"\$(dirname \"\${BASH_SOURCE[0]}\")\" && pwd)\"\nIAC_DIR=\"\$(cd \"\$SCRIPT_DIR/..\" && pwd)\"\n\nGREEN=\"\\033[0;32m\"\nCYAN=\"\\033[0;36m\"\nYELLOW=\"\\033[1;33m\"\nRED=\"\\033[0;31m\"\nNC=\"\\033[0m\"\n\nusage() {\n  echo -e \"\${CYAN}Usage:\${NC} \$0 [options] [all | <site> ...]\"\n  echo \"\"\n  echo \"Options:\"\n  echo \"  -s, --site <site>     Target site(s) to build and deploy (comma-separated or multiple args)\"\n  echo \"  --skip-build          Skip local Flutter/Vite/Go build step\"\n  echo \"  --skip-terraform      Skip Terraform provisioning & Cloudflare DNS sync\"\n  echo \"  --provision           Force Terraform & full server provisioning even for single-site deploy\"\n  echo \"  -h, --help            Show this help message\"\n  echo \"\"\n  echo \"Available site targets:\"\n  echo \"  all                   Deploy everything (default)\"\n  echo \"  archbtw               archbtw.sh\"\n  echo \"  bybl                  bybl.dev (Frontend) + api.bybl.dev & gofyr.bybl.dev (Backend)\"\n  echo \"  bybl_web              bybl.dev Frontend only\"\n  echo \"  bybl_backend          bybl Go Backend + gofyrAdmin only\"\n  echo \"  archerwoods           archerwoods.dev (fyrWeb)\"\n  echo \"  folja                 folja.archerwoods.dev (folja.app)\"\n  echo \"  libretrac             libretrac.site\"\n  echo \"  theolivebranch        theolivebranch.press\"\n  echo \"  welledumacated        welledumacated.dev\"\n  echo \"  fyr                   fyr.software (fyrDE/fyrwebsite)\"\n  echo \"  carlyleauto           carlyleauto.online (bcd_landing)\"\n}\n\nSKIP_BUILD=false\nSKIP_TERRAFORM=\"\"\nFORCE_PROVISION=false\nSITES=()\n\nwhile [[ \$\n  case \"\$1\" in\n    -h|--help)\n      usage\n      exit 0\n      ;;\n    -s|--site)\n      if [[ -z \"\${2:-}\" ]]; then\n        echo -e \"\${RED}❌ Error: --site requires an argument.\${NC}\"\n        exit 1\n      fi\n      SITES+=(\"\$2\")\n      shift 2\n      ;;\n    --skip-build)\n      SKIP_BUILD=true\n      shift\n      ;;\n    --skip-terraform)\n      SKIP_TERRAFORM=true\n      shift\n      ;;\n    --provision|--with-terraform)\n      FORCE_PROVISION=true\n      SKIP_TERRAFORM=false\n      shift\n      ;;\n    -*)\n      echo -e \"\${RED}❌ Unknown option: \$1\${NC}\"\n      usage\n      exit 1\n      ;;\n    *)\n      SITES+=(\"\$1\")\n      shift\n      ;;\n  esac\ndone\n\nif [ \${\n  TARGET_SITES=\"all\"\nelse\n  NORMALIZED_SITES=()\n  for s in \"\${SITES[@]}\"; do\n    IFS=',' read -ra PARTS <<< \"\$s\"\n    for p in \"\${PARTS[@]}\"; do\n      p=\"\$(echo \"\$p\" | xargs | tr '[:upper:]' '[:lower:]')\"\n      if [ -n \"\$p\" ]; then\n        NORMALIZED_SITES+=(\"\$p\")\n      fi\n    done\n  done\n  TARGET_SITES=\"\$(IFS=','; echo \"\${NORMALIZED_SITES[*]}\")\"\nfi\n\nif [ -z \"\$SKIP_TERRAFORM\" ]; then\n  if [ \"\$TARGET_SITES\" = \"all\" ] || [ ! -f \"\$IAC_DIR/ansible/inventory.ini\" ]; then\n    SKIP_TERRAFORM=false\n  else\n    SKIP_TERRAFORM=true\n  fi\nfi\n\necho -e \"\${CYAN}======================================================================\${NC}\"\nif [ \"\$TARGET_SITES\" = \"all\" ]; then\n  echo -e \"\${CYAN}🚀 WE-IAC: Complete GCP + Cloudflare + Server Deployment Automation\${NC}\"\nelse\n  echo -e \"\${CYAN}🚀 WE-IAC: Targeted Site Deployment (\${TARGET_SITES})\${NC}\"\nfi\necho -e \"\${CYAN}======================================================================\${NC}\"\n\nif ! command -v ansible-playbook >/dev/null 2>&1; then\n  echo -e \"\${RED}❌ ansible-playbook is not found in PATH!\${NC}\"\n  echo -e \"\${YELLOW}Install via Homebrew: brew install ansible\${NC}\"\n  exit 1\nfi\n\nif [ \"\$SKIP_TERRAFORM\" = false ]; then\n  if ! command -v terraform >/dev/null 2>&1; then\n    echo -e \"\${RED}❌ terraform is not found in PATH!\${NC}\"\n    echo -e \"\${YELLOW}Install via Homebrew: brew tap hashicorp/tap && brew install hashicorp/tap/terraform\${NC}\"\n    exit 1\n  fi\n\n  echo -e \"\\n\${YELLOW}=== Step 1: Provisioning GCP Infrastructure & Cloudflare DNS ===\${NC}\"\n  cd \"\$IAC_DIR/terraform\"\n\n  if [ ! -f \"terraform.tfvars\" ]; then\n    echo -e \"\${RED}❌ terraform/terraform.tfvars not found!\${NC}\"\n    echo -e \"Please create it from the example:\"\n    echo -e \"  cp terraform/terraform.tfvars.example terraform/terraform.tfvars\"\n    echo -e \"Fill in your gcp_project_id, cloudflare_api_token, and ssh_public_key_path.\"\n    exit 1\n  fi\n\n  echo \"Initializing Terraform...\"\n  terraform init\n\n  echo \"Applying Terraform configuration...\"\n  terraform apply -auto-approve\n\n  STATIC_IP=\"\$(terraform output -raw instance_static_ip)\"\n  echo -e \"\${GREEN}✓ Infrastructure provisioned! Static IP: \${STATIC_IP}\${NC}\"\n  echo -e \"\${GREEN}✓ Ansible inventory generated at ansible/inventory.ini\${NC}\"\n\n  echo -e \"\\n\${YELLOW}=== Pruning obsolete Cloudflare DNS records ===\${NC}\"\n  python3 \"\$IAC_DIR/scripts/sync_cloudflare_dns.py\"\nelse\n  echo -e \"\\n\${YELLOW}=== Step 1: Skipping Terraform Provisioning (deploying \${TARGET_SITES}) ===\${NC}\"\n  STATIC_IP=\"\$(grep -E '^[0-9]+\\.[0-9]+\\.[0-9]+\\.[0-9]+' \"\$IAC_DIR/ansible/inventory.ini\" | awk '{print \$1}' | head -n 1 || true)\"\nfi\n\nif [ \"\$SKIP_BUILD\" = false ]; then\n  echo -e \"\\n\${YELLOW}=== Step 2: Building Local Projects (\${TARGET_SITES}) ===\${NC}\"\n  \"\$IAC_DIR/scripts/build_all_local.sh\" \"\$TARGET_SITES\"\nelse\n  echo -e \"\\n\${YELLOW}=== Step 2: Skipping Local Builds (--skip-build) ===\${NC}\"\nfi\n\nif [ -n \"\$STATIC_IP\" ]; then\n  echo -e \"\\n\${YELLOW}=== Step 3: Verifying SSH Access to Server (\${STATIC_IP}) ===\${NC}\"\n  MAX_WAIT=30\n  WAITED=0\n  while ! ssh -o ConnectTimeout=5 -o StrictHostKeyChecking=accept-new -q \"archerwoods13@\${STATIC_IP}\" exit 2>/dev/null; do\n    echo \"Waiting for SSH to become ready... (\${WAITED}s/\${MAX_WAIT}s)\"\n    sleep 5\n    WAITED=\$((WAITED + 5))\n    if [ \$WAITED -ge \$MAX_WAIT ]; then\n      echo -e \"\${YELLOW}Warning: SSH took longer than expected. Proceeding with Ansible retry logic...\${NC}\"\n      break\n    fi\n  done\n  echo -e \"\${GREEN}✓ Server SSH is responding!\${NC}\"\nfi\n\necho -e \"\\n\${YELLOW}=== Step 4: Deploying (\${TARGET_SITES}) with Ansible ===\${NC}\"\ncd \"\$IAC_DIR/ansible\"\n\nif [ ! -f \"group_vars/all/vault.yml\" ]; then\n  echo -e \"\${YELLOW}Note: group_vars/all/vault.yml not found. Using default template values from vault.yml.example.\${NC}\"\n  echo -e \"\${YELLOW}To customize database passwords and API keys, copy vault.yml.example to vault.yml.\${NC}\"\nfi\n\nANSIBLE_EXTRA_ARGS=(-e \"site=\${TARGET_SITES}\")\nif [ \"\$FORCE_PROVISION\" = true ]; then\n  ANSIBLE_EXTRA_ARGS+=(-e \"provision=true\")\nfi\n\nansible-playbook playbook.yml \"\${ANSIBLE_EXTRA_ARGS[@]}\"\n\necho -e \"\\n\${GREEN}======================================================================\${NC}\"\necho -e \"\${GREEN}🎉 DEPLOYMENT COMPLETE (\${TARGET_SITES})!\${NC}\"\necho -e \"\${GREEN}======================================================================\${NC}\"",
};
